const SIDEBAR_BG: Color = Color::Rgb(24, 24, 37);
const ACTIVE_BG: Color = Color::Rgb(30, 30, 46);
const BORDER: Color = Color::Rgb(49, 50, 68);
const MUTED: Color = Color::Rgb(108, 112, 134);
const DIM: Color = Color::Rgb(147, 153, 178);
const MAUVE: Color = Color::Rgb(203, 166, 247);

fn relay_route_label(route: C2RelayRoute) -> &'static str {
    match route {
        C2RelayRoute::LocalIpc => "Local IPC",
        C2RelayRoute::SshForwardedLoopback => "SSH forwarded",
        C2RelayRoute::Unknown => "Unknown",
    }
}

fn node_route_value(app: &App, node_id: &str) -> String {
    let route = app
        .nodes
        .iter()
        .find(|node| node.node_id == node_id)
        .map(|node| node.relay_route)
        .unwrap_or(C2RelayRoute::Unknown);
    format!("{node_id} | {}", relay_route_label(route))
}
const ACTIVE_TAB_TEXT: Color = Color::Rgb(23, 23, 26);
const GREEN: Color = Color::Rgb(166, 227, 161);
const YELLOW: Color = Color::Rgb(249, 226, 175);
const RED: Color = Color::Rgb(243, 139, 168);
const TEAL: Color = Color::Rgb(148, 226, 213);

#[derive(Clone, Copy)]
struct Theme {
    surface: Color,
    panel: Color,
    modal: Color,
    active: Color,
    border: Color,
    text: Color,
    muted: Color,
    dim: Color,
    accent: Color,
    active_tab_text: Color,
    green: Color,
    yellow: Color,
    red: Color,
    teal: Color,
    diff_added: Color,
    diff_deleted: Color,
    diff_hunk: Color,
    diff_meta: Color,
}

impl Theme {
    fn for_mode(mode: PtyColorMode) -> Self {
        match mode {
            PtyColorMode::Inherited => Self {
                surface: Color::Reset,
                panel: Color::Reset,
                modal: Color::Black,
                active: Color::Reset,
                border: Color::Indexed(8),
                text: Color::Reset,
                muted: Color::Indexed(8),
                dim: Color::Indexed(8),
                accent: Color::Magenta,
                active_tab_text: Color::Black,
                green: Color::Green,
                yellow: Color::Yellow,
                red: Color::Red,
                teal: Color::Cyan,
                diff_added: Color::Indexed(22),
                diff_deleted: Color::Indexed(52),
                diff_hunk: Color::Indexed(24),
                diff_meta: Color::Indexed(0),
            },
            PtyColorMode::GateOverride => Self {
                surface: TERM_BG,
                panel: SIDEBAR_BG,
                modal: SIDEBAR_BG,
                active: ACTIVE_BG,
                border: BORDER,
                text: GATE_FG,
                muted: MUTED,
                dim: DIM,
                accent: MAUVE,
                active_tab_text: ACTIVE_TAB_TEXT,
                green: GREEN,
                yellow: YELLOW,
                red: RED,
                teal: TEAL,
                diff_added: Color::Indexed(22),
                diff_deleted: Color::Indexed(52),
                diff_hunk: Color::Indexed(24),
                diff_meta: Color::Indexed(0),
            },
        }
    }
}

pub fn render(app: &App, buf: &mut TerminalBuffer) -> LayoutRects {
    buf.clear();
    let full_area = Rect::new(0, 0, buf.width(), buf.height());
    let theme = Theme::for_mode(app.color_mode);
    if full_area.width < 56 || full_area.height < 14 {
        Paragraph::new("gate4agent operator needs at least 56x14")
            .style(Style::default().fg(theme.yellow).bg(theme.surface))
            .render(full_area, buf);
        return LayoutRects::default();
    }

    // The status bar (`render_status_bar`, below) owns the terminal's own
    // last row unconditionally -- every layout consumer in this function
    // reads `area`, already one row shorter than `full_area`, so nothing
    // computed from it (rail, sidebar, tab strip, viewport, or any of the
    // centered modals further down, which all take `area` too) can ever
    // overlap that row rather than silently painting under the bar. Only
    // `full_area` itself, threaded through to `render_status_bar`
    // separately, ever touches the true last row. `full_area.height >= 14`
    // is already guaranteed by the guard above, so this never underflows.
    let area = Rect::new(full_area.x, full_area.y, full_area.width, full_area.height - 1);

    Paragraph::new("")
        .style(Style::default().fg(theme.text).bg(theme.surface))
        .render(area, buf);
    let (activity_rail, sidebar_content, spaces, agents, right_area) =
        match (app.menu_placement, app.sidebar_presentation) {
            (MenuPlacement::Sidebar, SidebarPresentation::Split) => {
                let sidebar_width = app.sidebar_width.clamp(18, area.width.saturating_sub(24));
                let columns = split(
                    area,
                    Direction::Horizontal,
                    &[Constraint::Fixed(sidebar_width), Constraint::Min(1)],
                );
                let sidebar_content = Rect::new(
                    columns[0].x,
                    columns[0].y,
                    columns[0].width.saturating_sub(1),
                    columns[0].height,
                );
                let split_percent = app.sidebar_split_percent.clamp(20, 80) as u32;
                let top_height = ((sidebar_content.height as u32 * split_percent) / 100) as u16;
                let top_height = top_height.clamp(3, sidebar_content.height.saturating_sub(3));
                let spaces = Rect::new(
                    sidebar_content.x,
                    sidebar_content.y,
                    sidebar_content.width,
                    top_height,
                );
                let agents = Rect::new(
                    sidebar_content.x,
                    sidebar_content.y + top_height,
                    sidebar_content.width,
                    sidebar_content.height.saturating_sub(top_height),
                );
                (Rect::default(), sidebar_content, spaces, agents, columns[1])
            }
            (MenuPlacement::Sidebar, SidebarPresentation::Activity) => {
                // 6 wide: 1 margin column for the left accent bar (`▎`)
                // that marks the active button, 4 for the button body
                // (glyph centered on its middle row when tall enough for
                // the 3-row treatment), 1 trailing margin column back to
                // the rail background.
                let rail_width = 6_u16.min(area.width.saturating_sub(1));
                let content_width = if app.sidebar_collapsed {
                    0
                } else {
                    app.sidebar_width.clamp(18, area.width.saturating_sub(rail_width + 24))
                };
                let total_width = rail_width.saturating_add(content_width);
                let right_area = Rect::new(
                    area.x + total_width,
                    area.y,
                    area.width.saturating_sub(total_width),
                    area.height,
                );
                let rail = Rect::new(area.x, area.y, rail_width, area.height);
                let content = Rect::new(area.x + rail_width, area.y, content_width, area.height);
                let spaces = if matches!(app.control_section, ControlSection::Files | ControlSection::Git) {
                    content
                } else {
                    Rect::default()
                };
                let agents = if matches!(app.control_section, ControlSection::Agents | ControlSection::Workspaces) {
                    content
                } else {
                    Rect::default()
                };
                (rail, content, spaces, agents, right_area)
            }
            (MenuPlacement::Modal, _) => (
                Rect::default(),
                Rect::default(),
                Rect::default(),
                Rect::default(),
                area,
            ),
        };
    let right = split(
        right_area,
        Direction::Vertical,
        &[Constraint::Fixed(1), Constraint::Min(1)],
    );
    // FIX4: the sidebar Board view's own content area -- only ever the
    // full sidebar content rect (matching `spaces`/`agents`'s own
    // Activity-presentation convention just above), and only while the
    // rail even has a Board button to have activated it from (`board_
    // view_active` cannot legitimately be true otherwise, see `App::
    // activate_board_view`'s own light-mode gate, but this stays
    // defensive about it -- the one place that decides what actually
    // renders/hit-tests should not trust an upstream invariant alone).
    let board_sidebar = if app.menu_placement == MenuPlacement::Sidebar
        && app.sidebar_presentation == SidebarPresentation::Activity
        && app.board_view_active
        && app.harness_kanban.enabled
    {
        sidebar_content
    } else {
        Rect::default()
    };
    let mut layout = LayoutRects {
        activity_rail,
        sixel_icons: Vec::new(),
        pet_arcade_pixel_frame: None,
        overlays: Vec::new(),
        spaces,
        agents,
        board_sidebar,
        tabs: right[0],
        viewport: right[1],
        control_content: Rect::default(),
        control_modal: Rect::default(),
        spawn_modal: Rect::default(),
        existing_session_modal: Rect::default(),
        add_space_modal: Rect::default(),
        folder_browser_modal: Rect::default(),
        create_worktree_modal: Rect::default(),
        create_workspace_entry_modal: Rect::default(),
        remove_worktree_modal: Rect::default(),
        rename_session_modal: Rect::default(),
        task_id_modal: Rect::default(),
        forget_session_modal: Rect::default(),
        history_modal: Rect::default(),
        status_bar_left_modal: Rect::default(),
        status_bar_center_modal: Rect::default(),
        status_bar_right_modal: Rect::default(),
        harness_reverse_attribution_modal: Rect::default(),
        pet_arcade_modal: Rect::default(),
        pet_arcade_info_modal: Rect::default(),
        pet_arcade_menu: Rect::default(),
        status_bar_center_log_body: Rect::default(),
        status_bar_left: Rect::default(),
        status_bar_center: Rect::default(),
        status_bar_right: Rect::default(),
        global_search_field: Rect::default(),
        global_search_anchor: Rect::default(),
        global_search_dropdown: Rect::default(),
        surface_panes: Vec::new(),
        hits: Vec::new(),
    };

    if app.menu_placement == MenuPlacement::Sidebar
        && app.sidebar_presentation == SidebarPresentation::Split
    {
        Paragraph::new("")
            .style(Style::default().bg(theme.panel))
            .render(sidebar_content, buf);
        let x = sidebar_content.right();
        for y in sidebar_content.y..sidebar_content.bottom() {
            let cell = buf.get_mut(x, y);
            cell.symbol = "│".into();
            cell.style = Style::default().fg(theme.border).bg(theme.panel);
        }
        render_inspector(app, spaces, buf, &mut layout, theme);
        render_roster(app, agents, buf, &mut layout, theme);
        layout.hits.push(HitRegion {
            rect: Rect::new(sidebar_content.right(), sidebar_content.y, 1, sidebar_content.height),
            target: HitTarget::SidebarWidthDrag,
        });
        layout.hits.push(HitRegion {
            rect: Rect::new(agents.x, agents.y, agents.width, 1),
            target: HitTarget::SidebarSplitDrag,
        });
    } else if app.menu_placement == MenuPlacement::Sidebar {
        render_activity_rail(app, activity_rail, buf, &mut layout, theme);
        if !app.sidebar_collapsed && sidebar_content.width > 0 {
            Paragraph::new("")
                .style(Style::default().bg(theme.panel))
                .render(sidebar_content, buf);
            // FIX2/FIX4: the Board sidebar view reads `board_view_active`
            // FIRST, the same single piece of state `render_activity_
            // rail` now derives every button's `selected` from -- see
            // that field's own doc comment. `control_section` keeps
            // whatever it last held while Board is showing (Board is
            // deliberately not one of its variants), so it must never be
            // consulted here until this check has already ruled Board
            // out.
            if app.board_view_active && app.harness_kanban.enabled {
                render_agent_board_sidebar(app, sidebar_content, buf, &mut layout, theme);
            } else {
                match app.control_section {
                    ControlSection::Files => {
                        render_workspace_files(app, spaces, buf, &mut layout, theme)
                    }
                    ControlSection::Git => {
                        render_workspace_git(app, spaces, buf, &mut layout, theme)
                    }
                    ControlSection::Agents | ControlSection::Workspaces => match app.roster_mode {
                        RosterMode::Agents | RosterMode::NativeSessions => {
                            render_agents_surface(app, agents, buf, &mut layout, theme)
                        }
                        RosterMode::Workspaces => render_space_list(app, agents, buf, &mut layout, theme),
                    },
                    ControlSection::Settings => {}
                }
            }
            let divider_x = sidebar_content.right().saturating_sub(1);
            for y in sidebar_content.y..sidebar_content.bottom() {
                let cell = buf.get_mut(divider_x, y);
                cell.symbol = "│".into();
                cell.style = Style::default().fg(theme.border).bg(theme.panel);
            }
            layout.hits.push(HitRegion {
                rect: Rect::new(divider_x, sidebar_content.y, 1, sidebar_content.height),
                target: HitTarget::SidebarWidthDrag,
            });
        }
    }
    render_tabs(app, right[0], buf, &mut layout, theme);
    render_surface(app, right[1], buf, &mut layout, theme);
    render_status_bar(app, full_area, buf, &mut layout, theme);

    // The global search's own results dropdown paints HERE, not from
    // inside `render_tabs` above (where `render_global_search` computes
    // its anchor) -- it must run AFTER `render_surface`, whose pane
    // chrome (`render_surface_pane_tabs`/`render_surface_toolbar`, both
    // called from `render_surface_pane`) `fill_rect`s its own header/
    // actions rows in `right[1]` unconditionally, every frame, and those
    // rows are exactly where this dropdown's own top border and first
    // content row land when it opens (`right[1]`'s own top row sits
    // directly under the tab strip the dropdown hangs from). Painting the
    // dropdown from `render_tabs`, before the surface ever ran, meant the
    // surface's very next pass silently erased it. Still runs BEFORE
    // every modal dialog below, so an open modal keeps winning over it,
    // exactly as before this fix -- see `LayoutRects::global_search_
    // anchor`'s own doc comment for why a recorded rect, not a changed
    // open condition, is what moved.
    if !layout.global_search_anchor.is_empty() {
        render_global_search_dropdown(app, layout.global_search_anchor, buf, &mut layout, theme);
    }

    if app.focus == Focus::Spawn {
        render_spawn(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::ExistingSession {
        render_existing_session(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::AddSpace {
        render_add_space(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::FolderBrowser {
        render_folder_browser(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::CreateWorkspaceEntry {
        render_create_workspace_entry(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::CreateWorktree {
        render_create_worktree(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::RemoveWorktree {
        render_remove_worktree(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::RenameSession {
        render_rename_session(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::TaskId {
        render_task_id(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::ForgetSession {
        render_forget_session(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::History {
        render_history(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::Settings {
        render_settings(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::StatusBarLeft {
        render_status_bar_left_modal(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::StatusBarCenter {
        render_status_bar_center_modal(app, area, buf, &mut layout, theme);
    }
    if app.focus == Focus::StatusBarRight {
        render_status_bar_right_modal(app, area, buf, &mut layout, theme);
    }
    if app.agent_menu.is_some() {
        render_agent_menu(app, area, buf, &mut layout, theme);
    }
    if app.native_session_menu.is_some() {
        render_native_session_menu(app, area, buf, &mut layout, theme);
    }
    if app.harness_kanban.reverse_attribution.is_some() {
        render_harness_reverse_attribution(app, area, buf, &mut layout, theme);
    }
    if app.profiler_overlay_open {
        render_profile_overlay(app, area, buf, &mut layout, theme);
    }
    if app.pet_arcade_open {
        render_pet_arcade(app, area, buf, &mut layout, theme);
        // Stacked ON TOP of the arcade modal itself, painted (and hit-
        // tested, and registered as an overlay -- `render_pet_arcade_info`'s
        // own doc comment) only while the owner has actually opened it
        // (`HitTarget::PetArcadeInfo`, the `?` key) -- see `App::close_
        // overlay_outside_click`'s own doc comment for why this check runs
        // ahead of everything else that could close the arcade underneath.
        if app.pet_arcade_info_open {
            render_pet_arcade_info(app, area, buf, &mut layout, theme);
        }
        // Same shape as the mechanics modal just above -- the run menu
        // popup is the OTHER thing stacked on top of the arcade modal,
        // and the two are mutually exclusive (`App::toggle_pet_arcade_
        // menu`/`click_pet_arcade`'s own `PetArcadeInfo` arm each close
        // the other).
        if app.pet_arcade_menu.is_some() {
            render_pet_arcade_menu(app, area, buf, &mut layout, theme);
        }
        // Owner: "если наводим на вариант и держим на нем допустим 2
        // секунды" -- painted last of the three so it always reads on
        // top, though in practice it and the two overlays just above are
        // mutually exclusive already (`App::hover`'s own doc comment:
        // hovering either of THEIR hit regions is never tooltip-eligible,
        // so `pet_arcade_hover` is already `None` whenever one is open).
        render_pet_arcade_tooltip(app, area, buf, &mut layout, theme);
    }
    render_drag_preview(app, area, buf, &layout, theme);
    if let Some(notice) = app.notice() {
        render_notice(notice, right[1], buf, theme);
    }
    render_context_usage_tooltip(app.context_usage_hover, area, buf, &layout, theme);
    drop_sixel_icons_covered_by_overlays(&mut layout);
    drop_pet_arcade_pixel_frame_if_covered(&mut layout);
    layout
}

/// Fixed width of the status bar's own LEFT zone -- see `app::STATUS_BAR_
/// LEFT_WIDTH`'s own doc comment for why this constant lives in `app.rs`
/// (the animation gate needs the exact same number with no `Rect` to
/// measure against).
const STATUS_BAR_LEFT_WIDTH: u16 = crate::app::STATUS_BAR_LEFT_WIDTH;
/// Fixed width of the status bar's own RIGHT (pet) zone -- see `app::
/// STATUS_BAR_RIGHT_WIDTH`'s own doc comment.
const STATUS_BAR_RIGHT_WIDTH: u16 = crate::app::STATUS_BAR_RIGHT_WIDTH;

/// Draws the bottom status bar into `full_area`'s own true last row (see
/// `render::render`'s own doc comment on why every other renderer in this
/// module reads the SHRUNK `area` instead): three zones, LEFT and RIGHT
/// fixed-width, CENTRE taking whatever is left. Each zone is a single
/// `HitTarget` covering its own whole rect -- clicking anywhere in a zone
/// opens that zone's own modal (`App::begin_status_bar_zone`), never a
/// finer-grained per-pixel target.
fn render_status_bar(
    app: &App,
    full_area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if full_area.height == 0 {
        return;
    }
    let row = Rect::new(full_area.x, full_area.bottom() - 1, full_area.width, 1);
    fill_rect(row, theme.panel, buf);
    let left_width = STATUS_BAR_LEFT_WIDTH.min(row.width);
    let right_width = STATUS_BAR_RIGHT_WIDTH.min(row.width.saturating_sub(left_width));
    let center_width = row
        .width
        .saturating_sub(left_width)
        .saturating_sub(right_width);
    let left = Rect::new(row.x, row.y, left_width, 1);
    let center = Rect::new(left.right(), row.y, center_width, 1);
    let right = Rect::new(center.right(), row.y, right_width, 1);
    render_status_bar_left(app, left, buf, theme);
    render_status_bar_center(app, center, buf, theme);
    render_status_bar_right(app, right, buf, theme);
    layout.status_bar_left = left;
    layout.status_bar_center = center;
    layout.status_bar_right = right;
    if left.width > 0 {
        layout.hits.push(HitRegion { rect: left, target: HitTarget::StatusBarLeft });
    }
    if center.width > 0 {
        layout.hits.push(HitRegion { rect: center, target: HitTarget::StatusBarCenter });
    }
    if right.width > 0 {
        layout.hits.push(HitRegion { rect: right, target: HitTarget::StatusBarRight });
    }
}

fn status_bar_network_label(summary: NetworkSummary, theme: Theme) -> (&'static str, Color) {
    match summary {
        NetworkSummary::NoNodes => ("no nodes", theme.muted),
        NetworkSummary::Connected => ("connected", theme.green),
        NetworkSummary::Transitioning => ("connecting", theme.yellow),
        NetworkSummary::Disconnected => ("disconnected", theme.red),
    }
}

/// Reads a free-running wall-clock millisecond value directly -- section
/// 1.7's own requirement ("does not advance a frame counter or accumulate
/// an elapsed-time delta of its own"). Feeds BOTH the shimmer's own 72ms
/// tick (`shimmer::shimmer_tick_for_millis`) and the pet's own blink
/// phase -- there is no separate frame-counter clock anywhere in this
/// pairing.
fn wall_clock_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|elapsed| elapsed.as_millis() as u64)
        .unwrap_or(0)
}

/// Pads (with trailing spaces) or truncates `text` to EXACTLY `width`
/// `char`s -- the engine's grid is one `char` per cell with no double-width
/// concept at all (a real, separate gap from `color_to_rgb`'s own: see
/// this crate's own slice B report), so this is only exact for the
/// single-width ASCII content the clock/pet slots actually ever hold
/// (digits, `:`, `[`/`]`, the pet's own single-width figure glyphs) --
/// exactly what `truncate_cells`/`cell_width` already assumed at this
/// call site before the engine existed.
fn pad_chars_to_width(text: &str, width: usize) -> Vec<char> {
    let mut chars: Vec<char> = text.chars().collect();
    chars.resize(width, ' ');
    chars
}

/// The pointer's position local to `area` (section 1.4's own `cx`/`cy`),
/// clamped so a caller's own hit-test rounding can never underflow.
fn local_hover_coords(column: u16, row: u16, area: Rect) -> (u16, u16) {
    (column.saturating_sub(area.x), row.saturating_sub(area.y))
}

/// Paints one status-bar text slot (the LEFT clock or the RIGHT pet's
/// face row). `chars` must already be fit/padded to EXACTLY `area.width`
/// (see [`pad_chars_to_width`]), index 0 = the slot's own leftmost cell.
/// `hover_local`, when `Some`, is the pointer's position local to `area`
/// (section 1.4's `cx`/`cy`) -- every ASCII-alphanumeric character whose
/// cell falls inside the brush is re-rolled through `shimmer::apply_
/// shimmer_char` before painting; `None` paints `chars` completely
/// unchanged, so the effect reverts the instant the pointer leaves
/// (section 1.2's own "immediately and completely", no settle phase).
///
/// These cells are written STRAIGHT INTO THE BUFFER, deliberately, and
/// not through the ASCII cell-shader engine, even though routing them
/// through it was the shape this slice was first built to. The engine's
/// cell colour is three absolute sRGB channels with no reset, no named
/// and no indexed variant, and its blit emits a truecolour SGR
/// unconditionally, with no capability detection and no fallback. This
/// app's default colour mode INHERITS the terminal's own palette, which
/// is exactly what an absolute channel value cannot express -- there is
/// no honest approximation of "whatever this terminal calls default",
/// because a terminal never tells a program what that is. Routed through
/// the engine, the clock and the pet stopped following the terminal
/// theme and started emitting truecolour on terminals that may not have
/// it.
///
/// The engine bought nothing in exchange: the shader it was given was a
/// pure echo of a `char` and a colour this function had already decided,
/// so the whole per-cell shading model was doing no shading. The shimmer
/// is a pure function of index, tick and pointer position (`shimmer`,
/// which has no engine dependency at all), and it only ever substitutes
/// GLYPHS -- it never touches colour -- so nothing about the effect
/// needed the engine either.
///
/// The engine stays linked (the `ascii` feature is on) for the thing it
/// is actually good at: a panel that genuinely computes a colour per
/// cell per frame, where naming absolute channels is the point rather
/// than the cost.
fn render_status_bar_slot(
    mut chars: Vec<char>,
    color: Color,
    area: Rect,
    buf: &mut TerminalBuffer,
    hover_local: Option<(u16, u16)>,
) {
    if area.width == 0 {
        return;
    }
    let now_millis = wall_clock_millis();
    if let Some((cursor_column, cursor_row)) = hover_local {
        let tick = shimmer::shimmer_tick_for_millis(now_millis);
        let cursor_col = f64::from(cursor_column);
        let cursor_row = f64::from(cursor_row);
        for (index, ch) in chars.iter_mut().enumerate() {
            *ch = shimmer::apply_shimmer_char(*ch, index, cursor_col, cursor_row, tick);
        }
    }
    let style = Style::default().fg(color).bg(Color::Reset);
    for (index, ch) in chars.into_iter().enumerate() {
        let Ok(offset) = u16::try_from(index) else { break };
        if offset >= area.width {
            break;
        }
        let cell = buf.get_mut(area.x + offset, area.y);
        cell.symbol = ch.to_string().into();
        cell.style = style;
    }
}

/// The clock is painted across the WHOLE zone width -- slice A's own
/// network-status dot is gone from this zone entirely (owner instruction,
/// slice B item 5: the RIGHT zone's pet is now the app's only status-bar
/// connection indicator, see `app::pet_connection_color_key`'s own doc
/// comment); the full network word still lives one click away in this
/// zone's own modal (`render_status_bar_left_modal`), unchanged. Routed
/// through the engine (`render_status_bar_slot`) rather than a plain
/// `Paragraph`, with the hover shimmer applied when `App::status_bar_hover`
/// names this zone.
fn render_status_bar_left(app: &App, area: Rect, buf: &mut TerminalBuffer, theme: Theme) {
    if area.width == 0 {
        return;
    }
    let width = area.width as usize;
    let clock_text = format!(" {} ", app.clock_text());
    let clock_rendered = truncate_cells(&clock_text, width);
    let chars = pad_chars_to_width(&clock_rendered, width);
    let hover_local = app
        .status_bar_hover
        .filter(|hover| hover.zone == StatusBarHoverZone::Left)
        .map(|hover| local_hover_coords(hover.column, hover.row, area));
    render_status_bar_slot(chars, theme.text, area, buf, hover_local);
}

/// The CENTRE zone's own event strip: while `App::marquee_enabled` is
/// false, or nothing is currently playing (`App::event_current` is
/// `None`), this stays blank -- the on/off setting and the retained log
/// both live in `render_status_bar_center_modal`, one click away. Plays
/// the current `AppEvent`'s own text across the zone EXACTLY ONCE (`App::
/// event_strip_display` clamps its own scroll position rather than
/// wrapping it), then rests blank again until `App::advance_event_strip`
/// hands it the next queued event. Not one of the two shimmer/engine slots
/// (only the clock and the pet are, per slice B's own scope).
fn render_status_bar_center(app: &App, area: Rect, buf: &mut TerminalBuffer, theme: Theme) {
    if area.width == 0 || !app.marquee_enabled {
        return;
    }
    let Some(display) = app.event_strip_display(area.width) else {
        return;
    };
    Paragraph::new(display)
        .style(Style::default().fg(theme.muted).bg(theme.panel))
        .render(area, buf);
}

/// Colour-codes an `AppEvent` by its own `EventSeverity` for the CENTRE
/// zone modal's retained-log rows (`render_status_bar_center_modal`) --
/// the strip above it stays severity-neutral (`theme.muted`), same as the
/// old marquee always was; only the retained log a person actually reads
/// back gets the distinction.
fn event_severity_color(severity: EventSeverity, theme: Theme) -> Color {
    match severity {
        EventSeverity::Info => theme.green,
        EventSeverity::Warn => theme.yellow,
        EventSeverity::Error => theme.red,
    }
}

/// The RIGHT zone's own live ASCII pet -- see `docs/gate4agent/research/
/// hover-shimmer-and-animated-pet-spec-2026-08-24.md` section 2. Disabled
/// (`!App::pet_settings.enabled`) leaves the zone blank, the same
/// convention `render_status_bar_center` already uses for a disabled
/// marquee. The pet ALSO carries this app's connection state now (owner
/// instruction, slice B item 5): its colour is `app::
/// pet_connection_color_key(app.network_summary())`, and its face is
/// pinned to its own resting frame (blink suspended) whenever the network
/// summary is anything but `Connected` (`app::
/// pet_blink_suspended_for_connection`) -- a disconnected/unsettled pet
/// visibly stops "living," a connected one blinks normally. Hovering the
/// pet's own slot overrides both the blink-suspend AND the ordinary blink
/// cycle with the figure's own "looking at you" last frame (section 2.4),
/// and, like the clock, is routed through the engine with the hover
/// shimmer applied on top.
fn render_status_bar_right(app: &App, area: Rect, buf: &mut TerminalBuffer, theme: Theme) {
    if area.width == 0 || !app.pet_settings.enabled {
        return;
    }
    let width = area.width as usize;
    let network = app.network_summary();
    let color = pet_theme_color(pet_connection_color_key(network), theme);
    let figure = app.pet_settings.figure;
    let face_width = figure.face_width();
    let hovered = app
        .status_bar_hover
        .is_some_and(|hover| hover.zone == StatusBarHoverZone::Right);
    let frame_index = if hovered {
        figure.hover_frame_index()
    } else if pet_blink_suspended_for_connection(network) {
        0
    } else {
        figure.blink_frame_index(wall_clock_millis())
    };
    let face = centered_label(figure.frames()[frame_index], face_width);
    let mut chars = vec![' '; width];
    let room = width.saturating_sub(face_width);
    let x = app.pet_motion.x.round().clamp(0.0, room as f64) as usize;
    for (offset, ch) in face.chars().enumerate() {
        if x + offset < width {
            chars[x + offset] = ch;
        }
    }
    let hover_local = app
        .status_bar_hover
        .filter(|hover| hover.zone == StatusBarHoverZone::Right)
        .map(|hover| local_hover_coords(hover.column, hover.row, area));
    render_status_bar_slot(chars, color, area, buf, hover_local);
}

fn pet_theme_color(key: PetConnectionColor, theme: Theme) -> Color {
    match key {
        PetConnectionColor::Muted => theme.muted,
        PetConnectionColor::Green => theme.green,
        PetConnectionColor::Yellow => theme.yellow,
        PetConnectionColor::Red => theme.red,
    }
}

/// Row layout inside `render_status_bar_left_modal`'s own `inner` rect --
/// named so the height arithmetic and the row-by-row painting below can
/// never drift apart. Slice A adds the five clock rows (0..=4) and a
/// blank separator (5) ahead of the network content this modal already
/// had (`summary` used to be row 0, the per-node list row 2 -- both moved
/// down to make room, nothing about their OWN shape changed).
const CLOCK_MODAL_FOLLOW_ROW: u16 = 0;
const CLOCK_MODAL_SYSTEM_ROW: u16 = 1;
const CLOCK_MODAL_OFFSET_ROW: u16 = 2;
const CLOCK_MODAL_USE_24H_ROW: u16 = 3;
const CLOCK_MODAL_UTC_PREFIX_ROW: u16 = 4;
const CLOCK_MODAL_NETWORK_SUMMARY_ROW: u16 = 6;
const CLOCK_MODAL_NODES_START_ROW: u16 = 8;
/// Smallest this modal can ever need: the 8 rows through `CLOCK_MODAL_
/// NODES_START_ROW` plus at least 1 node row (`app.nodes.is_empty()`
/// still paints a "no nodes registered" line at that same row) plus 2
/// border rows.
const CLOCK_MODAL_MIN_HEIGHT: u16 = CLOCK_MODAL_NODES_START_ROW + 1 + 2;

/// Safe replacement for a bare `.clamp(floor, available)`: `u16::clamp`
/// panics if its own two bounds are inverted, which a pathologically
/// short terminal (`available < floor`) would trigger. `desired` still
/// shrinks to fit `available` exactly like a plain clamp would whenever
/// `available >= floor` (the overwhelming common case); only when the
/// terminal is shorter than `floor` itself does this diverge, returning
/// `floor` (letting the dialog run slightly past the bottom edge) rather
/// than panicking the whole render.
fn clamp_modal_dimension(desired: u16, floor: u16, available: u16) -> u16 {
    desired.min(available.max(floor)).max(floor)
}

fn render_status_bar_left_modal(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let node_rows = (app.nodes.len() as u16).max(1);
    let desired_height = CLOCK_MODAL_NODES_START_ROW + node_rows + 2;
    let width = 48.min(area.width.saturating_sub(4));
    let height = clamp_modal_dimension(desired_height, CLOCK_MODAL_MIN_HEIGHT, area.height.saturating_sub(2));
    let dialog = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::StatusBarLeft).copied());
    layout.status_bar_left_modal = dialog;
    layout.note_overlay(dialog);
    fill_rect(dialog, theme.modal, buf);
    Block::bordered()
        .title(" clock & network ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dialog, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(dialog.x, dialog.y, dialog.width, 1),
        target: HitTarget::StatusBarLeftDrag,
    });
    render_modal_close(dialog, buf, layout, theme);
    if dialog.width < 3 || dialog.height < 3 {
        return;
    }
    let inner = Rect::new(dialog.x + 1, dialog.y + 1, dialog.width - 2, dialog.height - 2);

    let settings = app.clock_settings;
    let follow_label = if settings.follow_system {
        "[x] follow system time"
    } else {
        "[ ] follow system time"
    };
    render_modal_line(
        follow_label,
        inner,
        CLOCK_MODAL_FOLLOW_ROW,
        Style::default().fg(theme.text).bg(theme.modal),
        buf,
    );
    push_modal_hit(layout, modal_row(inner, CLOCK_MODAL_FOLLOW_ROW), HitTarget::StatusBarClockFollowSystem);

    let system_label = match app.system_clock_offset_hours() {
        Some(hours) => format!("system: {}", clock_offset_label(hours)),
        None => "system: unknown".to_owned(),
    };
    render_modal_line(
        system_label,
        inner,
        CLOCK_MODAL_SYSTEM_ROW,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );

    let offset_row = modal_row(inner, CLOCK_MODAL_OFFSET_ROW);
    if offset_row.height > 0 {
        let mut x = render_toolbar_segment(
            "[<]",
            offset_row.x,
            offset_row,
            Style::default().fg(theme.teal).bg(theme.modal),
            Some(HitTarget::StatusBarClockOffsetPrevious),
            buf,
            layout,
        )
        .saturating_add(1);
        let label = format!(" {} ", clock_offset_label(settings.manual_offset_hours));
        let label_width = (cell_width(&label) as u16).min(offset_row.right().saturating_sub(x));
        if label_width > 0 {
            Paragraph::new(truncate_cells(&label, label_width as usize))
                .style(Style::default().fg(theme.text).bg(theme.modal))
                .render(Rect::new(x, offset_row.y, label_width, 1), buf);
        }
        x = x.saturating_add(label_width);
        render_toolbar_segment(
            "[>]",
            x,
            offset_row,
            Style::default().fg(theme.teal).bg(theme.modal),
            Some(HitTarget::StatusBarClockOffsetNext),
            buf,
            layout,
        );
    }

    let use_24h_label = if settings.use_24h { "[x] 24-hour clock" } else { "[ ] 24-hour clock" };
    render_modal_line(
        use_24h_label,
        inner,
        CLOCK_MODAL_USE_24H_ROW,
        Style::default().fg(theme.text).bg(theme.modal),
        buf,
    );
    push_modal_hit(layout, modal_row(inner, CLOCK_MODAL_USE_24H_ROW), HitTarget::StatusBarClockUse24h);

    let utc_prefix_label = if settings.show_utc_prefix {
        "[x] show UTC prefix"
    } else {
        "[ ] show UTC prefix"
    };
    render_modal_line(
        utc_prefix_label,
        inner,
        CLOCK_MODAL_UTC_PREFIX_ROW,
        Style::default().fg(theme.text).bg(theme.modal),
        buf,
    );
    push_modal_hit(layout, modal_row(inner, CLOCK_MODAL_UTC_PREFIX_ROW), HitTarget::StatusBarClockShowUtcPrefix);

    let (label, color) = status_bar_network_label(app.network_summary(), theme);
    render_modal_line(
        format!("summary: {label}"),
        inner,
        CLOCK_MODAL_NETWORK_SUMMARY_ROW,
        Style::default().fg(color).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    if app.nodes.is_empty() {
        render_modal_line(
            "no nodes registered",
            inner,
            CLOCK_MODAL_NODES_START_ROW,
            Style::default().fg(theme.muted).bg(theme.modal),
            buf,
        );
    } else {
        for (row, node) in app.nodes.iter().enumerate() {
            let (node_label, node_color) = status_bar_network_label(node_connection_summary(node), theme);
            render_modal_line(
                format!("{} -- {node_label}", node.node_id),
                inner,
                CLOCK_MODAL_NODES_START_ROW + row as u16,
                Style::default().fg(node_color).bg(theme.modal),
                buf,
            );
        }
    }
}

fn node_connection_summary(node: &NodeView) -> NetworkSummary {
    match node.connection {
        ConnectionState::Connected => NetworkSummary::Connected,
        ConnectionState::Connecting | ConnectionState::Resyncing => NetworkSummary::Transitioning,
        ConnectionState::Disconnected(_) => NetworkSummary::Disconnected,
    }
}

/// The CENTRE zone's own modal -- the strip's on/off toggle (unchanged),
/// plus (new, replacing the old static and already-inaccurate description
/// line) the retained event log itself: newest first, scrollable with the
/// same `[Up]`/`[Down]` toolbar-segment convention `render_harness_task_
/// detail_run_monitor` already uses for its own scrollable section, each
/// row coloured by severity (`event_severity_color`) and carrying its own
/// captured time (`App::event_log_line`). A taller default size than the
/// old six-row modal -- a log view needs real height to be worth opening.
fn render_status_bar_center_modal(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let width = 64.min(area.width.saturating_sub(4));
    let height = 18.min(area.height.saturating_sub(2));
    let dialog = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::StatusBarCenter).copied());
    layout.status_bar_center_modal = dialog;
    // Cleared unconditionally up front, then overwritten with the real
    // rect only once this function reaches the entries loop below --
    // otherwise a terminal shrunk just past one of the size guards below
    // this point would leave a STALE, previous-frame rect here, letting a
    // click land inside a body that was not actually painted this frame.
    layout.status_bar_center_log_body = Rect::default();
    layout.note_overlay(dialog);
    fill_rect(dialog, theme.modal, buf);
    Block::bordered()
        .title(" marquee ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dialog, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(dialog.x, dialog.y, dialog.width, 1),
        target: HitTarget::StatusBarCenterDrag,
    });
    render_modal_close(dialog, buf, layout, theme);
    if dialog.width < 3 || dialog.height < 3 {
        return;
    }
    let inner = Rect::new(dialog.x + 1, dialog.y + 1, dialog.width - 2, dialog.height - 2);
    let toggle_label = if app.marquee_enabled { "[x] marquee enabled" } else { "[ ] marquee enabled" };
    render_modal_line(
        toggle_label,
        inner,
        0,
        Style::default().fg(theme.text).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    push_modal_hit(layout, modal_row(inner, 0), HitTarget::StatusBarMarqueeToggle);
    if inner.height < 4 {
        return;
    }
    let entries: Vec<&AppEvent> = app.event_log.iter().rev().collect();
    let capacity = inner.height.saturating_sub(3) as usize;
    let offset = app.event_log_scroll.min(entries.len().saturating_sub(capacity.max(1)));
    let end = offset.saturating_add(capacity).min(entries.len());
    // The log body's own rect -- see `LayoutRects::status_bar_center_log_
    // body`'s own doc comment. Recorded even for an empty log (nothing
    // paints there yet, but a press still lands somewhere sensible once
    // the first event arrives) rather than only once `entries` is
    // non-empty, so `App::click_status_bar_zone`'s guard sees the SAME
    // rect this renderer just used to lay the rows out.
    layout.status_bar_center_log_body = Rect::new(inner.x, inner.y + 2, inner.width, capacity as u16);
    let controls_row = Rect::new(inner.x, inner.y + 1, inner.width, 1);
    let mut x = controls_row.x;
    x = render_toolbar_segment(
        "[Up]",
        x,
        controls_row,
        Style::default().fg(if offset > 0 { theme.teal } else { theme.muted }).bg(theme.modal),
        (offset > 0).then_some(HitTarget::StatusBarCenterLogScrollUp),
        buf,
        layout,
    ).saturating_add(1);
    let more = entries.len().saturating_sub(end);
    x = render_toolbar_segment(
        "[Down]",
        x,
        controls_row,
        Style::default().fg(if more > 0 { theme.teal } else { theme.muted }).bg(theme.modal),
        (more > 0).then_some(HitTarget::StatusBarCenterLogScrollDown),
        buf,
        layout,
    ).saturating_add(1);
    x = render_toolbar_segment(
        "[Clear]",
        x,
        controls_row,
        Style::default().fg(if entries.is_empty() { theme.muted } else { theme.teal }).bg(theme.modal),
        (!entries.is_empty()).then_some(HitTarget::StatusBarCenterLogClear),
        buf,
        layout,
    ).saturating_add(1);
    let count = format!("{} entries", entries.len());
    Paragraph::new(truncate_cells(&count, controls_row.right().saturating_sub(x) as usize))
        .style(Style::default().fg(theme.muted).bg(theme.modal))
        .render(Rect::new(x, controls_row.y, controls_row.right().saturating_sub(x), 1), buf);
    if entries.is_empty() {
        render_modal_line(
            "no retained events yet",
            inner,
            2,
            Style::default().fg(theme.dim).bg(theme.modal),
            buf,
        );
    }
    // The same selection this row's line falls at, if any -- `App::
    // event_log_selection`'s own doc comment explains why this is a frozen
    // snapshot rather than something resynced every frame: the practical
    // effect here is that its own line numbering (`offset + row`, matching
    // how the snapshot text was built) can drift from what is CURRENTLY on
    // screen if new events arrived since the interaction that produced it.
    // That drift self-heals the next time a press or Ctrl+A rebuilds the
    // snapshot; it is not a correctness bug this renderer needs to chase.
    let selection = app.event_log_selection.as_ref();
    let selection_range = selection.and_then(|editor| editor.selection_range());
    for (row, event) in entries[offset..end].iter().enumerate() {
        let text = app.event_log_line(event);
        let base_style = Style::default().fg(event_severity_color(event.severity, theme)).bg(theme.modal);
        let line_start_byte = selection.and_then(|editor| editor.line_byte_start(offset + row));
        let Some(line_start_byte) = line_start_byte.filter(|_| selection_range.is_some()) else {
            render_modal_line(text, inner, 2 + row as u16, base_style, buf);
            continue;
        };
        let truncated = truncate_cells(&text, inner.width as usize);
        // Same per-character highlight recipe `render_workspace_file_tab_
        // rich` already uses for the file editor's own selection (`theme.
        // active_tab_text` on `theme.accent`) -- one look for "this text is
        // selected" across the crate, not a second invention for the log.
        let spans: Vec<Span> = truncated
            .char_indices()
            .map(|(byte_offset, character)| {
                let absolute = line_start_byte + byte_offset;
                let style = if file_byte_is_selected(selection_range.as_ref(), absolute) {
                    Style::default().fg(theme.active_tab_text).bg(theme.accent)
                } else {
                    base_style
                };
                Span::styled(character.to_string(), style)
            })
            .collect();
        Paragraph::new(Text::from_lines(vec![Line::from_spans(spans)]))
            .style(Style::default().bg(theme.modal))
            .render(Rect::new(inner.x, inner.y + 2 + row as u16, inner.width, 1), buf);
    }
    render_modal_line(
        "click, or m, toggles | Up/Down scrolls log | Esc close",
        inner,
        inner.height.saturating_sub(1),
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

fn render_status_bar_right_modal(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let width = 32.min(area.width.saturating_sub(4));
    let height = 4.min(area.height.saturating_sub(2));
    let dialog = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::StatusBarRight).copied());
    layout.status_bar_right_modal = dialog;
    layout.note_overlay(dialog);
    fill_rect(dialog, theme.modal, buf);
    Block::bordered()
        .title(" pet ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dialog, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(dialog.x, dialog.y, dialog.width, 1),
        target: HitTarget::StatusBarRightDrag,
    });
    render_modal_close(dialog, buf, layout, theme);
    if dialog.width < 3 || dialog.height < 3 {
        return;
    }
    let inner = Rect::new(dialog.x + 1, dialog.y + 1, dialog.width - 2, dialog.height - 2);
    render_modal_line(
        "Pet Bastion: Night Garden",
        inner,
        0,
        Style::default().fg(theme.text).bg(theme.modal),
        buf,
    );
    render_modal_line(
        "[Enter] play",
        inner,
        1,
        Style::default().fg(theme.accent).bg(theme.modal),
        buf,
    );
    push_modal_hit(layout, modal_row(inner, 1), HitTarget::PetArcadeLaunch);
}

/// The Pet Bastion arcade overlay itself -- opened from the small "pet"
/// status-bar modal's own `[Enter] play` row (`App::open_pet_arcade`),
/// closed by `Escape`, its own `[x]`, or a click outside its rect
/// (`App::close_pet_arcade`, reached through `App::reduce`/`App::click`'s
/// own top-priority gate ahead of every `Focus`-driven dispatch -- see
/// `App::reduce_pet_arcade`'s own doc comment).
///
/// Built through `positioned_modal`/`DragState::OverlayMove`
/// (`OverlayId::PetArcade`) like every other draggable modal in this
/// crate now -- this overlay used to be centered fresh every frame with no
/// drag of its own, over a sixel-re-emission concern that does not apply
/// to this crate's glyph-tier board (see `pet_arcade`'s own module doc
/// comment): dragging a glyph-tier board costs nothing beyond the ordinary
/// per-cell diff every other draggable modal already pays.
///
/// Size comes entirely from the engine's own sizing contract
/// (`PetArcade::negotiate_size`, backed by `GameEntry::min_modal_size`/
/// `preferred_modal_size`), never hardcoded here. Those two sizes describe
/// the game's own CONTENT area (board + HUD panel + header/hint rows --
/// see `gate4agent_arcade_pet_bastion::sim`'s own `GameEntry` impl doc for
/// the exact accounting), not this overlay's outer bordered rect, so the
/// border this fn draws is budgeted OUTSIDE what gets negotiated (`content_
/// budget` below reserves 2 cells on each axis before ever asking), and
/// `inner` below is exactly the negotiated size, never smaller. A terminal
/// with no room for even the minimum gets an honest "needs more room"
/// message instead of a clipped board.
///
/// # Screen cell <-> board tile
///
/// The board is painted by projecting a `BOARD_WIDTH x BOARD_HEIGHT`
/// `Surface` onto `dest` at `footprint` cells per tile (`GlyphBackend::
/// project`, from `gate4agent-arcade-engine`) -- tile `(tx, ty)`'s own
/// glyph lands at screen cell `(dest.x + tx * footprint.cells_w, dest.y +
/// ty * footprint.cells_h)`. Below, once that same `dest`/`footprint` pair
/// is computed, this fn walks every tile that arithmetic actually painted
/// and pushes ONE `HitTarget::PetArcadeTile(tx, ty)` hit region per tile,
/// covering exactly the `footprint.cells_w x 1` screen cells that tile's
/// own glyph occupies -- the SAME multiplication, not a second, inverted
/// copy of it. `App::click`/`PetArcade::click_tile` never need to convert
/// a screen coordinate back into a tile coordinate at all: `layout.hits`'s
/// own rect-contains-point scan (`App::click`) already did that lookup by
/// construction, the same way every other per-cell click target in this
/// crate (e.g. `HitTarget::FolderBrowserEntry`) already works.
///
/// # The pixel tier's own cached board background
///
/// [`PET_ARCADE_PIXEL_BACKGROUND`] is `gate4agent_arcade_engine::
/// build_background`'s own expensive one-time raster (ground/decor/
/// routes/pool/anchors/Heartseed), built exactly once, process-wide, from
/// `gate4agent_arcade_pet_bastion_render::terrain_surface()` -- NOT from
/// this fn's own live, per-snapshot `surface` (see that function's own doc
/// comment for why a live surface is the wrong input: a placed tower
/// replaces a decor tile's own `art`, which would otherwise make the
/// cached seed drift and force a rebuild on every placement). A
/// `LazyLock`, not a `background_seed`-checked cache kept in `PetArcade`,
/// because Pet Bastion's own board LAYOUT is a fixed constant
/// (`terrain_surface`'s own doc comment: "calling this twice... always
/// produces byte-identical output") -- there is no seed that could ever
/// actually change to invalidate against.
static PET_ARCADE_PIXEL_BACKGROUND: std::sync::LazyLock<BoardBackground> =
    std::sync::LazyLock::new(|| build_background(&terrain_surface()));

fn render_pet_arcade(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let arcade = app.pet_arcade.borrow();
    let content_budget = CellArea {
        width: area.width.saturating_sub(2),
        height: area.height.saturating_sub(2),
    };
    let Some(negotiated) = arcade.negotiate_size(content_budget) else {
        render_pet_arcade_too_small(area, buf, layout, theme, crate::pet_arcade::min_modal_size());
        return;
    };
    let modal = positioned_modal(
        area,
        negotiated.width + 2,
        negotiated.height + 2,
        app.overlay_positions.get(&OverlayId::PetArcade).copied(),
    );
    layout.pet_arcade_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .title(" Pet Bastion: Night Garden ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(modal.x, modal.y, modal.width, 1),
        target: HitTarget::PetArcadeDrag,
    });
    render_modal_close(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let inner = Rect::new(modal.x + 1, modal.y + 1, negotiated.width, negotiated.height);

    if let Some((outcome, _final_hash)) = arcade.results() {
        render_pet_arcade_results(outcome, inner, buf, layout, theme);
        return;
    }
    let Some(snapshot) = arcade.snapshot() else {
        render_modal_line(
            "starting...",
            inner,
            0,
            Style::default().fg(theme.muted).bg(theme.modal),
            buf,
        );
        return;
    };

    let preferred = crate::pet_arcade::preferred_modal_size();
    let footprint_w: u16 = if negotiated.width >= preferred.width { 2 } else { 1 };
    let footprint = TileFootprint { cells_w: footprint_w, cells_h: 1 };
    let board_w = (BOARD_WIDTH as u16 * footprint_w).min(inner.width);
    let board_h = (BOARD_HEIGHT as u16).min(inner.height);
    // Whether THIS frame's own negotiated size actually fits the pixel
    // tier's own fixed-scale board (`backend_pixel::PX_PER_CELL_W`/`_H`
    // assume a `28 * 2 = 56`-cell-wide, `14`-cell-tall board -- exactly
    // `footprint_w == 2`'s own full, unclamped `board_w`/`board_h`, see
    // `gate4agent-arcade`'s own `backend_pixel.rs` module doc comment for
    // the `20px`/cell-tile derivation this depends on). `footprint_w == 1`
    // (a narrow terminal/modal) is the one real, common reason to fall
    // back -- the structurally impossible "landed on the terminal's own
    // true last row" case `client::flush_pet_arcade_pixel_frame_into` also
    // guards is not repeated here: `area` (this fn's own outer bound) is
    // already one row short of the real terminal height (`render::render`'s
    // own status-bar reservation), so this modal can never reach it at all.
    let pixel_tier_fits = footprint_w == 2 && board_h == BOARD_HEIGHT as u16;

    // `inner.height` is guaranteed `>= BOARD_HEIGHT + 1` (the min-size
    // contract's own one reserved row -- `gate4agent-arcade-pet-bastion`'s
    // own `sim.rs::MIN_HINT_ROWS`/`PREFERRED_HINT_ROWS`, which this crate
    // cannot edit: that game crate is off-limits for this pass) --
    // `extra_rows` is therefore always at least 1. Owner report: the two
    // legend lines that row used to hold ("Click: tile select..." / "Tab
    // tile [ ] anchor...") were dead screen space nobody read -- deleted
    // outright (`render_pet_arcade_hints` is gone; the keyboard bindings it
    // described still work exactly as before, unlisted). The threshold this
    // row's own header used to need (`extra_rows >= 3`, so it never fought
    // the legend for room) drops to `>= 1` now that there is no legend left
    // to fight: `negotiate_size` never returns more than 3 extra rows
    // (`preferred_modal_size`'s own `BOARD_HEIGHT + PREFERRED_HEADER_ROWS +
    // PREFERRED_HINT_ROWS` ceiling), so this reclaims the freed row for the
    // header -- the board's OWN wave/phase/tier/info chrome -- every frame
    // the board renders at all, not just at the one exact size that used to
    // clear the old `>= 3` bar.
    let extra_rows = inner.height.saturating_sub(board_h);
    let header_h: u16 = if extra_rows >= 1 { 1 } else { 0 };
    let board_y = inner.y + header_h;

    if header_h > 0 {
        render_modal_line(
            &pet_arcade_header_line(&snapshot),
            inner,
            0,
            Style::default().fg(theme.text).bg(theme.modal),
            buf,
        );
        push_modal_hit(layout, modal_row(inner, 0), HitTarget::PetArcadeWaveInspect);
        // Pushed AFTER `PetArcadeWaveInspect` above, onto the SAME row --
        // `App::click`'s own hit scan is last-pushed-wins
        // (`.iter().rev().find(...)`), so a click on this button's own
        // few columns resolves here, and a click anywhere else on the
        // header row still falls through to the wave inspector, exactly
        // like every other "small button pushed after a full-row hit"
        // pattern in this crate (`render_modal_close`'s own doc comment).
        let tier_label = pet_arcade_tier_label(app.pet_arcade_visual_tier, pixel_tier_fits);
        let tier_label_w = cell_width(&tier_label) as u16;
        let tier_rect = Rect::new(
            inner.right().saturating_sub(tier_label_w).max(inner.x),
            inner.y,
            tier_label_w.min(inner.width),
            1,
        );
        render_modal_line(&tier_label, tier_rect, 0, Style::default().fg(theme.accent).bg(theme.modal), buf);
        push_modal_hit(layout, tier_rect, HitTarget::PetArcadeToggleTier);
        // The mechanics explainer's own launch control (`HitTarget::
        // PetArcadeInfo` -> `render_pet_arcade_info`) -- owner report:
        // Spark/rune/pet-anchor mechanics were nowhere in the interface at
        // all, keyboard or mouse. Sits directly left of the tier toggle on
        // this SAME header row rather than costing the HUD panel a row of
        // its own (that panel's own budget is already fully spoken for --
        // see `render_pet_arcade_hud`'s own doc comment), reachable by
        // mouse here and by the `?` key (`App::reduce_pet_arcade`).
        const INFO_LABEL: &str = "[?] Info";
        let info_label_w = cell_width(INFO_LABEL) as u16;
        let info_right = tier_rect.x.saturating_sub(1);
        let info_x = info_right.saturating_sub(info_label_w).max(inner.x);
        let info_width = info_right.saturating_sub(info_x).min(info_label_w);
        let info_rect = Rect::new(info_x, inner.y, info_width, 1);
        render_modal_line(INFO_LABEL, info_rect, 0, Style::default().fg(theme.accent).bg(theme.modal), buf);
        push_modal_hit(layout, info_rect, HitTarget::PetArcadeInfo);
        // The run menu's own launch control (`HitTarget::PetArcadeMenuToggle`
        // -> `render_pet_arcade_menu`) -- owner report: "не хватает
        // какого-то меню там, где можно рестарт сделать" -- the only
        // existing way to restart was the Results screen's own button,
        // unreachable while a run was still in progress. Sits directly
        // left of `[?] Info` on this SAME header row, same reasoning as
        // that button's own doc comment for why here and not the HUD
        // panel; reachable by mouse here and by the `n` key (`App::
        // reduce_pet_arcade`).
        const MENU_LABEL: &str = "[N] Menu";
        let menu_label_w = cell_width(MENU_LABEL) as u16;
        let menu_right = info_x.saturating_sub(1);
        let menu_x = menu_right.saturating_sub(menu_label_w).max(inner.x);
        let menu_width = menu_right.saturating_sub(menu_x).min(menu_label_w);
        let menu_rect = Rect::new(menu_x, inner.y, menu_width, 1);
        render_modal_line(MENU_LABEL, menu_rect, 0, Style::default().fg(theme.accent).bg(theme.modal), buf);
        push_modal_hit(layout, menu_rect, HitTarget::PetArcadeMenuToggle);
    }

    let dest = Rect::new(inner.x, board_y, board_w, board_h);
    let mut surface = snapshot_to_surface(&snapshot);
    // Painted BEFORE the cursor/anchor highlight just below, so the more
    // specific, actionable cursor state always wins visually on whichever
    // tile the two happen to overlap (`pet_arcade_highlight_cursor`
    // unconditionally overwrites `bg`, last write wins).
    pet_arcade_highlight_field_zones(&mut surface, &snapshot);
    pet_arcade_highlight_cursor(&mut surface, arcade.selected_tile(), arcade.selected_anchor());
    if let Some(DragState::PetArcadeTowerPlacement { kind, current_column, current_row, .. }) = &app.drag_state {
        let hovered = pet_arcade_drag_hovered_tile(*current_column, *current_row, dest, footprint_w);
        pet_arcade_highlight_buildable_tiles(&mut surface, &snapshot, *kind, hovered);
    }
    GlyphBackend.project(&surface, footprint, dest, buf, false, DirtyHint::Full);
    // The glyph backend paints every tile's own `bg`, including `None`
    // (blank board tiles -- void cells with no terrain/unit, the majority
    // of a 28x14 board whose real features are a thin route plus ten pads,
    // four anchors and the Heartseed) as `Color::Reset`
    // (`backend_glyph::paint_tile`'s own fallback). `Color::Reset` reaches
    // the real terminal as ITS OWN default background (typically plain
    // black), unconditionally overwriting the `theme.modal` fill this fn
    // already laid down under the whole modal a few lines up -- that reads
    // as a stark black rectangle where the board sits, with a visible seam
    // right where it meets the HUD panel's own `theme.modal` background,
    // and the board's own sparsely-populated bottom rows read as "empty"
    // for the exact same reason. Backfilling every still-`Reset` cell
    // inside `dest` with `theme.modal` here (host-side, AFTER the engine's
    // own paint pass) is the only fix available without editing
    // `gate4agent-arcade`'s own render crate: it never touches a cell that
    // carries a real terrain/unit `bg`, only the ones the backend left as
    // a literal "no colour of my own" marker.
    for row in dest.y..dest.bottom() {
        for col in dest.x..dest.right() {
            let cell = buf.get_mut(col, row);
            if cell.style.bg == Color::Reset {
                cell.style.bg = theme.modal;
            }
        }
    }
    for ty in 0..board_h {
        for tx in 0..BOARD_WIDTH as u16 {
            let cell_x = inner.x + tx * footprint_w;
            if cell_x + footprint_w > inner.x + board_w {
                break;
            }
            push_modal_hit(
                layout,
                Rect::new(cell_x, board_y + ty, footprint_w, 1),
                HitTarget::PetArcadeTile(tx as u8, ty as u8),
            );
        }
    }

    // The pixel tier: composes and sixel-encodes the SAME board, on top of
    // (never instead of) the glyph-tier paint above -- see `render::render`'s
    // own end-of-frame occlusion pass and `client::flush_pet_arcade_pixel_
    // frame_into`'s own doc comment for why the glyph board underneath is
    // the correct, always-visible fallback content whenever this placement
    // ends up dropped for a reason only known later (occluded by an
    // overlay opened afterward) or at flush time (the terminal's own last
    // row -- structurally unreachable here, see `pixel_tier_fits`'s own
    // doc comment, but still guarded defensively at the one place that
    // actually writes to the real terminal).
    if app.pet_arcade_visual_tier == PetArcadeVisualTier::Pixel && pixel_tier_fits {
        let (drag_kind, drag_cursor) = match &app.drag_state {
            Some(DragState::PetArcadeTowerPlacement { kind, current_column, current_row, .. }) => {
                (Some(*kind), Some((*current_column, *current_row)))
            }
            _ => (None, None),
        };
        // The SINGLE hovered tile every drag-time visual on this frame
        // agrees on -- the ghost sprite below, and the highlight stroke
        // `pet_arcade_pixel_highlight_strokes` draws for it -- so neither
        // can independently drift onto a different tile than the other
        // (see `pet_arcade::build_drag_state_at`'s own doc comment for why
        // there is exactly one tile worth asking about at all now).
        let hovered_tile = drag_cursor
            .and_then(|(column, row)| pet_arcade_drag_hovered_tile(column, row, dest, footprint_w));
        // `prev`/`curr` -- `arcade.presenter().previous()` is the last
        // TICK-BOUNDARY snapshot before `snapshot` (already fetched above
        // for the glyph tier); the two are exactly the pair `interp::
        // interpolated_dynamic_sprites` needs to lerp between (see
        // `pet_arcade::PetArcade::presenter`'s own doc comment for why
        // `snapshot` itself IS `presenter`'s own `curr`, so there is no
        // second live-runner query here). `alpha` is real wall-clock
        // progress since that last tick fired
        // (`pet_arcade::PetArcade::tick_alpha`), which is what actually
        // lets this redraw at up to 60Hz look smoother than the sim's own
        // unchanged 20Hz tick.
        let prev = arcade.presenter().previous();
        let alpha = arcade.tick_alpha(Instant::now());
        let mut dynamic = interpolated_dynamic_sprites(prev, &snapshot, alpha);
        // Combat visuals (projectiles, impact flashes, death bursts, Prism
        // chain arcs, splash rings, Link Burst pulses) -- `EffectsLayer`
        // ages against SIMULATED time, never a real wall-clock read, and
        // the index that simulated time counts from is `prev`'s, NOT
        // `snapshot`'s: `snapshot` here is `presenter`'s own `curr`, one
        // tick AHEAD of the interval this frame is actually drawing
        // (`prev -> snapshot` at `alpha`), and that interval is the tick
        // whose events were ingested with `born_at = sim_time(tick_index_
        // before, 0.0)` in `PetArcade::advance`. `interp::render_sim_time`
        // owns that rule for both this call site and `gate4agent-arcade-
        // preview`'s own sequence loop -- see its doc comment for what
        // aging by `curr`'s index instead actually costs (every trail
        // invisible, every flash and burst missing its own first tick).
        let now = render_sim_time(prev, &snapshot, alpha);
        let (effect_sprites, effect_strokes) = arcade.age_and_effect_sprites(now);
        dynamic.extend(effect_sprites);
        // Owner report: dragging a tower out of the palette carried a text
        // label at the cursor, never the tower itself ("пусть сюда
        // рисуется башня, а не тянется надпись"). `dynamic` is pushed into
        // `compose_frame` AFTER `strokes` below (`build_scene`'s own
        // paint order: strokes first, then every `dynamic` sprite on top --
        // see `gate4agent-arcade`'s own `backend_pixel::build_scene`), so a
        // ghost pushed here always paints OVER the buildable-tile outlines
        // `pet_arcade_pixel_highlight_strokes` draws for this exact same
        // drag, matching "over the lit legal cells that already highlight
        // today". `render_drag_preview`'s own `PetArcadeTowerPlacement` arm
        // keeps painting the glyph-tier text chip unchanged -- that tier has
        // no sprite engine to borrow a real tower image from, so it stays
        // exactly what it was.
        if let (Some(kind), Some((column, row))) = (drag_kind, drag_cursor) {
            if let Some(ghost) = pet_arcade_drag_ghost_sprite(kind, column, row, dest, footprint_w) {
                dynamic.push(ghost);
            }
        }
        let mut strokes = pet_arcade_pixel_highlight_strokes(
            &snapshot,
            arcade.selected_tile(),
            arcade.selected_anchor(),
            drag_kind.zip(hovered_tile),
        );
        strokes.extend(effect_strokes);
        let canvas = compose_frame(&PET_ARCADE_PIXEL_BACKGROUND, &surface, &dynamic, &strokes, drag_kind.is_some());
        if let PixelFrameOutput::Frame(frame) = encode_frame(&canvas, dest) {
            layout.pet_arcade_pixel_frame = Some(PetArcadePixelPlacement {
                rect: frame.rect,
                encoded: frame.encoded,
                overlays_before: layout.overlays.len(),
            });
        }
    }

    let hud_x = inner.x + board_w;
    let hud_w = inner.width.saturating_sub(board_w);
    if hud_w > 0 {
        let hud = Rect::new(hud_x, board_y, hud_w, board_h);
        render_pet_arcade_hud(&snapshot, &arcade, hud, buf, layout, theme);
    }

    // Owner report: the two legend lines that used to paint below the board
    // ("Click: tile select..." / "Tab tile [ ] anchor...") were dead screen
    // space nobody read -- deleted outright, along with `render_pet_arcade_
    // hints` itself. Every binding it once listed still works exactly as
    // before; a genuinely undiscoverable one now lives on the button that
    // does the same thing instead (`render_pet_arcade_hud`'s own doc
    // comment, the header's own `[?] Info` button just above). Whatever
    // rows this freed (`header_h`'s own doc comment above covers the one
    // this fn can actually reclaim) are simply left as the modal's own
    // plain background now, never a re-purposed legend.
}

/// Formats `numerator/denominator` as `whole.tenths` (one decimal digit,
/// rounded toward zero) using pure integer arithmetic -- this crate's own
/// "no floats in presentation code either" convention (`tower_stats_line`'s
/// own doc comment), taken one digit further than that fn's own whole-tile
/// truncation because [`render_pet_arcade_info`]'s own numbers (a 1.5-tile
/// Symbiosis radius, a 1.2s pet move) would otherwise round down to a
/// genuinely WRONG whole number, not merely a less precise one.
fn one_decimal(numerator: i64, denominator: i64) -> String {
    if denominator == 0 {
        return "0".to_owned();
    }
    let whole = numerator / denominator;
    let tenths = ((numerator % denominator) * 10) / denominator;
    format!("{whole}.{tenths}")
}

/// The hover-and-hold tooltip's own text for `target`, or `None` if
/// `target` is not one of the controls this covers. Owner report: "что
/// дают руны мне не очевидно ... было бы неплохо делать тултип с инфой,
/// если наводим на вариант и держим на нем допустим 2 секунды". This is
/// the ONE place that decides both "is this eligible at all" (`App::
/// hover`'s own doc comment calls this to decide whether to start/keep
/// the hold timer) and "what does it say" (`render_pet_arcade_tooltip`
/// calls this again, once the hold has actually elapsed, for the text to
/// paint) -- never two independently-maintained lists.
///
/// Covers, at minimum (owner's own ask, "давай сделаем такие же тултипы с
/// инфой на все"): the rune draft options, the tower palette entries, the
/// pet's own ability buttons (Pulse/Blink/Full Circuit/Move), the Pet
/// Charge draft options, the evolution choices, a placed tower (hovering
/// the board tile it stands on), a board tile's own field zone, the
/// [Space] Start Wave control, and the HUD's own top resource row. EVERY
/// number below is read from `gate4agent_arcade_pet_bastion::constants`
/// (or, for towers, `TowerKind::base_stats`/`effective_stats`, the SAME
/// calls `render_pet_arcade_hud`/`render_pet_arcade_context` already make)
/// at call time, never copied into a string literal -- the same
/// discipline `render_pet_arcade_info`'s own doc comment already states
/// for the mechanics modal.
///
/// `snapshot` is `None` for every control whose tooltip is a pure function
/// of the target alone (a rune, a tower kind, an ability button, an
/// evolution, a Pet Charge) -- the same fixture-free shape this fn already
/// had. `HitTarget::PetArcadeTile`, `PetArcadeResources` and
/// `PetArcadeStartWave` all need a LIVE snapshot to answer at all (a placed
/// tower's own level, a field zone, or the current Sap/Spark/Integrity/
/// wave number are all genuinely per-run state) and return `None` without
/// one -- exactly `App::hover`'s own `PetArcade::snapshot()` read, and
/// `Home`/`Results` (no live run) correctly have no tooltip for any of the
/// three either, matching the render side: none of the controls they cover
/// ever paints outside a live run in the first place (`render_pet_arcade`
/// returns before `render_pet_arcade_hud` ever runs without one).
pub(crate) fn pet_arcade_tooltip_text(target: &HitTarget, snapshot: Option<&SimulationSnapshot>) -> Option<String> {
    match target {
        HitTarget::PetArcadeDraftRune(rune) => Some(pet_arcade_rune_tooltip(*rune)),
        HitTarget::PetArcadeDraftPetCharge(charge) => Some(pet_arcade_pet_charge_tooltip(*charge)),
        HitTarget::PetArcadeTowerKind(kind) => Some(pet_arcade_tower_tooltip(*kind)),
        HitTarget::PetArcadePetPulse => Some(format!(
            "Pet Pulse -{PET_PULSE_COST} Spark: an AoE burst centred on the pet's own anchor, {} tiles, {PET_PULSE_DAMAGE} damage (+{}% as a Crab) and a knockback. Requires the pet be standing at an anchor.",
            one_decimal(PET_PULSE_RADIUS_FP, FIXED_SCALE),
            (CRAB_PET_PULSE_DAMAGE_PERMILLE - 1000) / 10,
        )),
        HitTarget::PetArcadeBlink => Some(format!(
            "Blink -{BLINK_COST} Spark: teleports the pet to the selected anchor instantly. Free every {}s as a Wisp.",
            WISP_FREE_BLINK_INTERVAL_TICKS / TICKS_PER_SECOND as u64,
        )),
        HitTarget::PetArcadeFullCircuit => Some(format!(
            "Full Circuit -{FULL_CIRCUIT_COST} Spark: for {}s, links EVERY attacking tower on the board, ignoring the normal anchor slot limit.",
            FULL_CIRCUIT_TICKS / TICKS_PER_SECOND as u64,
        )),
        HitTarget::PetArcadeMovePet => Some(format!(
            "Move Pet: walks the pet to the selected anchor, {}s on foot ({}s as a Moth). Free -- Blink is the instant, Spark-costing alternative.",
            one_decimal(PET_MOVE_TICKS as i64, TICKS_PER_SECOND),
            one_decimal(PET_MOVE_TICKS_MOTH as i64, TICKS_PER_SECOND),
        )),
        HitTarget::PetArcadeChooseEvolution(evolution) => Some(pet_arcade_evolution_tooltip(*evolution)),
        HitTarget::PetArcadeTile(x, y) => {
            let snapshot = snapshot?;
            let position = (i32::from(*x), i32::from(*y));
            let zone_text = field_zone_at(snapshot, *x, *y).map(pet_arcade_field_zone_tooltip);
            match snapshot.towers.iter().find(|tower| tower.position == position) {
                Some(tower) => {
                    let mut text = pet_arcade_placed_tower_tooltip(tower);
                    if let Some(zone_text) = zone_text {
                        text.push(' ');
                        text.push_str(&zone_text);
                    }
                    Some(text)
                }
                None => zone_text,
            }
        }
        HitTarget::PetArcadeResources => Some(pet_arcade_resources_tooltip(snapshot?)),
        HitTarget::PetArcadeStartWave => Some(pet_arcade_start_wave_tooltip(snapshot?)),
        _ => None,
    }
}

/// The [`FieldZoneView`] (if any) whose own `tile_bounds` covers board tile
/// `(x, y)` -- `snapshot.field_zones` is always 0 or 2 entries
/// (`SimulationSnapshot::field_zones`'s own doc comment), never more, so a
/// linear scan of it is exactly as cheap as an indexed lookup would be.
fn field_zone_at(snapshot: &SimulationSnapshot, x: u8, y: u8) -> Option<&FieldZoneView> {
    let (x, y) = (i32::from(x), i32::from(y));
    snapshot.field_zones.iter().find(|zone| {
        let (x0, y0, x1, y1) = zone.tile_bounds;
        x >= x0 && x < x1 && y >= y0 && y < y1
    })
}

/// A Pet Charge draft option's own tooltip -- same "attaches to:" spirit
/// the rune tooltips already use (`pet_arcade_rune_tooltip`'s own doc
/// comment), except every one of these four attaches to exactly the same
/// thing: whichever tower(s) the Living Circuit currently LINKS, never the
/// pet itself and never every tower on the board (`pet.rs`'s own
/// `PetCharge` doc comment; `sim.rs`'s own `fire_tower`/`adjusted_interval`
/// gate every one of the four behind `linked &&`). Moving the pet off an
/// anchor that used to link a tower a charge was buffing genuinely turns
/// that buff off for that tower -- "where do I put the pet" stays a live
/// decision even after a pick, which is worth stating plainly rather than
/// leaving the player to infer it.
fn pet_arcade_pet_charge_tooltip(charge: PetCharge) -> String {
    const ATTACHES: &str = "attaches to: every tower currently LINKED to the pet's own Circuit.";
    match charge {
        PetCharge::Surge => format!(
            "Surge -- {ATTACHES} An extra +{}% attack speed on top of the Circuit's own link bonus.",
            (PET_CHARGE_SURGE_EXTRA_SPEED_PERMILLE - 1000) / 10,
        ),
        PetCharge::Fang => format!("Fang -- {ATTACHES} +{}% damage.", PET_CHARGE_FANG_DAMAGE_PERMILLE / 10),
        PetCharge::Bloom => format!(
            "Bloom -- {ATTACHES} +{}% splash/chain reach, plus one extra target slot.",
            PET_CHARGE_BLOOM_RADIUS_PERMILLE / 10,
        ),
        PetCharge::Attune => format!(
            "Attune -- {ATTACHES} Its outgoing damage family rotates through every family instead of staying fixed -- the real answer to Mirror's own resistance."
        ),
    }
}

/// A field zone's own tooltip -- read straight off `zone.rs`'s own
/// `tower_damage_bonus_permille`/`enemy_speed_permille` sign rules: a
/// tower-damage Buff/Debuff is a flat +/-`ZONE_TOWER_DAMAGE_PERMILLE`, an
/// enemy-speed Buff makes an enemy/boss SLOWER (`1000 - ZONE_ENEMY_SPEED_
/// PERMILLE`, good for the player) and a Debuff makes it FASTER (`1000 +
/// ...`, bad) -- stated in plain SLOWER/FASTER words rather than a signed
/// permille a player would have to mentally invert.
fn pet_arcade_field_zone_tooltip(zone: &FieldZoneView) -> String {
    let tower_pct = ZONE_TOWER_DAMAGE_PERMILLE / 10;
    let speed_pct = one_decimal(ZONE_ENEMY_SPEED_PERMILLE, 10);
    match (zone.kind, zone.polarity) {
        (ZoneKind::TowerDamage, ZonePolarity::Buff) => {
            format!("Tower damage zone (buff): an attacking tower built inside this sector deals +{tower_pct}% damage.")
        }
        (ZoneKind::TowerDamage, ZonePolarity::Debuff) => {
            format!("Tower damage zone (debuff): an attacking tower built inside this sector deals -{tower_pct}% damage.")
        }
        (ZoneKind::EnemySpeed, ZonePolarity::Buff) => {
            format!("Enemy speed zone (buff): an enemy or boss inside this sector moves {speed_pct}% SLOWER.")
        }
        (ZoneKind::EnemySpeed, ZonePolarity::Debuff) => {
            format!("Enemy speed zone (debuff): an enemy or boss inside this sector moves {speed_pct}% FASTER.")
        }
    }
}

/// A rune's own tooltip -- answers the owner's own two questions in plain
/// words: what the rune does, and what it attaches to (the pet, one
/// tower, or every tower). Read straight off `sim.rs`'s own per-rune
/// checks (`fire_tower`'s own `world.runes.has(Rune::X)` gates, `pet.rs`'s
/// own `start_move`) -- see this fn's own per-arm comment for exactly
/// which lines of `sim.rs` each one traces to.
fn pet_arcade_rune_tooltip(rune: Rune) -> String {
    match rune {
        // `fire_tower`'s own `!is_echo_bonus && world.runes.has(Rune::Echo)
        // && world.towers[idx].attack_count % ECHO_EVERY_NTH_ATTACK == 0`
        // -- a GLOBAL check against whichever tower is firing, not scoped
        // to one placed tower: every tower on the board is eligible.
        Rune::Echo => format!(
            "Echo -- attaches to: every tower. Every {ECHO_EVERY_NTH_ATTACK}th attack from a tower, a same-kind tower on the board fires again for free."
        ),
        // `pet.rs`'s own `start_move`: when the pet leaves an anchor with
        // this rune, `self.lingering = Some((linked_before_move, ...))` --
        // `sim.rs`'s own `linked_towers_now` then keeps treating exactly
        // those towers (the ones linked at THAT anchor, not "every
        // tower") as linked for a few more seconds, on top of whatever is
        // linked at the new anchor. Genuinely a hybrid -- a pet-side
        // trigger, a tower-side effect on a moving subset -- so it is
        // described in its own terms rather than forced into "one" or
        // "every".
        Rune::Anchor => format!(
            "Anchor -- attaches to: the pet's own Circuit link. When the pet leaves an anchor, whichever towers were linked to it keep that link's attack-speed buff for {}s longer.",
            ANCHOR_RUNE_LINGER_TICKS / TICKS_PER_SECOND as u64,
        ),
        // `fire_tower`'s own `world.runes.has(Rune::Overgrowth)` gate on
        // the overkill carried from one chain/splash jump into the next --
        // global, any tower's own kill can trigger it.
        Rune::Overgrowth => "Overgrowth -- attaches to: every tower. A kill's own overkill damage carries into the next chain/splash target instead of being wasted."
            .to_owned(),
        // `fire_tower`'s own `world.runes.has(Rune::Phase) && world.towers
        // [idx].hit_count % PHASE_EVERY_NTH_HIT == 0` -- global, keyed off
        // each tower's own accumulating hit count, but the rule itself
        // applies uniformly to every tower.
        Rune::Phase => format!(
            "Phase -- attaches to: every tower. Every {PHASE_EVERY_NTH_HIT}rd hit from a tower ignores the target's armour."
        ),
        // `symbiosis_bonus_permille` -- global, checked for whichever
        // tower is currently firing, against every OTHER placed tower's
        // own position.
        Rune::Symbiosis => format!(
            "Symbiosis -- attaches to: every tower. A tower within {} tiles of a DIFFERENT kind deals +{}% damage.",
            one_decimal(SYMBIOSIS_ADJACENCY_FP, FIXED_SCALE),
            SYMBIOSIS_DAMAGE_BONUS_PERMILLE / 10,
        ),
    }
}

/// A tower palette entry's own tooltip -- kind, cost, and the SAME combat
/// summary the empty-tile context card already shows for it
/// (`render_pet_arcade_context`'s own `None` arm), reusing `tower_stats_
/// line`/`tower_stats_extras_line` rather than a second formatter.
fn pet_arcade_tower_tooltip(kind: TowerKind) -> String {
    let stats = effective_stats(kind, UpgradeLevel::Base);
    let mut text = format!("{} -{}: {}", tower_kind_label(kind), kind.base_stats().cost, tower_stats_line(&stats));
    if let Some(extras) = tower_stats_extras_line(&stats) {
        text.push_str(" (");
        text.push_str(&extras);
        text.push(')');
    }
    text
}

/// A PLACED tower's own tooltip (`HitTarget::PetArcadeTile`, hovered over
/// whichever board tile this tower actually stands on) -- its real current
/// level and combat summary (the SAME `tower_stats_line`/`tower_stats_
/// extras_line` the HUD's own selected-tower context card already shows on
/// CLICK, `render_pet_arcade_context`'s own `Some(tower)` arm), plus what
/// its own NEXT upgrade step would actually buy: real `tower::effective_
/// stats` at the resulting level, read the exact same way `tower.stats`
/// itself already is (`TowerView::stats`'s own doc comment: `tower::
/// effective_stats(kind, level)`), never a hand-described "gets stronger".
/// Owner report: "для башни в поле это должно отражать её реальный
/// уровень и что купит апгрейд".
///
/// `UpgradeLevel::L2`'s own next step is genuinely two branches
/// (`UpgradeBranch::Power`/`Utility`, `render_pet_arcade_context`'s own
/// `[P]`/`[O]` rows), at the SAME Sap cost either way (`tower::
/// next_upgrade_cost`'s own doc comment) -- both previews are shown side by
/// side rather than picking one arbitrarily, so hovering never hides which
/// branch this tower would actually gain.
fn pet_arcade_placed_tower_tooltip(tower: &TowerView) -> String {
    let mut text = format!(
        "{} L{} @{},{}: {}",
        tower_kind_label(tower.kind),
        upgrade_level_label(tower.level),
        tower.position.0,
        tower.position.1,
        tower_stats_line(&tower.stats),
    );
    if let Some(extras) = tower_stats_extras_line(&tower.stats) {
        text.push_str(" (");
        text.push_str(&extras);
        text.push(')');
    }
    match (tower.level, tower.next_upgrade_cost) {
        (_, None) => text.push_str(". Already at max level."),
        (UpgradeLevel::L2, Some(cost)) => {
            let power = effective_stats(tower.kind, UpgradeLevel::L3(UpgradeBranch::Power));
            let utility = effective_stats(tower.kind, UpgradeLevel::L3(UpgradeBranch::Utility));
            text.push_str(&format!(
                ". Next upgrade -{cost}: Power {} vs Utility {}",
                tower_stats_line(&power),
                tower_stats_line(&utility),
            ));
        }
        (_, Some(cost)) => {
            let preview = effective_stats(tower.kind, UpgradeLevel::L2);
            text.push_str(&format!(". Next upgrade -{cost}: {}", tower_stats_line(&preview)));
            if let Some(extras) = tower_stats_extras_line(&preview) {
                text.push_str(" (");
                text.push_str(&extras);
                text.push(')');
            }
        }
    }
    text
}

/// The HUD's own top resource row (`HitTarget::PetArcadeResources`,
/// `render_pet_arcade_hud`'s own row 0) -- the current live Sap/Spark/
/// Integrity readouts, plus what each one actually means and how it
/// moves: Spark's own per-kill earn rate and cap (`SPARK_PER_KILLS`,
/// `SPARK_CAP`, the SAME numbers the mechanics modal's own SPARK section
/// states), and Integrity's own per-leak cost (`LEAK_INTEGRITY_DAMAGE`,
/// `BOSS_LAP_INTEGRITY_DAMAGE`, the SAME numbers its own WAVES section
/// states). Owner report: the resource readouts were three bare numbers
/// with no explanation of what earns or spends any of them.
fn pet_arcade_resources_tooltip(snapshot: &SimulationSnapshot) -> String {
    format!(
        "Sap {}: spent placing and upgrading towers. Spark {}/{SPARK_CAP}: only a KILL by a tower currently linked to the pet earns it -- {SPARK_PER_KILLS} linked kills = +1 Spark, doubled during Night Maw's final phase. Integrity {}: the run ends in Defeat at 0 -- a leaked minion costs -{LEAK_INTEGRITY_DAMAGE}, a leaked boss lap costs -{BOSS_LAP_INTEGRITY_DAMAGE}.",
        snapshot.sap, snapshot.pet.spark, snapshot.integrity,
    )
}

/// The `[Space] Start Wave` control's own tooltip (`HitTarget::
/// PetArcadeStartWave`) -- what pressing it actually does (ends the Build
/// phase early, `PetArcade::can_start_wave`'s own doc comment) and the
/// wave-loop rule the mechanics modal's own WAVES section already states
/// in full (`pet_arcade_info_lines`' own doc comment): a unit reaching the
/// Heartseed is NOT killed, it loops back to its own route start and costs
/// Integrity per lap instead, and the wave only ends once every enemy on
/// it is genuinely dead -- worth restating right on the button that starts
/// that wave, not only in the mechanics reference a player may never open.
fn pet_arcade_start_wave_tooltip(snapshot: &SimulationSnapshot) -> String {
    format!(
        "Start Wave: ends the Build phase now and begins Wave {}/{WAVE_COUNT} combat immediately. A unit reaching the Heartseed is NOT killed -- it loops back to its own route start at full health and keeps walking, costing Integrity per lap instead: -{LEAK_INTEGRITY_DAMAGE} for a minion, -{BOSS_LAP_INTEGRITY_DAMAGE} for a boss. The wave only ends once every enemy on it is dead.",
        snapshot.wave,
    )
}

/// An evolution choice's own tooltip -- the trade-off it makes, in the
/// same "attaches to" spirit the runes use, since an evolution is a
/// permanent choice about how the pet's own Circuit link and movement
/// behave for the rest of the run. `Pet::base_slots`/`move_duration_
/// ticks`/`pet_pulse_damage`/`on_arrival_shield` (`pet.rs`) are this fn's
/// own source for every number.
fn pet_arcade_evolution_tooltip(evolution: Evolution) -> String {
    match evolution {
        Evolution::Moth => format!(
            "Moth: links {CIRCUIT_MOTH_SLOTS} towers instead of {CIRCUIT_BASE_SLOTS}, but moves {}s per hop instead of {}s.",
            one_decimal(PET_MOVE_TICKS_MOTH as i64, TICKS_PER_SECOND),
            one_decimal(PET_MOVE_TICKS as i64, TICKS_PER_SECOND),
        ),
        Evolution::Crab => format!(
            "Crab: gains a shield (+{CRAB_SHIELD_ON_ARRIVAL}, capped at {CRAB_SHIELD_CAP}) on arriving at an anchor, absorbing Integrity loss before it reaches Integrity itself. Pet Pulse deals +{}% damage.",
            (CRAB_PET_PULSE_DAMAGE_PERMILLE - 1000) / 10,
        ),
        Evolution::Wisp => format!(
            "Wisp: links only {CIRCUIT_WISP_SLOTS} towers, but Blink is free once every {}s.",
            WISP_FREE_BLINK_INTERVAL_TICKS / TICKS_PER_SECOND as u64,
        ),
    }
}

/// Whether [`render_pet_arcade_info`]'s own content needs a scrollbar at
/// all THIS frame, and the scroll offset actually usable once the raw,
/// unclamped `App::pet_arcade_info_scroll` request is clamped against
/// `total_lines`/`visible_rows`. Pulled out as its own pure fn so the
/// "a bar shows only once content genuinely overflows" boundary is
/// directly unit-testable against synthetic `(total_lines, visible_rows)`
/// pairs, without needing a real, artificially-shortened content list --
/// the REAL content (`pet_arcade_info_lines`) is 35 lines against a fixed
/// 14-row budget ([`PET_ARCADE_INFO_VISIBLE_ROWS`]) and so always
/// overflows today, which proves the bar SHOWS but not that it would stay
/// hidden if it did not.
fn pet_arcade_info_scroll_state(total_lines: u16, visible_rows: u16, requested_scroll: u16) -> (bool, u16) {
    let needs_scrollbar = total_lines > visible_rows;
    let max_scroll = total_lines.saturating_sub(visible_rows);
    (needs_scrollbar, requested_scroll.min(max_scroll))
}

/// The arcade's own mechanics reference -- everything the header's own
/// `[?] Info` button (`HitTarget::PetArcadeInfo`, `render_pet_arcade`'s own
/// header block) and the `?` key (`App::reduce_pet_arcade`) open;
/// `Escape`/`?`/its own `<-` (`render_modal_back`, not `[x]` -- see that
/// fn's own doc comment)/a click outside it all close it (`App::
/// close_overlay_outside_click`'s own `pet_arcade_info_open` branch, which
/// runs AHEAD of the arcade's own outside-click guard so this always
/// closes first, never the arcade underneath it). Owner report: "мне не
/// ясна механика траты спарков ... рун и какого-то светлячка которая
/// куда-то встает" -- Spark, runes and the pet's own anchor mechanic were
/// nowhere in the interface at all, and clicking a pet anchor silently
/// issuing `Command::MovePet` was not something the owner knew he was
/// doing. A WAVES section covers a follow-up the rules crate changed out
/// from under the UI: an enemy reaching the Heartseed is no longer killed
/// (it loops back to its own route start at full health and keeps
/// walking, costing Integrity per lap instead) and a wave no longer ends
/// on the first Heartseed arrival (only once every enemy on it is dead) --
/// both are silent rule changes the owner has no other way to learn.
///
/// EVERY number below is read from `gate4agent_arcade_pet_bastion::
/// constants` (this module's own import list at the top of the file) AT
/// RENDER TIME, never copied into a string literal here -- a number that
/// can drift out of sync with the sim it describes is worse than showing
/// no number at all. The two genuinely non-integer ones (Symbiosis' own
/// 1.5-tile radius, the pet's own 1.2s move) go through [`one_decimal`]
/// rather than truncating to a wrong whole number.
///
/// Stacked on top of the arcade modal (`render::render`'s own call site,
/// right after `render_pet_arcade`) and registered as its own overlay
/// (`layout.note_overlay`) so `render::drop_pet_arcade_pixel_frame_if_
/// covered` correctly drops that frame's own occluded pixel-tier board for
/// this one frame -- the glyph-tier board underneath (always painted
/// first regardless of visual tier, `render_pet_arcade`'s own doc comment)
/// is what actually shows through behind this card.
///
/// # Scrolling
///
/// Owner report: "если в механике инфа не влазит сделай скролбар, окно
/// скроллбары мы умеем делать внутри модалок" -- fixed at [`PET_ARCADE_
/// INFO_VISIBLE_ROWS`] tall (14) rather than growing to fit every line
/// (this content's own predecessor, back when it was 17 lines and just
/// barely fit; it is 22 now and will grow again), so this modal ALWAYS has
/// to scroll in practice today, exercising the mechanism every frame it
/// is open rather than only once the text happens to overflow some
/// terminal-dependent budget. Reuses `render_file_scrollbar`'s own track-
/// plus-thumb visual contract (`|` track, `#` thumb, the identical
/// proportional-sizing formula) rather than a second scrollbar mechanism
/// -- see [`render_pet_arcade_info_scrollbar`]'s own doc comment for why
/// that is a sibling fn, not a literal call to the file-specific one.
/// `app.pet_arcade_info_scroll` is the raw, UNCLAMPED offset `App::scroll`/
/// `reduce_pet_arcade` nudge -- clamped against this frame's own real
/// `total_lines`/`visible_rows` right here, the same "nudge there, clamp
/// here" split `board_sidebar_scroll`'s own doc comment already
/// establishes, so a content change (a rune added, a WAVES section landing)
/// can never leave a stale scroll position pointing past the end. The
/// scrollbar's own track claims exactly one column, taken from the text
/// body's own width, ONLY while `total_lines > visible_rows` -- content
/// that fits needs no bar and loses no width to one; content that
/// scrolls still gets the full, un-truncated text width `pet_arcade_info_
/// modal_never_truncates` already tests, just one column narrower.
fn render_pet_arcade_info(app: &App, area: Rect, buf: &mut TerminalBuffer, layout: &mut LayoutRects, theme: Theme) {
    let lines = pet_arcade_info_lines();
    let total_lines = lines.len() as u16;
    let visible_rows = PET_ARCADE_INFO_VISIBLE_ROWS.min(total_lines).max(1);
    let (needs_scrollbar, scroll) = pet_arcade_info_scroll_state(total_lines, visible_rows, app.pet_arcade_info_scroll);

    const WIDTH: u16 = 88;
    let height = visible_rows + 2;
    let modal = positioned_modal(area, WIDTH, height, None);
    layout.pet_arcade_info_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .title(" Mechanics ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    // Owner report: "ты сделал возврат из механики через Х, лучше сделай
    // через стрелочку <-, иначе не очевидно" -- see `render_modal_back`'s
    // own doc comment for why this paints `<-` in `render_modal_close`'s
    // exact corner spot rather than that fn's own `[x]`.
    render_modal_back(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let full_inner = Rect::new(modal.x + 1, modal.y + 1, modal.width - 2, modal.height - 2);
    let text_width = if needs_scrollbar { full_inner.width.saturating_sub(1) } else { full_inner.width };
    let text_area = Rect::new(full_inner.x, full_inner.y, text_width, full_inner.height);
    for (index, line) in lines.iter().enumerate().skip(scroll as usize).take(visible_rows as usize) {
        let Ok(row) = u16::try_from(index - scroll as usize) else { break };
        match line {
            PetArcadeInfoLine::Label(text) => {
                render_modal_line(*text, text_area, row, Style::default().fg(theme.accent).bg(theme.modal), buf)
            }
            PetArcadeInfoLine::Body(text) => {
                render_modal_line(text, text_area, row, Style::default().fg(theme.text).bg(theme.modal), buf)
            }
        }
    }
    if needs_scrollbar {
        render_pet_arcade_info_scrollbar(full_inner, total_lines, visible_rows, scroll, buf, layout, theme);
    }
}

/// One line of [`render_pet_arcade_info`]'s own content -- `pub(crate)`
/// (not a function-local type) because `App::update_pet_arcade_info_
/// scrollbar`'s own click-to-jump math needs `pet_arcade_info_lines().len()`
/// to agree with what this fn actually painted, never a second,
/// independently-maintained line count.
pub(crate) enum PetArcadeInfoLine {
    Label(&'static str),
    Body(String),
}

/// The mechanics modal's own content -- a plain data list, split out of
/// [`render_pet_arcade_info`] so `App::update_pet_arcade_info_scrollbar`
/// can read its length without duplicating the formatting above (see that
/// fn's own doc comment). EVERY number below is read from `gate4agent_
/// arcade_pet_bastion::constants` (this module's own import list at the
/// top of the file) AT CALL TIME, never copied into a string literal here
/// -- a number that can drift out of sync with the sim it describes is
/// worse than showing no number at all. The two genuinely non-integer
/// ones (Symbiosis' own 1.5-tile radius, the pet's own 1.2s move) go
/// through [`one_decimal`] rather than truncating to a wrong whole number.
///
/// Owner report: "мне не ясна механика траты спарков ... рун и какого-то
/// светлячка которая куда-то встает" -- Spark, runes and the pet's own
/// anchor mechanic were nowhere in the interface at all, and clicking a
/// pet anchor silently issuing `Command::MovePet` was not something the
/// owner knew he was doing. The WAVES section covers a follow-up the
/// rules crate changed out from under the UI: an enemy reaching the
/// Heartseed is no longer killed (it loops back to its own route start at
/// full health and keeps walking, costing Integrity per lap instead) and
/// a wave no longer ends on the first Heartseed arrival (only once every
/// enemy on it is dead) -- both are silent rule changes the owner has no
/// other way to learn.
pub(crate) fn pet_arcade_info_lines() -> Vec<PetArcadeInfoLine> {
    let wisp_free_blink_s = WISP_FREE_BLINK_INTERVAL_TICKS / TICKS_PER_SECOND as u64;
    let anchor_linger_s = ANCHOR_RUNE_LINGER_TICKS / TICKS_PER_SECOND as u64;
    let move_s = one_decimal(PET_MOVE_TICKS as i64, TICKS_PER_SECOND);
    let symbiosis_tiles = one_decimal(SYMBIOSIS_ADJACENCY_FP, FIXED_SCALE);
    let symbiosis_pct = SYMBIOSIS_DAMAGE_BONUS_PERMILLE / 10;
    let linked_attack_speed_pct = (LINKED_ATTACK_SPEED_PERMILLE - 1000) / 10;
    let surge_pct = (PET_CHARGE_SURGE_EXTRA_SPEED_PERMILLE - 1000) / 10;
    let fang_pct = PET_CHARGE_FANG_DAMAGE_PERMILLE / 10;
    let bloom_pct = PET_CHARGE_BLOOM_RADIUS_PERMILLE / 10;
    let zone_tower_pct = ZONE_TOWER_DAMAGE_PERMILLE / 10;
    let zone_speed_pct = one_decimal(ZONE_ENEMY_SPEED_PERMILLE, 10);

    vec![
        PetArcadeInfoLine::Label("SPARK"),
        PetArcadeInfoLine::Body("Only a KILL by a tower currently linked to the pet earns it (see PET below).".to_owned()),
        PetArcadeInfoLine::Body(format!(
            "{SPARK_PER_KILLS} linked kills = +1 Spark, capped at {SPARK_CAP}. Doubled during Night Maw's final phase."
        )),
        PetArcadeInfoLine::Body(format!(
            "Spends: Pulse -{PET_PULSE_COST}  Blink -{BLINK_COST} (free every {wisp_free_blink_s}s on a Wisp)  Circuit -{FULL_CIRCUIT_COST}"
        )),
        PetArcadeInfoLine::Label("RUNES"),
        PetArcadeInfoLine::Body(format!(
            "Drafted after wave {} and wave {} -- pick 1 of {RUNE_DRAFT_OPTIONS}, blocking the build phase.",
            RUNE_DRAFT_AFTER_WAVES[0], RUNE_DRAFT_AFTER_WAVES[1],
        )),
        PetArcadeInfoLine::Body(format!("Echo: every {ECHO_EVERY_NTH_ATTACK}th attack, a same-kind tower fires again for free.")),
        PetArcadeInfoLine::Body(format!("Anchor: linked buffs linger {anchor_linger_s}s after the pet leaves that anchor.")),
        PetArcadeInfoLine::Body("Overgrowth: a kill's overkill damage carries into the next chain/splash hit.".to_owned()),
        PetArcadeInfoLine::Body(format!("Phase: every {PHASE_EVERY_NTH_HIT}rd hit ignores armour.")),
        PetArcadeInfoLine::Body(format!(
            "Symbiosis: towers within {symbiosis_tiles} tiles of a different kind deal +{symbiosis_pct}% damage."
        )),
        PetArcadeInfoLine::Label("PET"),
        PetArcadeInfoLine::Body("The glowing firefly is the pet -- it lives on a blue-highlighted anchor tile.".to_owned()),
        PetArcadeInfoLine::Body(format!(
            "Linked to its {CIRCUIT_BASE_SLOTS} nearest attacking towers (+1 per placed Relay), +{linked_attack_speed_pct}% attack speed."
        )),
        PetArcadeInfoLine::Body(format!("An evolution, drafted after wave {EVOLUTION_AFTER_WAVE}, can change that slot count.")),
        PetArcadeInfoLine::Body(format!("Click any anchor tile to move the pet there (or press M) -- {move_s}s on foot.")),
        PetArcadeInfoLine::Body(format!("[B] Blink -{BLINK_COST} arrives instantly instead, spending Spark.")),
        PetArcadeInfoLine::Label("WAVES"),
        PetArcadeInfoLine::Body("A unit that reaches the Heartseed is NOT killed and does not end the run.".to_owned()),
        PetArcadeInfoLine::Body("It loops back to its own route start at full health and keeps walking.".to_owned()),
        PetArcadeInfoLine::Body(format!(
            "Each lap costs Integrity instead: -{LEAK_INTEGRITY_DAMAGE} for a minion, -{BOSS_LAP_INTEGRITY_DAMAGE} for a boss."
        )),
        PetArcadeInfoLine::Body("A wave ends only once every enemy on it is dead, not on Heartseed arrival.".to_owned()),
        // `gate4agent-arcade`'s own concurrent rules addition -- the Living
        // Circuit's own build draft and the per-wave field zones, neither
        // of which had a single word of documentation anywhere in the
        // interface before this pass, the exact "мне не ясна механика"
        // owner report this whole modal already exists to answer.
        PetArcadeInfoLine::Label("PET CHARGES"),
        PetArcadeInfoLine::Body(format!(
            "Drafted after waves {}, {}, {} and {} -- pick 1 of {PET_CHARGE_DRAFT_OPTIONS}, blocking the build phase.",
            PET_CHARGE_DRAFT_AFTER_WAVES[0], PET_CHARGE_DRAFT_AFTER_WAVES[1], PET_CHARGE_DRAFT_AFTER_WAVES[2], PET_CHARGE_DRAFT_AFTER_WAVES[3],
        )),
        PetArcadeInfoLine::Body("Every charge applies ONLY to a tower currently LINKED to the pet's own Circuit.".to_owned()),
        PetArcadeInfoLine::Body(format!("Surge: +{surge_pct}% attack speed on top of the Circuit's own link bonus.")),
        PetArcadeInfoLine::Body(format!("Fang: +{fang_pct}% damage.")),
        PetArcadeInfoLine::Body(format!("Bloom: +{bloom_pct}% splash/chain reach, plus one extra target slot.")),
        PetArcadeInfoLine::Body("Attune: a linked tower's damage family rotates every hit instead of staying fixed --".to_owned()),
        PetArcadeInfoLine::Body("the real answer to Mirror's own resistance.".to_owned()),
        PetArcadeInfoLine::Body("Picking an already-held charge is a harmless no-op -- picks are idempotent.".to_owned()),
        PetArcadeInfoLine::Label("FIELD ZONES"),
        PetArcadeInfoLine::Body("Every wave draws two board sectors: one alters tower damage, one alters speed.".to_owned()),
        PetArcadeInfoLine::Body(format!(
            "Tower damage sector: +{zone_tower_pct}% (buff) or -{zone_tower_pct}% (debuff) for a tower built inside it."
        )),
        PetArcadeInfoLine::Body(format!(
            "Enemy speed sector: {zone_speed_pct}% slower (buff) or {zone_speed_pct}% faster (debuff) while inside it."
        )),
        PetArcadeInfoLine::Body("Redrawn every wave, always on two DIFFERENT sectors -- never the same one twice.".to_owned()),
    ]
}

/// [`render_file_scrollbar`]'s own track-plus-thumb visual contract,
/// generalized off plain `(total, visible, scroll)` integers instead of a
/// `WorkspaceFileTabView` -- that fn cannot be called directly here (it
/// is hard-wired to a file tab's own `editor.line_count()`/`scroll_line()`
/// and a `PaneId`), but the ALGORITHM it establishes (a `|` track the
/// full visible height, a `#` thumb sized `visible/total` of that height
/// and positioned `scroll/(total-1)` along it) is exactly what a scrolled
/// modal needs too, so this reuses that math verbatim rather than
/// inventing a second scrollbar look. `area` is the modal's own full
/// content rect (border-excluded) -- the track claims its own rightmost
/// column.
fn render_pet_arcade_info_scrollbar(
    area: Rect,
    total: u16,
    visible: u16,
    scroll: u16,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let track = Rect::new(area.right().saturating_sub(1), area.y, 1, area.height);
    for y in track.y..track.bottom() {
        let cell = buf.get_mut(track.x, y);
        cell.symbol = "|".into();
        cell.style = Style::default().fg(theme.border).bg(theme.modal);
    }
    let thumb_height = ((u32::from(visible) * u32::from(visible) + u32::from(total) - 1) / u32::from(total))
        .max(1)
        .min(u32::from(visible)) as u16;
    let travel = area.height.saturating_sub(thumb_height);
    let last_line = total.saturating_sub(1);
    let thumb_offset = if last_line == 0 {
        0
    } else {
        (u32::from(scroll.min(last_line)) * u32::from(travel) / u32::from(last_line)) as u16
    };
    for y in track.y.saturating_add(thumb_offset)..track.y.saturating_add(thumb_offset).saturating_add(thumb_height) {
        let cell = buf.get_mut(track.x, y);
        cell.symbol = "#".into();
        cell.style = Style::default().fg(theme.accent).bg(theme.modal);
    }
    layout.hits.push(HitRegion { rect: track, target: HitTarget::PetArcadeInfoScrollbar });
}

fn render_pet_arcade_too_small(
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    min: CellArea,
) {
    let message = format!(
        "Pet Bastion needs at least {}x{} -- resize the terminal (Esc closes)",
        min.width, min.height
    );
    let width = (message.chars().count() as u16 + 4).min(area.width);
    let height = 3.min(area.height);
    if width < 3 || height < 3 {
        return;
    }
    let modal = centered(area, width, height);
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .border_style(Style::default().fg(theme.yellow))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    let inner = Rect::new(
        modal.x + 1,
        modal.y + 1,
        modal.width.saturating_sub(2),
        modal.height.saturating_sub(2),
    );
    render_modal_line(&message, inner, 0, Style::default().fg(theme.yellow).bg(theme.modal), buf);
}

/// Owner report: restarting after a win/loss was keyboard-only (`r`).
/// `[R] Play Again` is now its own clickable button (`HitTarget::
/// PetArcadeRestart`, sized to its own label rather than the full-width
/// `modal_row` every other single-button row here uses -- there is a
/// second, unrelated hint line sharing this same card, and a full-width
/// hit on THIS row would swallow clicks meant for empty space next to the
/// button). Closing still works two ways without any new code: the
/// title bar's own `[x]` (`render_modal_close`, drawn once for every
/// screen this overlay can be in, Results included) and `Esc`.
fn render_pet_arcade_results(
    outcome: PetBastionRunOutcome,
    inner: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let (headline, color) = match outcome {
        PetBastionRunOutcome::Won => ("VICTORY -- the Heartseed holds.", theme.green),
        PetBastionRunOutcome::Lost => ("DEFEAT -- the Heartseed broke.", theme.red),
    };
    render_modal_line(headline, inner, 0, Style::default().fg(color).bg(theme.modal), buf);

    let restart_label = "[R] Play Again";
    let restart_width = (cell_width(restart_label) as u16).min(inner.width);
    if restart_width > 0 && inner.height > 2 {
        let rect = Rect::new(inner.x, inner.y + 2, restart_width, 1);
        Paragraph::new(restart_label)
            .style(Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD))
            .render(rect, buf);
        push_modal_hit(layout, rect, HitTarget::PetArcadeRestart);
    }
    render_modal_line(
        "[x] top-right or Esc closes",
        inner,
        3,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

fn difficulty_label(difficulty: Difficulty) -> &'static str {
    match difficulty {
        Difficulty::Cozy => "Cozy",
        Difficulty::Standard => "Standard",
        Difficulty::Wild => "Wild",
    }
}

/// One [`PetArcadeMenuState::ScoreList`] row -- everything on it comes
/// straight off the `PetArcadeScoreEntry` it was built from (`pet_arcade
/// ::PetArcadeScoreEntry`'s own doc comment covers where those three
/// fields came from), never a derived/re-computed quantity.
fn pet_arcade_score_line(entry: crate::pet_arcade::PetArcadeScoreEntry) -> String {
    let outcome = match entry.outcome {
        PetBastionRunOutcome::Won => "Won",
        PetBastionRunOutcome::Lost => "Lost",
    };
    format!(
        "{}  wave {}/{WAVE_COUNT}  {outcome}",
        difficulty_label(entry.difficulty),
        entry.wave_reached
    )
}

/// The run menu popup (`App::pet_arcade_menu`) -- see [`PetArcadeMenuState`]'s
/// own doc comment for the three things it can show. Owner report: "не
/// хватает какого-то меню там, где можно рестарт сделать, может какой-то
/// скор-лист там будет еще что-то" -- Restart is always the fixed first
/// row of `Open`, everything after it is [`PetArcadeMenuAction::ALL`], so
/// a future entry (a score list was named explicitly; more may follow)
/// costs one match arm and one more `ALL` element, never a rearrangement
/// of what is already here.
///
/// Same "it is a popup, not a modal" shape `render_agent_menu`'s own doc
/// comment already establishes for this crate's other context menu: no
/// `[x]`/back glyph in the popup's own corner -- `Open`'s own row list
/// closes via outside-click/Escape/re-click on the header's own trigger
/// button (`App::close_overlay_outside_click`'s own `pet_arcade_menu`
/// branch). `ConfirmRestart`/`ScoreList` each carry an explicit `<- Back`
/// ROW instead, one level further in than `render_modal_back`'s own
/// corner arrow reaches, but the SAME "arrow means step back one level,
/// never `[x]`" reasoning the owner asked applied here too.
fn render_pet_arcade_menu(app: &App, area: Rect, buf: &mut TerminalBuffer, layout: &mut LayoutRects, theme: Theme) {
    let Some(state) = app.pet_arcade_menu else { return };

    enum Row {
        /// A clickable, keyboard-selectable row -- `selected_index` (from
        /// `PetArcadeMenuState::Open`) highlights it if it matches.
        Action { label: String, target: HitTarget },
        /// Read-only text -- the confirm prompt's own warning line, and
        /// every score-list row.
        Plain(String),
    }

    let selected_index = match state {
        PetArcadeMenuState::Open { selected } => Some(selected),
        PetArcadeMenuState::ConfirmRestart | PetArcadeMenuState::ScoreList => None,
    };
    let rows: Vec<Row> = match state {
        PetArcadeMenuState::Open { .. } => {
            let mut rows = vec![Row::Action { label: "[R] Restart run".to_owned(), target: HitTarget::PetArcadeRestart }];
            for action in PetArcadeMenuAction::ALL {
                rows.push(Row::Action {
                    label: format!("[S] {}", action.label()),
                    target: HitTarget::PetArcadeMenuAction(action),
                });
            }
            rows
        }
        PetArcadeMenuState::ConfirmRestart => {
            // Owner: "make that consequence visible before it happens" --
            // named against the wave actually in progress when available
            // (`is_running` is required for this state to even be
            // reachable, `App::activate_pet_arcade_restart`'s own doc
            // comment), a generic warning otherwise rather than a panic
            // or a fabricated wave number.
            let warning = match app.pet_arcade.borrow().snapshot() {
                Some(snapshot) => format!("Restart wave {}? The run in progress will be thrown away.", snapshot.wave),
                None => "Restart? The run in progress will be thrown away.".to_owned(),
            };
            vec![
                Row::Plain(warning),
                Row::Action { label: "<- Back".to_owned(), target: HitTarget::PetArcadeMenuBack },
                Row::Action { label: "Yes, restart".to_owned(), target: HitTarget::PetArcadeRestart },
            ]
        }
        PetArcadeMenuState::ScoreList => {
            let mut rows = vec![Row::Action { label: "<- Back".to_owned(), target: HitTarget::PetArcadeMenuBack }];
            let arcade = app.pet_arcade.borrow();
            let scores = arcade.scores();
            if scores.is_empty() {
                rows.push(Row::Plain("No finished runs yet this session.".to_owned()));
            } else {
                for entry in scores.iter().rev() {
                    rows.push(Row::Plain(pet_arcade_score_line(*entry)));
                }
            }
            rows
        }
    };

    let width = 44u16.min(area.width);
    let height = (rows.len() as u16 + 2).min(area.height.saturating_sub(1));
    if width < 3 || height < 3 {
        return;
    }
    // Anchored under the header's own `[N] Menu` button (`render_pet_
    // arcade`'s own header block, `layout.pet_arcade_modal` -- ALREADY
    // painted this same frame, ahead of this fn's own call site in
    // `render::render`, so this is never a stale, one-frame-lagged
    // position) rather than a captured anchor column/row: the header's
    // own position never scrolls or moves independently of the modal
    // itself, so there is nothing here `agent_menu`'s own `anchor_column`/
    // `anchor_row` capture would ever need to account for.
    let arcade_modal = layout.pet_arcade_modal;
    let x = arcade_modal.right().saturating_sub(width).max(area.x);
    let y = arcade_modal.y.saturating_add(1).min(area.bottom().saturating_sub(height));
    let menu_area = Rect::new(x, y, width, height);
    layout.pet_arcade_menu = menu_area;
    layout.note_overlay(menu_area);
    fill_rect(menu_area, theme.modal, buf);
    Block::bordered()
        .title(" run menu ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(menu_area, buf);
    let inner = Rect::new(
        menu_area.x.saturating_add(1),
        menu_area.y.saturating_add(1),
        menu_area.width.saturating_sub(2),
        menu_area.height.saturating_sub(2),
    );
    for (index, row) in rows.iter().enumerate().take(inner.height as usize) {
        let Ok(row_y) = u16::try_from(index) else { break };
        let rect = Rect::new(inner.x, inner.y + row_y, inner.width, 1);
        match row {
            Row::Action { label, target } => {
                let selected = selected_index == Some(index);
                let style = if selected {
                    Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(theme.accent).bg(theme.modal)
                };
                Paragraph::new(truncate_cells(label, inner.width as usize)).style(style).render(rect, buf);
                push_modal_hit(layout, rect, target.clone());
            }
            Row::Plain(text) => {
                Paragraph::new(truncate_cells(text, inner.width as usize))
                    .style(Style::default().fg(theme.text).bg(theme.modal))
                    .render(rect, buf);
            }
        }
    }
}

/// The tooltip panel's own preferred width -- narrow and TALL on purpose
/// (owner report: "тултип крутой но слишком растянут вбок поэтому сцена
/// его перекрывает ... пусть более вертикально открывается"), replacing
/// the old flat 52-column `MAX_WIDTH` that was wide enough to reach across
/// the board almost wherever it opened. Still only a CAP, never a fixed
/// size: [`pet_arcade_tooltip_rect`]'s own candidates each shrink it to
/// whatever room their own side of `area` genuinely has, down to
/// [`PET_ARCADE_TOOLTIP_MIN_WIDTH`], and reject that side outright rather
/// than squeezing narrower than that floor.
const PET_ARCADE_TOOLTIP_WIDTH: u16 = 32;

/// The narrowest a tooltip panel may open at before a candidate side is
/// rejected as "not really room" -- below this a wrapped line holds only a
/// handful of characters, which reads as broken, not narrow.
const PET_ARCADE_TOOLTIP_MIN_WIDTH: u16 = 20;

/// The shortest a tooltip panel may open at -- one border row each side
/// plus at least one content row.
const PET_ARCADE_TOOLTIP_MIN_HEIGHT: u16 = 3;

/// The inner, wrapped-TEXT width for a tooltip panel of outer `width`
/// columns -- the panel's own bordered `Block` claims one column on each
/// side, so wrapping to the full outer `width` would let a maximally-wide
/// line collide with the border this fn's own caller draws around it.
fn pet_arcade_tooltip_content_width(width: u16) -> usize {
    width.saturating_sub(2) as usize
}

/// The x-clamp/flip every non-scene-constrained candidate below shares --
/// opens flush with the pointer's own column, but never lets the panel's
/// own right edge run past `area`'s.
fn clamp_tooltip_x(area: Rect, hover_col: u16, width: u16) -> u16 {
    hover_col.min(area.right().saturating_sub(width)).max(area.x)
}

/// The y-clamp/flip every non-scene-constrained candidate below shares --
/// opens one row BELOW the pointer if that fits inside `area`, otherwise
/// flips to open ABOVE it instead of running off the bottom edge. This is
/// the "flipping ... near an edge rather than being clipped" half of the
/// owner's own ask; [`clamp_tooltip_x`] is the other half.
fn clamp_tooltip_y(area: Rect, hover_row: u16, height: u16) -> u16 {
    let preferred = hover_row.saturating_add(1);
    if preferred.saturating_add(height) <= area.bottom() {
        preferred
    } else {
        hover_row.saturating_sub(height).max(area.y)
    }
}

/// One "beside the scene" candidate -- `prefer_right` picks the scene's
/// own right edge (the common case: the HUD panel already lives there) or
/// its left edge. `None` if that side does not have at least
/// [`PET_ARCADE_TOOLTIP_MIN_WIDTH`] genuine columns of room in `area` --
/// rejected outright rather than squeezed narrower, so [`pet_arcade_
/// tooltip_rect`] moves on to its next candidate instead of painting an
/// illegible sliver. `y` is unconstrained by `scene` here (this candidate's
/// own `x` range already never overlaps it, whatever `y` ends up being),
/// so it just follows the pointer like every non-scene tooltip already
/// does ([`clamp_tooltip_y`]).
fn pet_arcade_tooltip_beside(area: Rect, scene: Rect, hover_row: u16, text: &str, prefer_right: bool) -> Option<Rect> {
    let available_w = if prefer_right {
        area.right().saturating_sub(scene.right())
    } else {
        scene.x.saturating_sub(area.x)
    };
    if available_w < PET_ARCADE_TOOLTIP_MIN_WIDTH {
        return None;
    }
    let width = PET_ARCADE_TOOLTIP_WIDTH.min(available_w);
    let lines = wrap_preview_text(text, pet_arcade_tooltip_content_width(width));
    let height = (lines.len() as u16).saturating_add(2).min(area.height);
    if height < PET_ARCADE_TOOLTIP_MIN_HEIGHT {
        return None;
    }
    let x = if prefer_right { scene.right() } else { scene.x.saturating_sub(width) };
    let y = clamp_tooltip_y(area, hover_row, height);
    Some(Rect::new(x, y, width, height))
}

/// One "around the scene" candidate -- `below` picks the scene's own
/// bottom edge or its top edge, tried only once neither [`pet_arcade_
/// tooltip_beside`] candidate had room (e.g. a hover whose own column
/// sits ON the board, in a window too narrow for the HUD strip itself to
/// clear [`PET_ARCADE_TOOLTIP_MIN_WIDTH`]). `x` still follows the pointer
/// within `area` ([`clamp_tooltip_x`]) -- nothing about `scene` constrains
/// it horizontally here, only `y` is pinned to the scene's own edge.
fn pet_arcade_tooltip_around(area: Rect, scene: Rect, hover_col: u16, text: &str, below: bool) -> Option<Rect> {
    let available_h = if below {
        area.bottom().saturating_sub(scene.bottom())
    } else {
        scene.y.saturating_sub(area.y)
    };
    if available_h < PET_ARCADE_TOOLTIP_MIN_HEIGHT {
        return None;
    }
    let width = PET_ARCADE_TOOLTIP_WIDTH.min(area.width.saturating_sub(2)).max(6);
    let lines = wrap_preview_text(text, pet_arcade_tooltip_content_width(width));
    let height = (lines.len() as u16).saturating_add(2).min(available_h);
    let x = clamp_tooltip_x(area, hover_col, width);
    let y = if below { scene.bottom() } else { scene.y.saturating_sub(height) };
    Some(Rect::new(x, y, width, height))
}

/// The last-resort candidate -- pointer-anchored exactly like every
/// tooltip in this crate already opens (`render_context_usage_tooltip`'s
/// own established shape), used verbatim whenever `scene` is `None` (the
/// glyph tier, or a frame with no pixel-tier board painted at all -- a
/// plain terminal cell obeys normal paint-order z-ordering, so there is
/// nothing to avoid) and as the genuine fallback when every scene-aware
/// candidate above rejected its own side.
fn pet_arcade_tooltip_anchored(area: Rect, hover_col: u16, hover_row: u16, text: &str) -> Rect {
    let width = PET_ARCADE_TOOLTIP_WIDTH.min(area.width.saturating_sub(2)).max(6);
    let lines = wrap_preview_text(text, pet_arcade_tooltip_content_width(width));
    let height = (lines.len() as u16).saturating_add(2).min(area.height);
    let x = clamp_tooltip_x(area, hover_col, width);
    let y = clamp_tooltip_y(area, hover_row, height);
    Rect::new(x, y, width, height)
}

/// Chooses this frame's own tooltip panel rect. Owner report: "тултип
/// крутой но слишком растянут вбок поэтому сцена его перекрывает, она
/// оверрайдит все, пусть уважает сцену и более вертикально открывается с
/// учётом размеров окна и положения модалки" -- `scene` is the pixel
/// tier's own whole-board raster THIS frame (`layout.pet_arcade_pixel_
/// frame`'s own rect, a sixel image painted directly to the terminal that
/// "obeys no z-order of its own", `drop_pet_arcade_pixel_frame_if_
/// covered`'s own doc comment), or `None` on the glyph tier / whenever no
/// pixel frame painted at all this frame.
///
/// Tried in this order, the FIRST candidate with genuine room wins:
/// 1. beside the scene ([`pet_arcade_tooltip_beside`], right of it then
///    left of it) -- a narrow panel almost always fits in the HUD strip
///    beside the board, or the window's own margin outside the modal,
///    without touching the scene at all;
/// 2. around the scene ([`pet_arcade_tooltip_around`], below it then
///    above it) -- covers a hover whose own column sits ON the board (a
///    tile's own tooltip) for whichever window shape leaves no room
///    beside it;
/// 3. pointer-anchored ([`pet_arcade_tooltip_anchored`]) -- the true last
///    resort, reached only when `area` genuinely had no non-overlapping
///    room anywhere for this frame's own text. The caller (`render_pet_
///    arcade_tooltip`) is what actually registers this as an overlay when
///    that happens, so the end-of-frame occlusion pass drops the pixel
///    frame for this one redraw -- this fn only ever picks geometry, it
///    never touches `layout` itself.
fn pet_arcade_tooltip_rect(area: Rect, scene: Option<Rect>, hover_col: u16, hover_row: u16, text: &str) -> Rect {
    if let Some(scene) = scene {
        if let Some(rect) = pet_arcade_tooltip_beside(area, scene, hover_row, text, true) {
            return rect;
        }
        if let Some(rect) = pet_arcade_tooltip_beside(area, scene, hover_row, text, false) {
            return rect;
        }
        if let Some(rect) = pet_arcade_tooltip_around(area, scene, hover_col, text, true) {
            return rect;
        }
        if let Some(rect) = pet_arcade_tooltip_around(area, scene, hover_col, text, false) {
            return rect;
        }
    }
    pet_arcade_tooltip_anchored(area, hover_col, hover_row, text)
}

/// The hover-and-hold tooltip itself -- owner: "что дают руны мне не
/// очевидно ... было бы неплохо делать тултип с инфой, если наводим на
/// вариант и держим на нем допустим 2 секунды". Paints [`pet_arcade_
/// tooltip_text`]'s own text for whatever `app.pet_arcade_hover` is
/// currently tracking, but ONLY once the pointer has held it for at
/// least [`PET_ARCADE_TOOLTIP_HOLD_DELAY`] -- before that this paints
/// nothing at all, which is the entire "hold" half of "hover-and-hold"
/// (`App::hover`'s own doc comment covers the other half: dismissed the
/// instant the pointer moves off, by clearing `pet_arcade_hover`
/// outright rather than this fn hiding a stale one).
///
/// Re-verifies the hovered hit is STILL under the tracked column/row
/// THIS frame -- `render_context_usage_tooltip`'s own established
/// "still_hovered" check, reused here rather than trusting `pet_arcade_
/// hover` blindly: a click can change the board/HUD layout under an
/// unmoved pointer (upgrading a tower reflows the context card, say)
/// between one `App::hover` update and the next redraw.
fn render_pet_arcade_tooltip(app: &App, area: Rect, buf: &mut TerminalBuffer, layout: &mut LayoutRects, theme: Theme) {
    let Some(hover) = app.pet_arcade_hover.as_ref() else { return };
    if hover.since.elapsed() < PET_ARCADE_TOOLTIP_HOLD_DELAY {
        return;
    }
    let still_hovered = layout
        .hits
        .iter()
        .rev()
        .find(|hit| hit.rect.contains(hover.column, hover.row))
        .is_some_and(|hit| hit.target == hover.target);
    if !still_hovered {
        return;
    }
    let snapshot = app.pet_arcade.borrow().snapshot();
    let Some(text) = pet_arcade_tooltip_text(&hover.target, snapshot.as_ref()) else {
        return;
    };
    if area.width < 6 || area.height < 3 {
        return;
    }
    let scene = layout.pet_arcade_pixel_frame.as_ref().map(|placement| placement.rect);
    let rect = pet_arcade_tooltip_rect(area, scene, hover.column, hover.row, &text);
    if rect.height < PET_ARCADE_TOOLTIP_MIN_HEIGHT {
        return;
    }
    // Every non-overlapping placement `pet_arcade_tooltip_rect` could try
    // already failed this frame if we reach here still intersecting
    // `scene` -- the ONLY way left to keep this tooltip legible is to drop
    // the board's own sixel raster back to the always-present glyph tier
    // underneath for this one redraw (`render_pet_arcade`'s own doc
    // comment: the glyph board paints first, unconditionally, regardless
    // of visual tier). Registering as an overlay is what `drop_pet_arcade_
    // pixel_frame_if_covered` (`render::render`'s own end-of-frame
    // occlusion pass) keys off to actually do that -- a real cost (the
    // pixel-tier board vanishes for this redraw), so this only ever runs
    // as the fallback, never the default.
    if let Some(scene) = scene {
        if !rect.intersect(scene).is_empty() {
            layout.note_overlay(rect);
        }
    }
    let lines = wrap_preview_text(&text, pet_arcade_tooltip_content_width(rect.width));
    fill_rect(rect, theme.modal, buf);
    Block::bordered()
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(rect, buf);
    let inner = Rect::new(
        rect.x.saturating_add(1),
        rect.y.saturating_add(1),
        rect.width.saturating_sub(2),
        rect.height.saturating_sub(2),
    );
    for (row, line) in lines.iter().enumerate().take(inner.height as usize) {
        let Ok(row) = u16::try_from(row) else { break };
        render_modal_line(line, inner, row, Style::default().fg(theme.text).bg(theme.modal), buf);
    }
}

/// Ticks-remaining is converted to whole seconds rounded UP (never floats
/// -- this is presentation code, but it still follows the sim's own "no
/// floats" convention for consistency): `TICKS_PER_SECOND` is 20 (50ms
/// ticks), so `(ticks + 19) / 20` is the standard integer round-up.
fn pet_arcade_phase_label(phase: &RunPhaseView) -> String {
    match phase {
        RunPhaseView::Build { ticks_remaining } => format!("Build ({}s)", (ticks_remaining + 19) / 20),
        RunPhaseView::Combat => "Combat".to_owned(),
        RunPhaseView::RuneDraft => "Rune draft".to_owned(),
        RunPhaseView::EvolutionChoice => "Evolution choice".to_owned(),
        // The Living Circuit's own build draft (`pet.rs`'s own
        // `PetCharge`) -- the same structural shape as `RuneDraft` just
        // above, drafted after waves 1/3/5/7 instead of 2/6
        // (`PET_CHARGE_DRAFT_AFTER_WAVES`). `render_pet_arcade_context`'s
        // own `PetChargeDraft` arm is what actually answers it.
        RunPhaseView::PetChargeDraft => "Pet Charge draft".to_owned(),
        RunPhaseView::Victory => "Victory".to_owned(),
        RunPhaseView::Defeat => "Defeat".to_owned(),
    }
}

/// The board header row -- also a click target (`HitTarget::
/// PetArcadeWaveInspect`, pushed by the caller) that opens the wave
/// inspector card (`render_pet_arcade_inspect_card`'s own `Inspect::Wave`
/// arm).
fn pet_arcade_header_line(snapshot: &SimulationSnapshot) -> String {
    format!("Wave {}/{}  {}", snapshot.wave, WAVE_COUNT, pet_arcade_phase_label(&snapshot.phase))
}

/// Tints every board tile inside this wave's two field zones
/// (`snapshot.field_zones`) with a muted, kind/polarity-specific
/// background -- the glyph tier's own counterpart to the pixel tier's
/// [`push_zone_outline_stroke`] (which draws an outline via `DynamicStroke`
/// instead, since a `Surface` cell's own `bg` is invisible on plain terrain
/// at that tier -- see [`pet_arcade_pixel_highlight_strokes`]'s own doc
/// comment). This is the natural, already-established mechanism at THIS
/// tier: `pet_arcade_highlight_cursor`/`pet_arcade_highlight_buildable_
/// tiles` already tint a `Surface` cell's own `bg` for exactly this reason
/// (a `SurfaceCell`'s `glyph`/`fg` are never touched, so the real terrain/
/// unit character underneath always stays legible on top of the tint --
/// the same "tint, never replace" discipline this module's own doc
/// comments already establish).
///
/// Skips any cell that ALREADY carries its own `bg` (a stunned/slowed
/// enemy's status tint, a boss's own kind colour, the pet's own evolution
/// glow -- `gate4agent-arcade-pet-bastion-render`'s own `paint_enemy`/
/// `paint_boss`/`paint_pet`, the only three painters that ever set `bg` at
/// all) rather than overwriting it: that state is more specific and more
/// urgent than an ambient field zone, and overwriting it here would be
/// exactly the "drown the units standing on it" failure this mechanic must
/// avoid.
fn pet_arcade_highlight_field_zones(surface: &mut Surface, snapshot: &SimulationSnapshot) {
    for zone in &snapshot.field_zones {
        let tint = pet_arcade_field_zone_glyph_tint(zone.kind, zone.polarity);
        let (x0, y0, x1, y1) = zone.tile_bounds;
        for y in y0..y1 {
            for x in x0..x1 {
                let (ux, uy) = (x as u16, y as u16);
                let mut cell = surface.get(ux, uy);
                if cell.bg.is_some() {
                    continue;
                }
                cell.bg = Some(tint);
                surface.set(ux, uy, cell);
            }
        }
    }
}

/// The glyph tier's own muted tint for one field-zone kind/polarity --
/// deliberately far dimmer than [`pet_arcade_field_zone_color`]'s own
/// pixel-tier hues: this paints a FULL solid background across every one
/// of a sector's own ~49 cells (`ZONE_SECTOR_COLS x ZONE_SECTOR_ROWS`
/// tiles), not a thin translucent outline, so a saturated colour here
/// would read as a stark plate rather than an ambient tint -- the same
/// "must not drown the units on it" constraint [`push_zone_outline_stroke`]'s
/// own doc comment states for the pixel tier, answered differently at
/// this one (low saturation instead of low alpha, since a glyph-tier cell
/// has no alpha channel of its own to turn down).
fn pet_arcade_field_zone_glyph_tint(kind: ZoneKind, polarity: ZonePolarity) -> ArcadeRgb {
    match (kind, polarity) {
        (ZoneKind::TowerDamage, ZonePolarity::Buff) => ArcadeRgb(55, 45, 15),
        (ZoneKind::TowerDamage, ZonePolarity::Debuff) => ArcadeRgb(45, 22, 15),
        (ZoneKind::EnemySpeed, ZonePolarity::Buff) => ArcadeRgb(15, 42, 46),
        (ZoneKind::EnemySpeed, ZonePolarity::Debuff) => ArcadeRgb(45, 20, 38),
    }
}

/// Tints the currently selected build tile and pet anchor's own background
/// so the cursor (`PetArcade::selected_tile`/`selected_anchor` -- driven by
/// either `Tab`/`[`/`]` or a click, see `pet_arcade`'s own module doc
/// comment) is visible on the board -- never touches `glyph`/`fg`, so the
/// real terrain/unit glyph underneath always stays legible, the same
/// "tint, never replace" discipline `gate4agent-arcade-pet-bastion-render`
/// already uses for its own status-effect tiles.
fn pet_arcade_highlight_cursor(surface: &mut Surface, selected_tile: (u8, u8), selected_anchor: u8) {
    let (px, py) = (u16::from(selected_tile.0), u16::from(selected_tile.1));
    let mut tile_cell = surface.get(px, py);
    tile_cell.bg = Some(ArcadeRgb(90, 70, 20));
    surface.set(px, py, tile_cell);

    let anchor_tile = Board::anchor_tile(AnchorId(selected_anchor));
    let (ax, ay) = (anchor_tile.x as u16, anchor_tile.y as u16);
    let mut anchor_cell = surface.get(ax, ay);
    anchor_cell.bg = Some(ArcadeRgb(20, 60, 90));
    surface.set(ax, ay, anchor_cell);
}

/// The single discrete board tile a tower-placement drag's own cursor
/// (`current_column`/`current_row` off `DragState::PetArcadeTowerPlacement`)
/// is currently over -- the SAME snapping `HitTarget::PetArcadeTile`'s own
/// hit-region grid uses, so this always names whichever tile a drop THIS
/// frame would actually resolve against, never an independently-drifting
/// approximation. Shared by every drag-time visual that needs to know
/// "which ONE tile does this gesture concern right now": [`pet_arcade_
/// highlight_buildable_tiles`]/[`pet_arcade_pixel_highlight_strokes`]'s own
/// hover tint, and [`pet_arcade_drag_ghost_sprite`]'s own carried-tower
/// position. `None` while the cursor sits outside `dest` (still over the
/// palette, or off the board entirely) or `footprint_w` is degenerate.
fn pet_arcade_drag_hovered_tile(column: u16, row: u16, dest: Rect, footprint_w: u16) -> Option<(u8, u8)> {
    if footprint_w == 0 || !dest.contains(column, row) {
        return None;
    }
    let tx = (column - dest.x) / footprint_w;
    let ty = row - dest.y;
    Some((tx as u8, ty as u8))
}

/// Tints the ONE board tile a tower drag's own cursor (`hovered`,
/// [`pet_arcade_drag_hovered_tile`]) is currently over -- green if the
/// drop would actually place `kind` there right now, dim yellow if it is
/// otherwise eligible but unaffordable, dim red if another tower already
/// occupies it (`pet_arcade::BuildDragState`'s own three states). No-op
/// (nothing painted at all) once `hovered` is `None`, or once it names a
/// route/anchor/out-of-bounds tile (`pet_arcade::build_drag_state_at`'s
/// own `None`) -- those already read unambiguously as "not buildable"
/// from their own terrain/off-board rendering.
///
/// Free placement (owner's own "я хочу ставить куда хочу") dropped the old
/// build-radius concept entirely -- 333 of the board's 392 tiles are legal
/// now, and Sap-vs-cost affordability is one flat boolean true (or false)
/// for the WHOLE board at once, never spatial. Tinting every one of those
/// ~330 candidate tiles every drag frame (this fn's own predecessor) lit up
/// almost the entire board -- noise, not information. What a drag actually
/// needs, tile by tile, is only ever "what happens if I let go HERE" --
/// this now answers exactly that, for exactly the one tile the question is
/// actually about.
fn pet_arcade_highlight_buildable_tiles(surface: &mut Surface, snapshot: &SimulationSnapshot, kind: TowerKind, hovered: Option<(u8, u8)>) {
    let Some((tx, ty)) = hovered else { return };
    let Some(state) = crate::pet_arcade::build_drag_state_at(snapshot, kind, (i32::from(tx), i32::from(ty))) else {
        return;
    };
    let (x, y) = (u16::from(tx), u16::from(ty));
    let mut cell = surface.get(x, y);
    cell.bg = Some(match state {
        crate::pet_arcade::BuildDragState::Buildable => ArcadeRgb(30, 110, 40),
        crate::pet_arcade::BuildDragState::Unaffordable => ArcadeRgb(90, 80, 20),
        crate::pet_arcade::BuildDragState::Occupied => ArcadeRgb(110, 30, 30),
    });
    surface.set(x, y, cell);
}

/// The board header's own `[V]` render-tier button label (see `HitTarget::
/// PetArcadeToggleTier`'s own doc comment) -- names the owner's current
/// `PetArcadeVisualTier` PREFERENCE, plus an honest `(small)` suffix
/// whenever `Pixel` is preferred but this exact frame could not actually
/// honour it (`pixel_tier_fits`, `render_pet_arcade`'s own local): the
/// board falls back to the glyph tier that frame, and this label is what
/// tells the player why they are looking at a different picture than
/// usual, per this whole pass's own "переключение должно быть... видимым"
/// requirement -- never a silent downgrade.
fn pet_arcade_tier_label(tier: PetArcadeVisualTier, pixel_tier_fits: bool) -> String {
    match tier {
        PetArcadeVisualTier::Pixel if pixel_tier_fits => "[V] Pixel".to_string(),
        PetArcadeVisualTier::Pixel => "[V] Pixel (small)".to_string(),
        PetArcadeVisualTier::Glyph => "[V] Glyph".to_string(),
    }
}

/// Pixel-tier equivalent of [`pet_arcade_highlight_cursor`]/[`pet_arcade_
/// highlight_buildable_tiles`] above: those two mutate a `Surface` cell's
/// own `bg`, which `gate4agent-arcade`'s own pixel-tier painters only ever
/// read for a handful of `TileId`s (towers/enemies/bosses/the pet -- see
/// `backend_pixel::paint_overlay_layer` -> `sprites::paint_tile`'s own
/// match arms). Plain terrain (`Ground`/`Path`/`PetAnchor`/`Rock`/`Plant`/
/// `Firefly`/`WaterPool`/`Heartseed`) is not even reachable through that
/// path any more at all -- it is painted once into the cached
/// `background::BoardBackground` this crate's own `PET_ARCADE_PIXEL_
/// BACKGROUND` holds, from a terrain-only `Surface` with no cursor/drag
/// tint ever applied to it (see that static's own doc comment) -- so a
/// `bg`-only tint on an otherwise-bare tile (the common case: a cursor or
/// drag hover highlight usually lands on open ground) is silently
/// invisible in the pixel tier either way. `gate4agent-arcade` is out of
/// scope for this pass (a sibling agent owns it concurrently) -- the fix
/// on THIS side of that boundary is to draw the SAME information as a
/// bright inset outline via the engine's own public `DynamicStroke`
/// contract (`compose_frame`'s own `strokes` parameter), which paints
/// identically regardless of which `TileId` (or no `TileId` at all, per
/// the background split above) sits underneath. `drag` is `Some((kind,
/// hovered))` only while a tower drag is BOTH live and hovering the board
/// (`Option::zip` of the two, its own call site) -- see [`pet_arcade_
/// highlight_buildable_tiles`]'s own doc comment for why this is a single
/// tile now, never the whole legal set.
fn pet_arcade_pixel_highlight_strokes(
    snapshot: &SimulationSnapshot,
    selected_tile: (u8, u8),
    selected_anchor: u8,
    drag: Option<(TowerKind, (u8, u8))>,
) -> Vec<DynamicStroke> {
    let mut strokes = Vec::new();
    // Painted FIRST (bottom-most) -- the cursor/anchor/drag outlines below
    // are more specific, momentary state and must stay legible on top of
    // an ambient zone outline whenever the two land on the same tile, the
    // same priority `render_pet_arcade`'s own glyph-tier call order gives
    // `pet_arcade_highlight_field_zones` versus `pet_arcade_highlight_
    // cursor`.
    for zone in &snapshot.field_zones {
        push_zone_outline_stroke(&mut strokes, zone.tile_bounds, pet_arcade_field_zone_color(zone.kind, zone.polarity));
    }
    push_tile_outline_stroke(&mut strokes, selected_tile.0 as f64, selected_tile.1 as f64, ArcadeRgb(220, 180, 60), 2.0);
    let anchor_tile = Board::anchor_tile(AnchorId(selected_anchor));
    push_tile_outline_stroke(&mut strokes, anchor_tile.x as f64, anchor_tile.y as f64, ArcadeRgb(70, 160, 220), 2.0);
    if let Some((kind, (tx, ty))) = drag {
        if let Some(state) = crate::pet_arcade::build_drag_state_at(snapshot, kind, (i32::from(tx), i32::from(ty))) {
            let color = match state {
                crate::pet_arcade::BuildDragState::Buildable => ArcadeRgb(60, 200, 80),
                crate::pet_arcade::BuildDragState::Unaffordable => ArcadeRgb(210, 180, 60),
                crate::pet_arcade::BuildDragState::Occupied => ArcadeRgb(210, 70, 70),
            };
            push_tile_outline_stroke(&mut strokes, tx as f64, ty as f64, color, 1.6);
        }
    }
    strokes
}

/// Four straight [`DynamicStroke`]s forming one tile's own inset rectangle
/// outline, `(tile_x, tile_y)` being that tile's own top-left corner in
/// board-tile units -- see [`pet_arcade_pixel_highlight_strokes`]'s own doc
/// comment for why an outline, not a filled wash. Inset by a fixed
/// fraction of the tile so the outline reads as a distinct ring around the
/// tile's own content rather than touching (and visually fusing with) the
/// neighbouring tile's edge.
fn push_tile_outline_stroke(strokes: &mut Vec<DynamicStroke>, tile_x: f64, tile_y: f64, color: ArcadeRgb, width_px: f32) {
    const INSET: f64 = 0.1;
    let (x0, y0) = (tile_x + INSET, tile_y + INSET);
    let (x1, y1) = (tile_x + 1.0 - INSET, tile_y + 1.0 - INSET);
    let corners = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)];
    for i in 0..4 {
        let (fx, fy) = corners[i];
        let (tx, ty) = corners[(i + 1) % 4];
        strokes.push(DynamicStroke { from_tile: (fx, fy), to_tile: (tx, ty), color, width_px, bulge: 0.0, alpha: 0.95 });
    }
}

/// This wave's field-zone colour -- distinct hues for the two `ZoneKind`s
/// (gold/amber for tower damage, cyan for enemy speed) and a distinct
/// saturation/brightness for the two `ZonePolarity`s within each, so all
/// four combinations read apart at a glance without needing the tooltip
/// (`pet_arcade_field_zone_tooltip`) open at the same time.
fn pet_arcade_field_zone_color(kind: ZoneKind, polarity: ZonePolarity) -> ArcadeRgb {
    match (kind, polarity) {
        (ZoneKind::TowerDamage, ZonePolarity::Buff) => ArcadeRgb(255, 205, 70),
        (ZoneKind::TowerDamage, ZonePolarity::Debuff) => ArcadeRgb(170, 70, 40),
        (ZoneKind::EnemySpeed, ZonePolarity::Buff) => ArcadeRgb(90, 210, 230),
        (ZoneKind::EnemySpeed, ZonePolarity::Debuff) => ArcadeRgb(210, 80, 170),
    }
}

/// One field zone's own sector-wide outline -- the SAME `DynamicStroke`
/// contract [`push_tile_outline_stroke`] draws a single tile's inset ring
/// with, scaled up to a whole `ZONE_SECTOR_COLS x ZONE_SECTOR_ROWS` sector
/// (`bounds`, `SimulationSnapshot::field_zones`'s own pre-resolved tile
/// rectangle) instead of one tile. Two constraints this crate already
/// enforces elsewhere for terrain (`gate4agent-arcade`'s own `background.
/// rs` module doc: "No hard edge anywhere in this layer, by construction")
/// apply here too, on this side of that boundary:
///
/// - **No cell-aligned hard edge.** A flat, opaque fill sized to the
///   sector's own raw tile grid would read as exactly the checkerboard
///   that module's doc warns against. This draws an OUTLINE only, well
///   INSET from the sector's own raw tile boundary (`INSET`, comfortably
///   larger than a single tile's own `push_tile_outline_stroke` inset --
///   a sector is 7 tiles wide, so there is room to spare) so the border
///   never runs flush along the underlying tile grid, plus a second,
///   wider, much fainter pass underneath the crisp one for a soft glow
///   rather than a razor edge -- the same "fade to transparent, never a
///   flat-filled rectangle" shape that module's own doc describes,
///   available here via [`DynamicStroke::alpha`] rather than a real
///   gradient (this crate cannot add a raster gradient primitive of its
///   own; `gate4agent-arcade` -- where one lives -- is out of scope for
///   this pass).
/// - **Must not drown the units on it.** An outline covers a tiny fraction
///   of the sector's own interior compared to a fill, and every alpha here
///   stays translucent (`0.16`/`0.55`, never `1.0`) so a tower/enemy/the
///   pet standing near the border stays fully legible through it.
fn push_zone_outline_stroke(strokes: &mut Vec<DynamicStroke>, bounds: (i32, i32, i32, i32), color: ArcadeRgb) {
    const INSET: f64 = 0.4;
    let (x0, y0, x1, y1) = bounds;
    let corners = [
        (x0 as f64 + INSET, y0 as f64 + INSET),
        (x1 as f64 - INSET, y0 as f64 + INSET),
        (x1 as f64 - INSET, y1 as f64 - INSET),
        (x0 as f64 + INSET, y1 as f64 - INSET),
    ];
    for i in 0..4 {
        let (fx, fy) = corners[i];
        let (tx, ty) = corners[(i + 1) % 4];
        // Wide, faint glow pass first (painted underneath).
        strokes.push(DynamicStroke { from_tile: (fx, fy), to_tile: (tx, ty), color, width_px: 7.0, bulge: 0.0, alpha: 0.16 });
        // Crisp pass on top -- still translucent, per this fn's own "must
        // not drown the units on it" doc section above.
        strokes.push(DynamicStroke { from_tile: (fx, fy), to_tile: (tx, ty), color, width_px: 2.0, bulge: 0.0, alpha: 0.55 });
    }
}

fn rune_label(rune: Rune) -> &'static str {
    match rune {
        Rune::Echo => "Echo",
        Rune::Anchor => "Anchor",
        Rune::Overgrowth => "Overgrowth",
        Rune::Phase => "Phase",
        Rune::Symbiosis => "Symbiosis",
    }
}

fn pet_charge_label(charge: PetCharge) -> &'static str {
    match charge {
        PetCharge::Surge => "Surge",
        PetCharge::Fang => "Fang",
        PetCharge::Bloom => "Bloom",
        PetCharge::Attune => "Attune",
    }
}

/// The arcade's own right-hand panel -- a real control plane now, not a
/// readout: every action the player can take is a labelled, clickable
/// control here, its hotkey printed on it, its cost printed where it has
/// one, and a visibly dim (never invisibly-unclickable, see `render_pet_
/// arcade_button_row`'s own doc comment) state whenever it is currently
/// unaffordable or illegal. Owner report (twice): "справа сделать более
/// понятную контролплейн" / "кнопки должны быть под нажатие мышкой ну
/// максимум хоткей на них" -- every one of these rows already had a real
/// `HitTarget` and handler before this pass; what was missing was
/// PRESENTING them as a panel a mouse-only player could actually read.
///
/// Reads top to bottom in exactly the order asked for -- what I can build,
/// what the selected thing can do, what the pet can do, what the wave is
/// doing:
///
/// - one packed resource row (Sap/Spark/HP);
/// - a `Build:` label plus the three-row, two-column tower palette
///   (`HitTarget::PetArcadeTowerKind`);
/// - the five-row context block (`render_pet_arcade_context` -- the
///   selected tile/tower's own upgrade/sell actions, the inspector card,
///   or the rune-draft/evolution-choice cards, whichever currently applies
///   -- unchanged, already exactly this shape);
/// - a `Pet:` label plus the two packed Living Circuit ability rows
///   (Pulse/Blink, Full Circuit/Move);
/// - the Start Wave row.
///
/// `1 resource + 1 label + 3 palette + 5 context + 1 label + 2 ability + 1
/// wave = 14`, exactly `board_h`/`BOARD_HEIGHT` -- this column's own fixed
/// height every time it paints at all (`render_pet_arcade`'s own call
/// site). The panel's own width/row budget is unchanged by this
/// reordering; it does not, and structurally cannot, grow at the board's
/// expense -- `render_pet_arcade` hands this fn a fixed `area` it never
/// negotiates for itself.
fn render_pet_arcade_hud(
    snapshot: &SimulationSnapshot,
    arcade: &crate::pet_arcade::PetArcade,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let text_style = Style::default().fg(theme.text).bg(theme.modal);
    let muted_style = Style::default().fg(theme.muted).bg(theme.modal);

    render_modal_line(
        &format!("Sap {}  Spark {}/{}  HP {}", snapshot.sap, snapshot.pet.spark, SPARK_CAP, snapshot.integrity),
        area,
        0,
        text_style,
        buf,
    );
    push_modal_hit(layout, modal_row(area, 0), HitTarget::PetArcadeResources);

    render_modal_line("Build:", area, 1, muted_style, buf);
    let selected_kind = arcade.selected_tower_kind();
    let col_width = area.width / 2;
    for (index, kind) in TowerKind::ALL.iter().enumerate() {
        let index = index as u16;
        let Some(row) = 2u16.checked_add(index / 2) else { break };
        if row >= area.height {
            break;
        }
        let col = index % 2;
        let x = area.x + col * col_width;
        let width = if col == 0 { col_width } else { area.width - col_width };
        if width == 0 {
            continue;
        }
        let cost = kind.base_stats().cost;
        let affordable = cost <= snapshot.sap;
        let marker = if *kind == selected_kind { '>' } else { ' ' };
        let line = format!("{marker}{} {} {}", index + 1, tower_kind_label(*kind), cost);
        let style = if !affordable {
            Style::default().fg(theme.dim).bg(theme.modal)
        } else if *kind == selected_kind {
            Style::default().fg(theme.accent).bg(theme.modal)
        } else {
            text_style
        };
        let rect = Rect::new(x, area.y + row, width, 1);
        Paragraph::new(truncate_cells(&line, width as usize)).style(style).render(rect, buf);
        push_modal_hit(layout, rect, HitTarget::PetArcadeTowerKind(*kind));
    }

    let context_area = Rect::new(area.x, area.y + 5, area.width, 5.min(area.height.saturating_sub(5)));
    render_pet_arcade_context(snapshot, arcade, context_area, buf, layout, theme);

    render_modal_line("Pet:", area, 10, muted_style, buf);
    render_pet_arcade_button_row(
        &[
            (format!("[G] Pulse -{PET_PULSE_COST}"), PetArcade::can_pet_pulse(snapshot), HitTarget::PetArcadePetPulse),
            (format!("[B] Blink -{BLINK_COST}"), PetArcade::can_blink(snapshot), HitTarget::PetArcadeBlink),
        ],
        area,
        11,
        buf,
        layout,
        theme,
    );
    render_pet_arcade_button_row(
        &[
            (format!("[F] Circuit -{FULL_CIRCUIT_COST}"), PetArcade::can_full_circuit(snapshot), HitTarget::PetArcadeFullCircuit),
            (format!("[M] Move->#{}", arcade.selected_anchor()), true, HitTarget::PetArcadeMovePet),
        ],
        area,
        12,
        buf,
        layout,
        theme,
    );
    render_pet_arcade_button_row(
        &[("[Space] Start Wave".to_owned(), PetArcade::can_start_wave(snapshot), HitTarget::PetArcadeStartWave)],
        area,
        13,
        buf,
        layout,
        theme,
    );
}

/// Paints a row of 1-2 short action buttons packed left-to-right with a
/// two-column gap, each getting its OWN hit region sized to its own
/// label -- never one shared full-row hit the way `push_modal_hit`/
/// `modal_row` give every other single-button row in this HUD, since two
/// buttons sharing a row would otherwise fight over the same click.
/// `enabled` only changes the button's own colour (accent vs dim) -- every
/// arcade action button's own click handler (`PetArcade::click_pet_pulse`,
/// `click_blink`, ...) already queues its command unconditionally and lets
/// the sim itself no-op an unaffordable one, so a dim button here still
/// carries a live hit region rather than silently swallowing the click:
/// the owner's own ask was "visibly unavailable", not "unclickable".
fn render_pet_arcade_button_row(
    buttons: &[(String, bool, HitTarget)],
    area: Rect,
    row: u16,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if row >= area.height {
        return;
    }
    let y = area.y + row;
    let right = area.x + area.width;
    let mut x = area.x;
    for (label, enabled, target) in buttons {
        if x >= right {
            break;
        }
        let width = (cell_width(label) as u16).min(right - x);
        if width == 0 {
            break;
        }
        let style = if *enabled {
            Style::default().fg(theme.accent).bg(theme.modal)
        } else {
            Style::default().fg(theme.dim).bg(theme.modal)
        };
        let rect = Rect::new(x, y, width, 1);
        Paragraph::new(truncate_cells(label, width as usize)).style(style).render(rect, buf);
        push_modal_hit(layout, rect, target.clone());
        x += width + 2;
    }
}

/// The HUD's own context-sensitive block, right under the resource rows --
/// the inspector card (`Inspect`, if a click set one -- takes priority,
/// since inspecting an entity is a deliberate, explicit action) or
/// otherwise whatever `selected_tile` currently holds: a placed tower's own
/// action rows, or an empty tile's own placement preview for whichever
/// kind the palette currently has selected. Exactly `area.height` rows,
/// always -- every branch below pads its own unused rows with nothing
/// rather than leaving stale content from a previous frame's different
/// branch (each row is drawn fresh every frame, never carried over).
fn render_pet_arcade_context(
    snapshot: &SimulationSnapshot,
    arcade: &crate::pet_arcade::PetArcade,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if let Some(inspect) = arcade.inspect() {
        render_pet_arcade_inspect_card(snapshot, inspect, area, buf, theme);
        return;
    }
    match &snapshot.phase {
        // Owner report: neither of these two cards had a single clickable
        // option -- `F1`-`F3` were the ONLY way to resolve either, which
        // stalls a mouse-only run outright (both phases block every other
        // action until resolved). Each option row below is now also a
        // `HitTarget::PetArcadeDraftRune`/`PetArcadeChooseEvolution` hit,
        // dispatched to `PetArcade::click_draft_rune`/`click_choose_
        // evolution` -- the exact same commands the `F1`-`F3` keys queue.
        RunPhaseView::RuneDraft => {
            render_modal_line("Draft a rune (click below closed):", area, 0, Style::default().fg(theme.text).bg(theme.modal), buf);
            for (index, rune) in snapshot.rune_options.iter().enumerate() {
                let Ok(row) = u16::try_from(1 + index) else { break };
                render_modal_line(&format!("F{} {}", index + 1, rune_label(*rune)), area, row, Style::default().fg(theme.accent).bg(theme.modal), buf);
                push_modal_hit(layout, modal_row(area, row), HitTarget::PetArcadeDraftRune(*rune));
            }
            return;
        }
        RunPhaseView::EvolutionChoice => {
            render_modal_line("Choose an evolution:", area, 0, Style::default().fg(theme.text).bg(theme.modal), buf);
            for (row, (line, evolution)) in [
                ("F1 Moth", Evolution::Moth),
                ("F2 Crab", Evolution::Crab),
                ("F3 Wisp", Evolution::Wisp),
            ]
            .iter()
            .enumerate()
            {
                let Ok(row) = u16::try_from(1 + row) else { break };
                render_modal_line(line, area, row, Style::default().fg(theme.accent).bg(theme.modal), buf);
                push_modal_hit(layout, modal_row(area, row), HitTarget::PetArcadeChooseEvolution(*evolution));
            }
            return;
        }
        // The Living Circuit's own build draft -- structurally the SAME
        // decision point as `RuneDraft` just above (mirrored deliberately
        // rather than inventing a second kind of draft), reached after
        // waves 1/3/5/7 instead of 2/6. Owner report (`gate4agent-arcade`'s
        // own concurrent rules pass): this phase used to reach this crate
        // only as a header label string -- no overlay, no options drawn,
        // `Command::DraftPetCharge` never issued -- so a run stalled here
        // forever with no way to answer it, by mouse OR keyboard, the same
        // "blocks every other action until resolved" trap the rune/
        // evolution cards' own doc comment describes. A charge already
        // held (`snapshot.pet_charges_picked`) is marked `(held)` rather
        // than presented identically to a fresh pick -- `pet.rs`'s own
        // `PetChargeLoadout::add` is idempotent membership, not a stacking
        // counter, and re-drafting an already-held charge is a deliberate,
        // harmless no-op the interface must not disguise as progress.
        RunPhaseView::PetChargeDraft => {
            render_modal_line("Draft a Pet Charge (click or F1-F3):", area, 0, Style::default().fg(theme.text).bg(theme.modal), buf);
            for (index, charge) in snapshot.pet_charge_options.iter().enumerate() {
                let Ok(row) = u16::try_from(1 + index) else { break };
                let held = snapshot.pet_charges_picked.contains(charge);
                let line = if held {
                    format!("F{} {} (held)", index + 1, pet_charge_label(*charge))
                } else {
                    format!("F{} {}", index + 1, pet_charge_label(*charge))
                };
                render_modal_line(&line, area, row, Style::default().fg(theme.accent).bg(theme.modal), buf);
                push_modal_hit(layout, modal_row(area, row), HitTarget::PetArcadeDraftPetCharge(*charge));
            }
            return;
        }
        _ => {}
    }

    let text_style = Style::default().fg(theme.text).bg(theme.modal);
    let muted_style = Style::default().fg(theme.muted).bg(theme.modal);
    let action_style = Style::default().fg(theme.accent).bg(theme.modal);

    let (selected_x, selected_y) = arcade.selected_tile();
    match arcade.selected_tower_view(snapshot) {
        Some(tower) => {
            render_modal_line(
                &format!(
                    "{} L{} @{},{}",
                    tower_kind_label(tower.kind),
                    upgrade_level_label(tower.level),
                    selected_x,
                    selected_y
                ),
                area,
                0,
                text_style,
                buf,
            );
            render_modal_line(&tower_stats_line(&tower.stats), area, 1, muted_style, buf);
            // Owner report: an unaffordable Upgrade/L3 button used to paint
            // exactly like an affordable one and just silently no-op on
            // click (`apply_command`'s own `Command::UpgradeToL2`/`ToL3`
            // guard) -- indistinguishable from a real click swallowed by a
            // bug. Dimmed here the same way `render_pet_arcade_button_row`
            // already dims Pulse/Blink/Circuit/Start Wave: the HIT REGION
            // still gets pushed unconditionally either way (the sim gates
            // it, this fn only greys it), so a genuinely borderline click
            // (Sap earned mid-frame from a kill) is never dropped on the
            // floor by the render side second-guessing the sim's own gate.
            let dim_action_style = Style::default().fg(theme.dim).bg(theme.modal);
            match tower.level {
                UpgradeLevel::Base => {
                    let cost = tower.next_upgrade_cost.unwrap_or(0);
                    let style = if cost <= snapshot.sap { action_style } else { dim_action_style };
                    render_modal_line(&format!("[U] Upgrade L2  -{cost}"), area, 2, style, buf);
                    push_modal_hit(layout, modal_row(area, 2), HitTarget::PetArcadeUpgradeL2);
                }
                UpgradeLevel::L2 => {
                    let cost = tower.next_upgrade_cost.unwrap_or(0);
                    let style = if cost <= snapshot.sap { action_style } else { dim_action_style };
                    render_modal_line(&format!("[P] L3 Power  -{cost}"), area, 2, style, buf);
                    push_modal_hit(layout, modal_row(area, 2), HitTarget::PetArcadeUpgradeL3Power);
                    render_modal_line(&format!("[O] L3 Utility  -{cost}"), area, 3, style, buf);
                    push_modal_hit(layout, modal_row(area, 3), HitTarget::PetArcadeUpgradeL3Utility);
                }
                UpgradeLevel::L3(_) => {
                    render_modal_line("max level", area, 2, muted_style, buf);
                }
            }
            render_modal_line(&format!("[X] Sell  +{}", tower.sell_price), area, 4, Style::default().fg(theme.red).bg(theme.modal), buf);
            push_modal_hit(layout, modal_row(area, 4), HitTarget::PetArcadeSell);
        }
        None => {
            render_modal_line(&format!("Tile {selected_x},{selected_y} (empty)"), area, 0, text_style, buf);
            let kind = arcade.selected_tower_kind();
            render_modal_line(&format!("place: {} -{}", tower_kind_label(kind), kind.base_stats().cost), area, 1, muted_style, buf);
            let preview = effective_stats(kind, UpgradeLevel::Base);
            render_modal_line(&tower_stats_line(&preview), area, 2, muted_style, buf);
            if let Some(extras) = tower_stats_extras_line(&preview) {
                render_modal_line(&extras, area, 3, muted_style, buf);
            }
        }
    }
}

/// The tower context card's own single-line combat summary -- damage,
/// damage family, range and attack interval. Shared by a placed tower's
/// own real `TowerView::stats` and the empty-tile preview's `tower::
/// effective_stats(kind, UpgradeLevel::Base)`: identical `TowerStats`
/// shape either way, so one formatter serves both call sites.
/// `range_fp`/`FIXED_SCALE` is truncated to whole tiles (never a float --
/// this crate's own "no floats in presentation code either" convention,
/// matching `pet_arcade_header_line`'s own tick-to-seconds rounding).
fn tower_stats_line(stats: &TowerStats) -> String {
    let range_tiles = stats.range_fp / FIXED_SCALE;
    match stats.family {
        Some(family) => format!(
            "{} dmg {}  rng{} int{}t",
            stats.damage,
            damage_family_label(family),
            range_tiles,
            stats.interval_ticks
        ),
        None => "support tower (no attack)".to_owned(),
    }
}

/// The tower context card's own second line: whichever of pierce/splash/
/// chain/slow/dead-zone this tower's current stats actually carry, `None`
/// if none apply (Prism at Base with no chain bonus yet is a real example
/// -- `chain_jumps` starts at its own base value, which can be `0` before
/// any Utility upgrade for a kind whose base is already non-zero elsewhere
/// -- this fn never pads with a placeholder row, it just omits itself).
fn tower_stats_extras_line(stats: &TowerStats) -> Option<String> {
    let mut extras = Vec::new();
    if stats.pierce > 0 {
        extras.push(format!("pierce {}", stats.pierce));
    }
    if let Some(splash) = stats.splash_radius_fp {
        extras.push(format!("splash {}", splash / FIXED_SCALE));
    }
    if stats.chain_jumps > 0 {
        extras.push(format!("chain {}", stats.chain_jumps));
    }
    if let Some(slow) = stats.slow_permille {
        extras.push(format!("slow {}%", slow / 10));
    }
    if let Some(min_range) = stats.min_range_fp {
        extras.push(format!("deadzone {}", min_range / FIXED_SCALE));
    }
    if extras.is_empty() {
        None
    } else {
        Some(extras.join(", "))
    }
}

fn upgrade_level_label(level: UpgradeLevel) -> &'static str {
    match level {
        UpgradeLevel::Base => "1",
        UpgradeLevel::L2 => "2",
        UpgradeLevel::L3(UpgradeBranch::Power) => "3-Power",
        UpgradeLevel::L3(UpgradeBranch::Utility) => "3-Utility",
    }
}

fn damage_family_label(family: DamageFamily) -> &'static str {
    match family {
        DamageFamily::Physical => "Physical",
        DamageFamily::Impact => "Impact",
        DamageFamily::Arcane => "Arcane",
        DamageFamily::Fire => "Fire",
        DamageFamily::Nature => "Nature",
    }
}

fn enemy_kind_label(kind: EnemyKind) -> &'static str {
    match kind {
        EnemyKind::Mite => "Mite",
        EnemyKind::Skitter => "Skitter",
        EnemyKind::Shellback => "Shellback",
        EnemyKind::Splitter => "Splitter",
        EnemyKind::Husher => "Husher",
        EnemyKind::Mirror => "Mirror",
    }
}

fn boss_kind_label(kind: BossKind) -> &'static str {
    match kind {
        BossKind::Bellkeeper => "Bellkeeper",
        BossKind::NightMaw => "Night Maw",
    }
}

/// The entity inspector's own card -- see [`Inspect`]'s own doc comment
/// for what each variant carries and why. Every field this fn reads comes
/// straight off `SimulationSnapshot` (or, for an enemy's fixed armour, the
/// per-kind `EnemyKind::base_stats` lookup the snapshot's own doc comment
/// explicitly says NOT to duplicate per-instance) -- nothing here computes
/// a derived combat quantity (effective damage against this target,
/// time-to-kill, ...) that is not already one of those fields.
fn render_pet_arcade_inspect_card(
    snapshot: &SimulationSnapshot,
    inspect: Inspect,
    area: Rect,
    buf: &mut TerminalBuffer,
    theme: Theme,
) {
    let text_style = Style::default().fg(theme.text).bg(theme.modal);
    let muted_style = Style::default().fg(theme.muted).bg(theme.modal);
    match inspect {
        Inspect::Enemy(id) => {
            let Some(enemy) = snapshot.enemies.iter().find(|enemy| enemy.id == id) else {
                render_modal_line("enemy defeated", area, 0, muted_style, buf);
                return;
            };
            let armour = enemy.kind.base_stats().armour;
            render_modal_line(enemy_kind_label(enemy.kind), area, 0, text_style, buf);
            render_modal_line(&format!("HP {}/{}  Armour {}", enemy.hp.max(0), enemy.max_hp, armour), area, 1, text_style, buf);
            let slow_pct = enemy.slow_permille / 10;
            let stunned = if enemy.stunned { "stunned" } else { "not stunned" };
            render_modal_line(&format!("Slow {slow_pct}%  {stunned}"), area, 2, muted_style, buf);
            let last_hit = enemy.last_hit_family.map(damage_family_label).unwrap_or("none");
            render_modal_line(&format!("Last hit: {last_hit}"), area, 3, muted_style, buf);
            let resist = match enemy.resist {
                Some(resist) => format!(
                    "Resist {} ({}t left)",
                    damage_family_label(resist.family),
                    resist.ticks_remaining
                ),
                None => "Resist: none".to_owned(),
            };
            render_modal_line(&resist, area, 4, muted_style, buf);
        }
        Inspect::Boss => {
            let Some(boss) = &snapshot.boss else {
                render_modal_line("boss defeated", area, 0, muted_style, buf);
                return;
            };
            render_modal_line(&format!("{} (BOSS)", boss_kind_label(boss.kind)), area, 0, text_style, buf);
            render_modal_line(
                &format!("HP {}/{}  ({}%)", boss.hp.max(0), boss.max_hp, boss.hp_permille / 10),
                area,
                1,
                text_style,
                buf,
            );
            render_modal_line(if boss.final_phase { "Phase: final" } else { "Phase: normal" }, area, 2, muted_style, buf);
            let progress = if boss.kind == BossKind::NightMaw {
                format!("Split: {}", if boss.split_triggered { "yes" } else { "no" })
            } else {
                let triggered = boss.escort_triggered.iter().filter(|&&t| t).count();
                format!("Escort: {triggered}/{} triggered", boss.escort_triggered.len())
            };
            render_modal_line(&progress, area, 3, muted_style, buf);
            render_modal_line(&format!("Bodies {}", boss.bodies.len()), area, 4, muted_style, buf);
        }
        Inspect::Wave => {
            render_modal_line(&format!("Wave {}/{}", snapshot.wave, WAVE_COUNT), area, 0, text_style, buf);
            render_modal_line(&pet_arcade_phase_label(&snapshot.phase), area, 1, muted_style, buf);
            match &snapshot.wave_plan {
                Some(plan) => {
                    let composition: String = EnemyKind::ALL
                        .iter()
                        .filter_map(|kind| {
                            let count = plan.spawns.iter().filter(|spawn| spawn.kind == *kind).count();
                            (count > 0).then(|| format!("{} x{count}", enemy_kind_label(*kind)))
                        })
                        .collect::<Vec<_>>()
                        .join("  ");
                    render_modal_line(&composition, area, 2, muted_style, buf);
                    if let Some(boss) = plan.boss {
                        render_modal_line(&format!("Boss: {}", boss_kind_label(boss)), area, 3, muted_style, buf);
                    }
                }
                None => {
                    render_modal_line("no plan (Build phase)", area, 2, muted_style, buf);
                }
            }
        }
    }
}

fn tower_kind_label(kind: TowerKind) -> &'static str {
    match kind {
        TowerKind::Needle => "Needle",
        TowerKind::Bell => "Bell",
        TowerKind::Prism => "Prism",
        TowerKind::EmberNest => "EmberNest",
        TowerKind::Moonwell => "Moonwell",
        TowerKind::Relay => "Relay",
    }
}

/// The single-letter glyph a tower-placement drag's own carried ghost
/// (`render_drag_preview`) shows -- a host-side duplicate of `gate4agent-
/// arcade-pet-bastion-render`'s own PRIVATE `tower_glyph` (not reusable
/// from here, same reason `tower_kind_label` above already duplicates that
/// crate's own kind names instead of importing them): both happen to be
/// each kind's own first letter today, so this is purely cosmetic and
/// never drifts out of sync with what a PLACED tower actually paints as.
fn tower_kind_glyph(kind: TowerKind) -> char {
    match kind {
        TowerKind::Needle => 'N',
        TowerKind::Bell => 'B',
        TowerKind::Prism => 'P',
        TowerKind::EmberNest => 'E',
        TowerKind::Moonwell => 'M',
        TowerKind::Relay => 'R',
    }
}

/// A host-side duplicate of `gate4agent-arcade-pet-bastion-render`'s own
/// PRIVATE `tower_tile_id` table (`lib.rs`) -- same reason `tower_kind_
/// glyph`/`tower_kind_label` above already duplicate that crate's own
/// per-kind tables instead of importing them (that crate is off-limits to
/// edit for this pass, and its own tables are `pub(crate)`, not exported).
/// Feeds [`pet_arcade_drag_ghost_sprite`]'s own `DynamicSprite::tile`, so
/// the drag ghost paints as the exact same `TileId` a placed tower of this
/// kind uses (`gate4agent-arcade-pet-bastion-render`'s own `snapshot_to_
/// surface` adapter picks the identical variant for a REAL placement).
fn tower_kind_tile_id(kind: TowerKind) -> TileId {
    match kind {
        TowerKind::Needle => TileId::TowerNeedle,
        TowerKind::Bell => TileId::TowerBell,
        TowerKind::Prism => TileId::TowerPrism,
        TowerKind::EmberNest => TileId::TowerEmberNest,
        TowerKind::Moonwell => TileId::TowerMoonwell,
        TowerKind::Relay => TileId::TowerRelay,
    }
}

/// [`tower_kind_tile_id`]'s own colour counterpart -- a host-side duplicate
/// of `gate4agent-arcade-pet-bastion-render`'s own PRIVATE `tower_base_
/// color` table, for the exact same reason.
fn tower_kind_base_color(kind: TowerKind) -> ArcadeRgb {
    match kind {
        TowerKind::Needle => ArcadeRgb(200, 200, 200),
        TowerKind::Bell => ArcadeRgb(150, 120, 255),
        TowerKind::Prism => ArcadeRgb(255, 140, 255),
        TowerKind::EmberNest => ArcadeRgb(255, 110, 40),
        TowerKind::Moonwell => ArcadeRgb(110, 200, 255),
        TowerKind::Relay => ArcadeRgb(180, 180, 80),
    }
}

/// The pixel tier's own carried-tower drag ghost -- see this fn's own call
/// site (`render_pet_arcade`'s pixel-tier branch) for why it is pushed into
/// `dynamic`, never `strokes`. Snapped to whichever board tile is currently
/// under `(column, row)` (the SAME discrete tile `HitTarget::PetArcadeTile`
/// would resolve a drop at this point to, and the same tile `pet_arcade_
/// pixel_highlight_strokes` outlines for legality) rather than following
/// the pointer at sub-tile precision -- so the ghost always lands centred
/// exactly on one of the legality-tinted outlines it is being dragged
/// over, never straddling two. `None` while the cursor sits outside `dest`
/// (still over the palette, or off the board entirely -- nothing to snap
/// to yet) or `footprint_w` is degenerate (the narrow-terminal glyph
/// footprint this fn's own caller already excludes via `pixel_tier_fits`,
/// guarded here too since this is cheap and this fn has no other caller to
/// rely on that upstream guard).
fn pet_arcade_drag_ghost_sprite(kind: TowerKind, column: u16, row: u16, dest: Rect, footprint_w: u16) -> Option<DynamicSprite> {
    let (tile_x, tile_y) = pet_arcade_drag_hovered_tile(column, row, dest, footprint_w)?;
    Some(DynamicSprite {
        tile: tower_kind_tile_id(kind),
        variant: 0,
        fg: tower_kind_base_color(kind),
        bg: None,
        tile_x: tile_x as f64 + 0.5,
        tile_y: tile_y as f64 + 0.5,
        scale: 1.0,
        // Semi-transparent -- "пусть сюда рисуется башня, а не тянется
        // надпись", but still visibly a PREVIEW, not a placed tower (a
        // real placed tower always paints at `alpha: 1.0`, see `paint_
        // overlay_layer`'s own call into `paint_tile`).
        alpha: 0.6,
    })
}

/// A sixel image is raster painted directly over the terminal and obeys
/// no z-order of its own (see `LayoutRects::sixel_icons`'s own doc
/// comment) -- nothing downstream can tell "this placement is now
/// covered by a modal" on its own, `client::flush_sixel_icon_into` only
/// ever sees whatever `render::render` hands it. So occlusion is decided
/// HERE, once, at the very end of `render::render`, after every base-
/// content and overlay renderer above has already run and registered
/// whatever it painted (`LayoutRects::overlays`, via `LayoutRects::
/// note_overlay`).
///
/// A placement survives unless some overlay registered AFTER it was
/// pushed (the placement's own index in `sixel_icons` is STRICTLY LESS
/// THAN that overlay's `OverlayRegion::drawn_before` -- i.e. fewer
/// placements existed at the moment the overlay claimed its rect than
/// this placement's own position, so the overlay's rect did not exist
/// yet when this placement was painted, and necessarily painted on top
/// of it afterward) has an intersecting rect. This is an index cutoff,
/// not a draw-order guess dressed up: every overlay renderer calls
/// `note_overlay` for its own frame BEFORE painting any of its own
/// content (including its own icons, e.g. a control strip hosted inside
/// the Settings modal -- see `render_settings`'s own `render_workspace_
/// files`/`render_roster` dispatch), so an overlay's own placements
/// always sit at an index >= its own `drawn_before` marker -- `index <
/// drawn_before` is false for them, so they never match their own
/// entry -- while a STILL LATER overlay (a context menu popped open
/// over an already-open modal) has a HIGHER `drawn_before` than those
/// placements' own index and so correctly keeps occluding them, matching
/// what actually ends up on screen. Base content (pushed before any
/// overlay ran) sits at the lowest indices, below every overlay's own
/// `drawn_before`, and so is tested against all of them, as expected.
///
/// Partial intersection counts as covered -- there is no way to clip a
/// sixel to a sub-rect, so a half-covered placement is dropped whole,
/// never left to paint a corner that peeks out from under a modal.
///
/// Dropping a placement here removes it from `client::flush_sixel_icon_
/// into`'s own `emitted` set for this frame; that function already
/// treats any of its OWN remembered placements not reused at the exact
/// same rect as vacated and explicitly repaints the real, already-
/// correct content now sitting there (`clear_rect`, reading `screen.
/// current()` -- the cell buffer `render::render` just finished writing,
/// e.g. the modal's own border/text) -- no change needed there at all,
/// this was simply the input it was never given.
fn drop_sixel_icons_covered_by_overlays(layout: &mut LayoutRects) {
    let overlays = std::mem::take(&mut layout.overlays);
    let placements = std::mem::take(&mut layout.sixel_icons);
    layout.sixel_icons = placements
        .into_iter()
        .enumerate()
        .filter(|(index, placement)| {
            !overlays.iter().any(|overlay| {
                *index < overlay.drawn_before && !placement.rect.intersect(overlay.rect).is_empty()
            })
        })
        .map(|(_, placement)| placement)
        .collect();
    layout.overlays = overlays;
}

/// The pixel tier's own single-placement analogue of [`drop_sixel_icons_
/// covered_by_overlays`] above -- same index-cutoff reasoning (an overlay
/// registered AT OR AFTER this placement's own [`PetArcadePixelPlacement::
/// overlays_before`] marker painted on top of it and so must occlude it
/// whole; partial intersection counts as fully covered, same as that fn's
/// own doc comment explains -- there is no way to clip a sixel image to a
/// sub-rect), just keyed off `layout.overlays`'s own length at push time
/// rather than `sixel_icons`'s, since this placement is never itself a
/// member of that list (see [`PetArcadePixelPlacement`]'s own doc comment
/// for why). Must run AFTER `drop_sixel_icons_covered_by_overlays` at the
/// end of `render::render` -- that fn takes `layout.overlays` out
/// (`std::mem::take`) and puts it back before returning, so this only sees
/// a complete `overlays` list once that call has already finished.
fn drop_pet_arcade_pixel_frame_if_covered(layout: &mut LayoutRects) {
    let Some(placement) = &layout.pet_arcade_pixel_frame else {
        return;
    };
    let covered = layout
        .overlays
        .iter()
        .skip(placement.overlays_before)
        .any(|overlay| !placement.rect.intersect(overlay.rect).is_empty());
    if covered {
        layout.pet_arcade_pixel_frame = None;
    }
}

/// One rail button on the activity rail: a view-select action plus the
/// current selected/active state driving its accent styling, plus which
/// baked icon (`icons::IconId`) represents it. EVERY current rail
/// button carries a real baked icon (see `render_activity_rail`'s own
/// construction of `top` and the bottom group) -- there is no more
/// block-art fallback tier; `app::RailIcons` picks whether `icon` (the
/// baked sixel raster) or `ascii` (the plain-text fallback) paints,
/// globally, for the whole rail, not per button (see `render_rail_
/// button`'s own match). `glyph`/`ascii` stay plain single-character
/// labels, used only where the baked icon cannot fit: the short-terminal
/// fallback (`block.height` shorter than [`rail_button_body_rows`]'s own
/// tier) and `RailIcons::Ascii` mode's own tall-body label.
struct RailButton {
    target: HitTarget,
    glyph: &'static str,
    ascii: &'static str,
    selected: bool,
    icon: icons::IconId,
}

/// Ascii tier's own tall-body row count: a plain centered text label, not
/// a baked asset with its own pixel footprint to derive a row count from
/// the way `RailIcons::Sixel` does (see [`icons::SIXEL_ICON_CELLS_TALL`]),
/// so this is a standalone constant rather than a re-exported bake-tool
/// measurement. Kept at 3 -- the same body height this tier always had,
/// now independent of the removed Braille tier's own former asset height
/// it used to happen to match.
const ASCII_RAIL_BODY_ROWS: u16 = 3;

/// A rail button's own highlighted-body row count when there is room for
/// the tall treatment, one tier at a time -- the fix for "a rail button
/// is 3 rows tall but its sixel icon occupies exactly 2 rows, leaving a
/// dead row underneath" (icon size unchanged -- see [`icons::
/// SIXEL_ICON_WIDTH_PX`]'s own doc comment): `Sixel`'s own highlighted
/// body shrinks to EXACTLY [`icons::SIXEL_ICON_CELLS_TALL`] (2) rows, the
/// icon's own real footprint, so there is no leftover accent-colored row
/// the icon doesn't reach. `Ascii` stays at [`ASCII_RAIL_BODY_ROWS`] (3):
/// a centered text label, not an image with its own pixel footprint to
/// land evenly. The gap between two buttons (and the accent-bar column's
/// own height) both derive from whatever this returns, never a second
/// hand-tuned number -- see `render_activity_rail`'s own use of this fn.
fn rail_button_body_rows(icons: RailIcons) -> u16 {
    match icons {
        RailIcons::Sixel => icons::SIXEL_ICON_CELLS_TALL,
        RailIcons::Ascii => ASCII_RAIL_BODY_ROWS,
    }
}

/// Draws a single activity-rail entry as a real button. When there is
/// room (`block.height >= rail_button_body_rows(icons)`) this paints a
/// body exactly that many rows tall -- `block` inset by 1 column on each
/// side so it reads as a filled button block rather than a thin accent
/// stripe -- with the glyph/ascii label centered on the middle row:
/// `theme.active` at rest, `theme.accent` when selected, bold in both
/// states, and a `▎` accent bar down `block`'s leftmost column on every
/// body row while selected. `theme.active` at rest is DELIBERATELY the
/// SAME colour the rail column itself paints (`Color::Reset` in
/// `PtyColorMode::Inherited`, so the button is genuinely invisible until
/// selected; `ACTIVE_BG` in `PtyColorMode::GateOverride`, that mode's
/// own stated theme, still distinct from `theme.panel` there) -- an
/// UN-selected button is not a real state the owner needs to see, only a
/// SELECTED one is. The `RailIcons::Sixel` tier's own body must track
/// this EXACT SAME rule (never a fixed constant of its own) because
/// `client::flush_sixel_icon_into` composites that placement's icon
/// against whichever concrete RGB `icons::resolve_variant_background`
/// resolves for it using this SAME `PtyColorMode`-dependent logic -- see
/// that fn's own doc comment and `icons::SixelVariant`'s own doc comment
/// for the full reasoning; `Ascii` needs no such care (plain text, no
/// raster to keep in sync). Below `rail_button_body_rows(icons)` it falls
/// back to the original thin single row so every button and its hit
/// region still exist on a cramped terminal. Always registers `button.
/// target` as a hit region across the full block (including the margin/
/// accent column) so the accent bar is clickable too.
fn render_rail_button(
    block: Rect,
    button: &RailButton,
    icons: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if block.width == 0 || block.height == 0 {
        return;
    }
    let label = match icons {
        RailIcons::Sixel => button.glyph,
        RailIcons::Ascii => button.ascii,
    };

    if block.height < rail_button_body_rows(icons) {
        // Short-terminal fallback: the original thin single-row button.
        let bg = theme.panel;
        fill_rect(block, bg, buf);
        let has_accent_column = block.width >= 2;
        let label_area = if has_accent_column {
            Rect::new(block.x + 1, block.y, block.width - 1, 1)
        } else {
            block
        };
        Paragraph::new(centered_label(label, label_area.width as usize))
            .style(
                Style::default()
                    .fg(if button.selected { theme.text } else { theme.muted })
                    .bg(bg)
                    .add_modifier(if button.selected { Modifier::BOLD } else { Modifier::empty() }),
            )
            .render(label_area, buf);
        if has_accent_column && button.selected {
            let cell = buf.get_mut(block.x, block.y);
            cell.symbol = "▎".into();
            cell.style = Style::default().fg(theme.active_tab_text).bg(bg);
        }
        layout.hits.push(HitRegion { rect: block, target: button.target.clone() });
        return;
    }

    // No button states a background of its own, selected or not. The
    // active view is already marked by the accent bar in the button's own
    // left margin column, and a second, louder marker for the same state
    // reads as a coloured plate under the icon rather than as selection.
    // `theme.active` is the SAME colour `render_activity_rail`'s own
    // panel fill uses -- `Color::Reset` in `PtyColorMode::Inherited`, so
    // the button body is whatever the terminal's real background is;
    // `ACTIVE_BG` in `PtyColorMode::GateOverride`, that mode's own
    // deliberate stated theme. Because the body never changes colour, the
    // sixel placement never needs a second composited variant either.
    let bg = theme.active;
    let body = Rect::new(
        block.x.saturating_add(1),
        block.y,
        block.width.saturating_sub(2),
        block.height,
    );
    fill_rect(body, bg, buf);
    let fg = theme.text;
    let style = Style::default().fg(fg).bg(bg).add_modifier(Modifier::BOLD);
    match icons {
        RailIcons::Sixel => {
            // The real pixels are written by `client::run`'s post-flush
            // hook, not here. This only reserves the icon's own cell
            // footprint (already a plain `bg`-filled blank from the
            // `fill_rect` above -- nothing further is drawn on top of
            // it) and records where the flush hook should draw it, plus
            // `button.selected` (part of the flush hook's own gating
            // signature -- see `SixelIconPlacement`'s own doc comment).
            let icon_area = Rect::new(
                body.x,
                body.y,
                body.width.min(icons::SIXEL_ICON_CELLS_WIDE),
                body.height.min(icons::SIXEL_ICON_CELLS_TALL),
            );
            let variant = icons::SixelVariant::GateActive;
            layout.sixel_icons.push(SixelIconPlacement { icon: button.icon, rect: icon_area, variant, size: SixelIconSize::Rail, family });
        }
        RailIcons::Ascii => {
            let label_row = Rect::new(body.x, body.y + block.height / 2, body.width, 1);
            Paragraph::new(centered_label(label, label_row.width as usize))
                .style(style)
                .render(label_row, buf);
        }
    }
    if button.selected {
        for y in block.y..block.bottom() {
            let cell = buf.get_mut(block.x, y);
            cell.symbol = "▎".into();
            cell.style = Style::default().fg(theme.active_tab_text).bg(bg);
        }
    }
    layout.hits.push(HitRegion { rect: block, target: button.target.clone() });
}

/// Draws one inline, single-row icon button INSIDE `rect` -- `rect` is
/// never resized or repositioned here, so every call site keeps
/// registering the exact same [`HitRegion`] it always did; this only
/// repaints what is visually inside it. Unlike the activity rail's own
/// 4-cell x 2/3-row [`render_rail_button`], these buttons live in dense
/// single-row panel lists (the Explorer/Git sidebar panels and their
/// modals) where a rail-sized icon does not fit -- see `icons.rs`'s own
/// "Strip tier" doc section for the baked asset size this draws
/// (`icons::sixel_strip`, the SAME asset [`render_control_strip_button`]
/// already uses, not a runtime downscale).
///
/// This used to draw the much smaller Compact-tier asset (exactly one
/// assumed terminal cell) instead, and every caller used to pass a
/// trailing text label to paint right after it -- a 1-cell icon read as
/// an illegible speck on its own, so the word next to it was the only
/// thing telling a reader the speck was a button at all. Moving to the
/// Strip tier's 2-cell asset fixes the legibility problem directly, and
/// the trailing-text parameter is gone WITH it, not kept alongside a
/// bigger icon: once a glyph is actually big enough to read, a word
/// beside it doesn't clarify the control, it visually splits ONE button
/// into "a small picture" and "an unrelated bit of text" that a reader
/// cannot tell is (or isn't) part of the same click target. Every caller
/// that used to disambiguate two same-icon controls with a trailing word
/// (e.g. "working diff"/"staged diff", "cancel task"/"retry task") was
/// moved onto two DISTINCT `IconId`s instead (see e.g. [`icons::IconId::
/// Diff`]/[`icons::IconId::DiffAdded`], [`icons::IconId::DebugStop`]/
/// [`icons::IconId::DebugRestart`]) -- the icon alone always carries the
/// control's own meaning now, never an icon plus a disambiguating word.
///
/// `RailIcons::Ascii` mode is UNCHANGED by any of this: it still paints
/// `ascii_label` across the whole `rect`, ignoring `icon` entirely,
/// exactly as it always has.
fn render_compact_icon_button(
    rect: Rect,
    icon: icons::IconId,
    ascii_label: &str,
    style: Style,
    tier: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    if rect.width == 0 || rect.height == 0 {
        return;
    }
    fill_rect(rect, style.bg, buf);
    match tier {
        RailIcons::Ascii => {
            Paragraph::new(truncate_cells(ascii_label, rect.width as usize))
                .style(style)
                .render(rect, buf);
        }
        RailIcons::Sixel => {
            // Same split as the rail's own sixel branch: this only
            // reserves the icon's cell footprint (already a plain
            // `style.bg`-filled blank from the `fill_rect` above) and
            // records where `client::run`'s post-flush hook should
            // paint it -- see `SixelIconPlacement`'s own doc comment.
            let icon_width = icons::STRIP_SIXEL_ICON_CELLS_WIDE.min(rect.width);
            let icon_area = Rect::new(rect.x, rect.y, icon_width, 1);
            // `GateActive` unconditionally, the same choice the old
            // Compact-tier code made here (see `SixelIconSize::Compact`'s
            // own doc comment for why that was inert there): unlike
            // [`render_control_strip_button`]'s own single background
            // (`theme.active`, never selected), these buttons paint over
            // several different backgrounds across the Explorer/Git
            // panels and their modals (panel/active/accent/surface/
            // modal). Picking a variant that actually matches each
            // caller's own background is real compositing work this
            // task's own brief explicitly put out of scope ("do not
            // re-open the sixel compositing work for the compact tier");
            // `GateActive` is the closest match for the majority of this
            // fn's own callers (theme.panel in `Inherited`, theme.active
            // in `GateOverride`) and an accepted, known approximation
            // everywhere else, same as it already was before this icon
            // moved to a composited asset at all.
            layout.sixel_icons.push(SixelIconPlacement {
                icon,
                rect: icon_area,
                variant: icons::SixelVariant::GateActive,
                size: SixelIconSize::Strip,
                family,
            });
        }
    }
}

/// Cell width a [`render_compact_icon_button`] call will actually occupy,
/// mirroring that function's own paint logic exactly: the ASCII tier's
/// own `cell_width(ascii_label)` (the whole point of that tier is
/// painting the original bracketed label unchanged), or the Sixel
/// tier's fixed `STRIP_SIXEL_ICON_CELLS_WIDE`, alone -- there is no
/// trailing text to budget room for any more (see [`render_compact_icon_
/// button`]'s own doc comment). Callers that used to size a `Rect` from
/// a bracketed label's own literal width (e.g. `cell_width("[Harness
/// links]")`) call this instead, so the button's hit rect shrinks to
/// match its new, narrower icon body rather than keeping the old text's
/// footprint.
fn compact_icon_button_width(ascii_label: &str, tier: RailIcons) -> u16 {
    match tier {
        RailIcons::Ascii => cell_width(ascii_label) as u16,
        RailIcons::Sixel => icons::STRIP_SIXEL_ICON_CELLS_WIDE,
    }
}

/// Icon-aware sibling of [`render_toolbar_segment`] for a Harness board/
/// task-detail/monitor/surface-toolbar segment that should draw as a
/// compact icon in `RailIcons::Sixel` mode while keeping the segment's
/// original bracketed label, unchanged, in `RailIcons::Ascii` mode -- see
/// [`render_compact_icon_button`]'s own doc comment for that split.
/// `render_toolbar_segment` itself has no icon parameter or tier/family
/// to switch on: most of its callers draw no icon at all, so this exists
/// next to it rather than growing that one function's own signature for
/// every caller. Same x-cursor contract as `render_toolbar_segment`:
/// returns the position the caller's next segment should start from.
fn render_toolbar_icon_segment(
    icon: icons::IconId,
    ascii_label: &str,
    x: u16,
    area: Rect,
    style: Style,
    target: Option<HitTarget>,
    tier: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) -> u16 {
    if x >= area.right() {
        return x;
    }
    let width = compact_icon_button_width(ascii_label, tier)
        .min(area.right().saturating_sub(x));
    if width == 0 {
        return x;
    }
    let rect = Rect::new(x, area.y, width, 1);
    render_compact_icon_button(rect, icon, ascii_label, style, tier, family, buf, layout);
    if let Some(target) = target {
        layout.hits.push(HitRegion { rect, target });
    }
    x.saturating_add(width)
}

/// Height, in cell rows, of one sidebar content panel's own dedicated
/// control-plane strip (see [`render_control_strip`]): a single row of
/// real buttons, each hosting the STRIP tier's own dedicated sixel asset
/// (`icons::STRIP_SIXEL_ICON_CELLS_WIDE` x `_TALL` == 2x1, an exact fit).
/// Roughly a quarter the area of the 4-cell x 2-row body this strip used
/// before its own resize (the rail itself is unchanged and still uses
/// that original size -- see `render_rail_button`).
const CONTROL_STRIP_BUTTON_ROWS: u16 = 1;
/// One more row for the thin `─` separator painted directly under the
/// strip's own button row -- see [`render_control_strip`]'s own body.
const CONTROL_STRIP_ROWS: u16 = CONTROL_STRIP_BUTTON_ROWS + 1;
/// One strip button's own cell width -- exactly `icons::
/// STRIP_SIXEL_ICON_CELLS_WIDE` (2), so the sixel tier's own strip-size
/// asset fills the whole button body with no runtime scaling.
const CONTROL_STRIP_BUTTON_WIDTH: u16 = icons::STRIP_SIXEL_ICON_CELLS_WIDE;
/// Blank columns between two adjacent strip buttons.
const CONTROL_STRIP_BUTTON_GAP: u16 = 1;
/// Minimum panel height (the strip's own [`CONTROL_STRIP_ROWS`], plus at
/// least 1 title row, plus at least 2 content rows below that) below
/// which [`control_strip_fits`] rejects the strip in favor of the pre-
/// strip single-row inline buttons -- derived from [`CONTROL_STRIP_ROWS`]
/// above, so it shrinks along with the strip's own resize.
const CONTROL_STRIP_MIN_PANEL_ROWS: u16 = CONTROL_STRIP_ROWS + 1 + 2;
/// Minimum panel width to fit at least 2 strip buttons side by side
/// (`2 * CONTROL_STRIP_BUTTON_WIDTH + 1 * CONTROL_STRIP_BUTTON_GAP`) --
/// this strip's own "too narrow to fit at least two buttons" threshold.
const CONTROL_STRIP_MIN_PANEL_COLUMNS: u16 =
    CONTROL_STRIP_BUTTON_WIDTH * 2 + CONTROL_STRIP_BUTTON_GAP;

/// True when `area` has room for a sidebar content panel's own full
/// control-plane strip (see [`render_control_strip`]) -- the Explorer/
/// Files and Git panels share these same thresholds; neither is panel-
/// specific. Below either bound the CALLER keeps rendering its own pre-
/// strip single-row inline buttons instead (see `render_workspace_
/// files`/`render_git_snapshot`'s own fallback branches), so no hit
/// target is ever lost on a cramped sidebar.
fn control_strip_fits(area: Rect) -> bool {
    area.height >= CONTROL_STRIP_MIN_PANEL_ROWS && area.width >= CONTROL_STRIP_MIN_PANEL_COLUMNS
}

/// One action button hosted in a sidebar content panel's own control-
/// plane strip -- see [`render_control_strip`]. `enabled` mirrors the
/// button's own pre-strip visibility gate (e.g. NewFile/NewDirectory
/// only when a workspace is selected) so relocating it into the strip
/// does not change WHEN it can be clicked, only WHERE it is drawn; a
/// disabled button occupies no slot at all -- the same "just don't
/// render it" convention the pre-strip buttons already used (there is
/// no disabled/greyed-out visual state anywhere else in this sidebar to
/// match instead).
struct ControlStripButton {
    icon: icons::IconId,
    target: HitTarget,
    enabled: bool,
}

/// Draws one sidebar content panel's own control-plane strip: a full-
/// width, [`CONTROL_STRIP_BUTTON_ROWS`]-tall row of `buttons` (left to
/// right, [`CONTROL_STRIP_BUTTON_GAP`] apart, each [`CONTROL_STRIP_
/// BUTTON_WIDTH`] cells -- see [`render_control_strip_button`] for one
/// button's own paint) on the panel background, plus a thin `─`
/// separator on the row directly under it. Returns the panel's own
/// remaining area BELOW the strip (title row, then content), already
/// shrunk by [`CONTROL_STRIP_ROWS`] -- the caller must render everything
/// else into that returned rect, never the original `area`, so nothing
/// overdraws the strip. The caller must have already checked
/// [`control_strip_fits`]; this fn does not fall back on its own.
fn render_control_strip(
    area: Rect,
    buttons: &[ControlStripButton],
    theme: Theme,
    tier: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) -> Rect {
    let strip = Rect::new(area.x, area.y, area.width, CONTROL_STRIP_BUTTON_ROWS.min(area.height));
    // Inherits `theme.panel`, same as every other panel row -- a strip
    // button is never selected (see `render_control_strip_button`'s own
    // doc comment), so it never states a background distinct from its
    // own row either (see that function's own doc comment for the
    // matching fix on the button body itself). Stating `SIDEBAR_BG` here
    // unconditionally used to be this crate's own plate defect one level
    // up: in `PtyColorMode::Inherited`, `theme.panel` is `Color::Reset`
    // (the terminal's own real background), and `SIDEBAR_BG` is a
    // visibly LIGHTER constant than that on the owner's own terminal --
    // stating it painted the whole strip row as a plate, not just each
    // button.
    fill_rect(strip, theme.panel, buf);
    let mut x = strip.x;
    for button in buttons {
        if !button.enabled {
            continue;
        }
        if x.saturating_add(CONTROL_STRIP_BUTTON_WIDTH) > strip.right() {
            break;
        }
        let block = Rect::new(x, strip.y, CONTROL_STRIP_BUTTON_WIDTH, strip.height);
        render_control_strip_button(block, button.icon, button.target.clone(), theme, tier, family, buf, layout);
        x = x
            .saturating_add(CONTROL_STRIP_BUTTON_WIDTH)
            .saturating_add(CONTROL_STRIP_BUTTON_GAP);
    }
    let separator_y = area.y.saturating_add(CONTROL_STRIP_BUTTON_ROWS);
    if separator_y < area.bottom() {
        for cx in area.x..area.right() {
            let cell = buf.get_mut(cx, separator_y);
            cell.symbol = "─".into();
            cell.style = Style::default().fg(theme.border).bg(theme.panel);
        }
    }
    Rect::new(
        area.x,
        area.y.saturating_add(CONTROL_STRIP_ROWS.min(area.height)),
        area.width,
        area.height.saturating_sub(CONTROL_STRIP_ROWS),
    )
}

/// Draws one action button inside a sidebar panel's own control-plane
/// strip (see [`render_control_strip`]): a fixed [`CONTROL_STRIP_
/// BUTTON_WIDTH`]-cell x [`CONTROL_STRIP_BUTTON_ROWS`]-row body hosting
/// the STRIP tier's own dedicated `icons::sixel_strip_family` asset -- an
/// EXACT fit, no cropping. The body paints `theme.active` in every tier
/// and `PtyColorMode` now (`Color::Reset` in `PtyColorMode::Inherited`,
/// so it vanishes into the strip row exactly like [`render_rail_button`]'s
/// own at-rest body does -- see that function's own doc comment for the
/// matching fix and why an un-selected sixel body's cell fill must track
/// `theme.active` exactly, never a fixed constant): these are one-shot
/// actions, never a persisted `selected` view the way `ControlSection`
/// rail buttons are, the same "never shows as active" precedent as the
/// rail's own Settings button, so there is no distinct-accent case here
/// at all -- in `Sixel` mode this button only ever requests
/// `SixelVariant::GateActive`, never `GateAccent`, and `client::flush_
/// sixel_icon_into` resolves that to the exact same `theme.active`-
/// matching background this cell fill paints (`icons::resolve_variant_
/// background`). `RailIcons::Ascii` paints [`icons::ascii`]'s short
/// (<=2 char) catalog label centered on the block, not the long bracket-
/// text labels the pre-strip inline buttons used -- those were sized for
/// a much wider single-row rect and cannot fit this fixed narrow body.
fn render_control_strip_button(
    block: Rect,
    icon: icons::IconId,
    target: HitTarget,
    theme: Theme,
    tier: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    if block.width == 0 || block.height == 0 {
        return;
    }
    let bg = theme.active;
    fill_rect(block, bg, buf);
    match tier {
        RailIcons::Sixel => {
            let icon_area = Rect::new(
                block.x,
                block.y,
                block.width.min(icons::STRIP_SIXEL_ICON_CELLS_WIDE),
                block.height.min(icons::STRIP_SIXEL_ICON_CELLS_TALL),
            );
            layout.sixel_icons.push(SixelIconPlacement {
                icon,
                rect: icon_area,
                variant: icons::SixelVariant::GateActive,
                size: SixelIconSize::Strip,
                family,
            });
        }
        RailIcons::Ascii => {
            let row = Rect::new(block.x, block.y + block.height / 2, block.width, 1);
            Paragraph::new(centered_label(icons::ascii(icon), row.width as usize))
                .style(Style::default().fg(theme.text).bg(bg).add_modifier(Modifier::BOLD))
                .render(row, buf);
        }
    }
    layout.hits.push(HitRegion { rect: block, target });
}

/// Packs one inline compact-icon button immediately to the LEFT of
/// `*cursor_x`, `width` cells wide, on `area`'s own top row (`area.y`)
/// -- the pre-strip fallback title-row buttons (see [`control_strip_
/// fits`]'s own doc comment for when this path runs instead of the
/// strip). `*cursor_x` is both the right boundary to butt up against
/// (already excluding any gap -- the caller's very first call passes
/// `area`'s own right edge, flush, and every button drawn here already
/// leaves its own 1-column gap for whatever packs next) and, on
/// success, gets advanced past the button just drawn plus that same
/// 1-column gap. Renders nothing and leaves `*cursor_x` untouched when
/// there is no room -- the same "drop what doesn't fit" behaviour the
/// pre-existing NewFile/NewDirectory guard already had, just
/// generalized to more buttons.
fn pack_inline_button_left(
    area: Rect,
    cursor_x: &mut u16,
    width: u16,
    icon: icons::IconId,
    target: HitTarget,
    style: Style,
    tier: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    if cursor_x.saturating_sub(area.x) < width {
        return;
    }
    let x = *cursor_x - width;
    let rect = Rect::new(x, area.y, width, 1);
    render_compact_icon_button(rect, icon, icons::ascii(icon), style, tier, family, buf, layout);
    layout.hits.push(HitRegion { rect, target });
    *cursor_x = x.saturating_sub(1);
}

fn render_activity_rail(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    // Inherits `theme.panel`, in every `RailIcons` mode: this USED to
    // state an explicit `SIDEBAR_BG` here whenever the rail could host a
    // sixel icon, on the premise that a sixel button's own body already
    // paints an explicit truecolor background (`ACTIVE_BG`/`MAUVE`), so
    // the column around it had to match. That premise produced the
    // actual regression: in `PtyColorMode::Inherited`, `theme.panel` is
    // `Color::Reset` -- the terminal's own REAL background -- and
    // `SIDEBAR_BG` is a visibly LIGHTER constant than that on the
    // owner's own terminal (measured (12,12,12) vs `SIDEBAR_BG`'s
    // (24,24,37)), so the whole rail read as a lighter plate standing out
    // against the rest of the screen. The actual fix does not touch this
    // column at all: `render_rail_button`'s own body now tracks
    // `theme.active` at rest instead of a fixed constant (see that
    // function's own doc comment), so it already matches whatever THIS
    // fill paints, in every `PtyColorMode`, without this column ever
    // needing to state a colour of its own.
    fill_rect(area, theme.panel, buf);

    // Top group: primary views. Board only exists once the harness kanban
    // is enabled -- light mode never renders it (same invariant enforced
    // everywhere else the kanban surfaces).
    //
    // FIX2: every button's own `selected` now derives from EXACTLY the
    // state `app::App::board_view_active`'s own doc comment describes --
    // Board reads that field alone; Files/Git/Agents read `!board_view_
    // active && control_section == <theirs>`. The `!board_view_active`
    // guard is what makes the four mutually exclusive: without it, a
    // stale `control_section` left over from before Board was last
    // activated (Board never touches `control_section` -- see that same
    // doc comment for why) could make one of these three ALSO read
    // selected while Board's own button does too. Agents additionally
    // drops the old `matches!(app.roster_mode, Agents | NativeSessions)`
    // sub-check: `control_section` only ever equals `Agents` when `roster_
    // mode` is already one of those two (every path that sets `roster_
    // mode = Workspaces` also sets `control_section = ControlSection::
    // Workspaces` in the same assignment -- see `App::select_roster_mode`/
    // `App::activate_activity_section`), so the sub-check was always
    // redundant with `control_section` alone once stated as an invariant
    // rather than re-checked ad hoc.
    let mut top = vec![
        RailButton {
            target: HitTarget::ActivitySection(ControlSection::Files),
            glyph: "▤",
            ascii: "F",
            selected: !app.board_view_active
                && app.control_section == ControlSection::Files
                && !app.sidebar_collapsed,
            icon: icons::IconId::Files,
        },
        RailButton {
            target: HitTarget::ActivitySection(ControlSection::Git),
            glyph: "◈",
            ascii: "G",
            selected: !app.board_view_active
                && app.control_section == ControlSection::Git
                && !app.sidebar_collapsed,
            icon: icons::IconId::SourceControl,
        },
        RailButton {
            // FIX3: was `HitTarget::RosterMode(RosterMode::Agents)`, which
            // routed through `App::select_roster_mode` directly and so
            // never got the re-click-collapses treatment the other rail
            // buttons already had. Now goes through the exact same
            // `App::activate_activity_section` dispatch as Files/Git
            // (which itself still delegates to `select_roster_mode` for
            // the Agents arm -- see that function's own match -- so the
            // existing_session/native-catalog side effects are unchanged,
            // only the activation SHAPE around them changes).
            target: HitTarget::ActivitySection(ControlSection::Agents),
            glyph: "◉",
            ascii: "A",
            selected: !app.board_view_active
                && app.control_section == ControlSection::Agents
                && !app.sidebar_collapsed,
            icon: icons::IconId::Person,
        },
    ];
    if app.harness_kanban.enabled {
        top.push(RailButton {
            // FIX3/FIX4: was `HitTarget::AgentBoardOpen`, which opened the
            // full kanban straight into the viewport (`App::
            // open_agent_board`) -- inconsistent with every other rail
            // button, which switches SIDEBAR content. Now goes through
            // `App::activate_board_view`, the Board-specific sibling of
            // `activate_activity_section` (same re-click-collapses shape).
            // `HitTarget::AgentBoardOpen` still exists and still opens the
            // full viewport tab -- just from the sidebar Board view's own
            // control-strip button now (`render_agent_board_sidebar`), the
            // Split-presentation roster header's own `[B Board]` button,
            // the `B`/`b` key, and the agent context menu, all unchanged.
            target: HitTarget::ActivityBoard,
            glyph: "▦",
            ascii: "K",
            selected: app.board_view_active && !app.sidebar_collapsed,
            icon: icons::IconId::Project,
        });
    }

    // Each rail entry draws as a real button, [`rail_button_body_rows`]
    // rows tall for the current icon tier, with 1 blank rail-background
    // row between entries. On a terminal too short to fit the top group
    // and the bottom group at that size, everything falls back to the
    // original thin single-row-per-button rendering instead, so every
    // button and its hit region still exist.
    let body_rows = rail_button_body_rows(app.rail_icons);
    let top_len = top.len() as u16;
    let top_rows_tall = top_len.saturating_mul(body_rows).saturating_add(top_len.saturating_sub(1));
    // Bottom group at the tall size: 1 reserved blank row (for the future
    // D3 connection-health dot) + Settings, [`body_rows`] tall -- see the
    // bottom-group block below, which recomputes this same shape using
    // whichever row count `tall_enough` actually decides on.
    let bottom_group_rows_tall = body_rows.saturating_add(1);

    // FIX1: this rail always spans the terminal's FULL height (see
    // `render::render`'s own `SidebarPresentation::Activity` branch --
    // `Rect::new(area.x, area.y, rail_width, area.height)`, `area.height`
    // being `buf.height()` itself) -- so `area`'s own bottom edge IS the
    // terminal's last row, and the bottom group used to anchor directly
    // against `area.bottom()`. That put the Settings gear's icon on the
    // last row EVERY frame, where `client::flush_sixel_icon_into`'s own
    // bottom-row filter (a defense against a real unsolicited-scroll
    // ghosting trap on that row -- see that filter's own doc comment)
    // permanently, silently dropped it: not a rare edge case, a
    // guaranteed miss in every normal-sized terminal. The fix is a
    // LAYOUT rule, not a bigger emission-time guard: reserve exactly one
    // blank row at the rail's own bottom -- `usable_height`/
    // `usable_bottom` below -- so no button this function places can
    // ever land there in the first place. `flush_sixel_icon_into`'s own
    // filter is unchanged and stays exactly what its own doc comment
    // already says: a last-resort safety net for a placement this layout
    // should never produce (e.g. a mid-resize transient frame), which
    // this reservation means it never does in a normal layout -- see
    // `client::tests::activity_rail_gear_and_person_reach_the_real_
    // terminal_in_a_normal_size_window`.
    let usable_height = area.height.saturating_sub(1);
    let usable_bottom = area.bottom().saturating_sub(1);
    let tall_enough = usable_height >= top_rows_tall.saturating_add(bottom_group_rows_tall);
    let button_rows: u16 = if tall_enough { body_rows } else { 1 };
    let step = button_rows.saturating_add(if tall_enough { 1 } else { 0 });

    let mut y = area.y;
    for button in &top {
        if y >= usable_bottom {
            break;
        }
        render_rail_button(Rect::new(area.x, y, area.width, button_rows), button, app.rail_icons, app.icon_family, buf, layout, theme);
        y = y.saturating_add(step);
    }

    // Bottom group, bottom-anchored to `usable_bottom` (NOT `area.bottom()`
    // -- see this function's own `usable_height` doc comment above): one
    // reserved blank row for the future D3 connection-health dot (not
    // drawn yet), then Settings at the very bottom of the USABLE area --
    // the same button treatment and row count as the top group. There is
    // no separate collapse button here any more: the rail's own
    // re-click-the-active-view behaviour
    // (`App::activate_activity_section`) plus the Settings dialog's own
    // toggle/key already cover collapsing, so a dedicated chevron button
    // was a redundant hit target (see `app::HitTarget::SidebarCollapse`'s
    // own doc comment for what still references that target).
    let bottom_rows = button_rows;
    let bottom_group_rows = bottom_rows.saturating_add(1);
    if usable_height >= bottom_group_rows {
        // The row directly above Settings stays untouched (always exactly
        // 1 row, tall or fallback): reserved for the future D3
        // connection-health dot. The row below Settings (`area`'s own
        // true last row) stays untouched too -- that is this fix's own
        // one blank reserved row, never a button.

        render_rail_button(
            Rect::new(area.x, usable_bottom.saturating_sub(bottom_rows), area.width, bottom_rows),
            &RailButton {
                target: HitTarget::ActivitySection(ControlSection::Settings),
                glyph: "◇",
                ascii: "S",
                // Settings opens as an overlay dialog rather than selecting
                // a persistent control_section, so (matching the pre-D1a
                // rail) this row never shows as the active one.
                selected: false,
                icon: icons::IconId::SettingsGear,
            },
            app.rail_icons, app.icon_family,
            buf,
            layout,
            theme,
        );
    }

    // The icon gallery sits directly above Settings in the same bottom
    // group: it is a surface you open and look at, so it needs a button
    // where the other views have theirs. It reuses the Settings dialog's
    // own hit target rather than adding a second one -- one action, one
    // target, two places that can reach it. Drawn only when the group has
    // a whole extra button's worth of rows above the reserved
    // health-dot row, so it never displaces Settings on a short terminal.
    let gallery_group_rows = bottom_group_rows.saturating_add(bottom_rows);
    if usable_height >= top_rows_tall.saturating_add(gallery_group_rows) {
        render_rail_button(
            Rect::new(
                area.x,
                usable_bottom.saturating_sub(gallery_group_rows),
                area.width,
                bottom_rows,
            ),
            &RailButton {
                target: HitTarget::SettingsIconGallery,
                glyph: "▦",
                ascii: "I",
                // A surface tab, not a persistent sidebar view, so the
                // rail never marks it active -- same treatment as
                // Settings directly below it.
                selected: false,
                icon: icons::IconId::Layout,
            },
            app.rail_icons,
            app.icon_family,
            buf,
            layout,
            theme,
        );
    }
}

fn render_inspector(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.height == 0 {
        return;
    }
    let mut x = area.x;
    for mode in [SidebarMode::Files, SidebarMode::Git] {
        let label = format!(" {} ", mode.id());
        let width = (cell_width(&label) as u16).min(area.right().saturating_sub(x));
        if width == 0 {
            break;
        }
        let selected = app.sidebar_mode == mode;
        Paragraph::new(truncate_cells(&label, width as usize))
            .style(
                Style::default()
                    .fg(if selected { theme.active_tab_text } else { theme.muted })
                    .bg(if selected { theme.accent } else { theme.panel })
                    .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
            )
            .render(Rect::new(x, area.y, width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(x, area.y, width, 1),
            target: HitTarget::SidebarMode(mode),
        });
        x = x.saturating_add(width);
    }
    if area.height < 2 {
        return;
    }
    let content = Rect::new(area.x, area.y + 1, area.width, area.height - 1);
    match app.sidebar_mode {
        SidebarMode::Files => render_workspace_files(app, content, buf, layout, theme),
        SidebarMode::Git => render_workspace_git(app, content, buf, layout, theme),
    }
}

fn render_space_list(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.height == 0 {
        return;
    }
    fill_rect(area, theme.panel, buf);
    // Same panel-level/row-level split Files/Git already drew: AddSpace
    // acts on the roster as a whole and RemoveSpace on its own ambient
    // cursor selection (`App::remove_selected_space`, mirroring
    // RemoveWorktree's own strip button, never one specific row a click
    // landed on), so both move into the strip; the per-row Space/
    // SpawnSpace/HarnessLinks buttons in the list below stay exactly
    // where they render today.
    let use_strip = control_strip_fits(area);
    let area = if use_strip {
        render_control_strip(
            area,
            &[
                ControlStripButton { icon: icons::IconId::Add, target: HitTarget::AddSpace, enabled: true },
                ControlStripButton { icon: icons::IconId::Trash, target: HitTarget::RemoveSpace, enabled: true },
            ],
            theme,
            app.rail_icons, app.icon_family,
            buf,
            layout,
        )
    } else {
        area
    };
    if !use_strip {
        let add_label = " + workspace ";
        // `compact_icon_button_width`, not `cell_width(add_label)` alone:
        // that literal sized the OLD icon-plus-word Sixel footprint (and
        // the ascii bracket text unconditionally); now that the control
        // is icon-only in `Sixel` mode, the tier-aware width shrinks to
        // match rather than reserving the old, wider text footprint.
        let add_width = compact_icon_button_width(add_label, app.rail_icons).min(area.width);
        let add_rect = Rect::new(area.x, area.y, add_width, 1);
        render_compact_icon_button(
            add_rect,
            icons::IconId::Add,
            add_label,
            Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion {
            rect: add_rect,
            target: HitTarget::AddSpace,
        });
        let remove_label = " - remove ";
        let remove_width = (cell_width(remove_label) as u16).min(area.width.saturating_sub(add_width));
        let remove_x = area.right().saturating_sub(remove_width);
        if remove_width > 0 {
            let remove_rect = Rect::new(remove_x, area.y, remove_width, 1);
            render_compact_icon_button(
                remove_rect,
                icons::IconId::Trash,
                remove_label,
                Style::default().fg(theme.red).bg(theme.panel),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            layout.hits.push(HitRegion {
                rect: remove_rect,
                target: HitTarget::RemoveSpace,
            });
        }
    }

    // The strip already reserves its own button row (plus separator)
    // above `area`, so unlike the fallback, list content has no add/
    // remove row left to skip -- only the fallback's own inline row
    // needs this offset.
    let header_rows = if use_strip { 0 } else { 1 };
    let rows = app.space_rows();
    let capacity = area.height.saturating_sub(header_rows) as usize / 2;
    let start = app
        .workspaces_scroll
        .min(rows.len().saturating_sub(capacity));
    for (visible_index, (index, (node_index, workspace_index))) in rows
        .into_iter()
        .enumerate()
        .skip(start)
        .take(capacity)
        .enumerate()
    {
        let y = area.y + header_rows + visible_index as u16 * 2;
        let node = &app.nodes[node_index];
        let workspace = &node.workspaces[workspace_index];
        let selected = index == app.selected_space;
        let background = if selected { theme.active } else { theme.panel };
        let (marker, marker_color) = workspace_state(node, workspace, theme);
        fill_rect(Rect::new(area.x, y, area.width, 2.min(area.bottom().saturating_sub(y))), background, buf);
        let spawn_label = " +agent ";
        let spawn_width = (cell_width(spawn_label) as u16).min(area.width);
        let primary_area_width = area.width.saturating_sub(spawn_width);
        let primary_width = primary_area_width.saturating_sub(3) as usize;
        Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![
            Span::styled(format!(" {marker} "), Style::default().fg(marker_color)),
            Span::styled(
                truncate_cells(&workspace.label, primary_width),
                Style::default().fg(theme.text).add_modifier(Modifier::BOLD),
            ),
        ])]))
        .style(Style::default().bg(background))
        .render(Rect::new(area.x, y, primary_area_width, 1), buf);
        let spawn_x = area.right().saturating_sub(spawn_width);
        Paragraph::new(spawn_label)
            .style(
                Style::default()
                    .fg(if selected { theme.teal } else { theme.muted })
                    .bg(background)
                    .add_modifier(Modifier::BOLD),
            )
            .render(Rect::new(spawn_x, y, spawn_width, 1), buf);
        let secondary = format!(
            "{} | {} | {}",
            node.node_id,
            relay_route_label(node.relay_route),
            host_path_display(&workspace.canonical_root),
        );
        Paragraph::new(format!(
            "   {}",
            compact_middle_cells(&secondary, area.width.saturating_sub(3) as usize)
        ))
        .style(
            Style::default()
                .fg(if selected { theme.accent } else { theme.muted })
                .bg(background),
        )
        .render(Rect::new(area.x, y + 1, area.width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(area.x, y, primary_area_width, 1),
            target: HitTarget::Space(index),
        });
        layout.hits.push(HitRegion {
            rect: Rect::new(area.x, y + 1, area.width, 1),
            target: HitTarget::Space(index),
        });
        if selected && app.harness_kanban.enabled {
            if let Some(subject) = app.harness_workspace_links_subject(
                &node.node_id,
                &workspace.workspace_id,
            ) {
                let ascii_label = "[Harness links]";
                let width = compact_icon_button_width(ascii_label, app.rail_icons)
                    .min(area.width);
                let rect = Rect::new(area.right().saturating_sub(width), y + 1, width, 1);
                render_compact_icon_button(
                    rect,
                    icons::IconId::Link,
                    ascii_label,
                    Style::default().fg(theme.teal).bg(background),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                layout.hits.push(HitRegion {
                    rect,
                    target: HitTarget::HarnessLinks(subject),
                });
            }
        }
        layout.hits.push(HitRegion {
            rect: Rect::new(spawn_x, y, spawn_width, 1),
            target: HitTarget::SpawnSpace(index),
        });
    }
}

fn render_inspector_header(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) -> Rect {
    fill_rect(area, theme.panel, buf);
    let selected = app
        .selected_workspace()
        .map(|(node, workspace)| format!("{} / {}", node.node_id, workspace.workspace_id))
        .unwrap_or_else(|| "no workspace".to_owned());
    Paragraph::new(format!(
        " {}",
        compact_middle_cells(&selected, area.width.saturating_sub(1) as usize)
    ))
    .style(Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD))
    .render(Rect::new(area.x, area.y, area.width, 1), buf);
    if app.agent_run_lens.is_some() && area.width > 0 && area.height > 0 {
        let all_label = "[all]";
        let all_width = (cell_width(all_label) as u16).min(area.width);
        let all = Rect::new(area.right().saturating_sub(all_width), area.y, all_width, 1);
        Paragraph::new(all_label)
            .style(Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD))
            .render(all, buf);
        layout.hits.push(HitRegion { rect: all, target: HitTarget::AgentRunAll });
    }
    let scope_rows = u16::from(app.agent_run_lens.is_some() && area.height > 1);
    if scope_rows > 0 {
        let scope = match app.agent_run_git_scope_view() {
            AgentRunGitScopeView::Loading => " run scope: loading...".to_owned(),
            AgentRunGitScopeView::SharedWorkspace => " run scope: shared workspace".to_owned(),
            AgentRunGitScopeView::ExclusiveManagedWorktree { branch, base_commit } => {
                format!(" run scope: exclusive managed worktree | {branch} @ {base_commit}")
            }
            AgentRunGitScopeView::SharedManagedWorktree { branch, base_commit } => {
                format!(" run scope: shared managed worktree | {branch} @ {base_commit}")
            }
        };
        Paragraph::new(truncate_cells(&scope, area.width as usize))
            .style(Style::default().fg(theme.muted).bg(theme.panel))
            .render(Rect::new(area.x, area.y + 1, area.width, 1), buf);
    }
    Rect::new(
        area.x,
        area.y + 1 + scope_rows,
        area.width,
        area.height.saturating_sub(1 + scope_rows),
    )
}

fn render_workspace_files(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let selected = app.selected_workspace().is_some();
    let use_strip = control_strip_fits(area);
    let area = if use_strip {
        render_control_strip(
            area,
            &[
                ControlStripButton { icon: icons::IconId::NewFile, target: HitTarget::NewFile, enabled: selected },
                ControlStripButton { icon: icons::IconId::NewFolder, target: HitTarget::NewDirectory, enabled: selected },
                ControlStripButton { icon: icons::IconId::Add, target: HitTarget::AddSpace, enabled: true },
                ControlStripButton { icon: icons::IconId::Trash, target: HitTarget::RemoveSpace, enabled: true },
                ControlStripButton { icon: icons::IconId::Refresh, target: HitTarget::RefreshWorkspace, enabled: true },
            ],
            theme,
            app.rail_icons, app.icon_family,
            buf,
            layout,
        )
    } else {
        area
    };
    let list = render_inspector_header(app, area, buf, layout, theme);
    if !use_strip && area.width > 0 && area.height > 0 {
        let lens_offset = if app.agent_run_lens.is_some() { 6 } else { 0 };
        let mut cursor_x = area.right().saturating_sub(lens_offset);
        if selected {
            let directory_label = "[+>]";
            let file_label = "[+.]";
            let directory_width = cell_width(directory_label) as u16;
            let file_width = cell_width(file_label) as u16;
            if area.width >= directory_width.saturating_add(lens_offset) {
                let directory = Rect::new(cursor_x - directory_width, area.y, directory_width, 1);
                render_compact_icon_button(
                    directory,
                    icons::IconId::NewFolder,
                    directory_label,
                    Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                layout.hits.push(HitRegion {
                    rect: directory,
                    target: HitTarget::NewDirectory,
                });
                cursor_x = directory.x.saturating_sub(1);
                if directory.x >= area.x.saturating_add(file_width + 1) {
                    let file = Rect::new(directory.x - file_width - 1, area.y, file_width, 1);
                    render_compact_icon_button(
                        file,
                        icons::IconId::NewFile,
                        file_label,
                        Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD),
                        app.rail_icons, app.icon_family,
                        buf,
                        layout,
                    );
                    layout.hits.push(HitRegion {
                        rect: file,
                        target: HitTarget::NewFile,
                    });
                    cursor_x = file.x.saturating_sub(1);
                }
            }
        }
        let accent = Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD);
        let danger = Style::default().fg(theme.red).bg(theme.panel).add_modifier(Modifier::BOLD);
        for (icon, target, style) in [
            (icons::IconId::Add, HitTarget::AddSpace, accent),
            (icons::IconId::Trash, HitTarget::RemoveSpace, danger),
            (icons::IconId::Refresh, HitTarget::RefreshWorkspace, accent),
        ] {
            pack_inline_button_left(area, &mut cursor_x, 4, icon, target, style, app.rail_icons, app.icon_family, buf, layout);
        }
    }
    let Some(inspection) = app.selected_workspace_inspection() else {
        render_inspector_empty(app, list, buf, "loading workspace...", theme);
        return;
    };
    let entry_indices = app.visible_workspace_entry_indices();
    let capacity = list.height as usize;
    let start = app
        .files_scroll
        .min(entry_indices.len().saturating_sub(capacity));
    for (visible, (visible_index, index)) in entry_indices
        .iter()
        .copied()
        .enumerate()
        .skip(start)
        .take(capacity)
        .enumerate()
    {
        let entry = &inspection.entries[index];
        let y = list.y + visible as u16;
        let selected = visible_index == app.files_cursor;
        let background = if selected { theme.active } else { theme.panel };
        let depth = entry.relative_path.depth().min(4);
        let name = repository_path_file_name_display(&entry.relative_path);
        let dirty = workspace_entry_dirty(&entry.relative_path, entry.kind, &inspection.git);
        let dirty_color = dirty.map(|severe| if severe { theme.red } else { theme.yellow });
        let (marker, color) = match entry.kind {
            WorkspaceEntryKind::Directory => (
                if app.directory_is_collapsed(&entry.relative_path) { ">" } else { "v" },
                dirty_color.unwrap_or(theme.teal),
            ),
            WorkspaceEntryKind::File => (
                if dirty.is_some() { "M" } else { "·" },
                dirty_color.unwrap_or(theme.dim),
            ),
        };
        let prefix = format!(" {}{} ", "  ".repeat(depth), marker);
        let name_width = list.width.saturating_sub(cell_width(&prefix) as u16) as usize;
        Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![
            Span::styled(prefix, Style::default().fg(color)),
            Span::styled(
                truncate_cells(&name, name_width),
                Style::default().fg(dirty_color.unwrap_or(theme.text)),
            ),
        ])]))
        .style(Style::default().bg(background))
        .render(Rect::new(list.x, y, list.width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(list.x, y, list.width, 1),
            target: HitTarget::SidebarItem(index),
        });
    }
    if inspection.tree_truncated && list.height > 0 && entry_indices.len() <= capacity {
        Paragraph::new(" ... tree truncated")
            .style(Style::default().fg(theme.yellow).bg(theme.panel))
            .render(Rect::new(list.x, list.bottom() - 1, list.width, 1), buf);
    }
}

fn render_create_workspace_entry(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(dialog) = &app.create_workspace_entry else {
        return;
    };
    let width = 76.min(area.width.saturating_sub(4));
    let height = 10.min(area.height.saturating_sub(2));
    let modal = positioned_modal(
        area,
        width,
        height,
        app.overlay_positions.get(&OverlayId::CreateWorkspaceEntry).copied(),
    );
    layout.create_workspace_entry_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    let title = match dialog.kind {
        WorkspaceEntryKind::File => " create file ",
        WorkspaceEntryKind::Directory => " create directory ",
    };
    Block::bordered()
        .title(title)
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(modal.x, modal.y, modal.width, 1),
        target: HitTarget::CreateWorkspaceEntryDrag,
    });
    render_modal_close(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let inner = Rect::new(modal.x + 1, modal.y + 1, modal.width - 2, modal.height - 2);
    render_modal_line(
        format!("  workspace  {}/{}", dialog.node_id, dialog.workspace_id),
        inner,
        0,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_modal_line(
        format!("> path from workspace root [ {} ]", dialog.path),
        inner,
        2,
        Style::default()
            .fg(theme.active_tab_text)
            .bg(theme.accent)
            .add_modifier(Modifier::BOLD),
        buf,
    );
    let target = normalize_workspace_entry_input(&dialog.path);
    render_modal_line(
        format!(
            "  target     {}/{}",
            dialog.workspace_id,
            if target.is_empty() { "new/hello.txt" } else { &target },
        ),
        inner,
        3,
        Style::default().fg(theme.dim).bg(theme.modal),
        buf,
    );
    let status = if dialog.pending {
        format!("{} creating without overwrite...", app.activity_spinner())
    } else if let Some(error) = &dialog.error {
        error.clone()
    } else {
        "Enter creates. No overwrite; parent must already exist.".to_owned()
    };
    render_modal_line(
        status,
        inner,
        4,
        Style::default()
            .fg(if dialog.error.is_some() { theme.red } else { theme.muted })
            .bg(theme.modal),
        buf,
    );
    let action_y = inner.bottom().saturating_sub(1);
    let submit = Rect::new(
        inner.right().saturating_sub(9),
        action_y,
        9.min(inner.width),
        1,
    );
    Paragraph::new("[Create]")
        .style(Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD))
        .render(submit, buf);
    push_modal_hit(layout, submit, HitTarget::CreateWorkspaceEntrySubmit);
    let cancel = Rect::new(
        submit.x.saturating_sub(9).max(inner.x),
        action_y,
        8.min(inner.width),
        1,
    );
    Paragraph::new("[Cancel]")
        .style(Style::default().fg(theme.text).bg(theme.active))
        .render(cancel, buf);
    push_modal_hit(layout, cancel, HitTarget::CreateWorkspaceEntryCancel);
}

fn render_workspace_git(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let use_strip = control_strip_fits(area);
    let area = if use_strip {
        let selected_removable_worktree = app
            .selected_workspace_inspection()
            .and_then(|inspection| inspection.git.worktrees.get(app.git_cursor))
            .filter(|worktree| !worktree.is_main && !worktree.is_bare && !worktree.locked && !worktree.prunable)
            .map(|_| app.git_cursor);
        render_control_strip(
            area,
            &[
                ControlStripButton { icon: icons::IconId::RepoForked, target: HitTarget::CreateWorktree, enabled: true },
                ControlStripButton {
                    icon: icons::IconId::Trash,
                    target: HitTarget::RemoveWorktree(selected_removable_worktree.unwrap_or_default()),
                    enabled: selected_removable_worktree.is_some(),
                },
                ControlStripButton { icon: icons::IconId::Refresh, target: HitTarget::RefreshWorkspace, enabled: true },
            ],
            theme,
            app.rail_icons, app.icon_family,
            buf,
            layout,
        )
    } else {
        area
    };
    let body = render_inspector_header(app, area, buf, layout, theme);
    let Some(inspection) = app.selected_workspace_inspection() else {
        render_inspector_empty(app, body, buf, "loading workspace...", theme);
        return;
    };
    render_git_snapshot(app, inspection, body, buf, layout, theme, use_strip);
}

fn render_git_snapshot(
    app: &App,
    inspection: &WorkspaceInspection,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    use_strip: bool,
) {
    if area.height == 0 {
        return;
    }
    let git = &inspection.git;
    if !git.is_repository {
        let message = git.diagnostic.as_deref().unwrap_or("not a git repository");
        Paragraph::new(format!(" {}", truncate_cells(message, area.width.saturating_sub(1) as usize)))
            .style(Style::default().fg(theme.muted).bg(theme.panel))
            .render(area, buf);
        return;
    }
    let branch = git.branch.as_deref().unwrap_or("detached");
    if use_strip {
        Paragraph::new(format!(" branch {}", truncate_cells(branch, area.width.saturating_sub(8) as usize)))
            .style(Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD))
            .render(Rect::new(area.x, area.y, area.width, 1), buf);
    } else {
        let mut cursor_x = area.right();
        let refresh_style = Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD);
        pack_inline_button_left(
            area,
            &mut cursor_x,
            4,
            icons::IconId::Refresh,
            HitTarget::RefreshWorkspace,
            refresh_style,
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        let selected_removable_worktree = git
            .worktrees
            .get(app.git_cursor)
            .filter(|worktree| !worktree.is_main && !worktree.is_bare && !worktree.locked && !worktree.prunable)
            .map(|_| app.git_cursor);
        if let Some(index) = selected_removable_worktree {
            let remove_style = Style::default().fg(theme.red).bg(theme.panel).add_modifier(Modifier::BOLD);
            pack_inline_button_left(
                area,
                &mut cursor_x,
                4,
                icons::IconId::Trash,
                HitTarget::RemoveWorktree(index),
                remove_style,
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
        }
        let create = " + worktree ";
        let create_width = cell_width(create) as u16;
        let usable_width = cursor_x.saturating_sub(area.x);
        let branch_width = usable_width.saturating_sub(create_width);
        Paragraph::new(format!(" branch {}", truncate_cells(branch, branch_width.saturating_sub(8) as usize)))
            .style(Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD))
            .render(Rect::new(area.x, area.y, branch_width, 1), buf);
        if branch_width < usable_width {
            let create_rect = Rect::new(area.x + branch_width, area.y, usable_width - branch_width, 1);
            render_compact_icon_button(
                create_rect,
                icons::IconId::RepoForked,
                create,
                Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            layout.hits.push(HitRegion { rect: create_rect, target: HitTarget::CreateWorktree });
        }
    }
    let area = Rect::new(area.x, area.y + 1, area.width, area.height.saturating_sub(1));
    let capacity = area.height as usize;
    let detail_count = git.status.len().saturating_add(git.recent_commits.len());
    let count = git.worktrees.len().saturating_add(detail_count);
    if count == 0 {
        Paragraph::new(" clean workspace")
            .style(Style::default().fg(theme.green).bg(theme.panel))
            .render(area, buf);
        return;
    }
    let start = app.git_scroll.min(count.saturating_sub(capacity));
    for (visible, index) in (start..count).take(capacity).enumerate() {
        let y = area.y + visible as u16;
        let row = Rect::new(area.x, y, area.width, 1);
        if let Some(worktree) = git.worktrees.get(index) {
            let state = if worktree.is_main { "main" } else if worktree.locked { "locked" } else if worktree.prunable { "prunable" } else { "worktree" };
            let branch = worktree.branch.as_deref().unwrap_or("detached");
            let action = if worktree.workspace_id.is_some() { " open " } else { " add " };
            let removable = !worktree.is_main && !worktree.is_bare && !worktree.locked && !worktree.prunable;
            let remove = if removable { " rm " } else { "" };
            let reserved = cell_width(action) + cell_width(remove);
            let label = format!(" {state} {branch} · {}", host_path_display(&worktree.path));
            layout.hits.push(HitRegion { rect: row, target: HitTarget::Worktree(index) });
            Paragraph::new(truncate_cells(&label, area.width.saturating_sub(reserved as u16) as usize))
                .style(Style::default().fg(theme.text).bg(if index == app.git_cursor { theme.active } else { theme.panel }))
                .render(Rect::new(row.x, row.y, row.width.saturating_sub(reserved as u16), 1), buf);
            let action_x = row.right().saturating_sub(reserved as u16);
            let action_rect = Rect::new(action_x, y, cell_width(action) as u16, 1);
            Paragraph::new(action).style(Style::default().fg(theme.teal).bg(theme.panel)).render(action_rect, buf);
            layout.hits.push(HitRegion {
                rect: action_rect,
                target: if worktree.workspace_id.is_some() { HitTarget::Worktree(index) } else { HitTarget::RegisterWorktree(index) },
            });
            if removable {
                let remove_rect = Rect::new(action_rect.right(), y, cell_width(remove) as u16, 1);
                render_compact_icon_button(
                    remove_rect,
                    icons::IconId::Trash,
                    remove,
                    Style::default().fg(theme.red).bg(theme.panel),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                layout.hits.push(HitRegion { rect: remove_rect, target: HitTarget::RemoveWorktree(index) });
            }
        } else {
            let detail_index = index - git.worktrees.len();
            let line = if let Some(entry) = git.status.get(detail_index) {
                let code = format!("{}{}", entry.index_status, entry.worktree_status);
                let current_path = repository_path_display(&entry.path);
                let path = entry.previous_path.as_ref().map_or(current_path.clone(), |previous| {
                    format!("{} -> {current_path}", repository_path_display(previous))
                });
                Line::from_spans(vec![
                    Span::styled(format!(" {code} "), Style::default().fg(theme.yellow).add_modifier(Modifier::BOLD)),
                    Span::styled(
                        truncate_cells(
                            &path,
                            area.width.saturating_sub(4) as usize,
                        ),
                        Style::default().fg(theme.text),
                    ),
                ])
            } else if let Some(commit) = git.recent_commits.get(detail_index.saturating_sub(git.status.len())) {
                Line::from_spans(vec![
                    Span::styled(format!(" {} ", commit.id), Style::default().fg(theme.accent)),
                    Span::styled(truncate_cells(&commit.summary, area.width.saturating_sub(commit.id.len() as u16 + 2) as usize), Style::default().fg(theme.dim)),
                ])
            } else {
                Line::from_spans(Vec::new())
            };
            Paragraph::new(Text::from_lines(vec![line]))
                .style(Style::default().bg(if index == app.git_cursor { theme.active } else { theme.panel }))
                .render(row, buf);
            layout.hits.push(HitRegion { rect: row, target: HitTarget::SidebarItem(index) });
        }
    }
}

fn render_inspector_empty(app: &App, area: Rect, buf: &mut TerminalBuffer, text: &str, theme: Theme) {
    if area.height == 0 {
        return;
    }
    let text = if app.workspace_inspection_pending() { "loading..." } else { text };
    Paragraph::new(format!(" {text}"))
        .style(Style::default().fg(theme.muted).bg(theme.panel))
        .render(area, buf);
}

fn render_roster(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.height == 0 {
        return;
    }
    for x in area.x..area.right() {
        let cell = buf.get_mut(x, area.y);
        cell.symbol = "─".into();
        cell.style = Style::default().fg(theme.border).bg(theme.panel);
    }
    if area.height < 3 {
        return;
    }
    let mut x = area.x;
    for mode in [RosterMode::Agents, RosterMode::Workspaces] {
        let label = format!(" {} ", mode.compact_id());
        let width = (cell_width(&label) as u16).min(area.right().saturating_sub(x));
        if width == 0 {
            break;
        }
        let selected = app.roster_mode == mode
            || (mode == RosterMode::Agents && app.roster_mode == RosterMode::NativeSessions);
        Paragraph::new(truncate_cells(&label, width as usize))
            .style(
                Style::default()
                    .fg(if selected { theme.active_tab_text } else { theme.muted })
                    .bg(if selected { theme.accent } else { theme.panel })
                    .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
            )
            .render(Rect::new(x, area.y + 1, width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(x, area.y + 1, width, 1),
            target: HitTarget::RosterMode(mode),
        });
        x = x.saturating_add(width);
    }
    let board_label = " [B Board] ";
    let board_width = (cell_width(board_label) as u16)
        .min(area.right().saturating_sub(x));
    // The board button belongs to the full harness only (see
    // `App::open_agent_board`'s light gate) — a button that opens nothing
    // must not render.
    if board_width > 0 && app.harness_kanban.enabled {
        let board_x = area.right().saturating_sub(board_width);
        if board_x >= x {
            Paragraph::new(board_label)
                .style(
                    Style::default()
                        .fg(theme.teal)
                        .bg(theme.panel)
                        .add_modifier(Modifier::BOLD),
                )
                .render(Rect::new(board_x, area.y + 1, board_width, 1), buf);
            layout.hits.push(HitRegion {
                rect: Rect::new(board_x, area.y + 1, board_width, 1),
                target: HitTarget::AgentBoardOpen,
            });
        }
    }

    let content = Rect::new(area.x, area.y + 2, area.width, area.height.saturating_sub(2));
    match app.roster_mode {
        RosterMode::Agents | RosterMode::NativeSessions => {
            render_agents_surface(app, content, buf, layout, theme)
        }
        RosterMode::Workspaces => render_space_list(app, content, buf, layout, theme),
    }
}

fn render_agents_surface(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.height == 0 {
        return;
    }
    // The panel-level half of the roster's own actions (only `AddAgent` --
    // per-row actions like `AgentMore`/`AgentRun`/`NativeSessionsOpen` stay
    // inline in whichever list below actually owns the row) gets the same
    // strip Files/Git already carry, same `control_strip_fits` fallback so
    // the button is never lost on a cramped sidebar -- see
    // `render_workspace_files`'s own use of this pair.
    let use_strip = control_strip_fits(area);
    let area = if use_strip {
        render_control_strip(
            area,
            &[ControlStripButton { icon: icons::IconId::Add, target: HitTarget::AddAgent, enabled: true }],
            theme,
            app.rail_icons, app.icon_family,
            buf,
            layout,
        )
    } else {
        area
    };
    if app.existing_session.is_none() || area.height < 5 {
        render_agent_list(app, area, buf, layout, theme, use_strip);
        return;
    }

    // Native results remain a node-scoped subtree until the backend supplies stable
    // global identity annotations. Do not synthesize global rows or deduplicate here.
    render_native_session_list(app, area, buf, layout, theme, use_strip);
}

fn render_agent_list(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    use_strip: bool,
) {
    if area.height == 0 {
        return;
    }
    let roster_label = " managed/live agents ";
    let roster_width = (cell_width(roster_label) as u16).min(area.width);
    Paragraph::new(roster_label)
        .style(Style::default().fg(theme.muted).bg(theme.panel).add_modifier(Modifier::BOLD))
        .render(Rect::new(area.x, area.y, roster_width, 1), buf);
    if !use_strip {
        let add_label = " + agent ";
        let add_width = (cell_width(add_label) as u16).min(area.width);
        let add_x = area.right().saturating_sub(add_width);
        Paragraph::new(add_label)
            .style(Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD))
            .render(Rect::new(add_x, area.y, add_width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(add_x, area.y, add_width, 1),
            target: HitTarget::AddAgent,
        });
    }
    let rows = app.agent_rows();
    let visible_rows = area.height.saturating_sub(1) as usize;
    let start = app
        .agents_scroll
        .min(app.agent_roster_max_scroll(visible_rows));
    let mut y = area.y + 1;
    for (index, key) in rows.iter().enumerate().skip(start) {
        let expanded = app.agent_progress_expanded(key);
        let card_height = if expanded { 5 } else { 2 };
        if y.saturating_add(2) > area.bottom() {
            break;
        }
        let rendered_height = card_height.min(area.bottom().saturating_sub(y));
        let selected = index == app.selected_agent;
        let background = if selected { theme.active } else { theme.panel };
        let more_label = if area.width < 30 { "[act]" } else { "[actions]" };
        let more_width = (cell_width(more_label) as u16).min(area.width);
        let run_label = if area.width < 40 {
            if app.agent_run_lens_key() == Some(key) { "[all]" } else { "[ws]" }
        } else if app.agent_run_lens_key() == Some(key) {
            "[global]"
        } else {
            "[workspace]"
        };
        let mut run_width = (cell_width(run_label) as u16).min(area.width);
        let progress_label = if area.width < 40 {
            if expanded { "[d-]" } else { "[d+]" }
        } else if expanded {
            "[details -]"
        } else {
            "[details +]"
        };
        let mut progress_width = (cell_width(progress_label) as u16).min(area.width);
        let order_label = "[move]";
        let mut order_width = if matches!(key, AgentRowKey::Managed { .. }) {
            cell_width(order_label) as u16
        } else {
            0
        };
        // Shed controls in order of how replaceable they are: the run-lens and
        // progress toggles both fall back to the "[actions]" menu, but the order
        // handle is the only way to reorder a pinned managed agent, so it is kept
        // as long as the title still has room for a few characters. `MIN_TITLE`
        // mirrors the reservation `title_width` makes below (marker + 3 gaps).
        const MIN_TITLE: u16 = 5;
        let fixed_overhead = 6_u16.saturating_add(MIN_TITLE);
        let order_reserved = order_width.saturating_add(u16::from(order_width > 0));
        if fixed_overhead
            .saturating_add(more_width)
            .saturating_add(run_width)
            .saturating_add(progress_width)
            .saturating_add(order_reserved)
            > area.width
        {
            progress_width = 0;
        }
        if fixed_overhead
            .saturating_add(more_width)
            .saturating_add(run_width)
            .saturating_add(order_reserved)
            > area.width
        {
            run_width = 0;
        }
        if fixed_overhead
            .saturating_add(more_width)
            .saturating_add(order_reserved)
            > area.width
        {
            order_width = 0;
        }
        let title_width = area
            .width
            .saturating_sub(3)
            .saturating_sub(more_width)
            .saturating_sub(run_width)
            .saturating_sub(progress_width)
            .saturating_sub(1)
            .saturating_sub(1)
            .saturating_sub(1)
            .saturating_sub(order_width)
            .saturating_sub(u16::from(order_width > 0));
        let (title, marker, color, secondary) = match key {
            AgentRowKey::Managed { .. } => {
                let Some(record) = app.find_managed_session(key) else {
                    continue;
                };
                let active = record
                    .active_session
                    .as_ref()
                    .and_then(|address| app.find_session(address));
                let (marker, color, state) = if record.state
                    == gate4agent_node_protocol::ManagedSessionState::Live
                {
                    active
                        .map(|session| session_state(session, theme))
                        .unwrap_or_else(|| managed_session_state(record.state, theme))
                } else {
                    managed_session_state(record.state, theme)
                };
                let state = if record.mode == gate4agent_node_protocol::SessionMode::Inline {
                    format!("{state} inline")
                } else {
                    state.to_owned()
                };
                let mut secondary = format!(
                    "{state} | {} | {} | {}",
                    record.provider, record.workspace_id, record.node_id
                );
                if let Some(bundle) = record.bundle.as_ref() {
                    secondary.push_str(&format!(" | b:{}@{}", bundle.id, bundle.revision));
                }
                if let Some(context_id) = record.context_id.as_ref() {
                    secondary.push_str(&format!(" | c:{context_id}"));
                }
                if let Some(task_id) = record.task_binding.as_ref()
                    .and_then(|binding| binding.task_id.as_ref())
                {
                    secondary.push_str(&format!(" | {}", compact_task_id(task_id)));
                }
                let title = app.agent_local_alias(key)
                    .map(str::to_owned)
                    .unwrap_or_else(|| record.short_title().to_owned());
                if app.agent_local_alias(key).is_some() {
                    secondary = format!("{} | {secondary}", record.short_title());
                }
                (
                    title,
                    marker,
                    color,
                    secondary,
                )
            }
            AgentRowKey::Legacy(address) => {
                let Some(session) = app.find_session(address) else {
                    continue;
                };
                let (marker, color, status) = session_state(session, theme);
                (
                    session.short_title(),
                    marker,
                    color,
                    format!("{status} | {} | {}", address.workspace_id, address.node_id),
                )
            }
        };
        let order_offset = order_width.saturating_add(u16::from(order_width > 0));
        Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![
            Span::styled(format!(" {marker} "), Style::default().fg(color)),
            Span::styled(
                truncate_cells(&title, title_width as usize),
                Style::default().fg(theme.text).add_modifier(Modifier::BOLD),
            ),
        ])]))
        .style(Style::default().bg(background))
        .render(
            Rect::new(
                area.x.saturating_add(order_offset),
                y,
                area.width.saturating_sub(order_offset),
                1,
            ),
            buf,
        );
        Paragraph::new(format!(
            "   {}",
            compact_middle_cells(&secondary, area.width.saturating_sub(3) as usize)
        ))
        .style(
            Style::default()
                .fg(if selected { color } else { theme.dim })
                .bg(background),
        )
        .render(Rect::new(area.x, y + 1, area.width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(area.x, y, area.width, rendered_height),
            target: HitTarget::Agent(index),
        });
        if order_width > 0 {
            let order = Rect::new(area.x, y, order_width, 1);
            Paragraph::new(order_label)
                .style(Style::default().fg(theme.muted).bg(background))
                .render(order, buf);
            layout.hits.push(HitRegion {
                rect: order,
                target: HitTarget::AgentOrderHandle(key.clone()),
            });
        }
        if app.agent_is_pinned(key) && area.width > order_width {
            let pin_x = area.x.saturating_add(order_width);
            Paragraph::new("P")
                .style(Style::default().fg(theme.yellow).bg(background))
                .render(Rect::new(pin_x, y, 1, 1), buf);
        }
        if more_width > 0 {
            let more_x = area.right().saturating_sub(more_width);
            Paragraph::new(more_label)
                .style(
                    Style::default()
                        .fg(if selected { theme.accent } else { theme.muted })
                        .bg(background)
                        .add_modifier(Modifier::BOLD),
                )
                .render(Rect::new(more_x, y, more_width, 1), buf);
            layout.hits.push(HitRegion {
                rect: Rect::new(more_x, y, more_width, 1),
                target: HitTarget::AgentMore(index),
            });
        }
        if run_width > 0 {
            let run_x = area
                .right()
                .saturating_sub(more_width)
                .saturating_sub(run_width)
                .saturating_sub(1);
            let run = Rect::new(run_x, y, run_width, 1);
            Paragraph::new(run_label)
                .style(
                    Style::default()
                        .fg(if app.agent_run_lens_key() == Some(key) { theme.active_tab_text } else { theme.teal })
                        .bg(if app.agent_run_lens_key() == Some(key) { theme.accent } else { background })
                        .add_modifier(Modifier::BOLD),
                )
                .render(run, buf);
            layout.hits.push(HitRegion {
                rect: run,
                target: HitTarget::AgentRun(key.clone()),
            });
        }
        if progress_width > 0 {
            let progress_x = area
                .right()
                .saturating_sub(more_width)
                .saturating_sub(run_width)
                .saturating_sub(progress_width)
                .saturating_sub(2);
            let progress = Rect::new(progress_x, y, progress_width, 1);
            Paragraph::new(progress_label)
                .style(
                    Style::default()
                        .fg(if expanded { theme.active_tab_text } else { theme.teal })
                        .bg(if expanded { theme.accent } else { background })
                        .add_modifier(Modifier::BOLD),
                )
                .render(progress, buf);
            layout.hits.push(HitRegion {
                rect: progress,
                target: HitTarget::AgentProgressToggle(key.clone()),
            });
        }
        if expanded {
            for (offset, line) in agent_progress_lines(app, key).into_iter().enumerate() {
                let progress_y = y.saturating_add(2 + offset as u16);
                if progress_y >= area.bottom() {
                    break;
                }
                Paragraph::new(format!("   {}", compact_middle_cells(&line, area.width.saturating_sub(3) as usize)))
                    .style(Style::default().fg(theme.dim).bg(background))
                    .render(Rect::new(area.x, progress_y, area.width, 1), buf);
            }
        }
        y = y.saturating_add(card_height);
    }
}

fn agent_progress_lines(app: &App, key: &AgentRowKey) -> [String; 3] {
    let (progress, unavailable) = match key {
        AgentRowKey::Managed { .. } => {
            let Some(record) = app.find_managed_session(key) else {
                return unavailable_agent_progress_lines("unavailable");
            };
            if record.state == gate4agent_node_protocol::ManagedSessionState::Dormant {
                (None, "unavailable until resume")
            } else {
                let progress = record.active_session.as_ref()
                    .and_then(|address| app.find_session(address))
                    .and_then(|session| session.progress.as_ref());
                (progress, if record.state == gate4agent_node_protocol::ManagedSessionState::Live {
                    "syncing"
                } else {
                    "unavailable"
                })
            }
        }
        AgentRowKey::Legacy(address) => {
            let Some(session) = app.find_session(address) else {
                return unavailable_agent_progress_lines("unavailable");
            };
            (session.progress.as_ref(), if session.running { "syncing" } else { "unavailable" })
        }
    };
    let Some(progress) = progress else {
        return unavailable_agent_progress_lines(unavailable);
    };
    let current = match progress.current {
        gate4agent_node_protocol::AgentProgressCurrentV1::Idle => "idle",
        gate4agent_node_protocol::AgentProgressCurrentV1::Working => "working",
        gate4agent_node_protocol::AgentProgressCurrentV1::WaitingForInput => "waiting for input",
        gate4agent_node_protocol::AgentProgressCurrentV1::Blocked => "blocked",
    };
    let freshness = if progress.stale {
        "stale".to_owned()
    } else if progress.gap_count > 0 {
        format!("incomplete after event gap {}", progress.gap_count)
    } else {
        "fresh".to_owned()
    };
    let partial = if progress.truncated { " | partial" } else { "" };
    let attention = progress.attention.as_ref().map(|attention| {
        let kind = match attention.kind {
            gate4agent_node_protocol::AgentProgressAttentionKindV1::Approval => "approval",
            gate4agent_node_protocol::AgentProgressAttentionKindV1::Question => "question",
        };
        attention.tool_label.as_ref()
            .map(|tool| format!(" | attention {kind}: {tool}"))
            .unwrap_or_else(|| format!(" | attention {kind}"))
    }).unwrap_or_default();
    let labels = if progress.active_tool_labels.is_empty() {
        String::new()
    } else {
        format!(" [{}]", progress.active_tool_labels.join(", "))
    };
    let usage = progress.usage.map(|usage| format!(
        " | usage in {} out {} cache {}+{} reason {}",
        usage.input_tokens,
        usage.output_tokens,
        usage.cache_read_tokens,
        usage.cache_write_tokens,
        usage.reasoning_tokens,
    )).unwrap_or_default();
    [
        format!("{current} | {freshness}{partial}"),
        format!("tools {}{labels}{attention}", progress.active_tool_count),
        format!("turns {}{usage} | subagents {}", progress.completed_turns, progress.subagent_count),
    ]
}

fn unavailable_agent_progress_lines(state: &str) -> [String; 3] {
    [
        state.to_owned(),
        "tools unavailable | attention unavailable".to_owned(),
        "turns unavailable | usage unavailable | subagents unavailable".to_owned(),
    ]
}

fn render_native_session_list(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    use_strip: bool,
) {
    let Some(dialog) = app.existing_session.as_ref() else {
        Paragraph::new(" Native sessions are not initialized")
            .style(Style::default().fg(theme.muted).bg(theme.panel))
            .render(area, buf);
        return;
    };
    if area.height < 5 {
        return;
    }
    let node_value = node_route_value(app, &dialog.node_id);
    render_native_route_selector(
        "Node",
        &node_value,
        dialog.field == ExistingSessionField::Node,
        ExistingSessionField::Node,
        area,
        0,
        theme,
        buf,
        layout,
    );
    let status = match &dialog.catalog {
        NativeSessionCatalogState::Loading => format!(
            "loading... {} route(s) pending, {} session(s)",
            dialog.pending_routes.len(),
            dialog.rows.len(),
        ),
        NativeSessionCatalogState::Empty => format!(
            "{} managed/live agent(s) | no provider history",
            app.agent_rows().len(),
        ),
        NativeSessionCatalogState::Unavailable(reason) => format!("unavailable: {reason}"),
        NativeSessionCatalogState::Error(message) => format!("failed: {message}"),
        NativeSessionCatalogState::Ready => format!(
            "{} managed/live agent(s) | {} provider history session(s) - read-only",
            app.agent_rows().len(),
            dialog.rows.len(),
        ),
    };
    render_modal_line(
        status,
        area,
        1,
        Style::default().fg(theme.muted).bg(theme.panel),
        buf,
    );
    let provider_totals = dialog.native_history_provider_totals();
    let provider_summary = if provider_totals.is_empty() {
        "providers -".to_owned()
    } else {
        format!(
            "providers {}",
            provider_totals
                .into_iter()
                .map(|(provider, total)| format!("{provider}:{total}"))
                .collect::<Vec<_>>()
                .join(" "),
        )
    };
    render_modal_line(
        provider_summary,
        area,
        2,
        Style::default().fg(theme.dim).bg(theme.panel),
        buf,
    );
    let items = app.native_session_tree_items();
    let capacity = area.height.saturating_sub(5) as usize;
    let item_height = |item: &NativeSessionTreeItem| match item {
        NativeSessionTreeItem::Agent { agent_index, .. } => app.agent_rows()
            .get(*agent_index)
            .map(|key| {
                // 25 matches the roster's default sidebar content width (see
                // `compact_agent_actions` below): below it there is no room for
                // the run/progress controls, so the expanded detail lines never
                // render and the row only needs its single label line.
                if area.width >= 25 && app.agent_progress_expanded(key) {
                    4
                } else {
                    1
                }
            })
            .unwrap_or(1),
        _ => 1,
    };
    let mut start = dialog.scroll.min(items.len().saturating_sub(1));
    if dialog.tree_cursor < start {
        start = dialog.tree_cursor;
    } else {
        while start < dialog.tree_cursor
            && items[start..=dialog.tree_cursor]
                .iter()
                .map(&item_height)
                .sum::<usize>()
                > capacity
        {
            start += 1;
        }
    }
    let mut y = area.y + 3;
    let rows_bottom = area.y.saturating_add(3).saturating_add(capacity as u16);
    for (tree_index, item) in items.iter().enumerate().skip(start) {
        let height = item_height(item) as u16;
        if y >= rows_bottom {
            break;
        }
        let selected = tree_index == dialog.tree_cursor;
        let row_area = Rect::new(area.x, y, area.width, 1);
        let (label, target, foreground) = match item {
            NativeSessionTreeItem::Agent { agent_index, nested } => {
                let Some(key) = app.agent_rows().get(*agent_index).cloned() else {
                    continue;
                };
                let indent = if *nested { "       " } else { " " };
                match &key {
                    AgentRowKey::Managed { .. } => {
                        let Some(record) = app.find_managed_session(&key) else {
                            continue;
                        };
                        let active = record.active_session.as_ref()
                            .and_then(|address| app.find_session(address));
                        let (marker, color, state) = active
                            .map(|session| session_state(session, theme))
                            .unwrap_or_else(|| managed_session_state(record.state, theme));
                        let mut detail = format!(
                            "{state} | {} | {}",
                            record.workspace_id,
                            record.node_id,
                        );
                        if let Some(bundle) = record.bundle.as_ref() {
                            detail.push_str(&format!(" | b:{}@{}", bundle.id, bundle.revision));
                        }
                        if let Some(context_id) = record.context_id.as_ref() {
                            detail.push_str(&format!(" | c:{context_id}"));
                        }
                        let primary = app.agent_local_alias(&key)
                            .map(str::to_owned)
                            .unwrap_or_else(|| record.short_title().to_owned());
                        let authoritative = if app.agent_local_alias(&key).is_some() {
                            format!("{} | ", record.short_title())
                        } else {
                            String::new()
                        };
                        (
                            format!(
                                "{}{}{}{} {} | {}{}",
                                if selected { ">" } else { " " },
                                indent,
                                if app.agent_is_pinned(&key) { "P" } else { "" },
                                marker,
                                primary,
                                authoritative,
                                detail,
                            ),
                            HitTarget::Agent(*agent_index),
                            color,
                        )
                    }
                    AgentRowKey::Legacy(address) => {
                        let Some(session) = app.find_session(address) else {
                            continue;
                        };
                        let (marker, color, state) = session_state(session, theme);
                        (
                            format!(
                                "{}{}{} {} | {state} | {} | {}",
                                if selected { ">" } else { " " },
                                indent,
                                marker,
                                session.short_title(),
                                address.workspace_id,
                                address.node_id,
                            ),
                            HitTarget::Agent(*agent_index),
                            color,
                        )
                    }
                }
            }
            NativeSessionTreeItem::Workspace {
                key,
                label,
                session_count,
                collapsed,
                external,
            } => (
                format!(
                    "{}{} {} {}{}",
                    if selected { ">" } else { " " },
                    if *external && !matches!(key, NativeSessionGroupKey::OtherProjects) {
                        "     "
                    } else {
                        ""
                    },
                    if *collapsed { "+" } else { "-" },
                    label,
                    if *session_count > 0 {
                        format!(" ({session_count})")
                    } else {
                        String::new()
                    },
                ),
                HitTarget::NativeWorkspaceGroup(key.clone()),
                theme.teal,
            ),
            NativeSessionTreeItem::Provider {
                group,
                provider,
                session_count,
                collapsed,
            } => (
                format!(
                    "{}{}{} [{}]{}",
                    if selected { ">" } else { " " },
                    "   ",
                    if *collapsed { "+" } else { "-" },
                    provider,
                    if *session_count > 0 {
                        format!(" ({session_count})")
                    } else {
                        String::new()
                    },
                ),
                HitTarget::NativeProviderGroup(group.clone(), provider.clone()),
                theme.yellow,
            ),
            NativeSessionTreeItem::Session { row_index } => {
                let row = &dialog.rows[*row_index];
                let title = row.title.as_deref()
                    .filter(|title| !title.trim().is_empty())
                    .unwrap_or("Existing session");
                (
                    format!("{}       {}", if selected { ">" } else { " " }, title),
                    HitTarget::ExistingSessionRow(*row_index),
                    theme.text,
                )
            }
            NativeSessionTreeItem::LoadMore {
                route,
                window,
                remaining_count,
                loading,
            } => {
                let kind = match window {
                    gate4agent_types::NativeSessionCatalogWindow::Recent => "more recent",
                    gate4agent_types::NativeSessionCatalogWindow::Older => "older",
                };
                (
                    format!(
                        "{}       {}",
                        if selected { ">" } else { " " },
                        if *loading {
                            format!("Loading {kind} sessions...")
                        } else {
                            format!(
                                "Show {remaining_count} {kind} [{}] sessions...",
                                route.provider,
                            )
                        },
                    ),
                    HitTarget::NativeSessionsLoadMore(
                        route.clone(),
                        *window,
                    ),
                    theme.teal,
                )
            }
        };
        let agent_run_key = match item {
            NativeSessionTreeItem::Agent { agent_index, .. } => {
                app.agent_rows().get(*agent_index).cloned()
            }
            _ => None,
        };
        let agent_index = match item {
            NativeSessionTreeItem::Agent { agent_index, .. } => Some(*agent_index),
            _ => None,
        };
        // 25 is the default sidebar content width; narrower than that there is no
        // room left for the run-lens/progress toggles alongside the row label.
        let compact_agent_actions = agent_run_key.is_some() && area.width < 25;
        let agent_expanded = agent_run_key.as_ref()
            .is_some_and(|key| app.agent_progress_expanded(key));
        let progress_ascii_label = if agent_expanded { "[details -]" } else { "[details +]" };
        let progress_icon = if agent_expanded { icons::IconId::ChevronDown } else { icons::IconId::ChevronRight };
        let progress_width = if agent_run_key.is_some() && !compact_agent_actions {
            compact_icon_button_width(progress_ascii_label, app.rail_icons).min(area.width)
        } else {
            0
        };
        let agent_action_ascii_label = if area.width < 30 { "[act]" } else { "[actions]" };
        let agent_action_width = if compact_agent_actions {
            compact_icon_button_width(agent_action_ascii_label, app.rail_icons).min(area.width)
        } else {
            0
        };
        let native_action_ascii_label = "[menu]";
        let native_action_width = if matches!(item, NativeSessionTreeItem::Session { .. }) {
            compact_icon_button_width(native_action_ascii_label, app.rail_icons).min(area.width)
        } else {
            0
        };
        let label_width = if compact_agent_actions {
            area.width
                .saturating_sub(agent_action_width)
                .saturating_sub(u16::from(agent_action_width > 0))
        } else if agent_run_key.is_some() {
            area.width.saturating_sub(6).saturating_sub(progress_width).saturating_sub(1)
        } else {
            area.width
                .saturating_sub(native_action_width)
                .saturating_sub(u16::from(native_action_width > 0))
        };
        Paragraph::new(truncate_cells(&label, label_width as usize))
            .style(
                Style::default()
                    .fg(if selected { theme.active_tab_text } else { foreground })
                    .bg(if selected { theme.accent } else { theme.panel })
                    .add_modifier(if matches!(item, NativeSessionTreeItem::Workspace { .. } | NativeSessionTreeItem::Provider { .. }) {
                        Modifier::BOLD
                    } else {
                        Modifier::empty()
                    }),
            )
            .render(row_area, buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(area.x, y, area.width, height.min(rows_bottom.saturating_sub(y))),
            target,
        });
        if let NativeSessionTreeItem::Session { row_index } = item {
            let actions = Rect::new(
                row_area.right().saturating_sub(native_action_width),
                row_area.y,
                native_action_width,
                1,
            );
            render_compact_icon_button(
                actions,
                icons::IconId::Ellipsis,
                native_action_ascii_label,
                Style::default()
                    .fg(theme.teal)
                    .bg(if selected { theme.accent } else { theme.panel })
                    .add_modifier(Modifier::BOLD),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            layout.hits.push(HitRegion {
                rect: actions,
                target: HitTarget::NativeSessionMore(*row_index),
            });
        }
        if let Some(agent_index) = agent_index.filter(|_| compact_agent_actions) {
            let actions = Rect::new(
                row_area.right().saturating_sub(agent_action_width),
                row_area.y,
                agent_action_width,
                1,
            );
            render_compact_icon_button(
                actions,
                icons::IconId::Ellipsis,
                agent_action_ascii_label,
                Style::default()
                    .fg(theme.teal)
                    .bg(if selected { theme.accent } else { theme.panel })
                    .add_modifier(Modifier::BOLD),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            layout.hits.push(HitRegion {
                rect: actions,
                target: HitTarget::AgentMore(agent_index),
            });
        }
        if let Some(key) = agent_run_key {
            if compact_agent_actions {
                y = y.saturating_add(height);
                continue;
            }
            if matches!(key, AgentRowKey::Managed { .. }) {
                let handle = Rect::new(
                    row_area.x,
                    row_area.y,
                    (cell_width("[move]") as u16).min(row_area.width),
                    1,
                );
                Paragraph::new("[move]")
                    .style(Style::default().fg(theme.muted).bg(if selected { theme.accent } else { theme.panel }))
                    .render(handle, buf);
                layout.hits.push(HitRegion {
                    rect: handle,
                    target: HitTarget::AgentOrderHandle(key.clone()),
                });
            }
            let run_label = if app.agent_run_lens_key() == Some(&key) {
                "[global]"
            } else {
                "[workspace]"
            };
            let run_width = (cell_width(run_label) as u16).min(area.width);
            let run = Rect::new(
                row_area.right().saturating_sub(run_width),
                row_area.y,
                run_width,
                1,
            );
            Paragraph::new(run_label)
                .style(
                    Style::default()
                        .fg(if app.agent_run_lens_key() == Some(&key) { theme.active_tab_text } else { theme.teal })
                        .bg(if app.agent_run_lens_key() == Some(&key) { theme.accent } else if selected { theme.accent } else { theme.panel })
                        .add_modifier(Modifier::BOLD),
                )
                .render(run, buf);
            layout.hits.push(HitRegion {
                rect: run,
                target: HitTarget::AgentRun(key.clone()),
            });
            let progress = Rect::new(
                run.x.saturating_sub(progress_width).saturating_sub(1),
                row_area.y,
                progress_width,
                1,
            );
            render_compact_icon_button(
                progress,
                progress_icon,
                progress_ascii_label,
                Style::default()
                    .fg(if agent_expanded { theme.active_tab_text } else { theme.teal })
                    .bg(if agent_expanded { theme.accent } else if selected { theme.accent } else { theme.panel })
                    .add_modifier(Modifier::BOLD),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            layout.hits.push(HitRegion {
                rect: progress,
                target: HitTarget::AgentProgressToggle(key.clone()),
            });
            if agent_expanded {
                for (offset, line) in agent_progress_lines(app, &key).into_iter().enumerate() {
                    let progress_y = y.saturating_add(1 + offset as u16);
                    if progress_y >= rows_bottom {
                        break;
                    }
                    Paragraph::new(format!("       {}", compact_middle_cells(&line, area.width.saturating_sub(7) as usize)))
                        .style(Style::default().fg(theme.dim).bg(if selected { theme.active } else { theme.panel }))
                        .render(Rect::new(area.x, progress_y, area.width, 1), buf);
                }
            }
        }
        y = y.saturating_add(height);
    }
    let open_ascii_label = "[Open transcript]";
    // No trailing word to budget for any more (icon-only control, see
    // `render_compact_icon_button`'s own doc comment) -- the old literal
    // `19` was sized for the ascii label plus the sixel tier's own former
    // icon-plus-word footprint; `compact_icon_button_width` mirrors
    // whatever the actual paint needs per tier instead of a stale magic
    // number. Nothing else on this row anchors off `open`'s own width.
    let open = Rect::new(
        area.x,
        area.bottom().saturating_sub(1),
        compact_icon_button_width(open_ascii_label, app.rail_icons).min(area.width),
        1,
    );
    render_compact_icon_button(
        open,
        icons::IconId::GoToFile,
        open_ascii_label,
        Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    layout.hits.push(HitRegion {
        rect: open,
        target: HitTarget::NativeSessionsOpen,
    });
    if !use_strip {
        let add_ascii_label = "+ agent";
        let add_width = compact_icon_button_width(add_ascii_label, app.rail_icons).min(area.width);
        let add = Rect::new(
            area.right().saturating_sub(add_width),
            area.bottom().saturating_sub(1),
            add_width,
            1,
        );
        render_compact_icon_button(
            add,
            icons::IconId::Add,
            add_ascii_label,
            Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion {
            rect: add,
            target: HitTarget::AddAgent,
        });
    }
}

fn render_native_route_selector(
    label: &str,
    value: &str,
    active: bool,
    field: ExistingSessionField,
    area: Rect,
    row: u16,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    let text = format!("{} {:<3} < {} >", if active { ">" } else { " " }, label, value);
    let rect = modal_row(area, row);
    Paragraph::new(truncate_cells(&text, area.width as usize))
        .style(Style::default()
            .fg(if active { theme.active_tab_text } else { theme.text })
            .bg(if active { theme.accent } else { theme.panel }))
        .render(rect, buf);
    push_modal_hit(layout, rect, HitTarget::ExistingSessionField(field));
    if area.width > 2 {
        Paragraph::new("<>")
            .style(Style::default()
                .fg(if active { theme.active_tab_text } else { theme.teal })
                .bg(if active { theme.accent } else { theme.panel }))
            .render(Rect::new(area.right().saturating_sub(2), area.y + row, 2, 1), buf);
        push_modal_hit(
            layout,
            Rect::new(area.right().saturating_sub(2), area.y + row, 1, 1),
            HitTarget::ExistingSessionFieldPrevious(field),
        );
        push_modal_hit(
            layout,
            Rect::new(area.right().saturating_sub(1), area.y + row, 1, 1),
            HitTarget::ExistingSessionFieldNext(field),
        );
    }
}

fn render_agent_menu(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(menu) = app.agent_menu.as_ref() else {
        return;
    };
    let items = app.agent_menu_items();
    if items.is_empty() || area.width < 4 || area.height < 3 {
        return;
    }
    let width = 56.min(area.width);
    let height = (items.len() as u16 + 2).min(area.height);
    let x = menu
        .anchor_column
        .min(area.right().saturating_sub(width))
        .max(area.x);
    let y = menu
        .anchor_row
        .min(area.bottom().saturating_sub(height))
        .max(area.y);
    let menu_area = Rect::new(x, y, width, height);
    layout.note_overlay(menu_area);
    fill_rect(menu_area, theme.modal, buf);
    Block::bordered()
        .title(" agent actions ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(menu_area, buf);
    // No `[x]` here, deliberately. A popup is not a modal: it has no
    // header to hang a cross on and it is anchored to the control that
    // opened it, so its close paths are that same control and a click
    // outside it -- both of which `App::close_overlay_outside_click`
    // already owns, plus `Escape`. A cross was briefly painted here and
    // removed: it read as a modal's chrome on something that is not one.
    let inner = Rect::new(
        menu_area.x.saturating_add(1),
        menu_area.y.saturating_add(1),
        menu_area.width.saturating_sub(2),
        menu_area.height.saturating_sub(2),
    );
    let capacity = inner.height as usize;
    let start = if capacity == 0 {
        0
    } else if menu.selected >= capacity {
        menu.selected.saturating_add(1).saturating_sub(capacity)
    } else {
        0
    };
    for (row_index, (index, item)) in items
        .iter()
        .enumerate()
        .skip(start)
        .take(capacity)
        .enumerate()
    {
        let selected = index == menu.selected;
        let label = if item.enabled {
            item.label.clone()
        } else {
            format!(
                "{} - {}",
                item.label,
                item.disabled_reason.as_deref().unwrap_or("unsupported")
            )
        };
        let row = Rect::new(inner.x, inner.y + row_index as u16, inner.width, 1);
        Paragraph::new(format!(
            "{} {}",
            if selected { ">" } else { " " },
            truncate_cells(&label, inner.width.saturating_sub(2) as usize)
        ))
        .style(
            Style::default()
                .fg(if item.enabled { theme.text } else { theme.muted })
                .bg(if selected { theme.active } else { theme.modal })
                .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
        )
        .render(row, buf);
        layout.hits.push(HitRegion {
            rect: row,
            target: HitTarget::AgentMenuAction(item.action),
        });
    }
}

fn render_native_session_menu(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(menu) = app.native_session_menu.as_ref() else {
        return;
    };
    let items = app.native_session_menu_items();
    if items.is_empty() || area.width < 4 || area.height < 3 {
        return;
    }
    let width = 64.min(area.width);
    let height = (items.len() as u16 + 3).min(area.height);
    let x = menu
        .anchor_column
        .min(area.right().saturating_sub(width))
        .max(area.x);
    let y = menu
        .anchor_row
        .min(area.bottom().saturating_sub(height))
        .max(area.y);
    let menu_area = Rect::new(x, y, width, height);
    layout.note_overlay(menu_area);
    fill_rect(menu_area, theme.modal, buf);
    Block::bordered()
        .title(" provider history actions ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(menu_area, buf);
    // No `[x]`, same reasoning as `render_agent_menu` just above -- see
    // that call site's own comment.
    let inner = Rect::new(
        menu_area.x.saturating_add(1),
        menu_area.y.saturating_add(1),
        menu_area.width.saturating_sub(2),
        menu_area.height.saturating_sub(2),
    );
    for (index, item) in items.iter().take(inner.height as usize).enumerate() {
        let selected = index == menu.selected;
        let label = if item.enabled {
            item.label.clone()
        } else {
            format!(
                "{} - {}",
                item.label,
                item.disabled_reason.as_deref().unwrap_or("unsupported"),
            )
        };
        let row = Rect::new(inner.x, inner.y + index as u16, inner.width, 1);
        Paragraph::new(format!(
            "{} {}",
            if selected { ">" } else { " " },
            truncate_cells(&label, inner.width.saturating_sub(2) as usize),
        ))
        .style(
            Style::default()
                .fg(if item.enabled { theme.text } else { theme.muted })
                .bg(if selected { theme.active } else { theme.modal })
                .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
        )
        .render(row, buf);
        layout.hits.push(HitRegion {
            rect: row,
            target: HitTarget::NativeSessionMenuAction(item.action),
        });
    }
}

fn managed_session_state(
    state: gate4agent_node_protocol::ManagedSessionState,
    theme: Theme,
) -> (&'static str, Color, &'static str) {
    use gate4agent_node_protocol::ManagedSessionState;
    match state {
        ManagedSessionState::Live => ("*", theme.green, managed_state_label(state)),
        ManagedSessionState::IdentityPending => ("~", theme.yellow, managed_state_label(state)),
        ManagedSessionState::Dormant => ("o", theme.teal, managed_state_label(state)),
        ManagedSessionState::Unavailable => ("x", theme.red, managed_state_label(state)),
    }
}

fn render_tabs(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    // FIX5 made the rail gear (`HitTarget::ActivitySection(ControlSection::
    // Settings)`, see `render_activity_rail`) "the single mouse entry
    // point" to Settings and dropped this strip's own "[S]" button on
    // that assumption -- true only in (Sidebar, Activity), the one chrome
    // that actually draws a rail (see `render::render`'s own chrome
    // dispatch). (Sidebar, Split) and (Modal, _) have no rail at all, so
    // FIX5 silently left both with no mouse entry to Settings whatsoever.
    // This restores exactly the reservation `settings_width` used to make
    // before FIX5 -- an icon button, not the rejected "[S]" text (owner
    // call) -- gated to the two chromes that actually lost their gear;
    // (Sidebar, Activity) draws nothing here, the rail still owns it
    // there, so there is never more than one gear on screen at once.
    let rail_present = app.menu_placement == MenuPlacement::Sidebar
        && app.sidebar_presentation == SidebarPresentation::Activity;
    // Same fixed width the pre-strip compact icon buttons elsewhere in
    // this sidebar already use for an icon with no trailing text (see
    // `pack_inline_button_left`'s own call sites) -- not a new size.
    const GEAR_WIDTH: u16 = 4;
    let gear_width = if rail_present { 0 } else { GEAR_WIDTH.min(area.width) };
    let tabs_right = area.right().saturating_sub(gear_width);
    Paragraph::new("")
        .style(Style::default().bg(theme.active))
        .render(Rect::new(area.x, area.y, tabs_right.saturating_sub(area.x), 1), buf);
    // Read only by the `RailIcons::Ascii` arms below now -- that tier
    // keeps this exact old literal, padded label unchanged (no raster to
    // swap in, see this crate's own "RailIcons::Ascii must keep the
    // current text look exactly" requirement), while `RailIcons::Sixel`
    // draws `icons::IconId::Layout` at the STRIP tier instead.
    let layout_label = " [#] ";
    let preset_width = if app.layout_menu_open {
        LayoutPreset::ALL
            .iter()
            .map(|preset| cell_width(&format!(" {} ", preset.id())) as u16)
            .fold(0_u16, |total, width| total.saturating_add(width))
    } else {
        0
    };
    // Both controls' own real per-tier footprint -- for `RailIcons::
    // Sixel` this is the STRIP tier's own real icon width (`icons::
    // STRIP_SIXEL_ICON_CELLS_WIDE`, 2 cells: the same asset/size `render_
    // control_strip_button` already draws for `IconId::Add` elsewhere in
    // this sidebar) instead of the old padded-text widths (3 for `" + "`,
    // 5 for `" [#] "`); `RailIcons::Ascii` keeps those exact old numbers,
    // unchanged. `layout_control_width` additionally reserves ONE
    // leading column purely for the toggle's own open/closed marker
    // (painted below): that marker used to be a `theme.accent` plate
    // under the glyph itself; a real icon has no glyph colour of its own
    // to swap, so it needs a marker that lives beside the icon instead
    // -- see this fn's own "▎" comment below for why and what replaces
    // it.
    let add_control_width = match app.rail_icons {
        RailIcons::Sixel => icons::STRIP_SIXEL_ICON_CELLS_WIDE,
        RailIcons::Ascii => 3,
    };
    let layout_control_width = match app.rail_icons {
        RailIcons::Sixel => 1_u16.saturating_add(icons::STRIP_SIXEL_ICON_CELLS_WIDE),
        RailIcons::Ascii => cell_width(layout_label) as u16,
    };
    let controls_width = add_control_width
        .saturating_add(layout_control_width)
        .saturating_add(preset_width);
    let controls_right = tabs_right.min(area.x.saturating_add(controls_width));
    let mut x = area.x;
    if x < controls_right {
        let width = add_control_width.min(controls_right - x);
        let block = Rect::new(x, area.y, width, 1);
        match app.rail_icons {
            RailIcons::Sixel => {
                // Never a distinct-accent case, the same "one-shot action,
                // never a persisted selected view" precedent `render_
                // control_strip_button` already documents for this SAME
                // icon/tier elsewhere in this sidebar -- so this only ever
                // requests `GateActive`, never a variant of its own.
                layout.sixel_icons.push(SixelIconPlacement {
                    icon: icons::IconId::Add,
                    rect: Rect::new(
                        block.x,
                        block.y,
                        block.width.min(icons::STRIP_SIXEL_ICON_CELLS_WIDE),
                        1,
                    ),
                    variant: icons::SixelVariant::GateActive,
                    size: SixelIconSize::Strip,
                    family: app.icon_family,
                });
            }
            RailIcons::Ascii => {
                Paragraph::new(" + ")
                    .style(Style::default().fg(theme.muted).bg(theme.active))
                    .render(block, buf);
            }
        }
        layout.hits.push(HitRegion { rect: block, target: HitTarget::AddTab });
        x = x.saturating_add(width);
    }
    let layout_width = layout_control_width.min(controls_right.saturating_sub(x));
    if layout_width > 0 {
        let block = Rect::new(x, area.y, layout_width, 1);
        match app.rail_icons {
            RailIcons::Sixel => {
                // `render_rail_button`'s own lesson, reused verbatim: no
                // button states a background of its own, selected or not
                // -- a second, louder marker for the same state reads as
                // a coloured plate under the icon rather than as
                // selection (see that fn's own doc comment). So the body
                // here never changes colour either; the ONLY thing that
                // marks the preset menu as open is that same fn's own "▎"
                // accent bar, painted into the leading margin column
                // `layout_control_width` reserved above -- a column the
                // icon itself never occupies (a sixel image cannot share
                // a cell with a text glyph, see `icons.rs`'s own module
                // doc comment), so painting it never touches the icon.
                if app.layout_menu_open {
                    let cell = buf.get_mut(block.x, block.y);
                    cell.symbol = "▎".into();
                    cell.style = Style::default().fg(theme.active_tab_text).bg(theme.active);
                }
                let icon_x = block.x.saturating_add(1).min(block.right());
                let icon_width = block
                    .right()
                    .saturating_sub(icon_x)
                    .min(icons::STRIP_SIXEL_ICON_CELLS_WIDE);
                if icon_width > 0 {
                    layout.sixel_icons.push(SixelIconPlacement {
                        icon: icons::IconId::Layout,
                        rect: Rect::new(icon_x, block.y, icon_width, 1),
                        variant: icons::SixelVariant::GateActive,
                        size: SixelIconSize::Strip,
                        family: app.icon_family,
                    });
                }
            }
            RailIcons::Ascii => {
                Paragraph::new(truncate_cells(layout_label, layout_width as usize))
                    .style(
                        Style::default()
                            .fg(if app.layout_menu_open { theme.active_tab_text } else { theme.muted })
                            .bg(if app.layout_menu_open { theme.accent } else { theme.active })
                            .add_modifier(Modifier::BOLD),
                    )
                    .render(block, buf);
            }
        }
        layout.hits.push(HitRegion { rect: block, target: HitTarget::LayoutMenuToggle });
        x = x.saturating_add(layout_width);
    }
    if app.layout_menu_open {
        let presets_start_x = x;
        for preset in LayoutPreset::ALL {
            if x >= controls_right {
                break;
            }
            let label = format!(" {} ", preset.id());
            let width = (cell_width(&label) as u16).min(controls_right - x);
            let selected = app.surface.preset == Some(preset);
            Paragraph::new(truncate_cells(&label, width as usize))
                .style(
                    Style::default()
                        .fg(if selected { theme.active_tab_text } else { theme.muted })
                        .bg(if selected { theme.accent } else { theme.active })
                        .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
                )
                .render(Rect::new(x, area.y, width, 1), buf);
            layout.hits.push(HitRegion {
                rect: Rect::new(x, area.y, width, 1),
                target: HitTarget::LayoutPreset(preset),
            });
            x = x.saturating_add(width);
        }
        // Slice 1 of the uniform overlay-close contract: this is the ONE
        // overlay in the crate with no bordered frame at all -- a run of
        // plain preset labels inline in the tab strip, deliberately
        // excluded from `render_modal_close`'s `[x]` (see that fn's own
        // doc comment) because there is no frame to hang a cross on. It
        // still needs a rect registered here so `App::click`'s outside-
        // click guard can tell "click landed on one of these labels" from
        // "click landed elsewhere" -- covers only the preset labels just
        // painted above, deliberately NOT the toggle button that opened
        // them (`HitTarget::LayoutMenuToggle`, painted before this block):
        // that button is the opener, not overlay content, exactly like
        // every other overlay's opener control sits outside its own rect.
        layout.note_overlay(Rect::new(presets_start_x, area.y, x.saturating_sub(presets_start_x), 1));
    }
    // The app-wide quick search: centred in this WHOLE strip (`area.x` ..
    // `tabs_right`, before the gear's own reservation), but never at the
    // cost of anything already drawn above -- `x` is exactly where the
    // Add/Layout controls (and, if open, the layout-preset labels) really
    // stopped this frame, so the search can only ever use the leftover
    // span from there to `tabs_right`. Labels win; search only ever gets
    // what nothing else claimed.
    render_global_search(app, area.x, x, tabs_right, area.y, buf, layout, theme);
    if gear_width > 0 {
        let gear = Rect::new(tabs_right, area.y, gear_width, 1);
        render_compact_icon_button(
            gear,
            icons::IconId::SettingsGear,
            icons::ascii(icons::IconId::SettingsGear),
            // Same "never shows as active" convention the rail's own
            // gear uses (`render_activity_rail`'s own `RailButton` for
            // Settings, `selected: false` always): Settings is an
            // overlay dialog, not a persisted section, so this button
            // does not highlight while the dialog is open either.
            Style::default().fg(theme.muted).bg(theme.active),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion {
            rect: gear,
            target: HitTarget::ActivitySection(ControlSection::Settings),
        });
    }
}

/// Collapsed width of the global search's own magnifier frame -- same
/// "icon in a frame" footprint `render_tabs`'s own `GEAR_WIDTH` already
/// uses for a single icon with margin either side, not a new size.
const SEARCH_COLLAPSED_WIDTH: u16 = 4;
/// Widest the search field is ever allowed to grow to, fully expanded and
/// with room to spare -- a quick-jump box, not a full-row omnibox.
const SEARCH_MAX_EXPANDED_WIDTH: u16 = 34;

/// The app-wide quick search living in the GLOBAL tab strip (`render_
/// tabs`'s own call site) -- collapsed, this is a magnifier icon in a
/// frame; clicking it (`HitTarget::GlobalSearchToggle`) expands it over
/// several animation frames (`App::advance_animation_frame` stepping
/// `app.global_search.expand_step`) into a text field, with a results
/// dropdown appearing once that expansion actually settles (avoids a
/// dropdown reflowing under a still-growing field, which reads as noise
/// rather than a list). `strip_left`/`strip_right` are the WHOLE tab
/// strip's own ends (before the gear reservation) -- used only to compute
/// where "centred" actually is; `controls_end` is the hard left boundary
/// nothing here may cross (see this fn's own call site doc comment).
///
/// This fn only ever RECORDS that the dropdown should open, into
/// `layout.global_search_anchor` -- it does not paint it. See `render::
/// render`'s own top-level sequence (the call to `render_global_search_
/// dropdown` right after `render_surface`) for where that actually
/// happens now, and `LayoutRects::global_search_anchor`'s own doc comment
/// for why painting moved out of here.
fn render_global_search(
    app: &App,
    strip_left: u16,
    controls_end: u16,
    strip_right: u16,
    row_y: u16,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let available = strip_right.saturating_sub(controls_end);
    if available < SEARCH_COLLAPSED_WIDTH {
        // Narrow-row rule: existing controls/labels already claimed every
        // column this strip has -- there is truly nothing left, not even
        // for the magnifier alone.
        return;
    }
    let target_extra = u32::from(SEARCH_MAX_EXPANDED_WIDTH.saturating_sub(SEARCH_COLLAPSED_WIDTH))
        * u32::from(app.global_search.expand_step)
        / u32::from(crate::app::SEARCH_EXPAND_STEPS);
    let desired_width = SEARCH_COLLAPSED_WIDTH.saturating_add(target_extra as u16);
    let width = desired_width.min(available);
    let ideal_center = strip_left + strip_right.saturating_sub(strip_left) / 2;
    let left = ideal_center
        .saturating_sub(width / 2)
        .max(controls_end)
        .min(strip_right.saturating_sub(width));
    let block = Rect::new(left, row_y, width, 1);
    fill_rect(block, theme.active, buf);
    // A real one-row frame, not just a filled background -- `SEARCH_
    // COLLAPSED_WIDTH`'s own doc comment already calls this an "icon in a
    // frame", but nothing here ever drew one. The tab strip itself is
    // provably one row (`render_tabs`'s own call site), so a bordered
    // `Block` (which needs three) is not an option here -- paint the
    // frame as two edge cells on this same row instead, `▏` left and `▕`
    // right. Both are cells nothing else in this fn ever touches: `width`
    // is always >= `SEARCH_COLLAPSED_WIDTH` (the `available` guard above
    // already returned otherwise), the icon starts one cell in at `icon_
    // x` below, and the field span computed further down is deliberately
    // shortened by one cell so its text can never grow into the right
    // edge cell painted here.
    let left_edge = buf.get_mut(block.x, block.y);
    left_edge.symbol = "▏".into();
    left_edge.style = Style::default().fg(theme.border).bg(theme.active);
    let right_edge = buf.get_mut(block.right() - 1, block.y);
    right_edge.symbol = "▕".into();
    right_edge.style = Style::default().fg(theme.border).bg(theme.active);
    let icon_x = block.x + 1;
    let icon_width = icons::STRIP_SIXEL_ICON_CELLS_WIDE.min(block.width.saturating_sub(1));
    match app.rail_icons {
        RailIcons::Sixel => {
            layout.sixel_icons.push(SixelIconPlacement {
                icon: icons::IconId::Search,
                rect: Rect::new(icon_x, block.y, icon_width, 1),
                variant: icons::SixelVariant::GateActive,
                size: SixelIconSize::Strip,
                family: app.icon_family,
            });
        }
        RailIcons::Ascii => {
            Paragraph::new(truncate_cells(icons::ascii(icons::IconId::Search), icon_width as usize))
                .style(Style::default().fg(theme.muted).bg(theme.active))
                .render(Rect::new(icon_x, block.y, icon_width, 1), buf);
        }
    }
    layout.hits.push(HitRegion { rect: block, target: HitTarget::GlobalSearchToggle });
    let expanded = width > SEARCH_COLLAPSED_WIDTH;
    if !expanded {
        return;
    }
    let field_x = icon_x.saturating_add(icon_width).saturating_add(1);
    // Stops one cell short of `block.right()` -- that last column is the
    // `▕` frame edge painted above, and the query text must never grow
    // into it.
    let field_right = block.right().saturating_sub(1);
    if field_x >= field_right {
        return;
    }
    let field = Rect::new(field_x, block.y, field_right - field_x, 1);
    let (display, style) = if app.global_search.query.is_empty() {
        ("search...".to_owned(), Style::default().fg(theme.muted).bg(theme.active))
    } else {
        (app.global_search.query.clone(), Style::default().fg(theme.text).bg(theme.active))
    };
    Paragraph::new(truncate_cells(&display, field.width as usize))
        .style(style)
        .render(field, buf);
    layout.global_search_field = field;
    if app.focus == Focus::GlobalSearch && app.global_search.expand_step == crate::app::SEARCH_EXPAND_STEPS {
        // Recorded, not painted -- `render::render`'s own top-level
        // sequence reads this back and paints the dropdown itself AFTER
        // `render_surface` has already run this frame. See `LayoutRects::
        // global_search_anchor`'s own doc comment for why.
        layout.global_search_anchor = block;
    }
}

/// The global search's own results dropdown -- opens directly under the
/// magnifier/field frame, left-aligned with it. An overlay like any other
/// (`note_overlay`, opaque full-frame fill), so a sixel icon in the
/// viewport underneath never bleeds through it. Called from `render::
/// render`'s own top-level sequence, AFTER `render_surface` -- see that
/// call site's own doc comment, and `LayoutRects::global_search_anchor`'s,
/// for why: this used to be called from inside `render_global_search`
/// itself (`render_tabs`'s own call chain), which ran BEFORE the surface,
/// so the surface's own next pass silently painted over this dropdown's
/// top rows every frame it was open.
fn render_global_search_dropdown(
    app: &App,
    anchor: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let results = app.global_search_results();
    const MAX_VISIBLE_RESULTS: u16 = 8;
    let rows = (results.len() as u16).clamp(1, MAX_VISIBLE_RESULTS);
    let width = anchor.width.max(28);
    let dropdown = Rect::new(anchor.x, anchor.bottom(), width, rows + 2);
    // `width`/`rows + 2` alone assume the strip has that much room to the
    // right and that many rows free below it -- true on a comfortably
    // sized terminal, not guaranteed on a narrow or short one (the anchor
    // can legitimately sit close enough to the right edge, or close
    // enough to the bottom, that the raw rect above runs straight past
    // `buf`'s own bounds). Clamp against the real buffer before painting
    // a single cell -- same pattern `client::clear_rect` already uses for
    // a remembered rect that can outlive a shrink. Without this, `fill_
    // rect` below indexes straight past the buffer's own backing `Vec`
    // and panics; the library's own `Block`/border renderer bounds-checks
    // itself, but this crate's own `fill_rect` does not.
    let dropdown = dropdown.intersect(buf.area());
    layout.note_overlay(dropdown);
    fill_rect(dropdown, theme.modal, buf);
    Block::bordered()
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dropdown, buf);
    // No `[x]`: a dropdown is not a modal. It hangs off the search field
    // and closes by that same field, by a click outside it, or by
    // `Escape` -- `App::click_global_search`'s own `HitTarget::ModalClose`
    // arm stays, harmless and unreachable, for the day this grows a
    // header. A cross was briefly painted here and removed.
    if dropdown.width < 3 || dropdown.height < 3 {
        return;
    }
    let inner = Rect::new(dropdown.x + 1, dropdown.y + 1, dropdown.width - 2, dropdown.height - 2);
    if results.is_empty() {
        let hint = if app.global_search.query.is_empty() {
            "type to search tabs, workspaces, files, agents, views"
        } else {
            "no matches"
        };
        render_modal_line(hint, inner, 0, Style::default().fg(theme.muted).bg(theme.modal), buf);
    } else {
        for (index, result) in results.iter().enumerate().take(inner.height as usize) {
            let selected = index == app.global_search.selected;
            let style = if selected {
                Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(theme.text).bg(theme.modal)
            };
            render_modal_line(result.label.as_str(), inner, index as u16, style, buf);
            push_modal_hit(layout, modal_row(inner, index as u16), HitTarget::GlobalSearchResult(index));
        }
    }
    layout.global_search_dropdown = dropdown;
}

fn render_surface(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    layout.hits.push(HitRegion { rect: area, target: HitTarget::Viewport });
    let mut path = Vec::new();
    render_surface_node(app, &app.surface.root, area, &mut path, buf, layout, theme);
}

fn render_surface_node(
    app: &App,
    node: &PaneNode,
    area: Rect,
    path: &mut Vec<PaneBranch>,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    match node {
        PaneNode::Leaf(pane_id) => render_surface_pane(app, *pane_id, area, buf, layout, theme),
        PaneNode::Split {
            axis,
            ratio_bps,
            first,
            second,
        } => {
            let (first_area, divider, second_area) =
                split_surface_rect(area, *axis, *ratio_bps);
            draw_surface_divider(divider, *axis, buf, theme);
            path.push(PaneBranch::First);
            render_surface_node(app, first, first_area, path, buf, layout, theme);
            path.pop();
            path.push(PaneBranch::Second);
            render_surface_node(app, second, second_area, path, buf, layout, theme);
            path.pop();
            if divider.width > 0 && divider.height > 0 {
                layout.hits.push(HitRegion {
                    rect: divider,
                    target: HitTarget::SurfaceDivider {
                        path: PaneSplitPath(path.clone()),
                        axis: *axis,
                        area,
                    },
                });
            }
        }
    }
}

fn render_surface_pane(
    app: &App,
    pane_id: PaneId,
    frame: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let harness_board = app.agent_board_mode == crate::app::AgentBoardMode::HarnessKanban
        && app.surface.panes.get(&pane_id)
            .and_then(|pane| pane.active_tab()) == Some(&SurfaceTab::AgentBoard);
    let header = Rect::new(frame.x, frame.y, frame.width, frame.height.min(1));
    let actions = Rect::new(
        frame.x,
        frame.y.saturating_add(header.height),
        frame.width,
        frame.height.saturating_sub(header.height).min(if harness_board { 0 } else { 1 }),
    );
    let viewport = Rect::new(
        frame.x,
        frame.y.saturating_add(header.height).saturating_add(actions.height),
        frame.width,
        frame.height.saturating_sub(header.height).saturating_sub(actions.height),
    );
    layout.surface_panes.push(SurfacePaneLayout {
        pane_id,
        frame,
        header,
        viewport,
    });
    layout.hits.push(HitRegion {
        rect: viewport,
        target: HitTarget::SurfacePaneBody(pane_id),
    });
    layout.hits.push(HitRegion {
        rect: header,
        target: HitTarget::SurfacePaneHeader(pane_id),
    });
    let Some(pane) = app.surface.panes.get(&pane_id) else {
        return;
    };
    let focused = app.surface.focused == pane_id;
    let tabs_right = render_surface_pane_tabs(app, pane_id, pane, focused, header, buf, layout, theme);
    // FIX2 (owner report: viewport panes had no mouse close control): only
    // drawn when there is an active tab to actually close -- an empty
    // pane (the fresh-workspace default, the only way a pane can have
    // zero tabs -- see `SurfaceState::remove_pane_if_empty`'s own doc
    // comment) has nothing for it to do.
    if pane.active_tab().is_some() {
        render_surface_pane_close(pane_id, header, tabs_right, buf, layout, theme);
    }
    render_surface_toolbar(
        app,
        pane_id,
        pane.active_tab(),
        actions,
        buf,
        layout,
        theme,
    );
    match pane.active_tab() {
        Some(SurfaceTab::AgentBoard) => {
            render_agent_board(app, viewport, buf, layout, theme);
        }
        Some(SurfaceTab::IconGallery) => {
            render_icon_gallery(app, viewport, buf, layout, theme);
        }
        Some(SurfaceTab::SessionMonitor(key)) => {
            if let Some(monitor) = app.session_monitor(key) {
                render_session_monitor(app, monitor, viewport, buf, layout, theme);
            }
        }
        Some(SurfaceTab::Pty(address)) => {
            if let Some(session) = app.find_session(address) {
                render_terminal(
                    session,
                    viewport,
                    app.color_mode,
                    app.terminal_scroll_offset(&session.address),
                    app.terminal_selection.as_ref(),
                    theme,
                    buf,
                    &app.pty_render_cache,
                    focused,
                );
            }
        }
        Some(SurfaceTab::Preview(key)) => {
            if let Some(preview) = app.preview_tabs.get(key) {
                render_preview_tab(
                    preview,
                    pane_id,
                    viewport,
                    buf,
                    layout,
                    theme,
                    app.activity_spinner(),
                    app.rail_icons, app.icon_family,
                );
            }
        }
        Some(SurfaceTab::HarnessFile(key)) => {
            if let Some(file) = app.harness_file_tabs.get(key) {
                if file.state == WorkspaceFileState::Ready {
                    render_workspace_file_tab_rich(
                        file,
                        key.path.as_utf8().unwrap_or_default(),
                        viewport,
                        buf,
                        theme,
                        true,
                    );
                } else {
                    render_workspace_file_tab(
                        file,
                        key.path.as_utf8().unwrap_or_default(),
                        viewport,
                        buf,
                        theme,
                    );
                }
            }
        }
        Some(SurfaceTab::HarnessGit(key)) => {
            if let Some(git) = app.harness_git_tabs.get(key) {
                render_workspace_git_tab(
                    git,
                    pane_id,
                    viewport,
                    buf,
                    layout,
                    theme,
                    app.activity_spinner(),
                    true,
                );
            }
        }
        Some(SurfaceTab::File(key)) => {
            if let Some(file) = app.file_tabs.get(key) {
                if let Some(history) = file.inline_history.as_ref() {
                    render_workspace_file_history(
                        history,
                        pane_id,
                        viewport,
                        buf,
                        layout,
                        theme,
                        app.activity_spinner(),
                    );
                } else if file.state == WorkspaceFileState::Ready {
                    let content = Rect::new(
                        viewport.x,
                        viewport.y,
                        viewport.width.saturating_sub(if viewport.width > 2 { 1 } else { 0 }),
                        viewport.height,
                    );
                    render_workspace_file_tab_rich(
                        file,
                        key.path.as_utf8().unwrap_or_default(),
                        content,
                        buf,
                        theme,
                        false,
                    );
                    render_file_scrollbar(file, pane_id, viewport, buf, layout, theme);
                } else {
                    render_workspace_file_tab(
                        file,
                        key.path.as_utf8().unwrap_or_default(),
                        viewport,
                        buf,
                        theme,
                    );
                }
            }
        }
        Some(SurfaceTab::Git(key)) => {
            if let Some(git) = app.git_tabs.get(key) {
                render_workspace_git_tab(
                    git,
                    pane_id,
                    viewport,
                    buf,
                    layout,
                    theme,
                    app.activity_spinner(),
                    false,
                );
            }
        }
        None => {}
    }
}

/// FIX4's own main deliverable, widened by a later wave to be the Lucide-
/// vs-codicons comparison surface: the icon gallery dev surface (`app::
/// SurfaceTab::IconGallery`) -- a read-only comparison grid, one row per
/// icon ([`GALLERY_ICON_IDS`], the WHOLE catalog -- this surface is where
/// the owner decides which glyph belongs on which control, and that
/// cannot be decided about icons it does not show), one column PAIR per
/// size/tier variant: the
/// strip tier's own pixel size (`icons::STRIP_SIXEL_ICON_*` -- the SAME
/// asset the control-plane strip already ships), the rail tier's own
/// pixel size (`icons::SIXEL_ICON_*` -- ditto the activity rail), a
/// third, larger size (`icons::GALLERY_SIXEL_ICON_*` -- this surface's
/// own only consumer) -- each tier gets a `Codicons` column immediately
/// followed by its own `Lucide` column (see `render_gallery_size_swatch`)
/// so the two families read side by side AT EACH TIER without toggling
/// any setting, then a dedicated Ascii column.
///
/// The six size/family columns are the sixel tier's own comparison; in
/// `RailIcons::Ascii` (this crate's own single global icon-tier switch,
/// not a per-surface setting -- see `app::RailIcons`) they simply paint
/// that tier's own rendering instead of a sixel image, exactly like the
/// dedicated Ascii column already does -- there is no per-size ascii
/// asset to compare, and forcing a sixel image regardless of the owner's
/// own global tier choice would be new, untested behaviour no other icon
/// site in this crate has (the rail/strip themselves only ever paint
/// their own CURRENT tier too, see `render_rail_button`'s own match).
/// This is a deliberate reading of this surface's own brief ("in the
/// Ascii tier the sixel columns simply show the tier's own rendering"),
/// not a gap.
///
/// Wheel-scrollable (`App::scroll_terminal`'s own `SurfaceTab::
/// IconGallery` arm, `app.icon_gallery_scroll`) since the full grid is
/// taller than most terminal windows; a row only ever paints once it is
/// FULLY inside `area` (never a partially-clipped one) -- sixel bytes are
/// not croppable mid-image the way plain text is, so a partially-visible
/// row is skipped entirely rather than emitted and left to overflow past
/// `area`'s own bottom edge.
fn render_icon_gallery(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    // Every icon the catalog ships, not a curated subset: this surface
    // exists so the owner can decide which glyph belongs on which
    // control, and a decision cannot be made about icons that are not on
    // screen. The two documented Lucide mapping gaps (`CircleFilled`,
    // `RunAll` -- see `icons.rs`'s own "Lucide" doc section) come along
    // with the rest and show their own `n/a` swatch, so the gap is
    // something to look at rather than something to read about.
    const GALLERY_ICON_IDS: [icons::IconId; icons::IconId::ALL.len()] = icons::IconId::ALL;
    const NAME_COL_WIDTH: u16 = 15;
    const SIZE_COL_WIDTH: u16 = 11;
    const ASCII_COL_WIDTH: u16 = 8;
    const COLUMN_GAP: u16 = 1;
    const HEADER_ROWS: u16 = 2;
    let row_height = icons::GALLERY_SIXEL_ICON_CELLS_TALL;
    let row_block_height = row_height.saturating_add(1); // +1 blank gap row

    let size_20_cod = format!("{}x{} Cod", icons::STRIP_SIXEL_ICON_WIDTH_PX, icons::STRIP_SIXEL_ICON_HEIGHT_PX);
    let size_20_luc = format!("{}x{} Luc", icons::STRIP_SIXEL_ICON_WIDTH_PX, icons::STRIP_SIXEL_ICON_HEIGHT_PX);
    let size_40_cod = format!("{}x{} Cod", icons::SIXEL_ICON_WIDTH_PX, icons::SIXEL_ICON_HEIGHT_PX);
    let size_40_luc = format!("{}x{} Luc", icons::SIXEL_ICON_WIDTH_PX, icons::SIXEL_ICON_HEIGHT_PX);
    let size_60_cod = format!("{}x{} Cod", icons::GALLERY_SIXEL_ICON_WIDTH_PX, icons::GALLERY_SIXEL_ICON_HEIGHT_PX);
    let size_60_luc = format!("{}x{} Luc", icons::GALLERY_SIXEL_ICON_WIDTH_PX, icons::GALLERY_SIXEL_ICON_HEIGHT_PX);
    // Tier-major, family-minor ordering ("each row shows the same IconId
    // in BOTH families side by side AT EACH TIER" -- this task's own
    // brief) -- NOT grouped by family first, so the pair a column-scan
    // lands on at any tier is always directly comparable without
    // scrolling past the other two tiers first.
    let headers: [(&str, u16); 8] = [
        ("icon", NAME_COL_WIDTH),
        (size_20_cod.as_str(), SIZE_COL_WIDTH),
        (size_20_luc.as_str(), SIZE_COL_WIDTH),
        (size_40_cod.as_str(), SIZE_COL_WIDTH),
        (size_40_luc.as_str(), SIZE_COL_WIDTH),
        (size_60_cod.as_str(), SIZE_COL_WIDTH),
        (size_60_luc.as_str(), SIZE_COL_WIDTH),
        ("ascii", ASCII_COL_WIDTH),
    ];

    // Header row (column labels) + a `─` separator row directly under it.
    let mut columns: Vec<(u16, u16)> = Vec::with_capacity(headers.len());
    let mut x = area.x;
    for (label, width) in headers {
        columns.push((x, width));
        let visible_width = width.min(area.right().saturating_sub(x));
        if visible_width > 0 {
            Paragraph::new(truncate_cells(label, visible_width as usize))
                .style(Style::default().fg(theme.muted).bg(theme.surface).add_modifier(Modifier::BOLD))
                .render(Rect::new(x, area.y, visible_width, 1), buf);
        }
        x = x.saturating_add(width).saturating_add(COLUMN_GAP);
    }
    if area.height > 1 {
        let separator_y = area.y.saturating_add(1);
        for cx in area.x..area.right() {
            let cell = buf.get_mut(cx, separator_y);
            cell.symbol = "─".into();
            cell.style = Style::default().fg(theme.border).bg(theme.surface);
        }
    }

    let total_content_rows = (GALLERY_ICON_IDS.len() as u16).saturating_mul(row_block_height);
    let available_rows = area.height.saturating_sub(HEADER_ROWS);
    let max_scroll = total_content_rows.saturating_sub(available_rows);
    let scroll = app.icon_gallery_scroll.min(max_scroll);
    // The gallery is a read-only comparison grid with no selected state,
    // so every swatch requests the same "at rest" variant.
    let variant = icons::SixelVariant::GateActive;
    // FIX1: this is a scrollable, often bottom-most (sole-pane) viewport
    // tab, so `area`'s own bottom edge can be the terminal's true last
    // row exactly like the activity rail's own case (see `render_
    // activity_rail`'s own `usable_bottom` doc comment for the full
    // diagnosis) -- reserve the SAME one blank row here so a fully-
    // scrolled gallery row's own sixel swatches can never land there
    // either, not just the rail's buttons.
    let usable_bottom = area.bottom().saturating_sub(1);

    for (row_index, id) in GALLERY_ICON_IDS.into_iter().enumerate() {
        let content_y = HEADER_ROWS.saturating_add((row_index as u16).saturating_mul(row_block_height));
        if content_y < scroll {
            continue;
        }
        let y = area.y.saturating_add(content_y - scroll);
        if y.saturating_add(row_height) > usable_bottom {
            break;
        }

        let (name_x, name_width) = columns[0];
        let visible_name_width = name_width.min(area.right().saturating_sub(name_x));
        if visible_name_width > 0 {
            Paragraph::new(truncate_cells(&format!("{id:?}"), visible_name_width as usize))
                .style(Style::default().fg(theme.text).bg(theme.surface))
                .render(Rect::new(name_x, y, visible_name_width, 1), buf);
        }

        // Inherits `theme.surface`, in every `RailIcons` mode -- same fix
        // as `render_activity_rail`'s own panel fill (see that function's
        // own doc comment for the full regression this reverts): stating
        // `SIDEBAR_BG` here unconditionally used to paint the WHOLE icon-
        // columns band as a lighter plate against the terminal's own real
        // background in `PtyColorMode::Inherited`. `render_gallery_size_
        // swatch`'s own body now tracks `theme.active` at rest instead of
        // a fixed constant (same fix as `render_rail_button`'s own body),
        // so repainting this band with the pane's own `theme.surface`
        // first -- covering the gaps between the strip/rail/gallery/
        // family columns and any padding a swatch's own smaller icon
        // footprint leaves inside its wider column -- keeps the whole row
        // visually flat again, without ever stating a colour distinct
        // from what the pane already shows.
        let (band_x, _) = columns[1];
        let (last_x, last_width) = columns[6];
        let band_right = last_x.saturating_add(last_width).min(area.right());
        if band_right > band_x {
            fill_rect(Rect::new(band_x, y, band_right - band_x, row_height), theme.surface, buf);
        }

        for (col_index, cells_wide, cells_tall, size, family) in [
            (1usize, icons::STRIP_SIXEL_ICON_CELLS_WIDE, icons::STRIP_SIXEL_ICON_CELLS_TALL, SixelIconSize::Strip, IconFamily::Codicons),
            (2usize, icons::STRIP_SIXEL_ICON_CELLS_WIDE, icons::STRIP_SIXEL_ICON_CELLS_TALL, SixelIconSize::Strip, IconFamily::Lucide),
            (3usize, icons::SIXEL_ICON_CELLS_WIDE, icons::SIXEL_ICON_CELLS_TALL, SixelIconSize::Rail, IconFamily::Codicons),
            (4usize, icons::SIXEL_ICON_CELLS_WIDE, icons::SIXEL_ICON_CELLS_TALL, SixelIconSize::Rail, IconFamily::Lucide),
            (5usize, icons::GALLERY_SIXEL_ICON_CELLS_WIDE, icons::GALLERY_SIXEL_ICON_CELLS_TALL, SixelIconSize::Gallery, IconFamily::Codicons),
            (6usize, icons::GALLERY_SIXEL_ICON_CELLS_WIDE, icons::GALLERY_SIXEL_ICON_CELLS_TALL, SixelIconSize::Gallery, IconFamily::Lucide),
        ] {
            let (col_x, col_width) = columns[col_index];
            let swatch = Rect::new(col_x, y, col_width.min(area.right().saturating_sub(col_x)), row_height);
            render_gallery_size_swatch(swatch, id, cells_wide, cells_tall, size, variant, app.rail_icons, family, theme, buf, layout);
        }

        let (ascii_x, ascii_width) = columns[7];
        let visible_ascii_width = ascii_width.min(area.right().saturating_sub(ascii_x));
        if visible_ascii_width > 0 {
            let ascii_bg = Rect::new(ascii_x, y, visible_ascii_width, 1);
            fill_rect(ascii_bg, theme.active, buf);
            Paragraph::new(icons::ascii(id))
                .style(Style::default().fg(theme.text).bg(theme.active).add_modifier(Modifier::BOLD))
                .render(ascii_bg, buf);
        }
    }
}

/// One "size" swatch cell inside [`render_icon_gallery`]'s own grid, now
/// one per (tier, `family`) PAIR rather than one per tier: `RailIcons::
/// Sixel` reserves `area`'s own cell footprint (already a plain,
/// `theme.active`-filled blank -- the SAME background `icons::resolve_
/// variant_background` resolves for this swatch's own placement, in
/// every `PtyColorMode` (see [`icons::SixelVariant`]'s own doc comment);
/// the real pixels are written by `client::run`'s post-flush hook, same
/// split as `render_rail_button`'s own Sixel arm) and records the
/// placement, OR
/// -- when `family` is `Lucide` and `id` is one of the two documented
/// mapping gaps (`icons::lucide_slug(id).is_none()`) -- paints a plain
/// `n/a` label instead of pushing a placement at all: `client::
/// flush_sixel_icon_into` has no baked asset to resolve for that (icon,
/// family) pair and would just silently paint nothing, which would read
/// as a rendering defect rather than the deliberate, reported gap it
/// actually is. `Ascii` paints that tier's OWN rendering directly with
/// the theme-dependent `theme.active` (plain text, no raster to align --
/// see [`render_icon_gallery`]'s own doc comment for why this collapses
/// every size/family column to the SAME content in that tier).
///
/// DEFECT 2 (owner: gallery icons overflow onto the pane's own frame):
/// `client::flush_sixel_icon_into` prints whichever of `icons::sixel*`
/// matches `size` UNCONDITIONALLY at that asset's own fixed native pixel
/// size (`cells_wide` x `cells_tall` cells' worth) -- `placement.rect` is
/// bookkeeping for cursor position and occlusion, never a crop box (a
/// sixel image cannot be cropped to a sub-rect at all, only dropped
/// whole -- see `render::render`'s own `drop_sixel_icons_covered_by_
/// overlays` doc comment for the same constraint elsewhere). The former
/// `area.width.min(cells_wide)` here shrank the RESERVED rect to fit a
/// narrow pane, which looked safe (the bookkeeping rect always landed
/// inside `area`), but `flush_sixel_icon_into` still painted the FULL,
/// un-shrunk asset at that rect's origin -- the real pixels beyond the
/// shrunk width/height bled straight past `area`'s own edge onto
/// whatever the pane's frame or neighbor painted there. Reproduced (see
/// `render::tests::gallery_swatch_drops_a_placement_that_does_not_fit_
/// its_own_column_instead_of_shrinking_it`) at gallery pane widths where
/// the rightmost (Gallery-tier) column's own available width lands
/// strictly between 1 and `cells_wide - 1`. The fix: a placement is
/// emitted at its full native size or not at all.
fn render_gallery_size_swatch(
    area: Rect,
    id: icons::IconId,
    cells_wide: u16,
    cells_tall: u16,
    size: SixelIconSize,
    variant: icons::SixelVariant,
    tier: RailIcons,
    family: IconFamily,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    match tier {
        RailIcons::Sixel => {
            if area.width < cells_wide || area.height < cells_tall {
                // Does not fit whole: drop it (never crop it -- see this
                // fn's own doc comment). Still paint a plain background
                // patch over whatever room IS available so a too-narrow
                // column reads as an empty swatch, not stale content --
                // `theme.active`, matching every other at-rest sixel body
                // now (see `render_rail_button`'s own doc comment for why
                // this tracks the theme instead of a fixed constant): the
                // gallery is a read-only comparison grid, `variant` is
                // always `GateActive` here (`render_icon_gallery`'s own
                // caller), so this is the ONE background this swatch ever
                // needs.
                fill_rect(area, theme.active, buf);
                return;
            }
            let icon_area = Rect::new(area.x, area.y, cells_wide, cells_tall);
            fill_rect(icon_area, theme.active, buf);
            if family == IconFamily::Lucide && icons::lucide_slug(id).is_none() {
                let label_row = Rect::new(icon_area.x, icon_area.y + icon_area.height / 2, icon_area.width, 1);
                Paragraph::new(centered_label("n/a", label_row.width as usize))
                    .style(Style::default().fg(theme.muted).bg(theme.active))
                    .render(label_row, buf);
                return;
            }
            layout.sixel_icons.push(SixelIconPlacement { icon: id, rect: icon_area, variant, size, family });
        }
        RailIcons::Ascii => {
            let label_area = Rect::new(area.x, area.y, area.width.min(2), 1);
            fill_rect(Rect::new(area.x, area.y, area.width, 1), theme.active, buf);
            Paragraph::new(icons::ascii(id))
                .style(Style::default().fg(theme.text).bg(theme.active).add_modifier(Modifier::BOLD))
                .render(label_area, buf);
        }
    }
}

fn render_session_monitor_toolbar(
    app: &App,
    pane_id: PaneId,
    key: &SessionMonitorKey,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    fill_rect(area, theme.active, buf);
    let selected = app.session_monitor(key)
        .map(|monitor| monitor.section)
        .unwrap_or_default();
    let selected_index = SessionMonitorSection::ALL
        .iter()
        .position(|section| *section == selected)
        .unwrap_or(0);
    let segment_width = |section: SessionMonitorSection| {
        (cell_width(section.label()) + 2).min(u16::MAX as usize) as u16
    };
    let total_width = SessionMonitorSection::ALL
        .iter()
        .map(|section| segment_width(*section))
        .fold(0_u16, u16::saturating_add);
    let start = if total_width <= area.width { 0 } else { selected_index };
    let mut x = area.x;
    for section in SessionMonitorSection::ALL.iter().copied().skip(start) {
        if x >= area.right() {
            break;
        }
        let label = format!(" {} ", section.label());
        let width = segment_width(section).min(area.right().saturating_sub(x));
        if width == 0 {
            break;
        }
        let rect = Rect::new(x, area.y, width, 1);
        Paragraph::new(truncate_cells(&label, width as usize))
            .style(
                Style::default()
                    .fg(if section == selected { theme.active_tab_text } else { theme.muted })
                    .bg(if section == selected { theme.accent } else { theme.active })
                    .add_modifier(if section == selected { Modifier::BOLD } else { Modifier::empty() }),
            )
            .render(rect, buf);
        layout.hits.push(HitRegion {
            rect,
            target: HitTarget::SessionMonitorSection(pane_id, section),
        });
        x = x.saturating_add(width);
    }
}

fn render_session_monitor(
    app: &App,
    monitor: &SessionMonitorView,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    fill_rect(area, theme.surface, buf);
    if area.width == 0 || area.height == 0 {
        return;
    }
    let width = area.width.min(104);
    let content = Rect::new(
        area.x.saturating_add(area.width.saturating_sub(width) / 2),
        area.y,
        width,
        area.height,
    );
    fill_rect(content, theme.panel, buf);
    let mut lines = session_monitor_lines(app, monitor);
    let visible = content.height as usize;
    let maximum = lines.len().saturating_sub(visible);
    let scroll = monitor.section_scroll().min(maximum);
    lines = lines.into_iter().skip(scroll).take(visible).collect();
    for (index, line) in lines.iter().enumerate() {
        let y = content.y.saturating_add(index as u16);
        if y >= content.bottom() {
            break;
        }
        let source_index = scroll.saturating_add(index);
        if monitor.section == SessionMonitorSection::Usage && source_index == 3 {
            if let Some(projection) = app.session_monitor_projection(&monitor.key) {
                if let Ok((snapshot, context_window)) = available_context_occupancy(projection) {
                    render_context_usage_bar(
                        snapshot,
                        context_window,
                        Rect::new(content.x, y, content.width.min(72), 1),
                        buf,
                        layout,
                        theme,
                    );
                    continue;
                }
            }
        }
        Paragraph::new(truncate_cells(line, content.width as usize))
            .style(Style::default().fg(if index == 0 { theme.text } else { theme.dim }).bg(theme.panel))
            .render(Rect::new(content.x, y, content.width, 1), buf);
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ContextUsageBarSegment {
    hit: ContextUsageSegmentHit,
    width: u16,
    color: Color,
}

fn available_context_occupancy(
    projection: &SessionProjection,
) -> Result<(ContextOccupancySnapshot, u64), &'static str> {
    let snapshot = projection
        .usage
        .context_occupancy
        .ok_or("no authoritative usage snapshot")?;
    let context_window = exact_context_window(snapshot)?;
    if projection.availability != ProjectionAvailability::Current
        || projection.freshness != ProjectionFreshness::Live
    {
        return Err("projection is not current and live");
    }
    if projection.transport_incomplete
        || projection.incomplete_evidence.contains(&snapshot.evidence)
    {
        return Err("usage source is incomplete after a gap");
    }
    Ok((snapshot, context_window))
}

fn exact_context_window(snapshot: ContextOccupancySnapshot) -> Result<u64, &'static str> {
    if snapshot.provenance != ContextOccupancyProvenance::ExactCurrentWindow {
        return Err("usage accounting is not an exact current-window signal");
    }
    if snapshot.evidence
        != gate4agent_node_protocol::ObservationEvidenceV1::StructuredProvider
    {
        return Err("exact current-window source is not structured provider evidence");
    }
    let context_window = snapshot
        .context_window
        .ok_or("context window was not reported by this source")?;
    if context_window == 0 {
        return Err("reported context window is zero");
    }
    Ok(context_window)
}

/// The five cache/segment breakdown values together, only when every one
/// of them was actually observed. `None` means the source reported
/// `used_tokens`/`capacity_tokens` alone (e.g. an ACP `usage_update`) and
/// never observed how the total decomposes -- the caller must not draw or
/// print a per-segment figure in that case, since a zero would assert an
/// empty segment nobody measured.
fn context_usage_breakdown(
    snapshot: &ContextOccupancySnapshot,
) -> Option<(u64, u64, u64, u64, u64)> {
    Some((
        snapshot.uncached_input_tokens?,
        snapshot.cache_read_tokens?,
        snapshot.cache_write_tokens?,
        snapshot.output_tokens?,
        snapshot.unattributed_tokens?,
    ))
}

fn context_usage_bar_segments(
    snapshot: ContextOccupancySnapshot,
    context_window: u64,
    width: u16,
    theme: Theme,
) -> Vec<ContextUsageBarSegment> {
    let occupied = snapshot.occupied_tokens();
    let remaining = context_window.saturating_sub(occupied);
    let values: Vec<(ContextUsageSegment, u64, Color)> =
        match context_usage_breakdown(&snapshot) {
            Some((uncached_input, cache_read, cache_write, output, unattributed)) => vec![
                (ContextUsageSegment::UncachedInput, uncached_input, theme.accent),
                (ContextUsageSegment::CacheRead, cache_read, theme.teal),
                (ContextUsageSegment::CacheWrite, cache_write, theme.yellow),
                (ContextUsageSegment::ProviderOutput, output, theme.green),
                (ContextUsageSegment::Unattributed, unattributed, theme.red),
                (ContextUsageSegment::Remaining, remaining, theme.border),
            ],
            None => vec![
                (ContextUsageSegment::Occupied, occupied, theme.accent),
                (ContextUsageSegment::Remaining, remaining, theme.border),
            ],
        };
    let mut unassigned_width = width;
    let mut segments = values
        .into_iter()
        .map(|(segment, tokens, color)| {
            let proportional = ((tokens as u128 * width as u128) / context_window as u128)
                .min(width as u128) as u16;
            let segment_width = proportional.min(unassigned_width);
            unassigned_width = unassigned_width.saturating_sub(segment_width);
            ContextUsageBarSegment {
                hit: ContextUsageSegmentHit {
                    segment,
                    tokens,
                    context_window,
                    evidence: snapshot.evidence,
                },
                width: segment_width,
                color,
            }
        })
        .collect::<Vec<_>>();
    let assigned = segments
        .iter()
        .map(|segment| segment.width)
        .fold(0_u16, u16::saturating_add)
        .min(width);
    let leftover = width.saturating_sub(assigned);
    if leftover != 0 {
        let recipient = if remaining != 0 {
            segments.len().saturating_sub(1)
        } else {
            segments
                .iter()
                .rposition(|segment| segment.hit.tokens != 0)
                .unwrap_or(0)
        };
        segments[recipient].width = segments[recipient].width.saturating_add(leftover).min(width);
    }
    segments
}

fn render_context_usage_bar(
    snapshot: ContextOccupancySnapshot,
    context_window: u64,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let mut x = area.x;
    for segment in context_usage_bar_segments(snapshot, context_window, area.width, theme) {
        let width = segment.width.min(area.right().saturating_sub(x));
        if width == 0 {
            continue;
        }
        let rect = Rect::new(x, area.y, width, 1);
        fill_rect(rect, segment.color, buf);
        layout.hits.push(HitRegion {
            rect,
            target: HitTarget::ContextUsageSegment(segment.hit),
        });
        x = x.saturating_add(width);
        if x >= area.right() {
            break;
        }
    }
}

fn render_context_usage_tooltip(
    hover: Option<ContextUsageHover>,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &LayoutRects,
    theme: Theme,
) {
    let Some(hover) = hover else {
        return;
    };
    let still_hovered = layout.hits.iter().rev().any(|region| {
        region.rect.contains(hover.column, hover.row)
            && matches!(&region.target, HitTarget::ContextUsageSegment(hit) if *hit == hover.hit)
    });
    if !still_hovered || area.width == 0 || area.height < 3 {
        return;
    }
    let basis_points = (hover.hit.tokens as u128 * 10_000_u128)
        / hover.hit.context_window as u128;
    let percent_whole = basis_points / 100;
    let percent_fraction = basis_points % 100;
    let detail = format!(
        "{}: {} tokens | share {}/{} ({percent_whole}.{percent_fraction:02}%) | window {} tokens",
        hover.hit.segment.label(),
        hover.hit.tokens,
        hover.hit.tokens,
        hover.hit.context_window,
        hover.hit.context_window,
    );
    let source = format!(
        "Current / Live | source {}",
        observation_evidence_label(hover.hit.evidence),
    );
    // The formula has to describe the segment actually under the cursor. The
    // five breakdown segments only exist when the source reported a
    // breakdown, so the sum is true whenever one of them is hovered.
    // `Occupied` is drawn only when it did NOT, and stating a decomposition
    // there would claim a division of the total that nothing measured --
    // the same lie the wire stopped telling when these fields became
    // optional. `Remaining` is drawn in both cases, so its line has to hold
    // in both, and it does.
    let formula = match hover.hit.segment {
        ContextUsageSegment::UncachedInput
        | ContextUsageSegment::CacheRead
        | ContextUsageSegment::CacheWrite
        | ContextUsageSegment::ProviderOutput
        | ContextUsageSegment::Unattributed => {
            "Formula: used = uncached input + cache read + cache write + provider output + unattributed (reasoning excluded)"
        }
        ContextUsageSegment::Occupied => {
            "Formula: used = the total the provider reported; it reported no breakdown of that total"
        }
        ContextUsageSegment::Remaining => "Formula: remaining = window - used",
    };
    let desired_width = cell_width(&detail)
        .max(cell_width(&source))
        .max(cell_width(formula))
        .min(120);
    let width = (desired_width as u16).min(area.width);
    let x = hover
        .column
        .min(area.right().saturating_sub(width))
        .max(area.x);
    let preferred_y = hover.row.saturating_add(1);
    let y = if preferred_y.saturating_add(3) <= area.bottom() {
        preferred_y
    } else {
        hover.row.saturating_sub(3).max(area.y)
    };
    let rect = Rect::new(x, y, width, 3);
    fill_rect(rect, theme.modal, buf);
    Paragraph::new(format!(
        "{}\n{}\n{}",
        truncate_cells(&detail, width as usize),
        truncate_cells(&source, width as usize),
        truncate_cells(formula, width as usize),
    ))
    .style(Style::default().fg(theme.text).bg(theme.modal))
    .render(rect, buf);
}

fn session_monitor_lines(app: &App, monitor: &SessionMonitorView) -> Vec<String> {
    let mut lines = vec![format!("Session Monitor | {}", monitor.section.label())];
    let persistence = match &app.observation_persistence {
        ObservationPersistenceState::Available { revision } => {
            format!("Persistence: committed revision {revision}")
        }
        ObservationPersistenceState::Unavailable(reason) => {
            format!("Persistence unavailable: {reason}")
        }
    };
    let monitor_node = if monitor.node_restarted {
        None
    } else {
        app.nodes.iter().find(|node| {
            node.node_id == monitor.key.target.node_id()
                && node.incarnation_id == Some(monitor.key.target.incarnation())
        })
    };
    lines.push(format!(
        "{persistence} | Node route: {}",
        relay_route_label(
            monitor_node
                .map(|node| node.relay_route)
                .unwrap_or(C2RelayRoute::Unknown),
        ),
    ));
    if !monitor.support.known {
        lines.push("Observation support unknown: waiting for node metadata".to_owned());
        return lines;
    }
    if matches!(&monitor.key.target, SessionMonitorTarget::Managed { .. })
        && !monitor.support.managed_target
    {
        lines.push("Managed target unavailable: capability not negotiated".to_owned());
        return lines;
    }
    if !monitor.support.events {
        lines.push("Observation events unavailable: capability not negotiated".to_owned());
        return lines;
    }
    let Some(projection) = app.session_monitor_projection(&monitor.key) else {
        lines.push("Waiting for observation events".to_owned());
        if matches!(monitor.section, SessionMonitorSection::Workflow | SessionMonitorSection::FilesGit)
            && !monitor.support.workflow_detail
        {
            lines.push("Workflow detail unavailable: capability not negotiated".to_owned());
        }
        return lines;
    };
    if matches!(monitor.section, SessionMonitorSection::Workflow | SessionMonitorSection::FilesGit)
        && !monitor.support.workflow_detail
    {
        lines.push("Workflow detail unavailable: capability not negotiated".to_owned());
        match monitor.section {
            SessionMonitorSection::Workflow => lines.push(format!(
                "Todo snapshots: {}",
                observation_capability_label(projection, |capabilities| capabilities.todo),
            )),
            SessionMonitorSection::FilesGit => lines.push(format!(
                "File-change events: {}",
                observation_capability_label(projection, |capabilities| capabilities.file_changes),
            )),
            _ => {}
        }
        return lines;
    }

    match monitor.section {
        SessionMonitorSection::Overview => {
            let incarnation = monitor.key.target.incarnation().to_string();
            match &monitor.key.target {
                SessionMonitorTarget::Runtime { address, .. } => lines.push(format!(
                    "Identity: runtime {} / {} / #{}:{} / incarnation {}",
                    address.node_id,
                    address.workspace_id,
                    address.instance_id,
                    address.generation,
                    &incarnation[..incarnation.len().min(8)],
                )),
                SessionMonitorTarget::Managed { node_id, record_id, .. } => {
                    lines.push(format!(
                        "Identity: managed {node_id} / @{record_id} / incarnation {}",
                        &incarnation[..incarnation.len().min(8)],
                    ));
                    if let Some(record) = app.find_managed_session(&monitor.key.agent) {
                        lines.push(format!(
                            "Managed record: {} | {}",
                            managed_state_label(record.state),
                            if record.active_session.is_some() {
                                "active runtime linked"
                            } else {
                                "no active runtime"
                            },
                        ));
                    } else {
                        lines.push("Managed record: unavailable | retained facts".to_owned());
                    }
                }
            }
            let transport = if monitor.node_restarted {
                "node restarted; historical session"
            } else {
                monitor_node
                    .map(|node| match node.connection {
                        ConnectionState::Connected => "connected",
                        ConnectionState::Connecting => "connecting",
                        ConnectionState::Resyncing => "resyncing",
                        ConnectionState::Disconnected(_) => "disconnected; retained facts",
                    })
                    .unwrap_or("historical; retained facts")
            };
            lines.push(format!("Transport: {transport}"));
            lines.push(format!(
                "Projection: {} | {}",
                projection_availability_label(projection.availability),
                projection_freshness_label(projection.freshness),
            ));
            let last = projection.timeline.back();
            let source_epoch = projection.timeline.iter()
                .filter(|entry| matches!(entry.kind, gate4agent_node_protocol::ObservationKindV1::SourceReset))
                .count();
            lines.push(format!(
                "Source: epoch {} | sequence {} | {}",
                source_epoch,
                last.map(|entry| entry.cursor.sequence.to_string()).unwrap_or_else(|| "waiting".to_owned()),
                if projection.incomplete_evidence.is_empty() {
                    "no reported source gap"
                } else {
                    "partial"
                },
            ));
            if let Some(last) = last {
                lines.push(format!("Evidence: {}", observation_evidence_label(last.evidence)));
                if last.evidence == gate4agent_node_protocol::ObservationEvidenceV1::PtyHint {
                    lines.push("PTY hint is non-authoritative".to_owned());
                }
            }
            lines.push(format!("Observations retained: {}", projection.timeline.len()));
        }
        SessionMonitorSection::Workflow => {
            let current = projection.timeline.iter().rev()
                .find(|entry| !matches!(
                    entry.kind,
                    gate4agent_node_protocol::ObservationKindV1::TodoSnapshot { .. }
                        | gate4agent_node_protocol::ObservationKindV1::Usage { .. }
                        | gate4agent_node_protocol::ObservationKindV1::ContextWindowUsage { .. }
                        | gate4agent_node_protocol::ObservationKindV1::FileChanged { .. }
                        | gate4agent_node_protocol::ObservationKindV1::Gap { .. }
                        | gate4agent_node_protocol::ObservationKindV1::SourceReset
                        | gate4agent_node_protocol::ObservationKindV1::Stale
                ));
            lines.push(format!(
                "Current: {}",
                current.map(|entry| crate::app::observation_kind_label(&entry.kind))
                    .unwrap_or("not observed")
            ));
            if let Some(todo) = projection.todos.current.as_ref() {
                let todos = &todo.items;
                let pending = todos.iter().filter(|item| matches!(item.state, gate4agent_node_protocol::ObservationTodoStateV1::Pending)).count();
                let active = todos.iter().filter(|item| matches!(item.state, gate4agent_node_protocol::ObservationTodoStateV1::InProgress)).count();
                let completed = todos.iter().filter(|item| matches!(item.state, gate4agent_node_protocol::ObservationTodoStateV1::Completed)).count();
                let unknown = todos.len().saturating_sub(pending + active + completed);
                lines.push(format!("Todo snapshot: {} items | pending {pending} | active {active} | completed {completed} | unknown {unknown}", todos.len()));
                lines.push(format!("Todo complete: {}", todo.complete));
                if projection.todos.conflict {
                    lines.push("Todo revision conflict; projection is partial".to_owned());
                }
            } else {
                lines.push(format!(
                    "Todo snapshots: {}",
                    observation_capability_label(projection, |capabilities| capabilities.todo),
                ));
            }
            if !projection.stale_evidence.is_empty() {
                lines.push("Source marked stale; workflow projection is partial".to_owned());
            }
        }
        SessionMonitorSection::Subagents => {
            if projection.subagents.is_empty() {
                lines.push(format!(
                    "Subagent events: {}",
                    observation_capability_label(projection, |capabilities| capabilities.subagents),
                ));
            }
            for fact in projection.subagents.iter().rev() {
                lines.push(correlation_line(fact));
            }
        }
        SessionMonitorSection::Tools => {
            if projection.tools.is_empty() && projection.owned_processes.is_empty() {
                lines.push(format!(
                    "Tool events: {}",
                    observation_capability_label(projection, |capabilities| capabilities.tools),
                ));
                lines.push(format!(
                    "Owned-process events: {}",
                    observation_capability_label(projection, |capabilities| capabilities.owned_processes),
                ));
            }
            for fact in projection.tools.iter().rev() {
                lines.push(format!("tool | {}", correlation_line(fact)));
            }
            for fact in projection.owned_processes.iter().rev() {
                lines.push(format!("process | {}", correlation_line(fact)));
            }
        }
        SessionMonitorSection::Approvals => {
            if projection.interactions.is_empty() {
                lines.push(format!(
                    "Attention events: {}",
                    observation_capability_label(projection, |capabilities| capabilities.attention),
                ));
            }
            for fact in projection.interactions.iter().rev() {
                lines.push(correlation_line(fact));
            }
        }
        SessionMonitorSection::FilesGit => {
            if projection.files.is_empty() {
                lines.push(format!(
                    "File-change events: {}",
                    observation_capability_label(projection, |capabilities| capabilities.file_changes),
                ));
            }
            for file in projection.files.iter().rev() {
                lines.push(format!(
                    "Changed: {} | {}",
                    file.path.as_deref().unwrap_or("path not reported"),
                    observation_evidence_label(file.evidence),
                ));
            }
        }
        SessionMonitorSection::Usage => {
            let usage = projection.usage.observed_delta;
            match available_context_occupancy(projection) {
                Ok((snapshot, context_window)) => {
                    let occupied = snapshot.occupied_tokens();
                    let status = if occupied > context_window {
                        format!(
                            "Context: {occupied} / {context_window} tokens | over-capacity; exceeds reported window by {}",
                            occupied.saturating_sub(context_window),
                        )
                    } else {
                        format!("Context: {occupied} / {context_window} tokens")
                    };
                    lines.push(status);
                    lines.push(String::new());
                    if let Some((uncached_input, cache_read, cache_write, output, unattributed)) =
                        context_usage_breakdown(&snapshot)
                    {
                        lines.push(format!("Uncached input: {uncached_input}"));
                        lines.push(format!("Cache read: {cache_read}"));
                        lines.push(format!("Cache write: {cache_write}"));
                        lines.push(format!("Provider output: {output}"));
                        lines.push(format!("Unattributed: {unattributed}"));
                    }
                    lines.push(format!(
                        "Remaining: {}",
                        context_window.saturating_sub(occupied),
                    ));
                    lines.push(format!(
                        "Source: {} | exact current-window signal",
                        observation_evidence_label(snapshot.evidence),
                    ));
                }
                Err(reason) => lines.push(format!("Context: not reported | {reason}")),
            }
            if projection.usage.last_cumulative.is_some()
                || usage.input_tokens != 0
                || usage.output_tokens != 0
                || usage.cache_read_tokens != 0
                || usage.cache_write_tokens != 0
                || usage.reasoning_tokens != 0
            {
                lines.push(format!("Observed input delta: {}", usage.input_tokens));
                lines.push(format!("Observed output delta: {}", usage.output_tokens));
                lines.push(format!("Observed cache read / write delta: {} / {}", usage.cache_read_tokens, usage.cache_write_tokens));
                lines.push(format!("Observed reasoning delta: {}", usage.reasoning_tokens));
                lines.push("Accounting: observed delta; not active-context occupancy".to_owned());
            } else {
                lines.push(format!(
                    "Usage events: {}",
                    observation_capability_label(projection, |capabilities| capabilities.usage),
                ));
            }
            if let Some(history) = projection.history.as_ref() {
                let messages = if history.message_count_exact {
                    format!("{}", history.message_count)
                } else {
                    format!("{} observed; total incomplete", history.message_count)
                };
                let turns = history
                    .completed_turn_count
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_owned());
                let tokens = history
                    .total_tokens
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_owned());
                lines.push(format!(
                    "History summary: messages {messages} | completed turns {turns} | total tokens {tokens}",
                ));
            } else {
                lines.push(format!(
                    "History summary: {}",
                    observation_capability_label(projection, |capabilities| capabilities.history_summary),
                ));
            }
        }
        SessionMonitorSection::Timeline => {
            for item in projection.timeline.iter().rev() {
                lines.push(format!(
                    "node {} | received {} | {} | {}",
                    item.cursor.sequence,
                    item.received_at_ms,
                    observation_evidence_label(item.evidence),
                    crate::app::observation_kind_label(&item.kind),
                ));
            }
        }
    }
    lines
}

fn observation_capability_label(
    projection: &SessionProjection,
    supported: impl Fn(gate4agent_node_protocol::ObservationCapabilitiesV1) -> bool,
) -> &'static str {
    if projection.source_capabilities.is_empty() {
        "not observed"
    } else if projection
        .source_capabilities
        .iter()
        .any(|source| supported(source.capabilities))
    {
        "supported; no event observed"
    } else {
        "not supported by observed sources"
    }
}

fn projection_availability_label(availability: ProjectionAvailability) -> &'static str {
    match availability {
        ProjectionAvailability::Unknown => "unknown",
        ProjectionAvailability::NotObserved => "not observed",
        ProjectionAvailability::Current => "current",
        ProjectionAvailability::Partial => "partial",
        ProjectionAvailability::Frozen => "frozen",
    }
}

fn projection_freshness_label(freshness: ProjectionFreshness) -> &'static str {
    match freshness {
        ProjectionFreshness::Live => "live",
        ProjectionFreshness::LastKnown => "last known",
        ProjectionFreshness::Stale => "stale",
        ProjectionFreshness::IncompleteAfterGap => "incomplete after gap",
        ProjectionFreshness::ReplacedIncarnation => "replaced incarnation",
        ProjectionFreshness::Unavailable => "unavailable",
    }
}

fn correlation_line(fact: &CorrelationProjection) -> String {
    let class = fact.class.as_deref().unwrap_or("class not reported");
    let state = match fact.state {
        CorrelationState::Pending => "pending".to_owned(),
        CorrelationState::Completed { success } => success
            .map(|success| if success { "completed | success" } else { "completed | failure" })
            .unwrap_or("completed")
            .to_owned(),
        CorrelationState::Resolved { outcome } => {
            format!("resolved | {}", interaction_outcome_label(outcome))
        }
        CorrelationState::UnknownAfterGap => "unknown after gap".to_owned(),
        CorrelationState::OrphanCompletion { success } => success
            .map(|success| if success { "orphan completion | success" } else { "orphan completion | failure" })
            .unwrap_or("orphan completion")
            .to_owned(),
        CorrelationState::OrphanResolution { outcome } => {
            format!("orphan resolution | {}", interaction_outcome_label(outcome))
        }
    };
    format!("{class} | {state} | {}", observation_evidence_label(fact.evidence))
}

fn observation_evidence_label(evidence: gate4agent_node_protocol::ObservationEvidenceV1) -> &'static str {
    match evidence {
        gate4agent_node_protocol::ObservationEvidenceV1::StructuredProvider => "structured provider",
        gate4agent_node_protocol::ObservationEvidenceV1::ManagedHook => "managed hook",
        gate4agent_node_protocol::ObservationEvidenceV1::NodeLifecycle => "node lifecycle",
        gate4agent_node_protocol::ObservationEvidenceV1::WorkspaceObservation => "workspace observation",
        gate4agent_node_protocol::ObservationEvidenceV1::PtyHint => "PTY hint",
        gate4agent_node_protocol::ObservationEvidenceV1::HistoryProjection => "history",
    }
}

fn interaction_outcome_label(
    outcome: gate4agent_node_protocol::ObservationInteractionOutcomeV1,
) -> &'static str {
    match outcome {
        gate4agent_node_protocol::ObservationInteractionOutcomeV1::Approved => "approved",
        gate4agent_node_protocol::ObservationInteractionOutcomeV1::Answered => "answered",
        gate4agent_node_protocol::ObservationInteractionOutcomeV1::Denied => "denied",
        gate4agent_node_protocol::ObservationInteractionOutcomeV1::Interrupted => "interrupted",
        gate4agent_node_protocol::ObservationInteractionOutcomeV1::TurnEnded => "turn ended",
        gate4agent_node_protocol::ObservationInteractionOutcomeV1::Superseded => "superseded",
    }
}

fn render_agent_board(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    if app.agent_board_mode == crate::app::AgentBoardMode::HarnessKanban {
        render_harness_kanban(app, area, buf, layout, theme);
        return;
    }
    let cards = app.agent_board_cards();
    let area = if let Some(task_id) = app.agent_board.task_filter.as_ref().filter(|_| !cards.is_empty()) {
        let header = format!("Task {task_id} · {} observed runs", cards.len());
        Paragraph::new(truncate_cells(&header, area.width as usize))
            .style(Style::default().fg(theme.text).bg(theme.active).add_modifier(Modifier::BOLD))
            .render(Rect::new(area.x, area.y, area.width, 1), buf);
        Rect::new(area.x, area.y.saturating_add(1), area.width, area.height.saturating_sub(1))
    } else {
        area
    };
    if cards.is_empty() {
        Paragraph::new(
            "No managed or live agents in the current topology. Provider history is read-only; resume a session to monitor it here.",
        )
            .style(Style::default().fg(theme.muted).bg(theme.surface))
            .render(area, buf);
        return;
    }
    let visible_count = (area.width / 24).clamp(1, AgentBoardColumn::ALL.len() as u16) as usize;
    let maximum_start = AgentBoardColumn::ALL.len().saturating_sub(visible_count);
    let mut start = app.agent_board.column_scroll.min(maximum_start);
    if let Some(selected) = app.agent_board.selected.as_ref() {
        if let Some(card) = cards.iter().find(|card| &card.key == selected) {
            if let Some(index) = AgentBoardColumn::ALL
                .iter()
                .position(|column| *column == card.column)
            {
                if index < start {
                    start = index;
                } else if index >= start.saturating_add(visible_count) {
                    start = index.saturating_add(1).saturating_sub(visible_count);
                }
            }
        }
    }
    let base_width = area.width / visible_count as u16;
    let remainder = area.width % visible_count as u16;
    let card_height = 5_u16;
    let mut x = area.x;
    for visible_index in 0..visible_count {
        let column = AgentBoardColumn::ALL[start + visible_index];
        let width = base_width + u16::from((visible_index as u16) < remainder);
        let column_cards = cards
            .iter()
            .filter(|card| card.column == column)
            .collect::<Vec<_>>();
        Paragraph::new(format!("{} ({})", column.label(), column_cards.len()))
            .style(
                Style::default()
                    .fg(theme.text)
                    .bg(theme.active)
                    .add_modifier(Modifier::BOLD),
            )
            .render(Rect::new(x, area.y, width.saturating_sub(1), 1), buf);
        if column_cards.is_empty() {
            if area.height > 1 {
                Paragraph::new("No sessions observed")
                    .style(Style::default().fg(theme.muted).bg(theme.surface))
                    .render(Rect::new(x, area.y + 1, width.saturating_sub(1), 1), buf);
            }
            x = x.saturating_add(width);
            continue;
        }
        let capacity = area.height.saturating_sub(1) as usize / card_height as usize;
        if capacity == 0 {
            x = x.saturating_add(width);
            continue;
        }
        let mut offset = app
            .agent_board
            .vertical_offsets
            .get(&column)
            .copied()
            .unwrap_or(0)
            .min(column_cards.len().saturating_sub(1));
        if let Some(selected) = app.agent_board.selected.as_ref() {
            if let Some(index) = column_cards.iter().position(|card| &card.key == selected) {
                if index < offset {
                    offset = index;
                } else if index >= offset.saturating_add(capacity) {
                    offset = index.saturating_add(1).saturating_sub(capacity);
                }
            }
        }
        for (slot, card) in column_cards.iter().skip(offset).take(capacity).enumerate() {
            let y = area.y.saturating_add(1 + slot as u16 * card_height);
            let card_area = Rect::new(
                x,
                y,
                width.saturating_sub(1),
                card_height.min(area.bottom().saturating_sub(y)),
            );
            render_agent_board_card(app, card, card_area, buf, layout, theme);
        }
        x = x.saturating_add(width);
    }
}

/// Sessions strip caps out here (1 summary line + a few session rows) even
/// on a generously tall terminal; it stays a compact rail, not a second
/// board.
const HARNESS_SESSIONS_STRIP_MAX_ROWS: u16 = 4;
/// Rows the Harness Kanban board's own chrome (divider + column header row +
/// divider) plus at least two stacked task cards must keep before the
/// sessions strip may claim any of the remaining height. Keeps the strip
/// from crushing the kanban board on small terminals.
const HARNESS_SESSIONS_STRIP_RESERVED_KANBAN_ROWS: u16 = 13;

fn render_harness_kanban(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    use crate::app::HarnessKanbanColumn;
    if area.width == 0 || area.height == 0 {
        return;
    }
    if let Some(monitor) = app.harness_kanban.monitor.as_ref() {
        render_harness_monitor(app, monitor, area, buf, layout, theme);
        return;
    }
    if app.harness_kanban.detail.is_some() {
        render_harness_task_detail(app, area, buf, layout, theme);
        return;
    }
    draw_harness_board_frame(area, buf, theme);
    let inner = Rect::new(
        area.x.saturating_add(1),
        area.y.saturating_add(1),
        area.width.saturating_sub(2),
        area.height.saturating_sub(2),
    );
    let visible_count = (inner.width / 22)
        .clamp(1, HarnessKanbanColumn::ALL.len() as u16) as usize;
    let maximum_start = HarnessKanbanColumn::ALL.len().saturating_sub(visible_count);
    let start = app.harness_kanban.column_scroll.min(maximum_start);
    let button_style = Style::default().fg(theme.teal).bg(theme.active);
    let selected_tab_style = Style::default()
        .fg(theme.text)
        .bg(theme.panel)
        .add_modifier(Modifier::BOLD);
    let global_header = Rect::new(inner.x, inner.y, inner.width, inner.height.min(1));
    fill_rect(global_header, theme.active, buf);
    let mut action_x = render_toolbar_segment(
        "[Tasks]",
        global_header.x,
        global_header,
        selected_tab_style,
        Some(HitTarget::HarnessBoardMode(crate::app::AgentBoardMode::HarnessKanban)),
        buf,
        layout,
    ).saturating_add(1);
    action_x = render_toolbar_segment(
        "[Runtime]",
        action_x,
        global_header,
        button_style,
        Some(HitTarget::HarnessBoardMode(crate::app::AgentBoardMode::SessionMonitoring)),
        buf,
        layout,
    ).saturating_add(1);
    for (icon, ascii_label, target) in [
        (icons::IconId::Add, "[New task]", HitTarget::HarnessTaskCreate),
        (icons::IconId::Refresh, "[Refresh]", HitTarget::HarnessTaskRefresh),
        (icons::IconId::Play, "[Run next Ready]", HitTarget::HarnessScheduleNext),
    ] {
        action_x = render_toolbar_icon_segment(
            icon,
            ascii_label,
            action_x,
            global_header,
            button_style,
            Some(target),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        ).saturating_add(1);
    }
    let mut header_rows = 1_u16;
    let sessions_strip_capacity = inner
        .height
        .saturating_sub(header_rows)
        .saturating_sub(HARNESS_SESSIONS_STRIP_RESERVED_KANBAN_ROWS)
        .min(HARNESS_SESSIONS_STRIP_MAX_ROWS);
    let sessions_strip_area = Rect::new(
        inner.x,
        inner.y.saturating_add(header_rows),
        inner.width,
        sessions_strip_capacity,
    );
    header_rows = header_rows.saturating_add(render_harness_sessions_strip(
        app,
        sessions_strip_area,
        buf,
        layout,
        theme,
    ));
    if let Some(task) = app.harness_selected_task() {
        let context_area = Rect::new(
            inner.x,
            inner.y.saturating_add(header_rows),
            inner.width,
            inner.height.saturating_sub(header_rows).min(1),
        );
        fill_rect(context_area, theme.active, buf);
        let column = HarnessKanbanColumn::from_state(task.state);
        let index = HarnessKanbanColumn::ALL.iter()
            .position(|candidate| *candidate == column).unwrap_or(0);
        let previous = HarnessKanbanColumn::ALL[..index].iter().rev()
            .map(|column| column.state())
            .find(|state| crate::app::harness_operator_move_allowed(task.state, *state));
        let next = HarnessKanbanColumn::ALL[index.saturating_add(1)..].iter()
            .map(|column| column.state())
            .find(|state| crate::app::harness_operator_move_allowed(task.state, *state));
        let mut context_x = context_area.x;
        for state in previous.into_iter().chain(next) {
            let label = format!("[Move to {}]", HarnessKanbanColumn::from_state(state).label());
            context_x = render_toolbar_segment(
                &label,
                context_x,
                context_area,
                button_style,
                Some(HitTarget::HarnessTaskMove(state)),
                buf,
                layout,
            ).saturating_add(1);
        }
        if !matches!(task.state, gate4agent_harness_client::HarnessTaskStateV1::Done | gate4agent_harness_client::HarnessTaskStateV1::Cancelled) {
            context_x = render_toolbar_icon_segment(
                icons::IconId::DebugStop,
                "[Cancel task]",
                context_x,
                context_area,
                button_style,
                Some(HitTarget::HarnessTaskCancel),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
        }
        if matches!(task.state, gate4agent_harness_client::HarnessTaskStateV1::Failed | gate4agent_harness_client::HarnessTaskStateV1::Cancelled) {
            context_x = render_toolbar_icon_segment(
                icons::IconId::DebugRestart,
                "[Retry task]",
                context_x,
                context_area,
                button_style,
                Some(HitTarget::HarnessTaskRetry),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
        }
        let _ = render_toolbar_icon_segment(
            icons::IconId::GoToFile,
            "[Open]",
            context_x,
            context_area,
            button_style,
            Some(HitTarget::HarnessTaskOpen(task.task_id.clone())),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        header_rows = header_rows.saturating_add(1);
    }
    let status = app.harness_kanban.stale_reason.as_ref()
        .map(|reason| (
            format!("STALE | last complete Harness snapshot retained | {reason}"),
            theme.yellow,
        ))
        .or_else(|| app.harness_kanban.pending_refresh.map(|_| (
            "Refreshing authoritative Harness snapshot...".to_owned(),
            theme.muted,
        )));
    if let Some((status, color)) = status {
        let status_area = Rect::new(
            inner.x,
            inner.y.saturating_add(header_rows),
            inner.width,
            inner.height.saturating_sub(header_rows).min(1),
        );
        Paragraph::new(truncate_cells(&status, status_area.width as usize))
            .style(Style::default().fg(color).bg(theme.active).add_modifier(Modifier::BOLD))
            .render(status_area, buf);
        header_rows = header_rows.saturating_add(1);
    }
    let header_area = Rect::new(inner.x, inner.y, inner.width, header_rows.min(inner.height));
    let header_divider_y = inner.y.saturating_add(header_rows);
    draw_harness_board_divider(area, header_divider_y, buf, theme);
    let column_header_y = header_divider_y.saturating_add(1);
    let table_divider_y = column_header_y.saturating_add(1);
    draw_harness_board_divider(area, table_divider_y, buf, theme);
    let body_top = table_divider_y.saturating_add(1);
    let body_bottom = area.bottom().saturating_sub(1);
    let body_height = body_bottom.saturating_sub(body_top);
    let tasks = app.harness_tasks();
    let separator_count = visible_count.saturating_sub(1) as u16;
    let table_width = inner.width.saturating_sub(separator_count);
    let base_width = table_width / visible_count as u16;
    let remainder = table_width % visible_count as u16;
    let card_height = 5_u16;
    let mut x = inner.x;
    for visible_index in 0..visible_count {
        let column = HarnessKanbanColumn::ALL[start + visible_index];
        let width = base_width + u16::from((visible_index as u16) < remainder);
        let column_tasks = tasks.iter()
            .copied()
            .filter(|task| HarnessKanbanColumn::from_state(task.state) == column)
            .collect::<Vec<_>>();
        Paragraph::new(truncate_cells(
            &format!("{} ({})", column.label(), column_tasks.len()),
            width.saturating_sub(2) as usize,
        ))
            .style(Style::default().fg(theme.text).bg(theme.surface).add_modifier(Modifier::BOLD))
            .render(Rect::new(
                x.saturating_add(1),
                column_header_y,
                width.saturating_sub(2),
                u16::from(column_header_y < area.bottom()),
            ), buf);
        if column_tasks.is_empty() && body_height > 0 {
            Paragraph::new("No tasks")
                .style(Style::default().fg(theme.muted).bg(theme.surface))
                .render(Rect::new(
                    x.saturating_add(1),
                    body_top,
                    width.saturating_sub(2),
                    1,
                ), buf);
        }
        let capacity = body_height as usize / card_height as usize;
        let mut offset = app.harness_kanban.vertical_offsets.get(&column)
            .copied().unwrap_or(0).min(column_tasks.len().saturating_sub(1));
        if let Some(selected) = app.harness_kanban.selected.as_ref() {
            if let Some(index) = column_tasks.iter().position(|task| &task.task_id == selected) {
                if index < offset {
                    offset = index;
                } else if index >= offset.saturating_add(capacity.max(1)) {
                    offset = index.saturating_add(1).saturating_sub(capacity.max(1));
                }
            }
        }
        for (slot, task) in column_tasks.iter().skip(offset).take(capacity).enumerate() {
            let y = body_top.saturating_add(slot as u16 * card_height);
            render_harness_task_card(
                app,
                task,
                Rect::new(
                    x.saturating_add(1),
                    y,
                    width.saturating_sub(2),
                    card_height.min(body_bottom.saturating_sub(y)),
                ),
                buf,
                layout,
                theme,
            );
        }
        x = x.saturating_add(width);
        if visible_index + 1 < visible_count {
            for y in column_header_y..body_bottom {
                let separator = buf.get_mut(x, y);
                separator.symbol = if y == table_divider_y { "┼".into() } else { "│".into() };
                separator.style = Style::default().fg(theme.border).bg(theme.surface);
            }
            if area.height > 1 {
                let bottom = buf.get_mut(x, area.bottom() - 1);
                bottom.symbol = "┴".into();
                bottom.style = Style::default().fg(theme.border).bg(theme.surface);
            }
            x = x.saturating_add(1);
        }
    }
    if app.harness_kanban.hover_position
        .is_some_and(|(column, row)| header_area.contains(column, row))
    {
        let left_arrow = Rect::new(header_area.x, global_header.y, header_area.width.min(1), 1);
        let right_arrow = Rect::new(
            header_area.right().saturating_sub(1),
            global_header.y,
            header_area.width.min(1),
            1,
        );
        if start > 0 {
            Paragraph::new("‹")
                .style(Style::default().fg(theme.teal).bg(theme.active).add_modifier(Modifier::BOLD))
                .render(left_arrow, buf);
            layout.hits.push(HitRegion {
                rect: left_arrow,
                target: HitTarget::HarnessColumnScroll(start.saturating_sub(1)),
            });
        }
        if start < maximum_start {
            Paragraph::new("›")
                .style(Style::default().fg(theme.teal).bg(theme.active).add_modifier(Modifier::BOLD))
                .render(right_arrow, buf);
            layout.hits.push(HitRegion {
                rect: right_arrow,
                target: HitTarget::HarnessColumnScroll(start.saturating_add(1)),
            });
        }
    }
    if let Some(composer) = app.harness_kanban.composer.as_ref() {
        let width = area.width.min(72).max(1);
        let height = area.height.min(8).max(1);
        let modal = Rect::new(
            area.x.saturating_add(area.width.saturating_sub(width) / 2),
            area.y.saturating_add(area.height.saturating_sub(height) / 2),
            width,
            height,
        );
        draw_harness_composer_frame(modal, buf, theme);
        Paragraph::new("Create Harness task | Tab / Enter / Esc also work")
            .style(Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD))
            .render(Rect::new(
                modal.x.saturating_add(1),
                modal.y.saturating_add(1),
                modal.width.saturating_sub(2),
                1,
            ), buf);
        let title_marker = if composer.field == crate::app::HarnessTaskComposerField::Title { ">" } else { " " };
        let body_marker = if composer.field == crate::app::HarnessTaskComposerField::Body { ">" } else { " " };
        let title_rect = Rect::new(
            modal.x.saturating_add(1),
            modal.y.saturating_add(3),
            modal.width.saturating_sub(2),
            1,
        );
        Paragraph::new(truncate_cells(&format!("{title_marker} Title: {}", composer.title), title_rect.width as usize))
            .style(Style::default().fg(theme.teal).bg(theme.panel))
            .render(title_rect, buf);
        layout.hits.push(HitRegion {
            rect: title_rect,
            target: HitTarget::HarnessComposerField(crate::app::HarnessTaskComposerField::Title),
        });
        let body_rect = Rect::new(
            modal.x.saturating_add(1),
            modal.y.saturating_add(4),
            modal.width.saturating_sub(2),
            1,
        );
        Paragraph::new(truncate_cells(&format!("{body_marker} Body: {}", composer.body), body_rect.width as usize))
            .style(Style::default().fg(theme.dim).bg(theme.panel))
            .render(body_rect, buf);
        layout.hits.push(HitRegion {
            rect: body_rect,
            target: HitTarget::HarnessComposerField(crate::app::HarnessTaskComposerField::Body),
        });
        let buttons = Rect::new(
            modal.x.saturating_add(1),
            modal.bottom().saturating_sub(2),
            modal.width.saturating_sub(2),
            1,
        );
        let create_end = render_toolbar_icon_segment(
            icons::IconId::Add,
            "[Create in Backlog]",
            buttons.x,
            buttons,
            Style::default().fg(theme.teal).bg(theme.panel),
            Some(HitTarget::HarnessComposerCreate),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        let _ = render_toolbar_icon_segment(
            icons::IconId::Close,
            "[Cancel]",
            create_end.saturating_add(1),
            buttons,
            Style::default().fg(theme.yellow).bg(theme.panel),
            Some(HitTarget::HarnessComposerCancel),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
    }
}

/// Compact, always-visible rail of live sessions rendered above the Harness
/// Kanban board's task columns. Kanban cards are keyed by Harness task
/// state, so a session with no task/run binding (an operator's direct
/// spawn) never appears as a task card there; this strip surfaces the same
/// session roster the Runtime board (`K`/`M` toggle) shows, without
/// requiring the toggle. Returns the number of rows it actually painted so
/// the caller can shift the rest of the board's header stack down by that
/// much and hand any unused reserved height back to the kanban columns.
fn render_harness_sessions_strip(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) -> u16 {
    if area.width == 0 || area.height == 0 {
        return 0;
    }
    let cards = app.agent_board_cards();
    if cards.is_empty() {
        return 0;
    }
    let attention = cards.iter().filter(|card| card.column == AgentBoardColumn::Attention).count();
    let summary_rect = Rect::new(area.x, area.y, area.width, 1);
    fill_rect(summary_rect, theme.panel, buf);
    Paragraph::new(truncate_cells(
        &format!(" Sessions ({}, {attention} attention) ", cards.len()),
        area.width as usize,
    ))
        .style(
            Style::default()
                .fg(if attention > 0 { theme.red } else { theme.muted })
                .bg(theme.panel)
                .add_modifier(Modifier::BOLD),
        )
        .render(summary_rect, buf);
    let row_capacity = area.height.saturating_sub(1) as usize;
    if row_capacity == 0 {
        return 1;
    }
    let overflow = cards.len() > row_capacity;
    let shown = if overflow { row_capacity.saturating_sub(1) } else { cards.len() };
    for (index, card) in cards.iter().take(shown).enumerate() {
        let row = Rect::new(area.x, area.y.saturating_add(1 + index as u16), area.width, 1);
        render_harness_session_strip_row(app, card, row, buf, layout, theme);
    }
    if overflow {
        let hidden = cards.len() - shown;
        let row = Rect::new(area.x, area.y.saturating_add(1 + shown as u16), area.width, 1);
        fill_rect(row, theme.panel, buf);
        Paragraph::new(truncate_cells(
            &format!(" +{hidden} more session(s), press K for the full roster"),
            area.width as usize,
        ))
            .style(Style::default().fg(theme.muted).bg(theme.panel))
            .render(row, buf);
    }
    1_u16.saturating_add(shown as u16).saturating_add(u16::from(overflow))
}

/// One session row in the sessions strip. The whole row is a single click
/// target that opens the session's PTY tab directly (`HitTarget::
/// AgentBoardCardOpen`, the same target the Runtime board's cards use), so
/// an operator does not need to select-then-open on a compact rail.
fn render_harness_session_strip_row(
    app: &App,
    card: &AgentBoardCard,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 {
        return;
    }
    let selected = app.agent_board.selected.as_ref() == Some(&card.key);
    let background = if selected { theme.active } else { theme.panel };
    fill_rect(area, background, buf);
    layout.hits.push(HitRegion {
        rect: area,
        target: HitTarget::AgentBoardCardOpen(card.key.clone()),
    });
    let label = match &card.key {
        AgentRowKey::Managed { .. } => {
            let Some(record) = app.find_managed_session(&card.key) else {
                return;
            };
            format!("{} | {}", record.provider, record.short_title())
        }
        AgentRowKey::Legacy(address) => {
            let Some(session) = app.find_session(address) else {
                return;
            };
            session.short_title()
        }
    };
    let status_color = if card.column == AgentBoardColumn::Attention {
        theme.red
    } else {
        theme.dim
    };
    let text = format!(" {label} | {}: {} \u{203a}", card.column.label(), card.reason);
    Paragraph::new(truncate_cells(&text, area.width as usize))
        .style(
            Style::default()
                .fg(status_color)
                .bg(background)
                .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
        )
        .render(area, buf);
}

fn draw_harness_composer_frame(
    area: Rect,
    buf: &mut TerminalBuffer,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.panel, buf);
    let style = Style::default().fg(theme.accent).bg(theme.panel);
    for x in area.x..area.right() {
        let top = buf.get_mut(x, area.y);
        top.symbol = "─".into();
        top.style = style;
        if area.height > 1 {
            let bottom = buf.get_mut(x, area.bottom() - 1);
            bottom.symbol = "─".into();
            bottom.style = style;
        }
    }
    for y in area.y..area.bottom() {
        let left = buf.get_mut(area.x, y);
        left.symbol = "│".into();
        left.style = style;
        if area.width > 1 {
            let right = buf.get_mut(area.right() - 1, y);
            right.symbol = "│".into();
            right.style = style;
        }
    }
    if area.width > 1 && area.height > 1 {
        for (x, y, symbol) in [
            (area.x, area.y, "┌"),
            (area.right() - 1, area.y, "┐"),
            (area.x, area.bottom() - 1, "└"),
            (area.right() - 1, area.bottom() - 1, "┘"),
        ] {
            let corner = buf.get_mut(x, y);
            corner.symbol = symbol.into();
            corner.style = style;
        }
    }
    if area.height > 3 {
        let divider_y = area.y.saturating_add(2);
        for x in area.x..area.right() {
            let divider = buf.get_mut(x, divider_y);
            divider.symbol = if x == area.x {
                "├".into()
            } else if x == area.right().saturating_sub(1) {
                "┤".into()
            } else {
                "─".into()
            };
            divider.style = style;
        }
    }
}

fn draw_harness_board_frame(
    area: Rect,
    buf: &mut TerminalBuffer,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.surface, buf);
    let border_style = Style::default().fg(theme.border).bg(theme.surface);
    for x in area.x..area.right() {
        let top = buf.get_mut(x, area.y);
        top.symbol = "─".into();
        top.style = border_style;
        if area.height > 1 {
            let bottom = buf.get_mut(x, area.bottom() - 1);
            bottom.symbol = "─".into();
            bottom.style = border_style;
        }
    }
    for y in area.y..area.bottom() {
        let left = buf.get_mut(area.x, y);
        left.symbol = "│".into();
        left.style = border_style;
        if area.width > 1 {
            let right = buf.get_mut(area.right() - 1, y);
            right.symbol = "│".into();
            right.style = border_style;
        }
    }
    if area.width > 1 && area.height > 1 {
        for (x, y, symbol) in [
            (area.x, area.y, "┌"),
            (area.right() - 1, area.y, "┐"),
            (area.x, area.bottom() - 1, "└"),
            (area.right() - 1, area.bottom() - 1, "┘"),
        ] {
            let corner = buf.get_mut(x, y);
            corner.symbol = symbol.into();
            corner.style = border_style;
        }
    }
}

fn draw_harness_board_divider(
    area: Rect,
    y: u16,
    buf: &mut TerminalBuffer,
    theme: Theme,
) {
    if y <= area.y || y >= area.bottom().saturating_sub(1) {
        return;
    }
    let style = Style::default().fg(theme.border).bg(theme.surface);
    for x in area.x..area.right() {
        let cell = buf.get_mut(x, y);
        cell.symbol = if x == area.x {
            "├".into()
        } else if x == area.right().saturating_sub(1) {
            "┤".into()
        } else {
            "─".into()
        };
        cell.style = style;
    }
}

fn render_harness_task_card(
    app: &App,
    task: &gate4agent_harness_client::RedactedTaskV1,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let selected = app.harness_kanban.selected.as_ref() == Some(&task.task_id);
    let background = if selected { theme.active } else { theme.panel };
    fill_rect(area, background, buf);
    layout.hits.push(HitRegion {
        rect: area,
        target: HitTarget::HarnessTaskCard(task.task_id.clone()),
    });
    Paragraph::new(truncate_cells(&task.title, area.width as usize))
        .style(Style::default().fg(theme.text).bg(background).add_modifier(Modifier::BOLD))
        .render(Rect::new(area.x, area.y, area.width, 1), buf);
    if area.height > 1 {
        let id = task.task_id.as_str();
        let compact = format!("{}... | rev {}", &id[..id.len().min(14)], task.revision.get());
        Paragraph::new(truncate_cells(&compact, area.width as usize))
            .style(Style::default().fg(theme.dim).bg(background))
            .render(Rect::new(area.x, area.y + 1, area.width, 1), buf);
    }
    if area.height > 2 {
        let links = format!("deps {} | runs {}", task.dependency_ids.len(), task.run_ids.len());
        Paragraph::new(truncate_cells(&links, area.width as usize))
            .style(Style::default().fg(theme.muted).bg(background))
            .render(Rect::new(area.x, area.y + 2, area.width, 1), buf);
    }
    if area.height > 3 {
        Paragraph::new(truncate_cells(&task.body, area.width as usize))
            .style(Style::default().fg(theme.dim).bg(background))
            .render(Rect::new(area.x, area.y + 3, area.width, 1), buf);
    }
    if area.height > 4 {
        let open_width = area.width.min(6);
        let open_rect = Rect::new(area.x, area.y + 4, open_width, 1);
        render_compact_icon_button(
            open_rect,
            icons::IconId::GoToFile,
            "[Open]",
            Style::default().fg(theme.teal).bg(background),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion {
            rect: open_rect,
            target: HitTarget::HarnessTaskOpen(task.task_id.clone()),
        });
    }
}

/// FIX4: the activity rail's Board button's own sidebar content -- a
/// compact, scrollable, single-column task list built from the SAME
/// `app.harness_kanban`/`App::harness_tasks` state the full kanban board
/// (`render_harness_kanban`) already reads, grouped under one bold header
/// row per non-empty `HarnessKanbanColumn` (same grouping, order and
/// `"{label} ({count})"` text the full board's own column headers use --
/// see that function's own `column_tasks` header `Paragraph`) with each
/// task underneath rendered by [`render_harness_task_card`] itself, at a
/// 1-row-tall rect -- the EXACT SAME primitive the full board's own
/// column cards call, just handed a shorter rect: that function already
/// degrades gracefully to "title only" at `area.height == 1` (see its own
/// doc comment) and already pushes the same `HitTarget::HarnessTaskCard`
/// hit region the full board relies on, so a task row here is clickable
/// exactly like a task card there. This is a NEW view, not a new data
/// path: no field on `HarnessKanbanState` is read here that `render_
/// harness_kanban` does not already read the same way.
///
/// The leading control-strip button (reusing `render_control_strip`, the
/// SAME sidebar control-plane strip Explorer/Git already use) is the
/// sidebar's own "expand" affordance: `HitTarget::AgentBoardOpen`, wired
/// to `App::open_agent_board` completely unchanged -- opens the full
/// kanban as the viewport tab exactly as it always has (Split
/// presentation's own `[B Board]` button and the `B`/`b` key already go
/// through this same target/function, see `render_roster`'s own doc
/// comment). Uses `icons::IconId::GoToFile` rather than `Project` (the
/// rail button's OWN icon just to this view's left) specifically so the
/// two do not paint the same glyph twice in adjacent chrome; `GoToFile`
/// reads as "jump to the full view" the same way it does everywhere else
/// codicons ships it.
fn render_agent_board_sidebar(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    use crate::app::HarnessKanbanColumn;

    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.panel, buf);

    let content = if control_strip_fits(area) {
        render_control_strip(
            area,
            &[ControlStripButton {
                icon: icons::IconId::GoToFile,
                target: HitTarget::AgentBoardOpen,
                enabled: true,
            }],
            theme,
            app.rail_icons, app.icon_family,
            buf,
            layout,
        )
    } else {
        // Same "no strip, fall back to one inline row" precedent as the
        // Explorer/Git panels' own pre-strip fallback (see `control_strip_
        // fits`'s own doc comment) -- a cramped sidebar still keeps a
        // real, clickable way to reach the full board.
        let header = Rect::new(area.x, area.y, area.width, area.height.min(1));
        render_compact_icon_button(
            header,
            icons::IconId::GoToFile,
            " [Open full board] ",
            Style::default().fg(theme.teal).bg(theme.panel).add_modifier(Modifier::BOLD),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion { rect: header, target: HitTarget::AgentBoardOpen });
        Rect::new(area.x, area.y.saturating_add(1), area.width, area.height.saturating_sub(1))
    };

    if content.width == 0 || content.height == 0 {
        return;
    }
    let tasks = app.harness_tasks();
    if tasks.is_empty() {
        Paragraph::new("No Harness tasks yet.")
            .style(Style::default().fg(theme.muted).bg(theme.panel))
            .render(Rect::new(content.x, content.y, content.width, 1), buf);
        return;
    }

    // Flatten "one header row per non-empty column, one row per task in
    // it" into a single scrollable list -- the "columns collapsed into a
    // list with state-label groups" this view's own brief asks for.
    enum Row<'a> {
        Header { label: &'static str, count: usize },
        Task(&'a gate4agent_harness_client::RedactedTaskV1),
    }
    let mut rows: Vec<Row> = Vec::new();
    for column in HarnessKanbanColumn::ALL {
        let column_tasks: Vec<_> = tasks
            .iter()
            .copied()
            .filter(|task| HarnessKanbanColumn::from_state(task.state) == column)
            .collect();
        if column_tasks.is_empty() {
            continue;
        }
        rows.push(Row::Header { label: column.label(), count: column_tasks.len() });
        rows.extend(column_tasks.into_iter().map(Row::Task));
    }

    // Same "nudge now, clamp against real content every frame" contract
    // as `render_icon_gallery`'s own `app.icon_gallery_scroll` -- see that
    // field's own doc comment.
    let max_scroll = (rows.len() as u16).saturating_sub(content.height);
    let scroll = app.board_sidebar_scroll.min(max_scroll) as usize;
    let mut y = content.y;
    for row in rows.iter().skip(scroll) {
        if y >= content.bottom() {
            break;
        }
        let row_area = Rect::new(content.x, y, content.width, 1);
        match row {
            Row::Header { label, count } => {
                Paragraph::new(truncate_cells(&format!("{label} ({count})"), row_area.width as usize))
                    .style(Style::default().fg(theme.text).bg(theme.active).add_modifier(Modifier::BOLD))
                    .render(row_area, buf);
            }
            Row::Task(task) => render_harness_task_card(app, task, row_area, buf, layout, theme),
        }
        y = y.saturating_add(1);
    }
}

fn harness_feature_state_label(state: FeatureObservationStateV1) -> &'static str {
    match state {
        FeatureObservationStateV1::Unknown => "unknown",
        FeatureObservationStateV1::NotSupportedByObservedSources => "unsupported",
        FeatureObservationStateV1::SupportedNotObserved => "not-observed",
        FeatureObservationStateV1::Observed => "observed",
    }
}

fn harness_monitor_progress_line(monitor: &HarnessSessionMonitorV1) -> String {
    format!(
        "Observation: availability={:?} freshness={:?}{} | progress TODO {}/{} tools {} subagents {} | usage in {} out {}",
        monitor.availability,
        monitor.freshness,
        if monitor.transport_incomplete { " transport=incomplete" } else { "" },
        monitor.todo_completed,
        monitor.todo_total,
        monitor.active_tools,
        monitor.active_subagents,
        monitor.input_tokens,
        monitor.output_tokens,
    )
}

fn harness_monitor_features_line(
    monitor: &HarnessSessionMonitorV1,
    session_history_available: bool,
) -> String {
    let history = monitor.history.as_ref().map(|history| {
        format!(
            "observed(messages {}{} turns {} tokens {})",
            if history.message_count_exact { "" } else { ">=" },
            history.message_count,
            history.completed_turn_count
                .map(|value| value.to_string())
                .unwrap_or_else(|| "unavailable".to_owned()),
            history.total_tokens
                .map(|value| value.to_string())
                .unwrap_or_else(|| "unavailable".to_owned()),
        )
    }).unwrap_or_else(|| harness_feature_state_label(monitor.features.history).to_owned());
    format!(
        "Features: TODO={} tools={} subagents={} files={} history={} usage={} | session-history={}",
        harness_feature_state_label(monitor.features.todo),
        harness_feature_state_label(monitor.features.tools),
        harness_feature_state_label(monitor.features.subagents),
        harness_feature_state_label(monitor.features.files),
        history,
        harness_feature_state_label(monitor.features.usage),
        if session_history_available { "exact-managed" } else { "unavailable" },
    )
}

fn harness_history_detail_line(monitor: &HarnessSessionMonitorV1) -> String {
    let Some(history) = monitor.history.as_ref() else {
        return format!(
            "History: {} | no safe summary",
            harness_feature_state_label(monitor.features.history),
        );
    };
    format!(
        "History: messages {}{} | completed turns {} | total tokens {}",
        if history.message_count_exact { "" } else { ">=" },
        history.message_count,
        history.completed_turn_count
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unavailable".to_owned()),
        history.total_tokens
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unavailable".to_owned()),
    )
}

fn harness_feature_detail_heading(
    name: &str,
    state: FeatureObservationStateV1,
    count: usize,
) -> String {
    match state {
        FeatureObservationStateV1::Unknown => format!("{name}: unknown"),
        FeatureObservationStateV1::NotSupportedByObservedSources => {
            format!("{name}: unsupported by observed sources")
        }
        FeatureObservationStateV1::SupportedNotObserved => {
            format!("{name}: supported, not observed")
        }
        FeatureObservationStateV1::Observed if count == 0 => {
            format!("{name}: observed, empty")
        }
        FeatureObservationStateV1::Observed => format!("{name}: observed {count}"),
    }
}

fn harness_usage_detail_line(monitor: &HarnessSessionMonitorV1) -> String {
    match monitor.features.usage {
        FeatureObservationStateV1::Unknown => "Usage: unknown".to_owned(),
        FeatureObservationStateV1::NotSupportedByObservedSources => {
            "Usage: unsupported by observed sources".to_owned()
        }
        FeatureObservationStateV1::SupportedNotObserved => {
            "Usage: supported, not observed".to_owned()
        }
        FeatureObservationStateV1::Observed => format!(
            "Usage: input {} output {} cache-read {} cache-write {} reasoning {} context-window {}",
            monitor.input_tokens,
            monitor.output_tokens,
            monitor.cache_read_tokens,
            monitor.cache_write_tokens,
            monitor.reasoning_tokens,
            monitor.context_window_tokens
                .map(|value| value.to_string())
                .unwrap_or_else(|| "unavailable".to_owned()),
        ),
    }
}

fn harness_monitor_section_lines(
    app: &App,
    view: &crate::app::HarnessRunMonitorView,
    monitor: &HarnessSessionMonitorV1,
    theme: Theme,
) -> Vec<(String, Color, Option<HitTarget>)> {
    use crate::app::HarnessRunMonitorSection;

    let mut lines = Vec::new();
    if view.section == HarnessRunMonitorSection::Summary {
        lines.push((harness_monitor_progress_line(monitor), theme.dim, None));
        lines.push((
            harness_monitor_features_line(
                monitor,
                false,
            ),
            theme.muted,
            None,
        ));
        lines.push((harness_usage_detail_line(monitor), theme.dim, None));
        lines.push((harness_history_detail_line(monitor), theme.dim, None));
        return lines;
    }
    let Some(detail) = monitor.detail.as_ref() else {
        lines.push((
            "Structured detail unavailable at current visibility/availability".to_owned(),
            theme.yellow,
            None,
        ));
        return lines;
    };
    if view.section == HarnessRunMonitorSection::Todos {
        lines.push((
            harness_feature_detail_heading("TODO", monitor.features.todo, detail.todo_facts.len()),
            theme.text,
            None,
        ));
        lines.extend(detail.todo_facts.iter().map(|fact| (
            format!(
                "TODO id={} | {:?} | {} | via {:?}",
                fact.todo_id.as_deref().unwrap_or("unavailable"),
                fact.state,
                fact.label.as_deref().unwrap_or("label unavailable"),
                fact.evidence,
            ),
            theme.dim,
            None,
        )));
        return lines;
    }
    if view.section == HarnessRunMonitorSection::Activity {
        for (name, state, facts) in [
            ("Tools", monitor.features.tools, detail.tool_facts.as_slice()),
            ("Subagents", monitor.features.subagents, detail.subagent_facts.as_slice()),
            (
                "Owned processes",
                monitor.features.owned_processes,
                detail.process_facts.as_slice(),
            ),
        ] {
            lines.push((harness_feature_detail_heading(name, state, facts.len()), theme.text, None));
            lines.extend(facts.iter().map(|fact| (
                format!(
                    "{:?} correlation={} | {:?} | {} | via {:?}",
                    fact.class,
                    fact.correlation
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "unavailable".to_owned()),
                    fact.state,
                    fact.label.as_deref().unwrap_or("label unavailable"),
                    fact.evidence,
                ),
                theme.dim,
                None,
            )));
        }
        lines.push((
            harness_feature_detail_heading(
                "Interactions / approvals",
                monitor.features.interactions,
                detail.interaction_facts.len(),
            ),
            theme.text,
            None,
        ));
        lines.extend(detail.interaction_facts.iter().map(|fact| (
            format!(
                "{:?} correlation={} | {:?} | {} | via {:?}",
                fact.class,
                fact.correlation
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unavailable".to_owned()),
                fact.state,
                fact.label.as_deref().unwrap_or("label unavailable"),
                fact.evidence,
            ),
            theme.dim,
            None,
        )));
        return lines;
    }
    if view.section == HarnessRunMonitorSection::Files {
        lines.push((
            harness_feature_detail_heading("Files", monitor.features.files, detail.file_facts.len()),
            theme.text,
            None,
        ));
        let run = crate::app::HarnessRunRef {
            run_id: view.run.run_id.clone(),
            run_revision: view.run.revision,
        };
        for fact in &detail.file_facts {
            let path = fact.relative_path.as_ref()
                .and_then(|path| gate4agent_node_protocol::RepositoryPath::utf8(path.clone()).ok());
            let target = path.as_ref().and_then(|path| {
                let (origin, workspace) = app.harness_workspace_for_run(&run)?;
                workspace.entries.iter().any(|entry| {
                    entry.kind == WorkspaceEntryKind::File && entry.relative_path == *path
                }).then(|| HitTarget::HarnessWorkspaceFile(origin.clone(), path.clone()))
            });
            lines.push((
                format!(
                    "{:?} | {} | via {:?}{}",
                    fact.action,
                    fact.relative_path.as_deref().unwrap_or("path unavailable"),
                    fact.evidence,
                    if target.is_some() { " | [Open]" } else { " | open unavailable" },
                ),
                theme.dim,
                target,
            ));
        }
        return lines;
    }
    lines.push((
        format!(
            "Timeline: {} run-local events, ordered oldest to newest",
            view.timeline.len(),
        ),
        theme.text,
        None,
    ));
    lines.extend(view.timeline.iter().map(|event| {
        let label = event.label.as_deref().unwrap_or("label unavailable");
        let correlation = event.correlation
            .map(|value| value.to_string())
            .unwrap_or_else(|| "none".to_owned());
        (
            format!(
                "#{} @{} {:?} {:?} | {} | correlation {} | via {:?}",
                event.sequence,
                event.received_at_ms,
                event.category,
                event.state,
                label,
                correlation,
                event.evidence,
            ),
            theme.muted,
            None,
        )
    }));
    lines
}

fn short_opaque_marker(value: &str) -> String {
    let characters = value.chars().collect::<Vec<_>>();
    if characters.len() <= 22 {
        return value.to_owned();
    }
    let prefix = characters.iter().take(12).collect::<String>();
    let suffix = characters.iter().skip(characters.len() - 6).collect::<String>();
    format!("{prefix}...{suffix}")
}

fn optional_transfer_timestamp(value: Option<u64>) -> String {
    value.map(|timestamp| timestamp.to_string())
        .unwrap_or_else(|| "none".to_owned())
}

fn render_harness_launch_pager(
    inner: Rect,
    panel: crate::app::HarnessLaunchOptionPanel,
    offset: usize,
    count: usize,
    tier: RailIcons,
    family: IconFamily,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) -> Rect {
    if inner.height == 0 {
        return inner;
    }
    let header = Rect::new(inner.x, inner.y, inner.width, 1);
    let can_previous = offset > 0;
    let mut x = render_toolbar_icon_segment(
        icons::IconId::ArrowLeft,
        "[<]",
        header.x,
        header,
        Style::default().fg(if can_previous { theme.teal } else { theme.muted }).bg(theme.surface),
        can_previous.then_some(HitTarget::HarnessLaunchPanelPrevious(panel)),
        tier, family,
        buf,
        layout,
    ).saturating_add(1);
    let can_next = offset.saturating_add(1) < count;
    x = render_toolbar_icon_segment(
        icons::IconId::ArrowRight,
        "[>]",
        x,
        header,
        Style::default().fg(if can_next { theme.teal } else { theme.muted }).bg(theme.surface),
        can_next.then_some(HitTarget::HarnessLaunchPanelNext(panel)),
        tier, family,
        buf,
        layout,
    ).saturating_add(1);
    let position = if count == 0 { "0/0".to_owned() } else { format!("{}/{}", offset + 1, count) };
    if x < header.right() {
        Paragraph::new(position)
            .style(Style::default().fg(theme.muted).bg(theme.surface))
            .render(Rect::new(x, header.y, header.right() - x, 1), buf);
    }
    Rect::new(
        inner.x,
        inner.y.saturating_add(1),
        inner.width,
        inner.height.saturating_sub(1),
    )
}

fn harness_transfer_lines(
    state: Option<&crate::app::HarnessRunTransferState>,
) -> Vec<String> {
    let Some(state) = state else {
        return vec!["Transfers: None | not loaded for this exact run revision".to_owned()];
    };
    match state {
        crate::app::HarnessRunTransferState::Loading { .. } => {
            vec!["Transfers: Loading exact run-local summary...".to_owned()]
        }
        crate::app::HarnessRunTransferState::Error { message, .. } => {
            vec![format!("Transfers: Error | {message}")]
        }
        crate::app::HarnessRunTransferState::Ready(summary) => {
            let mut lines = Vec::new();
            match &summary.delivery {
                None => lines.push("Delivery: None".to_owned()),
                Some(delivery) => {
                    lines.push(format!(
                        "Delivery: {:?} r{} | ref {} | receipt {}",
                        delivery.state,
                        delivery.revision.get(),
                        short_opaque_marker(delivery.delivery_ref.as_str()),
                        delivery.receipt_ref.as_ref()
                            .map(|value| short_opaque_marker(value.as_str()))
                            .unwrap_or_else(|| "none".to_owned()),
                    ));
                    lines.push(format!(
                        "Bundle: selector {} | id {} | revision {}",
                        short_opaque_marker(delivery.selector.as_str()),
                        short_opaque_marker(delivery.bundle_id.as_str()),
                        short_opaque_marker(delivery.bundle_revision.as_str()),
                    ));
                    lines.push(format!(
                        "Bundle markers: bundle {} | manifest {}",
                        short_opaque_marker(delivery.bundle_digest.as_str()),
                        short_opaque_marker(delivery.manifest_digest.as_str()),
                    ));
                    lines.push(format!(
                        "Delivery timestamps: created {} | updated {} | staged {} | committed {}",
                        delivery.created_at_unix_ms,
                        delivery.updated_at_unix_ms,
                        optional_transfer_timestamp(delivery.staged_at_unix_ms),
                        optional_transfer_timestamp(delivery.committed_at_unix_ms),
                    ));
                }
            }
            match &summary.continuation {
                None => lines.push("Continuation: None".to_owned()),
                Some(continuation) => {
                    lines.push(format!(
                        "Continuation: {:?} r{} | ref {} | receipt {}",
                        continuation.state,
                        continuation.revision.get(),
                        short_opaque_marker(continuation.continuation_ref.as_str()),
                        short_opaque_marker(continuation.receipt_ref.as_str()),
                    ));
                    lines.push(format!(
                        "Source: run {} | provider {} | target {}",
                        short_opaque_marker(continuation.source_run_id.as_str()),
                        short_opaque_marker(continuation.source_provider.as_str()),
                        short_opaque_marker(continuation.target_run_id.as_str()),
                    ));
                    lines.push(format!(
                        "Continuation timestamps: prepared {} | exporting {} | exported {} | bound {}",
                        continuation.prepared_at_unix_ms,
                        optional_transfer_timestamp(continuation.exporting_at_unix_ms),
                        optional_transfer_timestamp(continuation.exported_at_unix_ms),
                        optional_transfer_timestamp(continuation.bound_at_unix_ms),
                    ));
                    lines.push(format!(
                        "Continuation terminal: expired {} | outcome-unknown {} | reason {:?}",
                        optional_transfer_timestamp(continuation.expired_at_unix_ms),
                        optional_transfer_timestamp(continuation.outcome_unknown_at_unix_ms),
                        continuation.outcome_unknown_reason,
                    ));
                    match &continuation.context {
                        None => lines.push("Context transfer: None".to_owned()),
                        Some(context) => {
                            lines.push(format!(
                                "Context: ref {} | digest {} | messages {}/{}",
                                short_opaque_marker(context.context_ref.as_str()),
                                short_opaque_marker(&context.digest),
                                context.retained_message_count,
                                context.source_message_count,
                            ));
                            lines.push(format!(
                                "Context bytes: {} | truncated {}",
                                context.byte_len,
                                context.truncated,
                            ));
                        }
                    }
                }
            }
            lines
        }
    }
}

fn render_harness_task_detail(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    use crate::app::HarnessTaskDetailSection;
    use gate4agent_harness_client::{HarnessRunCorrelationAvailabilityV1, HarnessRunSessionViewV1};

    let Some(detail) = app.harness_kanban.detail.as_ref() else {
        return;
    };
    let Some(task) = app.harness_kanban.tasks.get(&detail.task_id) else {
        return;
    };
    draw_harness_board_frame(area, buf, theme);
    let inner = Rect::new(
        area.x.saturating_add(1),
        area.y.saturating_add(1),
        area.width.saturating_sub(2),
        area.height.saturating_sub(2),
    );
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let header = Rect::new(inner.x, inner.y, inner.width, inner.height.min(1));
    fill_rect(header, theme.active, buf);
    let button_style = Style::default().fg(theme.teal).bg(theme.active);
    let back_end = render_toolbar_icon_segment(
        icons::IconId::ArrowLeft,
        "[Back]",
        header.x,
        header,
        button_style,
        Some(HitTarget::HarnessTaskDetailBack),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    let heading = format!("Task | {} | {:?} | rev {}", task.title, task.state, task.revision.get());
    let heading_x = back_end.saturating_add(1);
    Paragraph::new(truncate_cells(
        &heading,
        header.right().saturating_sub(heading_x) as usize,
    ))
        .style(Style::default().fg(theme.text).bg(theme.active).add_modifier(Modifier::BOLD))
        .render(Rect::new(
            heading_x,
            header.y,
            header.right().saturating_sub(heading_x),
            1,
        ), buf);

    let sections = Rect::new(
        inner.x,
        inner.y.saturating_add(1),
        inner.width,
        inner.height.saturating_sub(1).min(1),
    );
    fill_rect(sections, theme.active, buf);
    let mut section_x = sections.x;
    for section in HarnessTaskDetailSection::ALL {
        let style = if detail.section == section {
            Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD)
        } else {
            button_style
        };
        section_x = render_toolbar_segment(
            &format!("[{}]", section.label()),
            section_x,
            sections,
            style,
            Some(HitTarget::HarnessTaskDetailSection(section)),
            buf,
            layout,
        ).saturating_add(1);
    }
    let divider_y = inner.y.saturating_add(2);
    draw_harness_board_divider(area, divider_y, buf, theme);
    let body = Rect::new(
        inner.x,
        divider_y.saturating_add(1),
        inner.width,
        area.bottom().saturating_sub(1).saturating_sub(divider_y.saturating_add(1)),
    );
    match detail.section {
        HarnessTaskDetailSection::Overview => {
            let parent = task.parent_task_id.as_ref()
                .map(|task_id| task_id.as_str())
                .unwrap_or("none");
            let loaded_runs = app.harness_task_runs(&task.task_id).len();
            let lines = [
                format!("ID: {}", task.task_id),
                format!("Created by: {:?} | created {} | updated {}", task.creator, task.created_at_unix_ms, task.updated_at_unix_ms),
                format!("Parent: {parent} | dependencies: {}", task.dependency_ids.len()),
                format!("Runs: {} linked | {loaded_runs} loaded", task.run_ids.len()),
                format!("Results: {} | artifacts: {}", task.result_refs.len(), task.artifact_refs.len()),
                String::new(),
                format!("Body: {}", task.body),
            ];
            for (index, line) in lines.iter().take(body.height as usize).enumerate() {
                Paragraph::new(truncate_cells(line, body.width as usize))
                    .style(Style::default().fg(if index == 6 { theme.text } else { theme.dim }).bg(theme.surface))
                    .render(Rect::new(body.x, body.y + index as u16, body.width, 1), buf);
            }
        }
        HarnessTaskDetailSection::Runs => {
            let runs = app.harness_task_runs(&task.task_id);
            if body.height == 0 {
                return;
            }
            Paragraph::new(truncate_cells(
                "Run-local observation panels | select row | mouse-first actions",
                body.width as usize,
            ))
                .style(Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD))
                .render(Rect::new(body.x, body.y, body.width, 1), buf);
            let card_height = 4usize;
            let capacity = (body.height.saturating_sub(1) as usize / card_height).max(1);
            let selected_index = detail.selected_run.as_ref()
                .and_then(|selected| runs.iter().position(|run| &run.run_id == selected))
                .unwrap_or(0);
            let offset = detail.scroll.min(selected_index).min(runs.len().saturating_sub(capacity));
            for (slot, run) in runs.iter().skip(offset).take(capacity).enumerate() {
                let y = body.y.saturating_add(1 + (slot * card_height) as u16);
                let panel_height = (card_height as u16).min(body.bottom().saturating_sub(y));
                let panel = Rect::new(body.x, y, body.width, panel_height);
                if panel.height == 0 {
                    break;
                }
                let selected = detail.selected_run.as_ref() == Some(&run.run_id);
                let background = if selected { theme.active } else { theme.surface };
                fill_rect(panel, background, buf);
                layout.hits.push(HitRegion {
                    rect: panel,
                    target: HitTarget::HarnessTaskDetailRun(run.run_id.clone()),
                });
                let correlation = if app.harness_kanban.correlation_pending.contains(&run.run_id) {
                    "loading".to_owned()
                } else if let Some(value) = app.harness_kanban.correlations.get(&run.run_id) {
                    format!("{:?}", value.availability)
                } else if app.harness_kanban.correlation_failures.contains_key(&run.run_id) {
                    "unavailable".to_owned()
                } else {
                    "not loaded".to_owned()
                };
                let session_history_available = false;
                let monitor_label = if run.binding == gate4agent_harness_client::RedactedBindingStateV1::None {
                    "[Monitor unavailable]"
                } else {
                    "[Open monitor]"
                };
                let run_ref = crate::app::HarnessRunRef {
                    run_id: run.run_id.clone(),
                    run_revision: run.revision,
                };
                let context_loading = matches!(
                    app.harness_kanban.run_context_sources.get(&run_ref),
                    Some(crate::app::HarnessRunContextSourceState::Loading { .. }),
                );
                let observe_label = "[Observe context]";
                let transfers_label = "[Transfers]";
                let files_label = "[Files]";
                let git_label = "[Git]";
                let actions_width = (cell_width(observe_label)
                    + 1
                    + cell_width(transfers_label)
                    + 1
                    + cell_width(files_label)
                    + 1
                    + cell_width(git_label)
                    + 1
                    + cell_width(monitor_label)) as u16;
                let actions_x = panel.right().saturating_sub(actions_width.min(panel.width));
                let main_width = actions_x.saturating_sub(panel.x).saturating_sub(1);
                let id = run.run_id.as_str();
                let line = format!(
                    "{}... | created {} | {:?} | {:?} | correlation={correlation}",
                    &id[..id.len().min(16)],
                    run.created_at_unix_ms,
                    run.lifecycle,
                    run.binding,
                );
                Paragraph::new(truncate_cells(&line, main_width as usize))
                    .style(Style::default().fg(if selected { theme.text } else { theme.dim }).bg(background))
                    .render(Rect::new(panel.x, panel.y, main_width, 1), buf);
                let observe_width = cell_width(observe_label) as u16;
                let observe_rect = Rect::new(actions_x, panel.y, observe_width, 1);
                let can_observe = run.binding
                    != gate4agent_harness_client::RedactedBindingStateV1::None
                    && !context_loading;
                Paragraph::new(observe_label)
                    .style(Style::default().fg(if can_observe { theme.teal } else { theme.muted }).bg(background))
                    .render(observe_rect, buf);
                if can_observe {
                    layout.hits.push(HitRegion {
                        rect: observe_rect,
                        target: HitTarget::HarnessTaskDetailRunObserveContext(run.run_id.clone()),
                    });
                }
                let transfers_x = observe_rect.right().saturating_add(1);
                let transfers_width = cell_width(transfers_label) as u16;
                let transfers_rect = Rect::new(transfers_x, panel.y, transfers_width, 1);
                Paragraph::new(transfers_label)
                    .style(Style::default().fg(theme.teal).bg(background))
                    .render(transfers_rect, buf);
                layout.hits.push(HitRegion {
                    rect: transfers_rect,
                    target: HitTarget::HarnessTaskDetailRunTransfers(run.run_id.clone()),
                });
                let files_x = transfers_rect.right().saturating_add(1);
                let files_width = cell_width(files_label) as u16;
                let files_rect = Rect::new(files_x, panel.y, files_width, 1);
                Paragraph::new(files_label)
                    .style(Style::default().fg(theme.teal).bg(background))
                    .render(files_rect, buf);
                layout.hits.push(HitRegion {
                    rect: files_rect,
                    target: HitTarget::HarnessTaskDetailRunFiles(run.run_id.clone()),
                });
                let git_x = files_rect.right().saturating_add(1);
                let git_width = cell_width(git_label) as u16;
                let git_rect = Rect::new(git_x, panel.y, git_width, 1);
                Paragraph::new(git_label)
                    .style(Style::default().fg(theme.teal).bg(background))
                    .render(git_rect, buf);
                layout.hits.push(HitRegion {
                    rect: git_rect,
                    target: HitTarget::HarnessTaskDetailRunGit(run.run_id.clone()),
                });
                let monitor_x = git_rect.right().saturating_add(1);
                let monitor_width = cell_width(monitor_label) as u16;
                let monitor_rect = Rect::new(monitor_x, panel.y, monitor_width, 1);
                Paragraph::new(monitor_label)
                    .style(Style::default().fg(if run.binding == gate4agent_harness_client::RedactedBindingStateV1::None { theme.muted } else { theme.teal }).bg(background))
                    .render(monitor_rect, buf);
                if run.binding != gate4agent_harness_client::RedactedBindingStateV1::None {
                    layout.hits.push(HitRegion {
                        rect: monitor_rect,
                        target: HitTarget::HarnessTaskDetailRunMonitor(run.run_id.clone()),
                    });
                }
                let (progress, features, observation_error) = if run.binding
                    == gate4agent_harness_client::RedactedBindingStateV1::None
                {
                    (
                        "Observation: unavailable | run has no Harness binding".to_owned(),
                        "Features: TODO=unavailable tools=unavailable subagents=unavailable files=unavailable history=unavailable usage=unavailable | session-history=unavailable".to_owned(),
                        true,
                    )
                } else {
                    match app.harness_kanban.run_observations.get(&run.run_id) {
                        Some(crate::app::HarnessRunObservationState::Loading { run_revision })
                            if *run_revision == run.revision =>
                        {
                            (
                                format!("Observation: loading exact run revision r{}", run_revision.get()),
                                format!("Features: loading | session-history={}", if session_history_available { "exact-managed" } else { "unavailable" }),
                                false,
                            )
                        }
                        Some(crate::app::HarnessRunObservationState::Ready {
                            run_revision,
                            monitor,
                        }) if *run_revision == run.revision && monitor.run_id == run.run_id => {
                            (
                                harness_monitor_progress_line(monitor),
                                harness_monitor_features_line(monitor, session_history_available),
                                false,
                            )
                        }
                        Some(crate::app::HarnessRunObservationState::Error {
                            run_revision,
                            message,
                        }) if *run_revision == run.revision => {
                            (
                                format!("Observation error: {message}"),
                                format!("Features: unavailable after error | session-history={}", if session_history_available { "exact-managed" } else { "unavailable" }),
                                true,
                            )
                        }
                        _ => (
                            "Observation: not loaded for this exact run revision".to_owned(),
                            format!("Features: unavailable | session-history={}", if session_history_available { "exact-managed" } else { "unavailable" }),
                            true,
                        ),
                    }
                };
                if panel.height > 1 {
                    Paragraph::new(truncate_cells(&progress, panel.width as usize))
                        .style(Style::default().fg(if observation_error { theme.yellow } else { theme.dim }).bg(background))
                        .render(Rect::new(panel.x, panel.y + 1, panel.width, 1), buf);
                }
                if panel.height > 2 {
                    Paragraph::new(truncate_cells(&features, panel.width as usize))
                        .style(Style::default().fg(if observation_error { theme.yellow } else { theme.muted }).bg(background))
                        .render(Rect::new(panel.x, panel.y + 2, panel.width, 1), buf);
                }
                if panel.height > 3 {
                    let context_source = match app.harness_kanban.run_context_sources.get(&run_ref) {
                        None => "Context source: None | click [Observe context]".to_owned(),
                        Some(crate::app::HarnessRunContextSourceState::Loading { .. }) => {
                            format!("Context source: Loading | exact run r{}", run.revision.get())
                        }
                        Some(crate::app::HarnessRunContextSourceState::Observed {
                            observation,
                            ..
                        }) => format!(
                            "Context source: Observed | messages {} exact | turns {} | tokens {} | observed {}",
                            observation.message_count,
                            observation.completed_turn_count
                                .map(|value| value.to_string())
                                .unwrap_or_else(|| "unknown".to_owned()),
                            observation.total_tokens
                                .map(|value| value.to_string())
                                .unwrap_or_else(|| "unknown".to_owned()),
                            observation.observed_at_unix_ms
                                .map(|value| value.to_string())
                                .unwrap_or_else(|| "unknown".to_owned()),
                        ),
                        Some(crate::app::HarnessRunContextSourceState::Unavailable {
                            feature_state,
                            ..
                        }) => format!("Context source: Unavailable | {feature_state:?}"),
                        Some(crate::app::HarnessRunContextSourceState::Error { .. }) => {
                            "Context source: Error | retry exact run observation".to_owned()
                        }
                    };
                    let context_error = context_source.contains("Unavailable")
                        || context_source.contains("Error");
                    Paragraph::new(truncate_cells(&context_source, panel.width as usize))
                        .style(Style::default().fg(if context_error { theme.yellow } else { theme.dim }).bg(background))
                        .render(Rect::new(panel.x, panel.y + 3, panel.width, 1), buf);
                }
            }
            if runs.is_empty() && body.height > 1 {
                Paragraph::new("No run attempts")
                    .style(Style::default().fg(theme.muted).bg(theme.surface))
                    .render(Rect::new(body.x, body.y + 1, body.width, 1), buf);
            }
        }
        HarnessTaskDetailSection::Agents => {
            let runs = app.harness_task_runs(&task.task_id);
            let mut y = body.y;
            for run in &runs {
                if y >= body.bottom() {
                    break;
                }
                let correlation = app.harness_kanban.correlations.get(&run.run_id);
                let heading = if app.harness_kanban.correlation_pending.contains(&run.run_id) {
                    format!("Run {} | exact correlation: loading", run.run_id)
                } else if let Some(correlation) = correlation {
                    format!(
                        "Run {} | {:?} | node {} | workspace {} | profile {}",
                        run.run_id,
                        correlation.availability,
                        correlation.node_id.as_str(),
                        correlation.workspace_id.as_str(),
                        correlation.provider_profile.as_str(),
                    )
                } else {
                    format!("Run {} | exact correlation unavailable", run.run_id)
                };
                let row_selected = detail.selected_run.as_ref() == Some(&run.run_id);
                Paragraph::new(truncate_cells(&heading, body.width as usize))
                    .style(Style::default().fg(theme.text)
                        .bg(if row_selected { theme.active } else { theme.panel })
                        .add_modifier(Modifier::BOLD))
                    .render(Rect::new(body.x, y, body.width, 1), buf);
                y = y.saturating_add(1);
                if let Some(correlation) = correlation {
                    if y < body.bottom() {
                        let session = match &correlation.session {
                            HarnessRunSessionViewV1::Managed(session) => {
                                let runtime = session.active_session.as_ref()
                                    .map(|active| format!("{}:{}", active.instance_id, active.generation))
                                    .unwrap_or_else(|| "none".to_owned());
                                format!("Managed record {} | runtime {runtime} | mode {:?} | worktree {:?}", session.record_id.as_str(), correlation.mode, correlation.worktree)
                            }
                            HarnessRunSessionViewV1::Inline(session) => {
                                format!("Inline {} | mode {:?} | worktree {:?}", session.inline_ref, correlation.mode, correlation.worktree)
                            }
                        };
                        Paragraph::new(truncate_cells(&session, body.width as usize))
                            .style(Style::default().fg(theme.dim).bg(theme.surface))
                            .render(Rect::new(body.x, y, body.width, 1), buf);
                        y = y.saturating_add(1);
                    }
                } else if y < body.bottom() {
                    let reason = app.harness_kanban.correlation_failures.get(&run.run_id)
                        .map(String::as_str)
                        .unwrap_or("binding is not correlated");
                    Paragraph::new(truncate_cells(reason, body.width as usize))
                        .style(Style::default().fg(theme.yellow).bg(theme.surface))
                        .render(Rect::new(body.x, y, body.width, 1), buf);
                    y = y.saturating_add(1);
                }
                if y < body.bottom() {
                    if app.harness_run_terminal_address(&run.run_id).is_some() {
                        let actions = Rect::new(body.x, y, body.width, 1);
                        let _ = render_toolbar_icon_segment(
                            icons::IconId::Terminal,
                            "[Open terminal]",
                            actions.x,
                            actions,
                            Style::default().fg(theme.teal).bg(theme.surface),
                            Some(HitTarget::HarnessTaskDetailRunTerminal(run.run_id.clone())),
                            app.rail_icons, app.icon_family,
                            buf,
                            layout,
                        );
                    } else {
                        let dormant = correlation.is_some_and(|correlation| {
                            correlation.availability == HarnessRunCorrelationAvailabilityV1::Dormant
                        });
                        let label = if dormant {
                            "PTY: dormant | managed record has no active runtime session"
                        } else {
                            "PTY: none | run has no live managed binding"
                        };
                        Paragraph::new(truncate_cells(label, body.width as usize))
                            .style(Style::default().fg(theme.muted).bg(theme.surface))
                            .render(Rect::new(body.x, y, body.width, 1), buf);
                    }
                    y = y.saturating_add(1);
                }
                if y < body.bottom() {
                    let run_ref = app.harness_run_ref(&run.run_id);
                    if run_ref.as_ref().is_some_and(|run_ref| {
                        app.harness_workspace_for_run(run_ref).is_some()
                    }) {
                        let actions = Rect::new(body.x, y, body.width, 1);
                        let files_end = render_toolbar_icon_segment(
                            icons::IconId::Folder,
                            "[Files]",
                            actions.x,
                            actions,
                            Style::default().fg(theme.teal).bg(theme.surface),
                            Some(HitTarget::HarnessTaskDetailRunFiles(run.run_id.clone())),
                            app.rail_icons, app.icon_family,
                            buf,
                            layout,
                        );
                        let _ = render_toolbar_icon_segment(
                            icons::IconId::SourceControl,
                            "[Git]",
                            files_end.saturating_add(1),
                            actions,
                            Style::default().fg(theme.teal).bg(theme.surface),
                            Some(HitTarget::HarnessTaskDetailRunGit(run.run_id.clone())),
                            app.rail_icons, app.icon_family,
                            buf,
                            layout,
                        );
                    } else {
                        Paragraph::new(truncate_cells(
                            "Workspace/Git: open Files or Git to load",
                            body.width as usize,
                        ))
                            .style(Style::default().fg(theme.muted).bg(theme.surface))
                            .render(Rect::new(body.x, y, body.width, 1), buf);
                    }
                    y = y.saturating_add(1);
                }
            }
            if runs.is_empty() {
                Paragraph::new("No run attempts; no agents are correlated")
                    .style(Style::default().fg(theme.muted).bg(theme.surface))
                    .render(body, buf);
            }
        }
        HarnessTaskDetailSection::Transfers => {
            let runs = app.harness_task_runs(&task.task_id);
            if body.height == 0 {
                return;
            }
            let selected = detail.selected_run.as_ref()
                .and_then(|run_id| runs.iter().find(|run| &run.run_id == run_id).copied());
            let selected_index = selected.and_then(|run| {
                runs.iter().position(|candidate| candidate.run_id == run.run_id)
            });
            let toolbar = Rect::new(body.x, body.y, body.width, 1);
            let mut x = render_toolbar_icon_segment(
                icons::IconId::Refresh,
                "[Refresh]",
                toolbar.x,
                toolbar,
                Style::default().fg(if selected.is_some() { theme.teal } else { theme.muted }).bg(theme.surface),
                selected.is_some().then_some(HitTarget::HarnessTransferRefresh),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
            let can_previous = selected_index.is_some_and(|index| index > 0);
            x = render_toolbar_icon_segment(
                icons::IconId::ArrowUp,
                "[Up]",
                x,
                toolbar,
                Style::default().fg(if can_previous { theme.teal } else { theme.muted }).bg(theme.surface),
                can_previous.then_some(HitTarget::HarnessTransferPreviousRun),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
            let can_next = selected_index.is_some_and(|index| index + 1 < runs.len());
            let _ = render_toolbar_icon_segment(
                icons::IconId::ArrowDown,
                "[Down]",
                x,
                toolbar,
                Style::default().fg(if can_next { theme.teal } else { theme.muted }).bg(theme.surface),
                can_next.then_some(HitTarget::HarnessTransferNextRun),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            let Some(run) = selected else {
                if body.height > 1 {
                    Paragraph::new("Transfers: None | task has no selected run")
                        .style(Style::default().fg(theme.muted).bg(theme.surface))
                        .render(Rect::new(body.x, body.y + 1, body.width, 1), buf);
                }
                return;
            };
            let run_ref = crate::app::HarnessRunRef {
                run_id: run.run_id.clone(),
                run_revision: run.revision,
            };
            let mut lines = vec![format!(
                "Exact run {} | revision r{} | lifecycle {:?}",
                short_opaque_marker(run.run_id.as_str()),
                run.revision.get(),
                run.lifecycle,
            )];
            lines.extend(harness_transfer_lines(
                app.harness_kanban.run_transfers.get(&run_ref),
            ));
            for (index, line) in lines.into_iter().enumerate() {
                let y = body.y.saturating_add(1 + index as u16);
                if y >= body.bottom() {
                    break;
                }
                let color = if line.starts_with("Transfers: Error") {
                    theme.yellow
                } else if index == 0 || line.starts_with("Delivery:")
                    || line.starts_with("Continuation:")
                {
                    theme.text
                } else {
                    theme.dim
                };
                Paragraph::new(truncate_cells(&line, body.width as usize))
                    .style(Style::default().fg(color).bg(theme.surface))
                    .render(Rect::new(body.x, y, body.width, 1), buf);
            }
        }
        HarnessTaskDetailSection::Results => {
            // No new fetch machinery: every field rendered here
            // (`result_disposition`, `failure_category`, `context_pack`,
            // `git_facts`) already lives on the `RedactedRunV1` returned by
            // `app.harness_task_runs`, unlike Transfers' own
            // `HarnessRunTransferState` fetch above.
            let runs = app.harness_task_runs(&task.task_id);
            if body.height == 0 {
                return;
            }
            let selected = detail.selected_run.as_ref()
                .and_then(|run_id| runs.iter().find(|run| &run.run_id == run_id).copied());
            let selected_index = selected.and_then(|run| {
                runs.iter().position(|candidate| candidate.run_id == run.run_id)
            });
            let toolbar = Rect::new(body.x, body.y, body.width, 1);
            let can_previous = selected_index.is_some_and(|index| index > 0);
            let x = render_toolbar_icon_segment(
                icons::IconId::ArrowUp,
                "[Up]",
                toolbar.x,
                toolbar,
                Style::default().fg(if can_previous { theme.teal } else { theme.muted }).bg(theme.surface),
                can_previous.then_some(HitTarget::HarnessResultPreviousRun),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
            let can_next = selected_index.is_some_and(|index| index + 1 < runs.len());
            let _ = render_toolbar_icon_segment(
                icons::IconId::ArrowDown,
                "[Down]",
                x,
                toolbar,
                Style::default().fg(if can_next { theme.teal } else { theme.muted }).bg(theme.surface),
                can_next.then_some(HitTarget::HarnessResultNextRun),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );
            let Some(run) = selected else {
                if body.height > 1 {
                    Paragraph::new("Results: None | task has no selected run")
                        .style(Style::default().fg(theme.muted).bg(theme.surface))
                        .render(Rect::new(body.x, body.y + 1, body.width, 1), buf);
                }
                return;
            };
            let mut lines = vec![format!(
                "Run {} r{} | lifecycle {:?}",
                short_opaque_marker(run.run_id.as_str()),
                run.revision.get(),
                run.lifecycle,
            )];
            lines.push(match (run.result_disposition, run.failure_category) {
                (None, _) => "Result: None yet".to_owned(),
                (Some(disposition), Some(category)) => {
                    format!("Result: {disposition:?} | category {category:?}")
                }
                (Some(disposition), None) => format!("Result: {disposition:?}"),
            });
            lines.push(match &run.context_pack {
                None => "Context pack: none".to_owned(),
                Some(pack) => format!(
                    "Context pack: digest {} | {} messages retained | {}",
                    compact_digest(&pack.digest),
                    pack.retained_message_count,
                    if pack.truncated { "truncated" } else { "complete" },
                ),
            });
            lines.push(match &run.git_facts {
                None => "Git: not yet captured".to_owned(),
                Some(facts) => match &facts.outcome {
                    HarnessRunGitFactsOutcomeV1::Unavailable => "Git: unavailable".to_owned(),
                    HarnessRunGitFactsOutcomeV1::Captured(summary) if !summary.is_repository => {
                        "Git: not repository".to_owned()
                    }
                    HarnessRunGitFactsOutcomeV1::Captured(summary) => format!(
                        "Git: stored | branch {} | {} changed | {} commits | {}",
                        summary.branch.as_deref().unwrap_or("detached"),
                        summary.status.len(),
                        summary.recent_commits.len(),
                        if summary.truncated { "truncated" } else { "complete" },
                    ),
                },
            });
            for (index, line) in lines.into_iter().enumerate() {
                let y = body.y.saturating_add(1 + index as u16);
                if y >= body.bottom() {
                    break;
                }
                let color = if index == 0 {
                    theme.text
                } else if line.starts_with("Result: Failed") {
                    theme.yellow
                } else {
                    theme.dim
                };
                Paragraph::new(truncate_cells(&line, body.width as usize))
                    .style(Style::default().fg(color).bg(theme.surface))
                    .render(Rect::new(body.x, y, body.width, 1), buf);
            }
        }
        HarnessTaskDetailSection::Files => {
            let Some(run_id) = detail.selected_run.as_ref() else {
                Paragraph::new("Harness workspace unavailable: no run selected")
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            let Some(run_ref) = app.harness_run_ref(run_id) else {
                Paragraph::new("Harness workspace unavailable: selected run is not loaded")
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            let Some((origin, workspace)) = app.harness_workspace_for_run(&run_ref) else {
                let status = match app.harness_kanban.workspace_requests.get(&run_ref) {
                    Some(request) => match &request.state {
                        crate::app::HarnessWorkspaceRequestState::Loading => {
                            format!("Harness run {} r{} | loading workspace...", run_ref.run_id, run_ref.run_revision.get())
                        }
                        crate::app::HarnessWorkspaceRequestState::Error(failure) => {
                            format!("Harness run {} r{} | {}", run_ref.run_id, run_ref.run_revision.get(), failure.display())
                        }
                    },
                    None => format!(
                        "Harness run {} r{} | workspace not requested",
                        run_ref.run_id,
                        run_ref.run_revision.get(),
                    ),
                };
                Paragraph::new(truncate_cells(&status, body.width as usize))
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            let heading = format!(
                "{}{} | node {}@{} | workspace {} | read-only",
                if workspace.tree_truncated { "file tree truncated | " } else { "" },
                origin.label(),
                origin.node_id.as_str(),
                origin.node_incarnation_id.as_str(),
                origin.workspace_id.as_str(),
            );
            if body.height > 0 {
                Paragraph::new(truncate_cells(&heading, body.width as usize))
                    .style(Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD))
                    .render(Rect::new(body.x, body.y, body.width, 1), buf);
            }
            for (index, entry) in workspace.entries.iter()
                .skip(workspace.scroll)
                .take(body.height.saturating_sub(1) as usize)
                .enumerate()
            {
                let row = Rect::new(body.x, body.y + 1 + index as u16, body.width, 1);
                let marker = if entry.kind == WorkspaceEntryKind::Directory { "[dir] " } else { "      " };
                Paragraph::new(truncate_cells(
                    &format!("{marker}{}", entry.relative_path.display_text()),
                    row.width as usize,
                ))
                    .style(Style::default().fg(if entry.kind == WorkspaceEntryKind::File { theme.teal } else { theme.dim }).bg(theme.surface))
                    .render(row, buf);
                if entry.kind == WorkspaceEntryKind::File {
                    layout.hits.push(HitRegion {
                        rect: row,
                        target: HitTarget::HarnessWorkspaceFile(
                            origin.clone(),
                            entry.relative_path.clone(),
                        ),
                    });
                }
            }
            if workspace.entries.is_empty() && body.height > 1 {
                Paragraph::new("No workspace entries")
                    .style(Style::default().fg(theme.muted).bg(theme.surface))
                    .render(Rect::new(body.x, body.y + 1, body.width, 1), buf);
            }
        }
        HarnessTaskDetailSection::Git => {
            let Some(run_id) = detail.selected_run.as_ref() else {
                Paragraph::new("Harness Git unavailable: no run selected")
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            let Some(run_ref) = app.harness_run_ref(run_id) else {
                Paragraph::new("Harness Git unavailable: selected run is not loaded")
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            let Some((origin, workspace)) = app.harness_workspace_for_run(&run_ref) else {
                let status = match app.harness_kanban.workspace_requests.get(&run_ref) {
                    Some(request) => match &request.state {
                        crate::app::HarnessWorkspaceRequestState::Loading => "loading workspace Git state...".to_owned(),
                        crate::app::HarnessWorkspaceRequestState::Error(failure) => failure.display(),
                    },
                    None => "Harness Git workspace not requested".to_owned(),
                };
                Paragraph::new(truncate_cells(
                    &format!("Harness run {} r{} | {status}", run_ref.run_id, run_ref.run_revision.get()),
                    body.width as usize,
                ))
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            let Some(git) = workspace.git.as_ref() else {
                Paragraph::new(format!("{} | Git unavailable: projection omitted", origin.label()))
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(body, buf);
                return;
            };
            if body.height > 0 {
                Paragraph::new(truncate_cells(
                    &format!(
                        "{}{} | branch {} | status {} | read-only",
                        if git.truncated { "Git snapshot truncated | " } else { "" },
                        origin.label(),
                        git.branch.as_deref().unwrap_or("detached"),
                        git.status.len(),
                    ),
                    body.width as usize,
                ))
                    .style(Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD))
                    .render(Rect::new(body.x, body.y, body.width, 1), buf);
            }
            if body.height > 1 {
                let actions = Rect::new(body.x, body.y + 1, body.width, 1);
                let mut x = render_toolbar_icon_segment(
                    icons::IconId::History,
                    "[History]",
                    actions.x,
                    actions,
                    button_style,
                    Some(HitTarget::HarnessWorkspaceGitHistory(origin.clone())),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                x = render_toolbar_icon_segment(
                    icons::IconId::Diff,
                    "[Working diff]",
                    x.saturating_add(1),
                    actions,
                    button_style,
                    Some(HitTarget::HarnessWorkspaceGitWorking(origin.clone())),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                let _ = render_toolbar_icon_segment(
                    icons::IconId::DiffAdded,
                    "[Staged diff]",
                    x.saturating_add(1),
                    actions,
                    button_style,
                    Some(HitTarget::HarnessWorkspaceGitStaged(origin.clone())),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
            }
            let mut y = body.y.saturating_add(3);
            for commit in &git.recent_commits {
                if y >= body.bottom() {
                    break;
                }
                Paragraph::new(truncate_cells(
                    &format!("{} {}", &commit.id[..commit.id.len().min(10)], commit.summary),
                    body.width as usize,
                ))
                    .style(Style::default().fg(theme.dim).bg(theme.surface))
                    .render(Rect::new(body.x, y, body.width, 1), buf);
                y = y.saturating_add(1);
            }
            if !git.is_repository && y < body.bottom() {
                Paragraph::new("Git unavailable: run workspace is not a repository")
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(Rect::new(body.x, y, body.width, 1), buf);
            }
        }
        HarnessTaskDetailSection::Launch => {
            let pending = app.harness_kanban.execution_mutation.as_ref()
                .filter(|pending| pending.task.task_id == task.task_id
                    && pending.task.task_revision == task.revision);
            let status = match (pending, app.harness_launch_state()) {
                (Some(pending), _) => format!("Launch mutation: {:?} | exact task r{}", pending.kind, task.revision.get()),
                (_, None) => "Launch options: None | not loaded for this exact task revision".to_owned(),
                (_, Some(crate::app::HarnessLaunchOptionsState::Loading { .. })) => {
                    format!("Launch options: Loading exact task r{}...", task.revision.get())
                }
                (_, Some(crate::app::HarnessLaunchOptionsState::Error { message, .. })) => {
                    format!("Launch options: Error | {message}")
                }
                (_, Some(crate::app::HarnessLaunchOptionsState::Ready(view))) => format!(
                    "Launch options: Ready | plans {} | worktrees {} | contexts {} | deliveries {}{}",
                    view.options.plans.len(),
                    view.options.managed_worktree_profiles.len(),
                    view.options.context_sources.len(),
                    view.options.delivery_bundles.len(),
                    if view.options.truncated { " | catalog truncated" } else { "" },
                ),
            };
            if body.height > 0 {
                Paragraph::new(truncate_cells(&status, body.width as usize))
                    .style(Style::default().fg(if status.contains("Error") { theme.yellow } else { theme.dim }).bg(theme.surface))
                    .render(Rect::new(body.x, body.y, body.width, 1), buf);
            }
            let actions = Rect::new(body.x, body.y.saturating_add(1), body.width, body.height.saturating_sub(1).min(1));
            let can_refresh = pending.is_none();
            let mut action_x = render_toolbar_icon_segment(
                icons::IconId::Refresh,
                "[Refresh options]",
                actions.x,
                actions,
                Style::default().fg(if can_refresh { theme.teal } else { theme.muted }).bg(theme.surface),
                can_refresh.then_some(HitTarget::HarnessLaunchRefresh),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
            let can_save = app.harness_launch_save_enabled();
            action_x = render_toolbar_icon_segment(
                icons::IconId::Save,
                "[Save spec]",
                action_x,
                actions,
                Style::default().fg(if can_save { theme.teal } else { theme.muted }).bg(theme.surface),
                can_save.then_some(HitTarget::HarnessLaunchSave),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            ).saturating_add(1);
            let can_start = app.harness_launch_start_enabled();
            let _ = render_toolbar_icon_segment(
                icons::IconId::Play,
                "[Start task]",
                action_x,
                actions,
                Style::default().fg(if can_start { theme.teal } else { theme.muted }).bg(theme.surface),
                can_start.then_some(HitTarget::HarnessLaunchStart),
                app.rail_icons, app.icon_family,
                buf,
                layout,
            );

            let panels_area = Rect::new(
                body.x,
                body.y.saturating_add(2),
                body.width,
                body.height.saturating_sub(2),
            );
            let panels = split(
                panels_area,
                Direction::Vertical,
                &[
                    Constraint::Fixed(5),
                    Constraint::Fixed(5),
                    Constraint::Fixed(5),
                    Constraint::Fixed(5),
                    Constraint::Min(4),
                ],
            );
            for (panel, title) in panels.iter().zip([
                " Plan ",
                " Worktree ",
                " Context ",
                " Delivery ",
                " Current issuance ",
            ]) {
                Block::bordered()
                    .title(title)
                    .border_style(Style::default().fg(theme.border))
                    .style(Style::default().bg(theme.surface))
                    .render(*panel, buf);
            }
            let inners = panels.iter().map(|panel| Rect::new(
                panel.x.saturating_add(1),
                panel.y.saturating_add(1),
                panel.width.saturating_sub(2),
                panel.height.saturating_sub(2),
            )).collect::<Vec<_>>();
            let Some(view) = app.harness_launch_view() else {
                let label = match app.harness_launch_state() {
                    None => "None",
                    Some(crate::app::HarnessLaunchOptionsState::Loading { .. }) => "Loading",
                    Some(crate::app::HarnessLaunchOptionsState::Error { .. }) => "Error",
                    Some(crate::app::HarnessLaunchOptionsState::Ready(_)) => unreachable!(),
                };
                for inner in inners {
                    if inner.height > 0 {
                        Paragraph::new(label)
                            .style(Style::default().fg(theme.muted).bg(theme.surface))
                            .render(Rect::new(inner.x, inner.y, inner.width, 1), buf);
                    }
                }
                return;
            };

            let plan_inner = render_harness_launch_pager(
                inners[0],
                crate::app::HarnessLaunchOptionPanel::Plan,
                view.plan_offset,
                view.options.plans.len(),
                app.rail_icons, app.icon_family,
                buf,
                layout,
                theme,
            );
            for (index, plan) in view.options.plans.iter()
                .enumerate()
                .skip(view.plan_offset)
                .take(plan_inner.height as usize)
            {
                let selected = view.selected_plan == Some(index);
                let visible = index.saturating_sub(view.plan_offset);
                let row = Rect::new(plan_inner.x, plan_inner.y + visible as u16, plan_inner.width, 1);
                let background = if selected { theme.active } else { theme.surface };
                fill_rect(row, background, buf);
                let line = format!(
                    "{} {} r{} | node {} | workspace {} | profile {} | {:?}",
                    if selected { ">" } else { " " },
                    plan.plan.plan_id.as_str(),
                    plan.plan.revision.get(),
                    plan.node_id.as_str(),
                    plan.source_workspace_id.as_str(),
                    plan.provider_profile.as_str(),
                    plan.mode,
                );
                Paragraph::new(truncate_cells(&line, row.width as usize))
                    .style(Style::default().fg(if selected { theme.text } else { theme.dim }).bg(background))
                    .render(row, buf);
                layout.hits.push(HitRegion { rect: row, target: HitTarget::HarnessLaunchPlan(index) });
            }
            if view.options.plans.is_empty() && plan_inner.height > 0 {
                Paragraph::new("No ordinary launch plans available")
                    .style(Style::default().fg(theme.muted).bg(theme.surface))
                    .render(Rect::new(plan_inner.x, plan_inner.y, plan_inner.width, 1), buf);
            }

            let selected_plan = view.selected_plan.and_then(|index| view.options.plans.get(index));
            let compatible_profiles = view.options.managed_worktree_profiles.iter()
                .enumerate()
                .filter(|(_, profile)| selected_plan.is_some_and(|plan| {
                    plan.node_id == profile.node_id
                        && plan.source_workspace_id == profile.source_workspace_id
                }))
                .map(|(index, profile)| (Some(index), profile))
                .collect::<Vec<_>>();
            let worktree_count = compatible_profiles.len().saturating_add(1);
            let worktree_inner = render_harness_launch_pager(
                inners[1],
                crate::app::HarnessLaunchOptionPanel::Worktree,
                view.worktree_offset,
                worktree_count,
                app.rail_icons, app.icon_family,
                buf,
                layout,
                theme,
            );
            for virtual_index in view.worktree_offset
                ..worktree_count.min(view.worktree_offset.saturating_add(worktree_inner.height as usize))
            {
                let visible = virtual_index - view.worktree_offset;
                let profile = virtual_index.checked_sub(1)
                    .and_then(|index| compatible_profiles.get(index));
                let selected = match profile {
                    None => view.worktree == crate::app::HarnessLaunchWorktreeChoice::Existing,
                    Some((Some(index), _)) => {
                        view.worktree == crate::app::HarnessLaunchWorktreeChoice::Managed(*index)
                    }
                    Some((None, _)) => false,
                };
                let row = Rect::new(worktree_inner.x, worktree_inner.y + visible as u16, worktree_inner.width, 1);
                let line = match profile {
                    None => if selected { "> Existing workspace".to_owned() } else { "  Existing workspace".to_owned() },
                    Some((_, profile)) => format!(
                        "{} Managed {} r{} | {:?}",
                        if selected { ">" } else { " " },
                        profile.profile_id.as_str(),
                        profile.profile_revision.as_str(),
                        profile.retention,
                    ),
                };
                let background = if selected { theme.active } else { theme.surface };
                fill_rect(row, background, buf);
                Paragraph::new(truncate_cells(&line, row.width as usize))
                    .style(Style::default().fg(if selected { theme.text } else { theme.dim }).bg(background))
                    .render(row, buf);
                let target = match profile {
                    None => HitTarget::HarnessLaunchWorktreeExisting,
                    Some((Some(index), _)) => HitTarget::HarnessLaunchWorktreeProfile(*index),
                    Some((None, _)) => continue,
                };
                layout.hits.push(HitRegion { rect: row, target });
            }

            let context_count = view.options.context_sources.len().saturating_add(1);
            let context_inner = render_harness_launch_pager(
                inners[2],
                crate::app::HarnessLaunchOptionPanel::Context,
                view.context_offset,
                context_count,
                app.rail_icons, app.icon_family,
                buf,
                layout,
                theme,
            );
            for virtual_index in view.context_offset
                ..context_count.min(view.context_offset.saturating_add(context_inner.height as usize))
            {
                let visible = virtual_index - view.context_offset;
                let source = virtual_index.checked_sub(1)
                    .and_then(|index| view.options.context_sources.get(index));
                let selected = match source {
                    None => view.selected_context.is_none(),
                    Some(_) => view.selected_context == virtual_index.checked_sub(1),
                };
                let row = Rect::new(context_inner.x, context_inner.y + visible as u16, context_inner.width, 1);
                let line = source.map(|source| format!(
                        "{} run {} r{} | {} | messages {}{} | turns {} | tokens {} | digest {}",
                        if selected { ">" } else { " " },
                        short_opaque_marker(source.source_run_id.as_str()),
                        source.source_run_revision.get(),
                        match source.availability {
                            HarnessContextSourceAvailabilityV1::Live => "live",
                            HarnessContextSourceAvailabilityV1::Durable => "stored",
                        },
                        source.message_count,
                        if source.message_count_exact { " exact" } else { "+" },
                        source.completed_turn_count.map(|value| value.to_string()).unwrap_or_else(|| "unknown".to_owned()),
                        source.total_tokens.map(|value| value.to_string()).unwrap_or_else(|| "unknown".to_owned()),
                        short_opaque_marker(source.metadata_digest.as_str()),
                    ))
                    .unwrap_or_else(|| if selected { "> None".to_owned() } else { "  None".to_owned() });
                let background = if selected { theme.active } else { theme.surface };
                fill_rect(row, background, buf);
                Paragraph::new(truncate_cells(&line, row.width as usize))
                    .style(Style::default().fg(if selected { theme.text } else { theme.dim }).bg(background))
                    .render(row, buf);
                let target = virtual_index.checked_sub(1)
                    .map(HitTarget::HarnessLaunchContextSource)
                    .unwrap_or(HitTarget::HarnessLaunchContextNone);
                layout.hits.push(HitRegion { rect: row, target });
            }
            if view.options.context_sources.is_empty() && context_inner.height > 1 {
                Paragraph::new(truncate_cells(
                    "Open a source run -> Observe context",
                    context_inner.width as usize,
                ))
                    .style(Style::default().fg(theme.yellow).bg(theme.surface))
                    .render(
                        Rect::new(
                            context_inner.x,
                            context_inner.y.saturating_add(1),
                            context_inner.width,
                            1,
                        ),
                        buf,
                    );
            }

            let delivery_count = view.options.delivery_bundles.len().saturating_add(1);
            let delivery_inner = render_harness_launch_pager(
                inners[3],
                crate::app::HarnessLaunchOptionPanel::Delivery,
                view.delivery_offset,
                delivery_count,
                app.rail_icons, app.icon_family,
                buf,
                layout,
                theme,
            );
            for virtual_index in view.delivery_offset
                ..delivery_count.min(view.delivery_offset.saturating_add(delivery_inner.height as usize))
            {
                let visible = virtual_index - view.delivery_offset;
                let delivery = virtual_index.checked_sub(1)
                    .and_then(|index| view.options.delivery_bundles.get(index));
                let selected = match delivery {
                    None => view.selected_delivery.is_none(),
                    Some(_) => view.selected_delivery == virtual_index.checked_sub(1),
                };
                let row = Rect::new(delivery_inner.x, delivery_inner.y + visible as u16, delivery_inner.width, 1);
                let line = delivery.map(|delivery| {
                    let counts = delivery.component_counts.iter().map(|count| format!(
                        "{:?} w{} s{}",
                        count.kind,
                        count.workspace_count,
                        count.session_count,
                    )).collect::<Vec<_>>().join(", ");
                    format!(
                        "{} {} | {} r{} | digest {} | {}",
                        if selected { ">" } else { " " },
                        delivery.bundle.selector.as_str(),
                        delivery.bundle.bundle_id.as_str(),
                        delivery.bundle.revision.as_str(),
                        short_opaque_marker(delivery.bundle.digest.as_str()),
                        counts,
                    )
                }).unwrap_or_else(|| if selected { "> None".to_owned() } else { "  None".to_owned() });
                let background = if selected { theme.active } else { theme.surface };
                fill_rect(row, background, buf);
                Paragraph::new(truncate_cells(&line, row.width as usize))
                    .style(Style::default().fg(if selected { theme.text } else { theme.dim }).bg(background))
                    .render(row, buf);
                let target = virtual_index.checked_sub(1)
                    .map(HitTarget::HarnessLaunchDeliveryBundle)
                    .unwrap_or(HitTarget::HarnessLaunchDeliveryNone);
                layout.hits.push(HitRegion { rect: row, target });
            }

            let issuance_inner = inners[4];
            if issuance_inner.height > 0 {
                let line = view.options.current_issued_spec.as_ref().map(|spec| format!(
                    "spec {} r{} | issuance {} r{} | digest {} | review {:?}",
                    short_opaque_marker(spec.execution_spec_id.as_str()),
                    spec.revision.get(),
                    short_opaque_marker(spec.launch_issuance.issuance_id.as_str()),
                    spec.launch_issuance.revision.get(),
                    short_opaque_marker(spec.launch_issuance.digest.as_str()),
                    spec.review_policy,
                )).unwrap_or_else(|| "None | save an exact reviewed selection before start".to_owned());
                Paragraph::new(truncate_cells(&line, issuance_inner.width as usize))
                    .style(Style::default().fg(theme.dim).bg(theme.surface))
                    .render(Rect::new(issuance_inner.x, issuance_inner.y, issuance_inner.width, 1), buf);
            }
        }
    }
}

fn render_harness_monitor(
    app: &App,
    view: &crate::app::HarnessRunMonitorView,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    fill_rect(area, theme.surface, buf);
    let heading = format!(
        "Harness run details | {} | binding {:?} | Esc board",
        view.run.run_id,
        view.run.binding,
    );
    Paragraph::new(truncate_cells(&heading, area.width as usize))
        .style(Style::default().fg(theme.text).bg(theme.active).add_modifier(Modifier::BOLD))
        .render(Rect::new(area.x, area.y, area.width, 1), buf);
    let status = if let Some(monitor) = view.monitor.as_ref() {
        format!(
            "availability {:?} | freshness {:?} | transport {} | exact run revision r{}",
            monitor.availability,
            monitor.freshness,
            if monitor.transport_incomplete { "incomplete" } else { "complete" },
            view.run.revision.get(),
        )
    } else if view.loading {
        "loading authoritative run details...".to_owned()
    } else if let Some(reason) = view.stale_reason.as_ref() {
        format!("ERROR / STALE | {reason}")
    } else {
        "run details unavailable for this exact run".to_owned()
    };
    if area.height > 1 {
        Paragraph::new(truncate_cells(&status, area.width as usize))
            .style(Style::default().fg(if view.stale_reason.is_some() { theme.yellow } else { theme.dim }).bg(theme.surface))
            .render(Rect::new(area.x, area.y + 1, area.width, 1), buf);
    }
    if area.height > 2 {
        let actions = Rect::new(area.x, area.y + 2, area.width, 1);
        let mut x = render_toolbar_icon_segment(
            icons::IconId::ArrowLeft,
            "[Back]",
            actions.x,
            actions,
            Style::default().fg(theme.teal).bg(theme.surface),
            Some(HitTarget::HarnessRunMonitorBack),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        x = render_toolbar_icon_segment(
            icons::IconId::Folder,
            "[Files]",
            x.saturating_add(1),
            actions,
            Style::default().fg(theme.teal).bg(theme.surface),
            Some(HitTarget::HarnessTaskDetailRunFiles(view.run.run_id.clone())),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        x = render_toolbar_icon_segment(
            icons::IconId::SourceControl,
            "[Git]",
            x.saturating_add(1),
            actions,
            Style::default().fg(theme.teal).bg(theme.surface),
            Some(HitTarget::HarnessTaskDetailRunGit(view.run.run_id.clone())),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        let note_x = x.saturating_add(2);
        Paragraph::new(truncate_cells(
            "History stays in Harness [Summary]; no legacy session route",
            actions.right().saturating_sub(note_x) as usize,
        ))
            .style(Style::default().fg(theme.muted).bg(theme.surface))
            .render(Rect::new(note_x, actions.y, actions.right().saturating_sub(note_x), 1), buf);
    }

    let mut lines = Vec::<(String, Color, Option<HitTarget>)>::new();
    if let Some(reason) = view.stale_reason.as_ref() {
        lines.push((format!("Stale/error state: {reason}"), theme.yellow, None));
    }
    if let Some(monitor) = view.monitor.as_ref() {
        lines.extend(harness_monitor_section_lines(app, view, monitor, theme));
    } else if view.loading {
        lines.push((
            "Loading structured facts and ordered timeline...".to_owned(),
            theme.dim,
            None,
        ));
    } else if view.stale_reason.is_none() {
        lines.push((
            "Observation unavailable for this exact run".to_owned(),
            theme.yellow,
            None,
        ));
    }
    let capacity = area.height.saturating_sub(4) as usize;
    let offset = view.scroll.min(lines.len().saturating_sub(capacity.max(1)));
    let end = offset.saturating_add(capacity).min(lines.len());
    if area.height > 3 {
        let sections = Rect::new(area.x, area.y + 3, area.width, 1);
        let mut x = sections.x;
        for section in crate::app::HarnessRunMonitorSection::ALL {
            x = render_toolbar_segment(
                &format!("[{}]", section.label()),
                x,
                sections,
                Style::default()
                    .fg(if section == view.section { theme.text } else { theme.teal })
                    .bg(if section == view.section { theme.panel } else { theme.surface }),
                Some(HitTarget::HarnessRunMonitorSection(section)),
                buf,
                layout,
            ).saturating_add(1);
        }
        x = render_toolbar_icon_segment(
            icons::IconId::ArrowUp,
            "[Up]",
            x,
            sections,
            Style::default().fg(if offset > 0 { theme.teal } else { theme.muted }).bg(theme.surface),
            (offset > 0).then_some(HitTarget::HarnessRunMonitorScrollUp),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        ).saturating_add(1);
        let more = lines.len().saturating_sub(end);
        x = render_toolbar_icon_segment(
            icons::IconId::ArrowDown,
            "[Down]",
            x,
            sections,
            Style::default().fg(if more > 0 { theme.teal } else { theme.muted }).bg(theme.surface),
            (more > 0).then_some(HitTarget::HarnessRunMonitorScrollDown),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        ).saturating_add(1);
        let count = format!("items {} | above {} | {} more", lines.len(), offset, more);
        Paragraph::new(truncate_cells(&count, sections.right().saturating_sub(x) as usize))
            .style(Style::default().fg(theme.muted).bg(theme.surface))
            .render(Rect::new(x, sections.y, sections.right().saturating_sub(x), 1), buf);
    }
    for (index, (line, color, target)) in lines.into_iter()
        .skip(offset)
        .take(capacity)
        .enumerate()
    {
        let row = Rect::new(area.x, area.y + 4 + index as u16, area.width, 1);
        Paragraph::new(truncate_cells(&line, area.width as usize))
            .style(Style::default().fg(color).bg(theme.surface))
            .render(row, buf);
        if let Some(target) = target {
            layout.hits.push(HitRegion { rect: row, target });
        }
    }
}

/// The owner-visible readout for `App::profiler` -- `Ctrl+P` toggles it
/// open, the same key or `Escape` closes it (`App::reduce`'s own top-of-
/// function guard), and a click anywhere outside its rect closes it too
/// (`App::close_overlay_outside_click`). No `.title(...)` call and no
/// `[x]`, deliberately, same contract `render_global_search_dropdown`'s
/// own doc comment documents for that dropdown: a diagnostic readout is
/// not a modal you configure, it is a window you glance at and dismiss the
/// same way you opened it. Every number here comes from one `snapshot()`
/// call -- the same one `TuiProfiler::maybe_write_log` formats into the
/// log file, so the overlay and the log can never disagree about what
/// "right now" means.
fn render_profile_overlay(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let snapshot = app.profiler.snapshot();
    let width = 70.min(area.width);
    // 17, not 16: one more row than before this feature's own `term_
    // coalesced` line (below) joined `lines` -- see `render_modal_line`'s
    // own bounds check for why silently reusing the old height would just
    // as silently have dropped this line (and, before it, the "Ctrl+P or
    // Esc closes" hint) off the bottom of the modal on any terminal tall
    // enough to show the full overlay uncropped.
    let height = 17.min(area.height);
    if width < 3 || height < 3 {
        return;
    }
    let modal = centered(area, width, height);
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    let inner = Rect::new(
        modal.x + 1,
        modal.y + 1,
        modal.width.saturating_sub(2),
        modal.height.saturating_sub(2),
    );
    let dist_line = |name: &str, dist: crate::profile::Distribution| {
        format!("{name:<11} p50={:<6} p95={:<6} max={:<6} n={}", dist.p50, dist.p95, dist.max, dist.count)
    };
    let empty_pct = if snapshot.terminal_polls_total == 0 {
        0.0
    } else {
        100.0 * snapshot.terminal_polls_empty as f64 / snapshot.terminal_polls_total as f64
    };
    let lines = [
        // The redraw tick's own phases, in the order the tick runs them,
        // then the whole tick and what none of the phases accounted for.
        // A `frame_rest_us` that is not near zero means a step joined the
        // tick without being measured -- see `profile::FramePhases`.
        dist_line("animate_us", snapshot.animate_us),
        dist_line("render_us", snapshot.render_us),
        dist_line("queue_us", snapshot.queue_us),
        dist_line("cur_hide_us", snapshot.cursor_hide_us),
        dist_line("cur_sync_us", snapshot.cursor_sync_us),
        dist_line("flush_us", snapshot.flush_us),
        dist_line("sixel_us", snapshot.sixel_us),
        dist_line("frame_us", snapshot.frame_us),
        dist_line("frame_rest_us", snapshot.frame_remainder_us),
        dist_line("wait_us", snapshot.wait_us),
        format!(
            "{:<11} p50={:<6} p95={:<6} max={:<6} n={} (ceiling {})",
            "fps", snapshot.fps.p50, snapshot.fps.p95, snapshot.fps.max, snapshot.fps.count,
            snapshot.fps_ceiling,
        ),
        dist_line("frame_age_ms", snapshot.frame_age_ms),
        dist_line("term_rtt_us", snapshot.terminal_rtt_us),
        dist_line("term_fps", snapshot.terminal_frames_per_sec),
        dist_line("term_bps", snapshot.terminal_bytes_per_sec),
        format!(
            "term_polls  empty={} of total={} ({empty_pct:.0}% empty)",
            snapshot.terminal_polls_empty, snapshot.terminal_polls_total,
        ),
        format!(
            "term_total  frames={} bytes={}",
            snapshot.terminal_frames_total, snapshot.terminal_bytes_total,
        ),
        // 0 in steady state on a session the push path can keep up with --
        // see `TuiProfiler::record_terminal_coalesced`'s own doc comment
        // for why a nonzero reading here means the harness is dropping
        // intermediate frames for a session producing output faster than
        // this connection drains it, not a bug.
        format!(
            "term_coalesced total={}",
            snapshot.terminal_coalesced_total,
        ),
        String::new(),
        "Ctrl+P or Esc closes".to_owned(),
    ];
    for (row, line) in lines.iter().enumerate() {
        render_modal_line(
            line,
            inner,
            row as u16,
            Style::default().fg(theme.text).bg(theme.modal),
            buf,
        );
    }
}

fn render_harness_reverse_attribution(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(detail) = app.harness_kanban.reverse_attribution.as_ref() else {
        return;
    };
    let link_count = match &detail.state {
        HarnessReverseAttributionState::Ready { value, .. } => value.links.len(),
        HarnessReverseAttributionState::Loading { .. }
        | HarnessReverseAttributionState::Error { .. } => 0,
    };
    let width = area.width.saturating_sub(4).min(104).max(3);
    let height = area.height.saturating_sub(2)
        .min(8_u16.saturating_add(link_count.min(10) as u16))
        .max(3);
    let modal = positioned_modal(
        area,
        width,
        height,
        app.overlay_positions.get(&OverlayId::HarnessReverseAttribution).copied(),
    );
    layout.harness_reverse_attribution_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .title(" Harness links ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(modal.x, modal.y, modal.width, 1),
        target: HitTarget::HarnessReverseAttributionDrag,
    });
    // In addition to (not instead of) this modal's own pre-existing
    // `[Close]` content-row button just below -- see `render_modal_
    // close`'s own doc comment.
    render_modal_close(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let inner = Rect::new(modal.x + 1, modal.y + 1, modal.width - 2, modal.height - 2);
    let close = "[Close]";
    let close_width = (cell_width(close) as u16).min(inner.width);
    let close_rect = Rect::new(
        inner.right().saturating_sub(close_width),
        inner.y,
        close_width,
        1,
    );
    Paragraph::new(close)
        .style(Style::default().fg(theme.teal).bg(theme.modal))
        .render(close_rect, buf);
    layout.hits.push(HitRegion {
        rect: close_rect,
        target: HitTarget::HarnessLinksClose,
    });

    let subject = harness_reverse_subject_label(&detail.subject);
    let subject_width = inner.width.saturating_sub(close_width.saturating_add(1));
    render_modal_line(
        truncate_cells(&subject, subject_width as usize),
        Rect::new(inner.x, inner.y, subject_width, inner.height),
        0,
        Style::default().fg(theme.text).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    let workspace = harness_reverse_subject_workspace(&detail.subject);
    render_modal_line(
        format!(
            "exact tuple | node {} | incarnation {} | workspace {}",
            workspace.node_id.as_str(),
            workspace.node_incarnation_id.as_str(),
            workspace.workspace_id.as_str(),
        ),
        inner,
        1,
        Style::default().fg(theme.dim).bg(theme.modal),
        buf,
    );
    let mut row = 2;
    if let Some(warning) = harness_reverse_scope_warning(&detail.subject) {
        render_modal_line(
            warning,
            inner,
            row,
            Style::default().fg(theme.yellow).bg(theme.modal),
            buf,
        );
        row += 1;
    }
    match &detail.state {
        HarnessReverseAttributionState::Loading { token } => {
            render_modal_line(
                format!("Loading exact reverse attribution | token {token}"),
                inner,
                row,
                Style::default().fg(theme.dim).bg(theme.modal),
                buf,
            );
        }
        HarnessReverseAttributionState::Error { message, .. } => {
            render_modal_line(
                format!("Error | {message}"),
                inner,
                row,
                Style::default().fg(theme.red).bg(theme.modal),
                buf,
            );
        }
        HarnessReverseAttributionState::Ready { value, .. } => {
            let workspace_scope_only = matches!(
                &detail.subject,
                HarnessReverseAttributionSubjectV1::FileScope { .. }
                    | HarnessReverseAttributionSubjectV1::CommitScope { .. }
            );
            let outcome = match value.outcome {
                HarnessReverseAttributionOutcomeV1::Attributed if workspace_scope_only => {
                    format!(
                        "Workspace-scope links | {} exact Harness run(s)",
                        value.links.len(),
                    )
                }
                HarnessReverseAttributionOutcomeV1::Attributed => {
                    format!("Attributed | {} exact Harness link(s)", value.links.len())
                }
                HarnessReverseAttributionOutcomeV1::Unattributed => {
                    "Unattributed | No durable attribution recorded".to_owned()
                }
            };
            render_modal_line(
                outcome,
                inner,
                row,
                Style::default().fg(if value.links.is_empty() { theme.yellow } else { theme.green }).bg(theme.modal),
                buf,
            );
            row += 1;
            for link in value.links.iter().take(inner.height.saturating_sub(row) as usize) {
                let line = format!(
                    "task {} | run {} r{} | {} | {}",
                    link.task_id,
                    link.run_id,
                    link.run_revision.get(),
                    harness_reverse_relation_label(link.relation),
                    harness_reverse_binding_label(&link.binding),
                );
                let rect = Rect::new(inner.x, inner.y + row, inner.width, 1);
                Paragraph::new(truncate_cells(&line, inner.width as usize))
                    .style(Style::default().fg(theme.teal).bg(theme.modal))
                    .render(rect, buf);
                layout.hits.push(HitRegion {
                    rect,
                    target: HitTarget::HarnessAgentTask(
                        link.task_id.clone(),
                        link.run_id.clone(),
                    ),
                });
                row += 1;
            }
        }
    }
}

fn harness_reverse_subject_workspace(
    subject: &HarnessReverseAttributionSubjectV1,
) -> &gate4agent_harness_client::HarnessReverseAttributionWorkspaceV1 {
    match subject {
        HarnessReverseAttributionSubjectV1::ManagedRecord { workspace, .. }
        | HarnessReverseAttributionSubjectV1::RuntimeSession { workspace, .. }
        | HarnessReverseAttributionSubjectV1::Workspace { workspace }
        | HarnessReverseAttributionSubjectV1::FileScope { workspace, .. }
        | HarnessReverseAttributionSubjectV1::CommitScope { workspace, .. } => workspace,
    }
}

fn harness_reverse_subject_label(subject: &HarnessReverseAttributionSubjectV1) -> String {
    match subject {
        HarnessReverseAttributionSubjectV1::ManagedRecord { record_id, .. } => {
            format!("Managed agent | record {}", record_id.as_str())
        }
        HarnessReverseAttributionSubjectV1::RuntimeSession {
            instance_id,
            generation,
            ..
        } => format!("Runtime session | #{instance_id}:{generation}"),
        HarnessReverseAttributionSubjectV1::Workspace { .. } => "Workspace".to_owned(),
        HarnessReverseAttributionSubjectV1::FileScope { relative_path, .. } => {
            format!("File | {}", relative_path.as_str())
        }
        HarnessReverseAttributionSubjectV1::CommitScope { object_id, .. } => {
            format!("Commit | {}", object_id.as_str())
        }
    }
}

fn harness_reverse_scope_warning(subject: &HarnessReverseAttributionSubjectV1) -> Option<&'static str> {
    match subject {
        HarnessReverseAttributionSubjectV1::FileScope { .. } => Some(
            "Workspace-scope only; never claim this file was produced or modified by a linked run.",
        ),
        HarnessReverseAttributionSubjectV1::CommitScope { .. } => Some(
            "Workspace-scope only; never claim this commit was produced or modified by a linked run.",
        ),
        HarnessReverseAttributionSubjectV1::ManagedRecord { .. }
        | HarnessReverseAttributionSubjectV1::RuntimeSession { .. }
        | HarnessReverseAttributionSubjectV1::Workspace { .. } => None,
    }
}

fn harness_reverse_relation_label(relation: HarnessReverseAttributionRelationV1) -> &'static str {
    match relation {
        HarnessReverseAttributionRelationV1::ManagedRecordBinding => "managed binding",
        HarnessReverseAttributionRelationV1::RuntimeSessionBinding => "runtime binding",
        HarnessReverseAttributionRelationV1::WorkspaceBinding => "workspace binding",
        HarnessReverseAttributionRelationV1::WorkspaceScope => "workspace-scope only",
    }
}

fn harness_reverse_binding_label(binding: &HarnessReverseAttributionBindingV1) -> String {
    match binding {
        HarnessReverseAttributionBindingV1::ManagedRecord {
            record_id,
            active_instance_id,
            active_generation,
            ..
        } => active_instance_id.zip(*active_generation).map_or_else(
            || format!("record {}", record_id.as_str()),
            |(instance, generation)| format!(
                "record {} | #{instance}:{generation}",
                record_id.as_str(),
            ),
        ),
        HarnessReverseAttributionBindingV1::RuntimeSession {
            instance_id,
            generation,
            ..
        } => format!("session #{instance_id}:{generation}"),
        HarnessReverseAttributionBindingV1::Workspace { .. } => "workspace tuple".to_owned(),
    }
}

fn render_agent_board_card(
    app: &App,
    card: &AgentBoardCard,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let selected = app.agent_board.selected.as_ref() == Some(&card.key);
    let background = if selected { theme.active } else { theme.panel };
    fill_rect(area, background, buf);
    layout.hits.push(HitRegion {
        rect: area,
        target: HitTarget::AgentBoardCard(card.key.clone()),
    });
    let (primary, mut secondary) = match &card.key {
        AgentRowKey::Managed { .. } => {
            let Some(record) = app.find_managed_session(&card.key) else {
                return;
            };
            let primary = app
                .agent_local_alias(&card.key)
                .unwrap_or(&record.display_name)
                .to_owned();
            let state = managed_state_label(record.state);
            let task = record.task_binding.as_ref()
                .and_then(|binding| binding.task_id.as_ref())
                .map(|task_id| format!(" | {}", compact_task_id(task_id)))
                .unwrap_or_default();
            (
                primary,
                format!("{} | {state} | {} | {}{task}", record.provider, record.node_id, record.workspace_id),
            )
        }
        AgentRowKey::Legacy(address) => {
            let Some(session) = app.find_session(address) else {
                return;
            };
            (
                format!("{} agent", session.provider),
                format!(
                    "{} | {} | {}",
                    if session.running { "running" } else { "stopped" },
                    address.node_id,
                    address.workspace_id,
                ),
            )
        }
    };
    if let Some((task_id, run_id)) = app.harness_agent_run_links(&card.key).last() {
        let task = task_id.as_str();
        let run = run_id.as_str();
        secondary.push_str(&format!(
            " | Harness {}.../{}...",
            &task[..task.len().min(10)],
            &run[..run.len().min(10)],
        ));
    }
    let open_ascii_label = "[open]";
    let open_width = compact_icon_button_width(open_ascii_label, app.rail_icons)
        .min(area.width);
    let open_rect = Rect::new(area.right().saturating_sub(open_width), area.y, open_width, 1);
    let pin = if app.agent_is_pinned(&card.key) { "P " } else { "" };
    let title_width = area.width.saturating_sub(open_width).saturating_sub(1);
    Paragraph::new(truncate_cells(&format!("{pin}{primary}"), title_width as usize))
        .style(
            Style::default()
                .fg(theme.text)
                .bg(background)
                .add_modifier(Modifier::BOLD),
        )
        .render(Rect::new(area.x, area.y, title_width, 1), buf);
    if open_width > 0 {
        render_compact_icon_button(
            open_rect,
            icons::IconId::GoToFile,
            open_ascii_label,
            Style::default().fg(theme.teal).bg(background),
            app.rail_icons, app.icon_family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion {
            rect: open_rect,
            target: HitTarget::AgentBoardCardOpen(card.key.clone()),
        });
    }
    if area.height > 1 {
        Paragraph::new(truncate_cells(&secondary, area.width as usize))
            .style(Style::default().fg(theme.dim).bg(background))
            .render(Rect::new(area.x, area.y + 1, area.width, 1), buf);
    }
    if area.height > 2 {
        let status = format!(
            "status: {}{}",
            card.reason,
            if card.partial { " partial" } else { "" },
        );
        Paragraph::new(truncate_cells(&status, area.width as usize))
            .style(Style::default().fg(theme.yellow).bg(background))
            .render(Rect::new(area.x, area.y + 2, area.width, 1), buf);
    }
    if area.height > 3 {
        let summary = app
            .agent_board_fresh_progress(card)
            .map(agent_board_progress_summary)
            .unwrap_or_else(|| "progress unavailable".to_owned());
        Paragraph::new(truncate_cells(&summary, area.width as usize))
            .style(Style::default().fg(theme.dim).bg(background))
            .render(Rect::new(area.x, area.y + 3, area.width, 1), buf);
        if app.harness_kanban.enabled {
            if let Some(subject) = app.harness_agent_links_subject(&card.key) {
                let ascii_label = "[Harness links]";
                let width = compact_icon_button_width(ascii_label, app.rail_icons)
                    .min(area.width);
                let rect = Rect::new(
                    area.right().saturating_sub(width),
                    area.y + 3,
                    width,
                    1,
                );
                render_compact_icon_button(
                    rect,
                    icons::IconId::Link,
                    ascii_label,
                    Style::default().fg(theme.teal).bg(background),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                layout.hits.push(HitRegion {
                    rect,
                    target: HitTarget::HarnessLinks(subject),
                });
            }
        }
    }
    if area.height > 4 {
        let run_label = if app.agent_run_lens_key() == Some(&card.key) {
            "[global]"
        } else {
            "[workspace]"
        };
        let progress_label = "[monitor]";
        let run_width = (cell_width(run_label) as u16).min(area.width);
        let run_rect = Rect::new(area.x, area.y + 4, run_width, 1);
        Paragraph::new(run_label)
            .style(Style::default().fg(theme.teal).bg(background))
            .render(run_rect, buf);
        if run_width > 0 {
            layout.hits.push(HitRegion {
                rect: run_rect,
                target: HitTarget::AgentBoardCardRun(card.key.clone()),
            });
        }
        let progress_x = run_rect.right().saturating_add(1);
        let progress_width = (cell_width(progress_label) as u16)
            .min(area.right().saturating_sub(progress_x));
        if progress_width > 0 {
            let progress_rect = Rect::new(progress_x, area.y + 4, progress_width, 1);
            Paragraph::new(progress_label)
                .style(Style::default().fg(theme.teal).bg(background))
                .render(progress_rect, buf);
            layout.hits.push(HitRegion {
                rect: progress_rect,
                target: HitTarget::AgentBoardCardProgress(card.key.clone()),
            });
        }
        if let Some((task_id, run_id)) = app.harness_agent_run_links(&card.key).last() {
            let harness_label = "[task]";
            let harness_width = (cell_width(harness_label) as u16).min(area.width);
            let harness_rect = Rect::new(
                area.right().saturating_sub(harness_width),
                area.y + 4,
                harness_width,
                1,
            );
            if harness_rect.x > progress_x.saturating_add(progress_width) {
                Paragraph::new(harness_label)
                    .style(Style::default().fg(theme.teal).bg(background))
                    .render(harness_rect, buf);
                layout.hits.push(HitRegion {
                    rect: harness_rect,
                    target: HitTarget::HarnessAgentTask(task_id.clone(), run_id.clone()),
                });
            }
        }
    }
}

fn agent_board_progress_summary(progress: &gate4agent_node_protocol::AgentProgressV1) -> String {
    let tool_classes = progress
        .active_tool_labels
        .iter()
        .filter_map(|label| match label.to_ascii_lowercase().as_str() {
            "read" => Some("Read"),
            "write" => Some("Write"),
            "edit" => Some("Edit"),
            "shell" => Some("Shell"),
            "search" => Some("Search"),
            "browse" => Some("Browse"),
            "git" => Some("Git"),
            "ask" => Some("Ask"),
            "task" => Some("Task"),
            _ => None,
        })
        .collect::<Vec<_>>();
    let tools = if tool_classes.is_empty() {
        format!("tools {}", progress.active_tool_count)
    } else {
        format!("tools {} [{}]", progress.active_tool_count, tool_classes.join(","))
    };
    let usage = progress
        .usage
        .map(|usage| format!(" | tokens {}/{}", usage.input_tokens, usage.output_tokens))
        .unwrap_or_default();
    format!(
        "turns {} | {tools}{usage} | subagents {}",
        progress.completed_turns,
        progress.subagent_count,
    )
}

/// Renders this pane's own tab strip into `area` (its header row) and
/// returns the column immediately after the last tab label actually
/// drawn (`area.x` when nothing was drawn at all) -- FIX2's own close-
/// cross overlay (`render_surface_pane_close`, called right after this
/// in `render_surface_pane`) needs this exact, already-truncated value to
/// know how much of the row is genuinely free background rather than a
/// rendered label; a value recomputed from label widths alone would drift
/// from what this loop's own truncation/scroll-to-selected logic (`start`
/// below) actually painted.
fn render_surface_pane_tabs(
    app: &App,
    pane_id: PaneId,
    pane: &crate::surface::Pane<SurfaceTab>,
    focused: bool,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) -> u16 {
    fill_rect(area, theme.active, buf);
    if area.width == 0 || pane.tabs.is_empty() {
        return area.x;
    }
    let labels = pane
        .tabs
        .iter()
        .map(|tab| surface_pane_tab_title(app, tab))
        .collect::<Vec<_>>();
    let selected_end = labels
        .iter()
        .take(pane.active.saturating_add(1))
        .map(|label| cell_width(&format!(" {label} ")).min(u16::MAX as usize) as u16)
        .fold(0_u16, |sum, width| sum.saturating_add(width));
    let start = if selected_end <= area.width {
        0
    } else {
        pane.active.min(labels.len().saturating_sub(1))
    };
    let mut x = area.x;
    for (index, label) in labels.iter().enumerate().skip(start) {
        if x >= area.right() {
            break;
        }
        let text = format!(" {label} ");
        let width = (cell_width(&text) as u16).min(area.right().saturating_sub(x));
        let selected = index == pane.active;
        let selected_background = if focused { theme.accent } else { theme.panel };
        Paragraph::new(truncate_cells(&text, width as usize))
            .style(
                Style::default()
                    .fg(if selected && focused { theme.active_tab_text } else if selected { theme.text } else { theme.muted })
                    .bg(if selected { selected_background } else { theme.active })
                    .add_modifier(if selected { Modifier::BOLD } else { Modifier::empty() }),
            )
            .render(Rect::new(x, area.y, width, 1), buf);
        layout.hits.push(HitRegion {
            rect: Rect::new(x, area.y, width, 1),
            target: HitTarget::SurfaceTab(pane_id, index),
        });
        x = x.saturating_add(width);
    }
    x
}

/// FIX2 (owner report: viewport panes had no mouse close control): the
/// per-pane `[x]` overlay closing THAT pane's own active tab -- drawn at
/// `header`'s own top-right corner, following [`render_modal_close`]'s
/// own `[x]`/`theme.teal` visual convention, backgrounded with `theme.
/// active` (the header/tab-strip row's own fill colour from `render_
/// surface_pane_tabs`'s `fill_rect` call, regardless of `focused` -- see
/// that fn's own doc comment) rather than `theme.modal`: a pane header is
/// a plain tab strip, not a bordered dialog box, so there is no border
/// corner glyph here to leave a margin column for either.
///
/// `tabs_right` is exactly what `render_surface_pane_tabs` just returned
/// for THIS same header this THIS same frame -- the real column its tab
/// labels actually stopped at, already accounting for truncation and the
/// scroll-to-keep-the-active-tab-visible logic, not a guess. The
/// candidate cross rect is flush against `header`'s own right edge; if it
/// would start at or before `tabs_right` (the tab strip already reaches,
/// or comes within the cross's own 3-cell width of, the corner), this
/// draws nothing at all rather than truncating or sitting on top of a
/// real label -- the narrow-pane rule this fix's own brief asked for.
/// Every pane is rendered independently (`render_surface_node`'s own
/// per-leaf recursion into `render_surface_pane`), so a split showing two
/// (or more) panes gets one independently-computed cross per pane for
/// free, each with its own [`HitTarget::SurfacePaneClose`] carrying that
/// exact pane's own [`PaneId`].
fn render_surface_pane_close(
    pane_id: PaneId,
    header: Rect,
    tabs_right: u16,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    const CLOSE: &str = "[x]";
    let width = CLOSE.len() as u16;
    if header.width < width || header.height == 0 {
        return;
    }
    let rect = Rect::new(header.right().saturating_sub(width), header.y, width, 1);
    if rect.x < tabs_right {
        return;
    }
    Paragraph::new(CLOSE)
        .style(Style::default().fg(theme.teal).bg(theme.active))
        .render(rect, buf);
    layout.hits.push(HitRegion { rect, target: HitTarget::SurfacePaneClose(pane_id) });
}

fn surface_pane_tab_title(app: &App, tab: &SurfaceTab) -> String {
    match tab {
        SurfaceTab::AgentBoard => "Agent board".to_owned(),
        SurfaceTab::SessionMonitor(key) => match &key.target {
            SessionMonitorTarget::Runtime { address, .. } => format!(
                "Monitor #{}:{}",
                address.instance_id,
                address.generation,
            ),
            SessionMonitorTarget::Managed { record_id, .. } => format!("Monitor @{record_id}"),
        },
        SurfaceTab::File(key) => repository_path_file_name_display(&key.path),
        SurfaceTab::Git(key) => git_surface_title(app, key),
        SurfaceTab::HarnessFile(key) => repository_path_file_name_display(&key.path),
        SurfaceTab::HarnessGit(key) => key.history_path.as_ref()
            .map(|path| format!("{} Git", repository_path_file_name_display(path)))
            .unwrap_or_else(|| "workspace Git".to_owned()),
        SurfaceTab::Preview(key) => app
            .preview_tabs
            .get(key)
            .map(|preview| preview.title.clone())
            .unwrap_or_else(|| "detached session".to_owned()),
        SurfaceTab::Pty(_) => app.surface_tab_title(tab),
        SurfaceTab::IconGallery => "Icon gallery".to_owned(),
    }
}

fn git_surface_title(app: &App, key: &crate::app::WorkspaceGitTabKey) -> String {
    let Some(tab) = app.git_tabs.get(key) else {
        return format!("{} commits", key.workspace_id);
    };
    let target = tab
        .diff
        .as_ref()
        .map(|diff| &diff.target)
        .or(tab.pending_diff.as_ref());
    if let Some(target) = target {
        use crate::app::WorkspaceGitDiffTarget;
        let path_name = |path: &Option<gate4agent_node_protocol::RepositoryPath>| {
            path.as_ref()
                .map(repository_path_file_name_display)
                .unwrap_or_else(|| key.workspace_id.clone())
        };
        return match target {
            WorkspaceGitDiffTarget::Working { path } => {
                format!("{} changes", path_name(path))
            }
            WorkspaceGitDiffTarget::Staged { path } => {
                format!("{} staged", path_name(path))
            }
            WorkspaceGitDiffTarget::Commit { revision, path } => format!(
                "{} @ {}",
                path_name(path),
                &revision[..revision.len().min(8)],
            ),
        };
    }
    tab.history_path
        .as_ref()
        .map(|path| format!("{} commits", repository_path_file_name_display(path)))
        .unwrap_or_else(|| format!("{} commits", key.workspace_id))
}

fn render_surface_toolbar(
    app: &App,
    pane_id: PaneId,
    tab: Option<&SurfaceTab>,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    fill_rect(area, theme.active, buf);
    let button_style = Style::default().fg(theme.teal).bg(theme.active);
    let selected_tab_style = Style::default().fg(theme.text).bg(theme.panel).add_modifier(Modifier::BOLD);
    let detail_style = Style::default().fg(theme.muted).bg(theme.active);
    let mut x = area.x;
    match tab {
        Some(SurfaceTab::AgentBoard) => {
            if app.agent_board_mode == crate::app::AgentBoardMode::HarnessKanban {
                return;
            }
            if app.harness_kanban.enabled {
                x = render_toolbar_segment(
                    "[Harness tasks]",
                    x,
                    area,
                    button_style,
                    Some(HitTarget::HarnessBoardMode(crate::app::AgentBoardMode::HarnessKanban)),
                    buf,
                    layout,
                );
                x = render_toolbar_segment(
                    "[Runtime sessions]",
                    x.saturating_add(1),
                    area,
                    selected_tab_style,
                    Some(HitTarget::HarnessBoardMode(crate::app::AgentBoardMode::SessionMonitoring)),
                    buf,
                    layout,
                );
                x = render_toolbar_segment(
                    if app.agent_board.task_filter.is_some() { "[All sessions]" } else { "[Task filter]" },
                    x.saturating_add(1),
                    area,
                    button_style,
                    Some(HitTarget::AgentBoardTaskFilter),
                    buf,
                    layout,
                );
            } else {
                x = render_toolbar_segment(
                    if app.agent_board.task_filter.is_some() { "[All sessions]" } else { "[Task filter]" },
                    x,
                    area,
                    button_style,
                    Some(HitTarget::AgentBoardTaskFilter),
                    buf,
                    layout,
                );
            }
            let _ = render_toolbar_segment(
                " Agent board | observed runtime states | t task filter | arrows navigate | Enter open ",
                x.saturating_add(1),
                area,
                detail_style,
                None,
                buf,
                layout,
            );
        }
        Some(SurfaceTab::SessionMonitor(key)) => {
            render_session_monitor_toolbar(app, pane_id, key, area, buf, layout, theme);
        }
        Some(SurfaceTab::File(key)) => {
            let file = app.file_tabs.get(key);
            let ready = file.is_some_and(|file| file.state == WorkspaceFileState::Ready);
            if ready {
                if let Some(history) = file.and_then(|file| file.inline_history.as_ref()) {
                    x = render_toolbar_icon_segment(
                        icons::IconId::File,
                        "[Source]",
                        x,
                        area,
                        button_style,
                        Some(HitTarget::FileSource(pane_id)),
                        app.rail_icons, app.icon_family,
                        buf,
                        layout,
                    );
                    if history.mode == WorkspaceGitPaneMode::Detail {
                        x = render_toolbar_icon_segment(
                            icons::IconId::History,
                            "[Commits]",
                            x.saturating_add(1),
                            area,
                            button_style,
                            Some(HitTarget::FileHistoryBack(pane_id)),
                            app.rail_icons, app.icon_family,
                            buf,
                            layout,
                        );
                        if history.selected > 0 {
                            x = render_toolbar_icon_segment(
                                icons::IconId::ArrowLeft,
                                "<",
                                x.saturating_add(1),
                                area,
                                button_style,
                                Some(HitTarget::FileHistoryPrevious(pane_id)),
                                app.rail_icons, app.icon_family,
                                buf,
                                layout,
                            );
                        }
                        if history.selected.saturating_add(1) < history.commits.len() {
                            x = render_toolbar_icon_segment(
                                icons::IconId::ArrowRight,
                                ">",
                                x.saturating_add(1),
                                area,
                                button_style,
                                Some(HitTarget::FileHistoryNext(pane_id)),
                                app.rail_icons, app.icon_family,
                                buf,
                                layout,
                            );
                        }
                        let position = format!(
                            " commit {}/{} ",
                            history.selected.saturating_add(1).min(history.commits.len()),
                            history.commits.len(),
                        );
                        let _ = render_toolbar_segment(
                            &position,
                            x.saturating_add(1),
                            area,
                            detail_style,
                            None,
                            buf,
                            layout,
                        );
                    } else {
                        let _ = render_toolbar_segment(
                            " commits | Up/Down select | Enter diff ",
                            x.saturating_add(1),
                            area,
                            detail_style,
                            None,
                            buf,
                            layout,
                        );
                    }
                    render_harness_links_toolbar(app, tab, area, buf, layout, theme);
                    return;
                }
                x = render_toolbar_icon_segment(
                    icons::IconId::History,
                    "[History]",
                    x,
                    area,
                    button_style,
                    Some(HitTarget::FileHistory(pane_id)),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                x = render_toolbar_icon_segment(
                    icons::IconId::Diff,
                    "[Changes]",
                    x.saturating_add(1),
                    area,
                    button_style,
                    Some(HitTarget::FileChanges(pane_id)),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                let editing = app.file_tabs.get(key).is_some_and(|file| file.edit_mode);
                let (edit_icon, edit_ascii_label) = if editing {
                    (icons::IconId::Eye, "[View]")
                } else {
                    (icons::IconId::Edit, "[Edit]")
                };
                x = render_toolbar_icon_segment(
                    edit_icon,
                    edit_ascii_label,
                    x.saturating_add(1),
                    area,
                    button_style,
                    Some(HitTarget::FileEdit(pane_id)),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
                let _ = render_toolbar_icon_segment(
                    icons::IconId::Save,
                    "[Save]",
                    x.saturating_add(1),
                    area,
                    button_style,
                    Some(HitTarget::FileSave(pane_id)),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
            }
        }
        Some(SurfaceTab::Git(key)) => {
            let git = app.git_tabs.get(key);
            let mode = git.and_then(|git| git.diff.as_ref()).map_or(
                "commits",
                |diff| match &diff.target {
                    crate::app::WorkspaceGitDiffTarget::Working { .. } => "working changes",
                    crate::app::WorkspaceGitDiffTarget::Staged { .. } => "staged changes",
                    crate::app::WorkspaceGitDiffTarget::Commit { .. } => "commit diff",
                },
            );
            let _ = render_toolbar_segment(
                &format!(" {mode} | Enter diff | w working | s staged "),
                x,
                area,
                detail_style,
                None,
                buf,
                layout,
            );
        }
        Some(SurfaceTab::HarnessFile(key)) => {
            let ready = app.harness_file_tabs.get(key)
                .is_some_and(|file| file.state == WorkspaceFileState::Ready);
            if ready {
                x = render_toolbar_icon_segment(
                    icons::IconId::History,
                    "[History]",
                    x,
                    area,
                    button_style,
                    Some(HitTarget::HarnessFileHistory(pane_id)),
                    app.rail_icons, app.icon_family,
                    buf,
                    layout,
                );
            }
            let _ = render_toolbar_segment(
                &format!(" read-only | {} ", key.origin.label()),
                x.saturating_add(1),
                area,
                detail_style,
                None,
                buf,
                layout,
            );
        }
        Some(SurfaceTab::HarnessGit(key)) => {
            let _ = render_toolbar_segment(
                &format!(" read-only Git | {} ", key.origin.label()),
                x,
                area,
                detail_style,
                None,
                buf,
                layout,
            );
        }
        Some(SurfaceTab::Pty(_)) => {
            let _ = render_toolbar_segment(
                " live PTY | drag select | wheel scrollback ",
                x,
                area,
                detail_style,
                None,
                buf,
                layout,
            );
        }
        Some(SurfaceTab::IconGallery) => {
            let _ = render_toolbar_segment(
                " icon gallery | read-only | wheel scroll ",
                x,
                area,
                detail_style,
                None,
                buf,
                layout,
            );
        }
        Some(SurfaceTab::Preview(key)) => {
            let preview = app.preview_tabs.get(key);
            let skin = preview
                .map(|preview| ProviderPreviewSkin::for_provider(preview.provider.as_str()))
                .unwrap_or(ProviderPreviewSkin::Generic);
            let _ = render_toolbar_segment(
                &format!(" {} | read-only transcript | no input ", skin.name()),
                x,
                area,
                Style::default().fg(skin.accent(theme)).bg(theme.active),
                None,
                buf,
                layout,
            );
        }
        None => {}
    }
    render_harness_links_toolbar(app, tab, area, buf, layout, theme);
}

fn render_harness_links_toolbar(
    app: &App,
    tab: Option<&SurfaceTab>,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    if !app.harness_kanban.enabled {
        return;
    }
    let Some(subject) = tab.and_then(|tab| app.harness_surface_links_subject(tab)) else {
        return;
    };
    let ascii_label = "[Harness links]";
    let width = compact_icon_button_width(ascii_label, app.rail_icons)
        .min(area.width);
    if width == 0 {
        return;
    }
    let rect = Rect::new(area.right().saturating_sub(width), area.y, width, 1);
    render_compact_icon_button(
        rect,
        icons::IconId::Link,
        ascii_label,
        Style::default().fg(theme.teal).bg(theme.active),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    layout.hits.push(HitRegion {
        rect,
        target: HitTarget::HarnessLinks(subject),
    });
}

fn render_toolbar_segment(
    label: &str,
    x: u16,
    area: Rect,
    style: Style,
    target: Option<HitTarget>,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) -> u16 {
    if x >= area.right() {
        return x;
    }
    let width = (cell_width(label) as u16).min(area.right().saturating_sub(x));
    if width == 0 {
        return x;
    }
    let rect = Rect::new(x, area.y, width, 1);
    Paragraph::new(truncate_cells(label, width as usize))
        .style(style)
        .render(rect, buf);
    if let Some(target) = target {
        layout.hits.push(HitRegion { rect, target });
    }
    x.saturating_add(width)
}

fn render_workspace_file_tab(
    tab: &WorkspaceFileTabView,
    _path: &str,
    area: Rect,
    buf: &mut TerminalBuffer,
    theme: Theme,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.surface, buf);
    match &tab.state {
        WorkspaceFileState::Loading => {
            Paragraph::new(" loading file...")
                .style(Style::default().fg(theme.muted).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::NonUtf8 { byte_len } => {
            Paragraph::new(format!(" binary file ({byte_len} bytes); text editor unavailable"))
                .style(Style::default().fg(theme.yellow).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::TooLarge { limit_bytes } => {
            Paragraph::new(format!(" file exceeds the {limit_bytes}-byte editor limit"))
                .style(Style::default().fg(theme.yellow).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::Error(message) => {
            Paragraph::new(format!(" × {message}"))
                .style(Style::default().fg(theme.red).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::Ready => {
            let status_height = usize::from(area.height > 1);
            let rows = area.height as usize - status_height;
            let number_width = tab.editor.line_count().max(1).to_string().len().max(3);
            let content_width = (area.width as usize).saturating_sub(number_width + 3);
            let lines = tab.editor.visible_lines(rows, content_width);
            let first_line = tab.editor.scroll_line();
            for (row, line) in lines.iter().enumerate() {
                let y = area.y + row as u16;
                let number = format!("{:>width$} ", first_line + row + 1, width = number_width);
                let text = format!(
                    "{}{}{}",
                    if line.clipped_left { "‹" } else { "" },
                    line.text,
                    if line.clipped_right { "›" } else { "" },
                );
                Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![
                    Span::styled(number, Style::default().fg(theme.muted)),
                    Span::styled(text, Style::default().fg(theme.text)),
                ])]))
                .style(Style::default().bg(theme.surface))
                .render(Rect::new(area.x, y, area.width, 1), buf);
            }
            if status_height > 0 {
                let status = format!(
                    " {} | {} | {} bytes | {}",
                    if tab.edit_mode { "EDIT" } else { "VIEW" },
                    if tab.editor.dirty() { "modified" } else { "saved" },
                    tab.editor.byte_len(),
                    match tab.editor.sync_state() {
                        crate::text_editor::SyncState::Clean => "e edit",
                        crate::text_editor::SyncState::Dirty => "Ctrl+S save",
                        crate::text_editor::SyncState::Saving => "saving...",
                        crate::text_editor::SyncState::Conflict(_) => "save conflict",
                        crate::text_editor::SyncState::Error(_) => "save failed",
                    },
                );
                Paragraph::new(truncate_cells(&status, area.width as usize))
                    .style(Style::default().fg(theme.teal).bg(theme.active))
                    .render(Rect::new(area.x, area.bottom() - 1, area.width, 1), buf);
            }
        }
    }
}

fn render_workspace_file_tab_rich(
    tab: &WorkspaceFileTabView,
    path: &str,
    area: Rect,
    buf: &mut TerminalBuffer,
    theme: Theme,
    harness_read_only: bool,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.surface, buf);
    match &tab.state {
        WorkspaceFileState::Loading => {
            Paragraph::new(" loading file...")
                .style(Style::default().fg(theme.muted).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::NonUtf8 { byte_len } => {
            Paragraph::new(format!(" binary file ({byte_len} bytes); text editor unavailable"))
                .style(Style::default().fg(theme.yellow).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::TooLarge { limit_bytes } => {
            Paragraph::new(format!(" file exceeds the {limit_bytes}-byte editor limit"))
                .style(Style::default().fg(theme.yellow).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::Error(message) => {
            Paragraph::new(format!(" x {message}"))
                .style(Style::default().fg(theme.red).bg(theme.surface))
                .render(area, buf);
        }
        WorkspaceFileState::Ready => {
            let status_height = usize::from(area.height > 1);
            let rows = area.height as usize - status_height;
            let number_width = tab.editor.line_count().max(1).to_string().len().max(3);
            let content_width = (area.width as usize).saturating_sub(number_width + 3);
            let lines = tab.editor.visible_lines(rows, content_width);
            let first_line = tab.editor.scroll_line();
            let selection = tab.editor.selection_range();
            let syntax_language = crate::text_editor::syntax_language_for_path(path);
            for (row, line) in lines.iter().enumerate() {
                let y = area.y + row as u16;
                let logical_line = first_line + row;
                let Some(source) = tab
                    .editor
                    .render_line_slice(logical_line, 0, usize::MAX)
                else {
                    continue;
                };
                let syntax = crate::text_editor::syntax_spans_for_line(syntax_language, source.text);
                let visible_start_byte = byte_offset_for_scalar_column(
                    source.text,
                    tab.editor.scroll_column(),
                );
                let line_start_byte = tab.editor.line_byte_start(logical_line).unwrap_or_default();
                let mut syntax_index = 0;
                let mut spans = vec![Span::styled(
                    format!("{:>width$} ", logical_line + 1, width = number_width),
                    Style::default().fg(theme.muted),
                )];
                if line.clipped_left {
                    spans.push(Span::styled("<", Style::default().fg(theme.muted)));
                }
                for (column_offset, (offset, character)) in line.text.char_indices().enumerate() {
                    let column = tab.editor.scroll_column().saturating_add(column_offset);
                    let byte_offset = line_start_byte
                        .saturating_add(visible_start_byte)
                        .saturating_add(offset);
                    let style = if file_byte_is_selected(selection.as_ref(), byte_offset) {
                        Style::default()
                            .fg(theme.active_tab_text)
                            .bg(theme.accent)
                    } else {
                        syntax_style_for_column(&syntax, &mut syntax_index, column, theme)
                    };
                    spans.push(Span::styled(character.to_string(), style));
                }
                if line.clipped_right {
                    spans.push(Span::styled(">", Style::default().fg(theme.muted)));
                }
                Paragraph::new(Text::from_lines(vec![Line::from_spans(spans)]))
                    .style(Style::default().bg(theme.surface))
                    .render(Rect::new(area.x, y, area.width, 1), buf);
            }
            if status_height > 0 {
                let status = if harness_read_only {
                    " read-only Harness run file | select/copy | d Git".to_owned()
                } else {
                    let sync = match tab.editor.sync_state() {
                        crate::text_editor::SyncState::Clean => "saved",
                        crate::text_editor::SyncState::Dirty => "modified",
                        crate::text_editor::SyncState::Saving => "saving...",
                        crate::text_editor::SyncState::Conflict(_) => "save conflict",
                        crate::text_editor::SyncState::Error(_) => "save failed",
                    };
                    format!(
                        " {} | {} | {} bytes | click/drag select | Ctrl+A/C/X/V",
                        if tab.edit_mode { "EDIT" } else { "VIEW" },
                        sync,
                        tab.editor.byte_len(),
                    )
                };
                Paragraph::new(truncate_cells(&status, area.width as usize))
                    .style(Style::default().fg(theme.teal).bg(theme.active))
                    .render(Rect::new(area.x, area.bottom() - 1, area.width, 1), buf);
            }
        }
    }
}

fn render_file_scrollbar(
    tab: &WorkspaceFileTabView,
    pane_id: PaneId,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let track_height = area.height.saturating_sub(1);
    if area.width <= 2 || track_height == 0 {
        return;
    }
    let track = Rect::new(area.right().saturating_sub(1), area.y, 1, track_height);
    for y in track.y..track.bottom() {
        let cell = buf.get_mut(track.x, y);
        cell.symbol = "|".into();
        cell.style = Style::default().fg(theme.border).bg(theme.surface);
    }
    let line_count = tab.editor.line_count().max(1);
    let visible_rows = track_height as usize;
    let thumb_height = if line_count <= visible_rows {
        track_height
    } else {
        ((visible_rows.saturating_mul(visible_rows) + line_count - 1) / line_count)
            .max(1)
            .min(visible_rows) as u16
    };
    let travel = track_height.saturating_sub(thumb_height);
    let last_line = line_count.saturating_sub(1);
    let thumb_offset = if last_line == 0 {
        0
    } else {
        (tab.editor.scroll_line().min(last_line).saturating_mul(travel as usize) / last_line)
            as u16
    };
    for y in track.y.saturating_add(thumb_offset)
        ..track.y.saturating_add(thumb_offset).saturating_add(thumb_height)
    {
        let cell = buf.get_mut(track.x, y);
        cell.symbol = "#".into();
        cell.style = Style::default().fg(theme.accent).bg(theme.surface);
    }
    layout.hits.push(HitRegion {
        rect: track,
        target: HitTarget::FileScrollbar(pane_id),
    });
}

fn byte_offset_for_scalar_column(text: &str, column: usize) -> usize {
    text.char_indices()
        .nth(column)
        .map(|(offset, _)| offset)
        .unwrap_or(text.len())
}

fn file_byte_is_selected(selection: Option<&std::ops::Range<usize>>, byte_offset: usize) -> bool {
    selection.is_some_and(|selection| selection.contains(&byte_offset))
}

fn syntax_style_for_column(
    spans: &[crate::text_editor::SyntaxSpan],
    syntax_index: &mut usize,
    column: usize,
    theme: Theme,
) -> Style {
    use crate::text_editor::SyntaxClass;

    while spans
        .get(*syntax_index)
        .is_some_and(|span| span.end_column <= column)
    {
        *syntax_index += 1;
    }
    let class = spans
        .get(*syntax_index)
        .filter(|span| span.start_column <= column && column < span.end_column)
        .map(|span| span.class)
        .unwrap_or(SyntaxClass::Plain);
    match class {
        SyntaxClass::Plain => Style::default().fg(theme.text),
        SyntaxClass::Keyword => Style::default().fg(theme.accent).add_modifier(Modifier::BOLD),
        SyntaxClass::String => Style::default().fg(theme.green),
        SyntaxClass::Number | SyntaxClass::Boolean => Style::default().fg(theme.yellow),
        SyntaxClass::Comment => Style::default().fg(theme.muted),
        SyntaxClass::Heading => Style::default().fg(theme.accent).add_modifier(Modifier::BOLD),
        SyntaxClass::Emphasis => Style::default().fg(theme.teal),
        SyntaxClass::Key => Style::default().fg(theme.teal).add_modifier(Modifier::BOLD),
        SyntaxClass::Punctuation => Style::default().fg(theme.dim),
    }
}

fn render_workspace_file_history(
    tab: &WorkspaceGitTabView,
    pane_id: PaneId,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    spinner: char,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.surface, buf);
    match &tab.state {
        WorkspaceGitState::Loading => {
            Paragraph::new(format!(" {spinner} loading file history..."))
                .style(Style::default().fg(theme.muted).bg(theme.surface))
                .render(area, buf);
            return;
        }
        WorkspaceGitState::Error(message) => {
            Paragraph::new(format!(" x {message}"))
                .style(Style::default().fg(theme.red).bg(theme.surface))
                .render(area, buf);
            return;
        }
        WorkspaceGitState::Ready => {}
    }

    if tab.mode == WorkspaceGitPaneMode::List {
        let footer_height = usize::from(area.height > 1);
        let capacity = area.height as usize - footer_height;
        let start = tab.list_scroll.min(tab.commits.len().saturating_sub(capacity));
        for (visible, (index, commit)) in tab
            .commits
            .iter()
            .enumerate()
            .skip(start)
            .take(capacity)
            .enumerate()
        {
            let short_id = &commit.id[..commit.id.len().min(8)];
            let label = format!(" {short_id} {}", commit.subject);
            let row = Rect::new(area.x, area.y + visible as u16, area.width, 1);
            Paragraph::new(truncate_cells(&label, area.width as usize))
                .style(
                    Style::default()
                        .fg(theme.text)
                        .bg(if index == tab.selected { theme.active } else { theme.surface }),
                )
                .render(row, buf);
            layout.hits.push(HitRegion {
                rect: row,
                target: HitTarget::FileHistoryCommit(pane_id, index),
            });
        }
        if tab.commits.is_empty() && capacity > 0 {
            Paragraph::new(" no commits found for this file")
                .style(Style::default().fg(theme.muted).bg(theme.surface))
                .render(Rect::new(area.x, area.y, area.width, 1), buf);
        }
        if footer_height > 0 {
            let footer = if tab.has_more {
                " Up/Down select | Enter open | l older "
            } else {
                " Up/Down select | Enter open "
            };
            Paragraph::new(truncate_cells(footer, area.width as usize))
                .style(Style::default().fg(theme.teal).bg(theme.active))
                .render(Rect::new(area.x, area.bottom() - 1, area.width, 1), buf);
        }
        return;
    }

    let lines = git_detail_lines(tab, spinner);
    let maximum_scroll = lines.len().saturating_sub(area.height as usize);
    let detail_scroll = tab.detail_scroll.min(maximum_scroll);
    for (row, line) in lines
        .iter()
        .skip(detail_scroll)
        .take(area.height as usize)
        .enumerate()
    {
        let style = git_detail_line_style(line.kind, theme);
        let row_area = Rect::new(area.x, area.y + row as u16, area.width, 1);
        fill_rect(row_area, style.bg, buf);
        Paragraph::new(truncate_cells(&line.text, row_area.width as usize))
            .style(style)
            .render(row_area, buf);
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GitDetailLineKind {
    Metadata,
    Summary,
    Added,
    Deleted,
    Hunk,
    DiffMeta,
    Context,
    Error,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct GitDetailLine {
    text: String,
    kind: GitDetailLineKind,
}

fn git_detail_lines(tab: &WorkspaceGitTabView, spinner: char) -> Vec<GitDetailLine> {
    let mut lines = Vec::new();
    if let Some(commit) = tab.commits.get(tab.selected) {
        for text in [
            format!("Commit: {}", commit.id),
            format!("Message: {}", commit.subject),
        ] {
            lines.push(GitDetailLine { text, kind: GitDetailLineKind::Metadata });
        }
        if !commit.parents.is_empty() {
            lines.push(GitDetailLine {
                text: format!(
                    "Parents: {}",
                    commit
                        .parents
                        .iter()
                        .map(|parent| &parent[..parent.len().min(12)])
                        .collect::<Vec<_>>()
                        .join(" ")
                ),
                kind: GitDetailLineKind::Metadata,
            });
        }
        for text in [
            format!("Author: {} <{}>", commit.author_name, commit.author_email),
            format!("Author date: {}", commit.authored_at),
            format!("Committer: {} <{}>", commit.committer_name, commit.committer_email),
            format!("Commit date: {}", commit.committed_at),
            format!(
                "Signature: {}{}",
                commit.signature_status,
                commit
                    .signer
                    .as_ref()
                    .map_or(String::new(), |signer| format!(" ({signer})")),
            ),
        ] {
            lines.push(GitDetailLine { text, kind: GitDetailLineKind::Metadata });
        }
        lines.push(GitDetailLine { text: String::new(), kind: GitDetailLineKind::Context });
    }
    if let Some(error) = tab.diff_error.as_ref() {
        lines.push(GitDetailLine {
            text: format!("x {error}"),
            kind: GitDetailLineKind::Error,
        });
    } else if let Some(diff) = tab.diff.as_ref() {
        let stats = git_diff_stats(&diff.text);
        lines.push(GitDetailLine {
            text: format!(
                "Summary: {} file{} | +{} -{} | {} bytes{}",
                stats.files,
                if stats.files == 1 { "" } else { "s" },
                stats.added,
                stats.deleted,
                diff.byte_len,
                if diff.truncated { " | truncated" } else { "" },
            ),
            kind: GitDetailLineKind::Summary,
        });
        lines.push(GitDetailLine {
            text: format!("Diff: {}", git_diff_target_label(&diff.target)),
            kind: GitDetailLineKind::DiffMeta,
        });
        lines.extend(diff.text.lines().map(|text| GitDetailLine {
            text: text.to_owned(),
            kind: git_diff_line_kind(text),
        }));
    } else if let Some(target) = tab.pending_diff.as_ref() {
        lines.push(GitDetailLine {
            text: format!("{spinner} loading diff {}...", git_diff_target_label(target)),
            kind: GitDetailLineKind::Metadata,
        });
    }
    lines
}

fn git_diff_line_kind(line: &str) -> GitDetailLineKind {
    if line.starts_with("+++") || line.starts_with("---") || is_git_diff_meta(line) {
        GitDetailLineKind::DiffMeta
    } else if line.starts_with('+') {
        GitDetailLineKind::Added
    } else if line.starts_with('-') {
        GitDetailLineKind::Deleted
    } else if line.starts_with("@@") {
        GitDetailLineKind::Hunk
    } else {
        GitDetailLineKind::Context
    }
}

fn is_git_diff_meta(line: &str) -> bool {
    [
        "diff --git ",
        "index ",
        "new file mode ",
        "deleted file mode ",
        "old mode ",
        "new mode ",
        "similarity index ",
        "dissimilarity index ",
        "rename from ",
        "rename to ",
        "copy from ",
        "copy to ",
        "Binary files ",
        "\\ No newline at end of file",
    ]
    .iter()
    .any(|prefix| line.starts_with(prefix))
}

fn git_detail_line_style(kind: GitDetailLineKind, theme: Theme) -> Style {
    match kind {
        GitDetailLineKind::Metadata => Style::default().fg(theme.muted).bg(theme.surface),
        GitDetailLineKind::Summary => Style::default()
            .fg(theme.teal)
            .bg(theme.active)
            .add_modifier(Modifier::BOLD),
        GitDetailLineKind::Added => Style::default().fg(theme.green).bg(theme.diff_added),
        GitDetailLineKind::Deleted => Style::default().fg(theme.red).bg(theme.diff_deleted),
        GitDetailLineKind::Hunk => Style::default()
            .fg(theme.teal)
            .bg(theme.diff_hunk)
            .add_modifier(Modifier::BOLD),
        GitDetailLineKind::DiffMeta => Style::default().fg(theme.muted).bg(theme.diff_meta),
        GitDetailLineKind::Context => Style::default().fg(theme.text).bg(theme.surface),
        GitDetailLineKind::Error => Style::default().fg(theme.red).bg(theme.surface),
    }
}

fn render_workspace_git_tab(
    tab: &WorkspaceGitTabView,
    pane_id: PaneId,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    spinner: char,
    harness_origin: bool,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    fill_rect(area, theme.surface, buf);
    match &tab.state {
        WorkspaceGitState::Loading => {
            Paragraph::new(format!(" {spinner} loading Git history..."))
                .style(Style::default().fg(theme.muted).bg(theme.surface))
                .render(area, buf);
            return;
        }
        WorkspaceGitState::Error(message) => {
            Paragraph::new(format!(" x {message}"))
                .style(Style::default().fg(theme.red).bg(theme.surface))
                .render(area, buf);
            return;
        }
        WorkspaceGitState::Ready => {}
    }
    if tab.mode == WorkspaceGitPaneMode::List {
        let capacity = area.height.saturating_sub(1) as usize;
        let start = tab.list_scroll.min(tab.commits.len().saturating_sub(capacity));
        for (visible, (index, commit)) in tab
            .commits
            .iter()
            .enumerate()
            .skip(start)
            .take(capacity)
            .enumerate()
        {
            let label = format!(" {} {}", &commit.id[..commit.id.len().min(8)], commit.subject);
            let row = Rect::new(area.x, area.y + visible as u16, area.width, 1);
            Paragraph::new(truncate_cells(&label, area.width as usize))
                .style(Style::default().fg(theme.text).bg(if index == tab.selected { theme.active } else { theme.surface }))
                .render(row, buf);
            layout.hits.push(HitRegion {
                rect: row,
                target: if harness_origin {
                    HitTarget::HarnessGitCommit(pane_id, index)
                } else {
                    HitTarget::GitCommit(pane_id, index)
                },
            });
        }
        let footer = if harness_origin && tab.history_truncated && tab.has_more {
            " history truncated | Up/Down select | Enter open | Load more: l older "
        } else if harness_origin && tab.history_truncated {
            " history truncated | no continuation cursor "
        } else if harness_origin && tab.has_more {
            " Up/Down select | Enter open | w working | s staged | Load more: l older "
        } else if tab.has_more {
            " Up/Down select | Enter open | w working | s staged | l older "
        } else {
            " Up/Down select | Enter open | w working | s staged "
        };
        Paragraph::new(truncate_cells(footer, area.width as usize))
            .style(Style::default().fg(theme.teal).bg(theme.active))
            .render(Rect::new(area.x, area.bottom() - 1, area.width, 1), buf);
        return;
    }

    let detail_height = area.height.saturating_sub(1);
    let details = Rect::new(area.x, area.y, area.width, detail_height);
    let lines = git_detail_lines(tab, spinner);
    let maximum_scroll = lines.len().saturating_sub(details.height as usize);
    let detail_scroll = tab.detail_scroll.min(maximum_scroll);
    for (row, line) in lines.iter().skip(detail_scroll).take(details.height as usize).enumerate() {
        let row_area = Rect::new(details.x, details.y + row as u16, details.width, 1);
        let style = git_detail_line_style(line.kind, theme);
        fill_rect(row_area, style.bg, buf);
        Paragraph::new(truncate_cells(&line.text, details.width as usize))
            .style(style)
            .render(row_area, buf);
    }
    if area.height > 0 {
        let footer = " [Back] Esc/Backspace | Up/Down scroll | Left/Right commit | PgUp/PgDn ";
        let footer_area = Rect::new(area.x, area.bottom() - 1, area.width, 1);
        Paragraph::new(truncate_cells(footer, area.width as usize))
            .style(Style::default().fg(theme.teal).bg(theme.active))
            .render(footer_area, buf);
        let back_width = 7.min(area.width);
        layout.hits.push(HitRegion {
            rect: Rect::new(area.x + 1.min(area.width.saturating_sub(1)), footer_area.y, back_width, 1),
            target: if harness_origin {
                HitTarget::HarnessGitBack(pane_id)
            } else {
                HitTarget::GitBack(pane_id)
            },
        });
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct GitDiffStats {
    files: usize,
    added: usize,
    deleted: usize,
}

fn git_diff_stats(text: &str) -> GitDiffStats {
    let mut stats = GitDiffStats::default();
    for line in text.lines() {
        if line.starts_with("diff --git ") {
            stats.files = stats.files.saturating_add(1);
        } else if line.starts_with('+') && !line.starts_with("+++") {
            stats.added = stats.added.saturating_add(1);
        } else if line.starts_with('-') && !line.starts_with("---") {
            stats.deleted = stats.deleted.saturating_add(1);
        }
    }
    stats
}

fn git_diff_target_label(target: &crate::app::WorkspaceGitDiffTarget) -> String {
    use crate::app::WorkspaceGitDiffTarget;

    let path_suffix = |path: &Option<gate4agent_node_protocol::RepositoryPath>| {
        path.as_ref()
            .map(|path| format!(" | {}", path.display_text()))
            .unwrap_or_default()
    };
    match target {
        WorkspaceGitDiffTarget::Working { path } => {
            format!("working tree{}", path_suffix(path))
        }
        WorkspaceGitDiffTarget::Staged { path } => format!("staged{}", path_suffix(path)),
        WorkspaceGitDiffTarget::Commit { revision, path } => format!(
            "commit {}{}",
            &revision[..revision.len().min(12)],
            path_suffix(path),
        ),
    }
}

fn render_preview_tab(
    tab: &PreviewTabView,
    pane_id: PaneId,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
    activity_spinner: char,
    tier: RailIcons,
    family: IconFamily,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let skin = ProviderPreviewSkin::for_provider(tab.provider.as_str());
    fill_rect(area, theme.surface, buf);
    let lines = native_agent_chat_lines(tab, area.width as usize, activity_spinner);
    let resume_available = preview_resume_available(tab);
    let action_height = usize::from(resume_available && area.height > 1);
    let summary_height = usize::from(area.height as usize > action_height);
    let capacity = area.height as usize - action_height - summary_height;
    let maximum_start = lines.len().saturating_sub(capacity);
    let start = if tab.scroll > maximum_start {
        maximum_start.saturating_sub(usize::MAX.saturating_sub(tab.scroll))
    } else {
        tab.scroll
    };
    if summary_height > 0 {
        let visible_end = start.saturating_add(capacity).min(lines.len());
        let position = if lines.is_empty() || capacity == 0 {
            String::new()
        } else {
            format!(" | lines {}-{}/{}", start.saturating_add(1), visible_end, lines.len())
        };
        let summary = format!(" read-only | {}{}", preview_history_summary(tab), position);
        Paragraph::new(truncate_cells(&summary, area.width as usize))
            .style(Style::default().fg(theme.muted).bg(theme.active))
            .render(Rect::new(area.x, area.y, area.width, 1), buf);
    }
    for (row, line) in lines.iter().skip(start).take(capacity).enumerate() {
        let rect = Rect::new(
            area.x,
            area.y + summary_height as u16 + row as u16,
            area.width,
            1,
        );
        let (marker_style, text_style) = match line.kind {
            NativeAgentChatLineKind::User => (
                Style::default().fg(theme.teal).bg(theme.surface).add_modifier(Modifier::BOLD),
                Style::default().fg(theme.text).bg(theme.surface),
            ),
            NativeAgentChatLineKind::Assistant => (
                Style::default().fg(skin.accent(theme)).bg(theme.surface).add_modifier(Modifier::BOLD),
                Style::default().fg(theme.text).bg(theme.surface),
            ),
            NativeAgentChatLineKind::Error => (
                Style::default().fg(theme.red).bg(theme.surface).add_modifier(Modifier::BOLD),
                Style::default().fg(theme.red).bg(theme.surface),
            ),
            NativeAgentChatLineKind::Status => (
                Style::default().fg(skin.accent(theme)).bg(theme.surface),
                Style::default().fg(theme.dim).bg(theme.surface),
            ),
            NativeAgentChatLineKind::Empty => (
                Style::default().fg(theme.muted).bg(theme.surface),
                Style::default().fg(theme.muted).bg(theme.surface),
            ),
            NativeAgentChatLineKind::Gap => (
                Style::default().bg(theme.surface),
                Style::default().bg(theme.surface),
            ),
        };
        let marker_width = cell_width(&line.marker);
        let text_width = (area.width as usize).saturating_sub(marker_width);
        Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![
            Span::styled(line.marker.clone(), marker_style),
            Span::styled(truncate_cells(&line.text, text_width), text_style),
        ])]))
        .style(Style::default().bg(theme.surface))
        .render(rect, buf);
    }
    if action_height > 0 {
        // The ascii_label keeps choosing between the long/short bracketed
        // text exactly as before -- that is what `RailIcons::Ascii` still
        // paints unchanged. `RailIcons::Sixel` draws the icon alone (no
        // trailing "session" word any more, see `render_compact_icon_
        // button`'s own doc comment), so it needs no separate short-icon
        // variant the way the ascii text needed a shorter literal.
        let ascii_label = if area.width as usize >= cell_width("[Resume session]") {
            "[Resume session]"
        } else {
            "[Resume]"
        };
        let width = compact_icon_button_width(ascii_label, tier).min(area.width);
        let footer = Rect::new(
            area.x,
            area.bottom().saturating_sub(1),
            area.width,
            1,
        );
        fill_rect(footer, theme.active, buf);
        let hint_width = area.width.saturating_sub(width);
        if hint_width > 0 {
            Paragraph::new(truncate_cells(
                " read-only transcript | Up/Down scroll | Home/End ",
                hint_width as usize,
            ))
            .style(Style::default().fg(theme.muted).bg(theme.active))
            .render(Rect::new(area.x, footer.y, hint_width, 1), buf);
        }
        let rect = Rect::new(
            area.right().saturating_sub(width),
            area.bottom().saturating_sub(1),
            width,
            1,
        );
        render_compact_icon_button(
            rect,
            icons::IconId::Play,
            ascii_label,
            Style::default().fg(theme.teal).bg(theme.active).add_modifier(Modifier::BOLD),
            tier, family,
            buf,
            layout,
        );
        layout.hits.push(HitRegion {
            rect,
            target: HitTarget::PreviewResume(pane_id),
        });
    }
}

fn preview_history_summary(tab: &PreviewTabView) -> String {
    match &tab.preview {
        NativeSessionPreviewState::Loading => "loading bounded history".to_owned(),
        NativeSessionPreviewState::Unavailable(_) => "history unavailable".to_owned(),
        NativeSessionPreviewState::Error(_) => "history failed".to_owned(),
        NativeSessionPreviewState::Ready(preview)
        | NativeSessionPreviewState::Empty(preview) => {
            let visible = preview.messages.len();
            let messages = if preview.message_count_exact {
                if preview.truncated || visible < preview.message_count as usize {
                    format!("latest {visible} of {} messages", preview.message_count)
                } else {
                    format!("{} messages", preview.message_count)
                }
            } else {
                format!("latest {visible} messages; total incomplete")
            };
            let turns = preview
                .completed_turn_count
                .map(|count| format!(" | {count} completed turns"))
                .unwrap_or_default();
            let tokens = preview
                .total_tokens
                .map(|count| count.to_string())
                .unwrap_or_else(|| "unknown".to_owned());
            format!("{messages}{turns} | total tokens {tokens}")
        }
    }
}

fn preview_resume_available(tab: &PreviewTabView) -> bool {
    tab.resume_available
        && provider_supports_native_resume(&tab.provider)
        && tab.phase == PreviewTabPhase::Hydrated
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NativeAgentChatLineKind {
    User,
    Assistant,
    Error,
    Status,
    Empty,
    Gap,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct NativeAgentChatLine {
    marker: String,
    text: String,
    kind: NativeAgentChatLineKind,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProviderPreviewSkin {
    Claude,
    Codex,
    Kimi,
    Grok,
    Generic,
}

impl ProviderPreviewSkin {
    fn for_provider(provider: &str) -> Self {
        match provider {
            "claude" => Self::Claude,
            "codex" => Self::Codex,
            "kimi" => Self::Kimi,
            "grok" => Self::Grok,
            _ => Self::Generic,
        }
    }

    fn name(self) -> &'static str {
        match self {
            Self::Claude => "CLAUDE",
            Self::Codex => "CODEX",
            Self::Kimi => "KIMI",
            Self::Grok => "GROK",
            Self::Generic => "SESSION",
        }
    }

    fn assistant_label(self) -> &'static str {
        match self {
            Self::Claude => "CLAUDE",
            Self::Codex => "CODEX",
            Self::Kimi => "KIMI",
            Self::Grok => "GROK",
            Self::Generic => "AGENT",
        }
    }

    fn accent(self, theme: Theme) -> Color {
        match self {
            Self::Claude => theme.yellow,
            Self::Codex => theme.green,
            Self::Kimi => theme.teal,
            Self::Grok => theme.text,
            Self::Generic => theme.muted,
        }
    }

}

fn native_agent_chat_lines(
    tab: &PreviewTabView,
    width: usize,
    activity_spinner: char,
) -> Vec<NativeAgentChatLine> {
    let width = width.max(1);
    let mut lines = Vec::new();
    match &tab.preview {
        NativeSessionPreviewState::Loading => push_agent_status(
            &mut lines,
            &format!("{activity_spinner} Loading session…"),
            width,
        ),
        NativeSessionPreviewState::Unavailable(reason) => {
            push_agent_error(&mut lines, &format!("Session unavailable: {reason}"), width)
        }
        NativeSessionPreviewState::Error(message) => {
            push_agent_error(&mut lines, &format!("Session failed: {message}"), width)
        }
        NativeSessionPreviewState::Ready(preview)
        | NativeSessionPreviewState::Empty(preview) => {
            for message in &preview.messages {
                push_agent_turn(
                    &mut lines,
                    &message.role,
                    &message.text,
                    width,
                    ProviderPreviewSkin::for_provider(tab.provider.as_str()),
                );
            }
            if preview.messages.is_empty() {
                lines.push(NativeAgentChatLine {
                    marker: "  ".to_owned(),
                    text: "No conversation turns yet.".to_owned(),
                    kind: NativeAgentChatLineKind::Empty,
                });
            }
        }
    }
    match tab.phase {
        PreviewTabPhase::Hydrated => {}
        PreviewTabPhase::Indexing => push_agent_status(
            &mut lines,
            &format!("{activity_spinner} Linking session…"),
            width,
        ),
        PreviewTabPhase::Resuming => push_agent_status(
            &mut lines,
            &format!("{activity_spinner} Reconnecting session…"),
            width,
        ),
    }
    if let Some(message) = tab.reconnect_error.as_deref() {
        push_agent_error(&mut lines, message, width);
    }
    lines
}

fn push_agent_turn(
    lines: &mut Vec<NativeAgentChatLine>,
    role: &str,
    text: &str,
    width: usize,
    skin: ProviderPreviewSkin,
) {
    let normalized = role.trim().to_ascii_lowercase();
    if normalized == "user" {
        let marker = transcript_marker("YOU", width);
        let continuation = " ".repeat(cell_width(&marker));
        let wrapped = wrap_preview_text(text, width.saturating_sub(cell_width(&marker)).max(1));
        for (index, line) in wrapped.into_iter().enumerate() {
            lines.push(NativeAgentChatLine {
                marker: if index == 0 { marker.clone() } else { continuation.clone() },
                text: line,
                kind: NativeAgentChatLineKind::User,
            });
        }
    } else if normalized == "assistant" {
        let label = transcript_marker(skin.assistant_label(), width);
        let continuation = " ".repeat(cell_width(&label));
        let wrapped = wrap_preview_text(text, width.saturating_sub(cell_width(&label)).max(1));
        for (index, line) in wrapped.into_iter().enumerate() {
            lines.push(NativeAgentChatLine {
                marker: if index == 0 { label.clone() } else { continuation.clone() },
                text: line,
                kind: NativeAgentChatLineKind::Assistant,
            });
        }
    } else {
        return;
    }
    lines.push(NativeAgentChatLine {
        marker: String::new(),
        text: String::new(),
        kind: NativeAgentChatLineKind::Gap,
    });
}

fn transcript_marker(label: &str, width: usize) -> String {
    if width >= 12 {
        format!("{label:<9} ")
    } else {
        format!("{} ", label.chars().next().unwrap_or('?'))
    }
}

fn push_agent_error(lines: &mut Vec<NativeAgentChatLine>, text: &str, width: usize) {
    let marker = transcript_marker("ERROR", width);
    let continuation = " ".repeat(cell_width(&marker));
    for (index, line) in wrap_preview_text(
        text,
        width.saturating_sub(cell_width(&marker)).max(1),
    )
        .into_iter()
        .enumerate()
    {
        lines.push(NativeAgentChatLine {
            marker: if index == 0 { marker.clone() } else { continuation.clone() },
            text: line,
            kind: NativeAgentChatLineKind::Error,
        });
    }
}

fn push_agent_status(lines: &mut Vec<NativeAgentChatLine>, text: &str, width: usize) {
    if !lines.is_empty() && !matches!(lines.last().map(|line| line.kind), Some(NativeAgentChatLineKind::Gap)) {
        lines.push(NativeAgentChatLine {
            marker: String::new(),
            text: String::new(),
            kind: NativeAgentChatLineKind::Gap,
        });
    }
    lines.push(NativeAgentChatLine {
        marker: transcript_marker("STATUS", width),
        text: text.to_owned(),
        kind: NativeAgentChatLineKind::Status,
    });
}

fn split_surface_rect(area: Rect, axis: SplitAxis, ratio_bps: u16) -> (Rect, Rect, Rect) {
    let extent = match axis {
        SplitAxis::Horizontal => area.width,
        SplitAxis::Vertical => area.height,
    };
    if extent < 3 {
        return (area, Rect::default(), Rect::default());
    }
    let usable = extent - 1;
    let first_extent = ((u32::from(usable) * u32::from(ratio_bps.min(10_000))) / 10_000)
        .clamp(1, u32::from(usable - 1)) as u16;
    let second_extent = usable - first_extent;
    match axis {
        SplitAxis::Horizontal => (
            Rect::new(area.x, area.y, first_extent, area.height),
            Rect::new(area.x + first_extent, area.y, 1, area.height),
            Rect::new(area.x + first_extent + 1, area.y, second_extent, area.height),
        ),
        SplitAxis::Vertical => (
            Rect::new(area.x, area.y, area.width, first_extent),
            Rect::new(area.x, area.y + first_extent, area.width, 1),
            Rect::new(area.x, area.y + first_extent + 1, area.width, second_extent),
        ),
    }
}

fn draw_surface_divider(
    divider: Rect,
    axis: SplitAxis,
    buf: &mut TerminalBuffer,
    theme: Theme,
) {
    for row in divider.y..divider.bottom() {
        for column in divider.x..divider.right() {
            let cell = buf.get_mut(column, row);
            cell.symbol = match axis {
                SplitAxis::Horizontal => "|".into(),
                SplitAxis::Vertical => "-".into(),
            };
            cell.style = Style::default().fg(theme.border).bg(theme.surface);
        }
    }
}

/// Cursor blink cadence expressed in shimmer ticks (`SHIMMER_TICK_MILLIS`
/// = 72ms each): `8 * 72 = 576ms` per half-cycle, close to the ~530ms
/// on/off period most terminals default a block cursor to. Deliberately
/// rides the crate's ALREADY-existing free-running tick source
/// (`wall_clock_millis` + `shimmer::shimmer_tick_for_millis` -- the same
/// pair the status bar's shimmer effect and `PetFigure::blink_frame_index`
/// both already read) instead of starting a second timer just for this.
const CURSOR_BLINK_HALF_PERIOD_TICKS: u64 = 8;

/// Renders one PTY panel: the live screen plus however much scrollback is
/// scrolled into view, then the selection overlay, then (focused panel,
/// not scrolled back) the blinking cursor block.
///
/// The live screen and every visible scrollback row are vt100 PROJECTIONS
/// -- parsing ANSI bytes into a cell grid -- and that work is cached on
/// `cache` (session-identity + geometry + input-bytes + color-mode keyed;
/// see `pty_render_cache`'s own module doc comment for why reusing rather
/// than reparsing is correct here). A frame where nothing changed for
/// this session does no vt100 work at all, just copies already-projected
/// cells into `buf`.
fn render_terminal(
    session: &SessionView,
    area: Rect,
    color_mode: PtyColorMode,
    scroll_offset: usize,
    selection: Option<&crate::app::TerminalSelection>,
    theme: Theme,
    buf: &mut TerminalBuffer,
    cache: &RefCell<PtyRenderCache>,
    focused: bool,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    if session.terminal_formatted.is_empty() && session.terminal_scrollback.is_empty() {
        return;
    }
    let mut cache = cache.borrow_mut();
    // Owned copy: the loop below also needs `&mut cache` (for
    // `project_row`), which could not coexist with a borrow of `current`
    // still pointing into `cache`. This is the SAME one full-screen buffer
    // the old per-frame code built from scratch every time, so it is not
    // a new cost -- only the (expensive) vt100 parse behind it is now
    // conditional.
    let current = cache
        .project_current(
            &session.address,
            &session.terminal_formatted,
            area.width,
            area.height,
            color_mode,
        )
        .clone();
    let history_len = session.terminal_scrollback.len();
    let scroll_offset = scroll_offset.min(history_len);
    let first_logical_row = history_len.saturating_sub(scroll_offset);
    for row in 0..area.height {
        let logical_row = first_logical_row.saturating_add(row as usize);
        let current_row = logical_row.saturating_sub(history_len) as u16;
        if logical_row < history_len {
            // Borrowed straight from `cache` and consumed cell-by-cell
            // within this one iteration -- never cloned as a whole row,
            // so a cached row costs this frame nothing but the same
            // per-cell copy a live (uncached) row would already need.
            let history_row = cache.project_row(
                &session.address,
                logical_row,
                &session.terminal_scrollback[logical_row],
                area.width,
                color_mode,
            );
            for column in 0..area.width {
                buf.set(area.x + column, area.y + row, history_row.get(column, 0).clone());
            }
        } else {
            for column in 0..area.width {
                let cell = if current_row < area.height {
                    current.get(column, current_row).clone()
                } else {
                    current.get(column, area.height.saturating_sub(1)).clone()
                };
                buf.set(area.x + column, area.y + row, cell);
            }
        }
    }
    drop(cache);
    if let Some(selection) = selection.filter(|selection| selection.address == session.address) {
        let (start, end) = if (selection.start.1, selection.start.0)
            <= (selection.end.1, selection.end.0)
        {
            (selection.start, selection.end)
        } else {
            (selection.end, selection.start)
        };
        for row in start.1..=end.1.min(area.height.saturating_sub(1)) {
            let from = if row == start.1 { start.0 } else { 0 };
            let to = if row == end.1 {
                end.0.saturating_add(1).min(area.width)
            } else {
                area.width
            };
            for column in from..to {
                let cell = buf.get_mut(area.x + column, area.y + row);
                cell.style = cell
                    .style
                    .fg(theme.active_tab_text)
                    .bg(theme.accent)
                    .add_modifier(Modifier::BOLD);
            }
        }
    }
    // Cursor: only the focused panel's own session (a hidden pane's cursor
    // would be a second, misleading blinking block elsewhere on screen),
    // and only when not scrolled into history (a cursor drawn into
    // scrollback would sit on text that no longer reflects where input
    // actually lands). The wire carries no cursor-visibility flag
    // (`gate4agent_types::control::TerminalFrame` has no such field, and
    // neither does the harness's own frame type it is built from) -- a
    // provider that hides its own cursor therefore cannot be honoured
    // here; this always paints the reported position when the above two
    // conditions hold and the blink phase is in its "on" half.
    if focused && scroll_offset == 0 {
        if let Some((cursor_row, cursor_column)) = session.terminal_cursor {
            let blink_visible = (shimmer::shimmer_tick_for_millis(wall_clock_millis())
                / CURSOR_BLINK_HALF_PERIOD_TICKS)
                % 2
                == 0;
            if blink_visible {
                let row = cursor_row.min(area.height.saturating_sub(1));
                let column = cursor_column.min(area.width.saturating_sub(1));
                let cell = buf.get_mut(area.x + column, area.y + row);
                // Invert whatever is already there rather than replacing
                // the symbol, so the character under the cursor stays
                // readable. XOR (not OR): a cell the PTY already marked
                // reverse-video must come back OUT of reverse for the
                // cursor to still read as visually distinct from its
                // surroundings.
                cell.style.modifiers ^= Modifier::REVERSE;
            }
        }
    }
}

fn render_existing_session(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(session) = &app.existing_session else {
        return;
    };
    let width = 112.min(area.width);
    let height = 24.min(area.height);
    let dialog = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::ExistingSession).copied());
    layout.existing_session_modal = dialog;
    layout.note_overlay(dialog);
    fill_rect(dialog, theme.modal, buf);
    Block::bordered()
        .title(if session.mode == ExistingSessionMode::Catalog && session.preview.is_some() {
            " native session details "
        } else {
            " existing sessions "
        })
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dialog, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(dialog.x, dialog.y, dialog.width, 1),
        target: HitTarget::ExistingSessionDrag,
    });
    render_modal_close(dialog, buf, layout, theme);
    if dialog.width < 3 || dialog.height < 3 {
        return;
    }
    let inner = Rect::new(dialog.x + 1, dialog.y + 1, dialog.width - 2, dialog.height - 2);
    match session.mode {
        ExistingSessionMode::Catalog => render_existing_session_catalog(
            session, inner, theme, buf, layout,
        ),
        ExistingSessionMode::AdvancedImport => render_existing_session_advanced(
            app, session, inner, theme, buf, layout,
        ),
    }
}

fn render_existing_session_catalog(
    session: &crate::app::ExistingSessionDialog,
    area: Rect,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    let buttons_row = area.height.saturating_sub(5);
    let message_height = usize::from(buttons_row.saturating_sub(6));
    let mut message_lines = Vec::new();
    match session.preview.as_ref() {
        Some(NativeSessionPreviewState::Ready(preview))
        | Some(NativeSessionPreviewState::Empty(preview)) => {
            let source = session.preview_record_id.as_deref().unwrap_or("native catalog");
            render_modal_line(
                format!("  Title       {}", preview.title.as_deref().unwrap_or(&session.display_name)),
                area, 0, Style::default().fg(theme.text).bg(theme.modal), buf,
            );
            render_modal_line(
                format!("  Source      {}", truncate_cells(source, area.width.saturating_sub(14) as usize)),
                area, 1, Style::default().fg(theme.dim).bg(theme.modal), buf,
            );
            render_modal_line(
                format!("  Modified    {}    Model  {}", preview.modified_at.as_deref().unwrap_or("-"), preview.model.as_deref().unwrap_or("-")),
                area, 2, Style::default().fg(theme.dim).bg(theme.modal), buf,
            );
            let message_summary = if preview.message_count_exact {
                if preview.truncated {
                    format!("last {} of {}", preview.messages.len(), preview.message_count)
                } else {
                    preview.message_count.to_string()
                }
            } else {
                format!("showing latest {}", preview.messages.len())
            };
            render_modal_line(
                format!("  Messages    {message_summary}    Completed turns  {}",
                    preview.completed_turn_count.map(|count| count.to_string()).unwrap_or_else(|| "-".to_owned())),
                area, 3, Style::default().fg(theme.dim).bg(theme.modal), buf,
            );
            for message in &preview.messages {
                message_lines.push((format!("{}:", message.role.to_uppercase()), true));
                for line in wrap_preview_text(&message.text, area.width.saturating_sub(4) as usize) {
                    message_lines.push((format!("  {line}"), false));
                }
            }
            if preview.messages.is_empty() {
                message_lines.push(("No user/assistant messages are available in this bounded preview.".to_owned(), false));
            }
        }
        Some(NativeSessionPreviewState::Loading) => {
            render_modal_line("  Loading bounded native session preview...", area, 2,
                Style::default().fg(theme.yellow).bg(theme.modal), buf);
        }
        Some(NativeSessionPreviewState::Unavailable(reason)) => {
            render_modal_line(format!("  Preview unavailable: {reason}"), area, 2,
                Style::default().fg(theme.yellow).bg(theme.modal), buf);
        }
        Some(NativeSessionPreviewState::Error(message)) => {
            render_modal_line(format!("  Preview or resume failed: {message}"), area, 2,
                Style::default().fg(theme.red).bg(theme.modal), buf);
        }
        None => {
            render_modal_line("  Select a Native session from the sidebar to inspect it.", area, 2,
                Style::default().fg(theme.muted).bg(theme.modal), buf);
        }
    }
    let start = session.preview_scroll.min(message_lines.len().saturating_sub(message_height));
    for (visible, (line, heading)) in message_lines.iter().skip(start).take(message_height).enumerate() {
        let style = if *heading {
            Style::default().fg(theme.teal).bg(theme.modal).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(theme.text).bg(theme.modal)
        };
        render_modal_line(line, area, 5 + visible as u16, style, buf);
    }
    if let Some(operation) = &session.operation {
        let phase = match operation {
            ExistingSessionOperation::IndexingOnly { .. } => "Index phase: saving exact provider session ID...",
            ExistingSessionOperation::IndexingForResume { .. } => "Native resume phase: indexing exact provider session ID...",
            ExistingSessionOperation::IndexingNativeForResume { .. } => "Native resume phase: linking selected history...",
            ExistingSessionOperation::Resuming { .. } => "Native resume phase: runtime admission / provider resume...",
        };
        render_modal_line(
            phase,
            area,
            buttons_row.saturating_sub(1),
            Style::default().fg(theme.yellow).bg(theme.modal),
            buf,
        );
    } else if let Some(message) = session.operation_error.as_deref() {
        render_modal_line(
            format!("Native resume failed: {message}"),
            area,
            buttons_row.saturating_sub(1),
            Style::default().fg(theme.red).bg(theme.modal),
            buf,
        );
    }
    render_existing_session_field(
        "Ask (not sent)",
        &session.ask_after_resume,
        session.field == ExistingSessionField::AskAfterResume,
        false,
        ExistingSessionField::AskAfterResume,
        area,
        buttons_row,
        theme,
        buf,
        layout,
    );
    let action_row = buttons_row.saturating_add(2);
    let can_resume = session.preview.as_ref().is_some_and(|preview| {
        matches!(preview, NativeSessionPreviewState::Ready(_) | NativeSessionPreviewState::Empty(_))
    }) && session.operation.is_none()
        && session.rows.get(session.selected).is_some_and(|row| {
            row.route.scope == gate4agent_types::NativeSessionCatalogScope::Workspace
                && provider_supports_native_resume(&row.route.provider)
        });
    let resume_label = "[Resume and open PTY]";
    let native_resume = Rect::new(area.x, area.y + action_row, 23.min(area.width), 1);
    Paragraph::new(resume_label)
        .style(if can_resume {
            Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(theme.muted).bg(theme.modal)
        })
        .render(native_resume, buf);
    if can_resume {
        push_modal_hit(layout, native_resume, HitTarget::ExistingSessionNativeResume);
    }
    let restore = Rect::new(native_resume.right().saturating_add(1), native_resume.y, 20.min(area.width), 1);
    Paragraph::new("[Restore via skill]")
        .style(Style::default().fg(theme.muted).bg(theme.modal))
        .render(restore, buf);
    push_modal_hit(layout, restore, HitTarget::ExistingSessionRestoreViaSkill);
    let advanced = Rect::new(restore.right().saturating_add(1), restore.y, 19.min(area.width), 1);
    Paragraph::new("[Advanced import]")
        .style(Style::default().fg(theme.teal).bg(theme.modal).add_modifier(Modifier::BOLD))
        .render(advanced, buf);
    push_modal_hit(layout, advanced, HitTarget::ExistingSessionAdvancedImport);
    let cancel = Rect::new(area.right().saturating_sub(6), native_resume.y, 6.min(area.width), 1);
    Paragraph::new("[Back]")
        .style(Style::default().fg(theme.text).bg(theme.active))
        .render(cancel, buf);
    push_modal_hit(layout, cancel, HitTarget::ExistingSessionBackToCatalog);
    let disabled_reason = session.rows.get(session.selected)
        .filter(|row| {
            row.route.scope != gate4agent_types::NativeSessionCatalogScope::Workspace
                || !provider_supports_native_resume(&row.route.provider)
        })
        .map(|row| {
            if row.route.scope == gate4agent_types::NativeSessionCatalogScope::Unregistered {
                "Preview available; register this project as a workspace to resume".to_owned()
            } else {
                format!(
                    "{} history and preview are available; native resume is not supported",
                    row.route.provider,
                )
            }
        })
        .unwrap_or_else(|| RESTORE_VIA_SKILL_DISABLED_REASON.to_owned());
    render_modal_line(
        disabled_reason,
        area,
        action_row + 2,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_modal_line(
        "Tab messages/query | Enter resumes and opens PTY; query is retained but not sent | Esc back",
        area,
        action_row + 3,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

fn render_existing_session_advanced(
    app: &App,
    session: &crate::app::ExistingSessionDialog,
    area: Rect,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    let node_value = node_route_value(app, &session.node_id);
    render_existing_session_field(
        "Node", &node_value, session.field == ExistingSessionField::Node, true,
        ExistingSessionField::Node, area, 0, theme, buf, layout,
    );
    render_existing_session_field(
        "Workspace", &session.workspace_id, session.field == ExistingSessionField::Workspace, true,
        ExistingSessionField::Workspace, area, 1, theme, buf, layout,
    );
    let provider = session.provider.to_string();
    render_existing_session_field(
        "Provider", &provider, session.field == ExistingSessionField::Provider, true,
        ExistingSessionField::Provider, area, 2, theme, buf, layout,
    );
    render_existing_session_field(
        "Display name",
        &session.display_name,
        session.field == ExistingSessionField::DisplayName,
        false,
        ExistingSessionField::DisplayName,
        area,
        4,
        theme,
        buf,
        layout,
    );
    render_existing_session_field(
        "Native session ID",
        &session.session_id,
        session.field == ExistingSessionField::SessionId,
        false,
        ExistingSessionField::SessionId,
        area,
        5,
        theme,
        buf,
        layout,
    );
    let import = Rect::new(area.right().saturating_sub(8), area.y + 8, 8.min(area.width), 1);
    Paragraph::new("[Import]")
        .style(Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD))
        .render(import, buf);
    push_modal_hit(layout, import, HitTarget::ExistingSessionImport);
    let back = Rect::new(area.x, import.y, 18.min(area.width), 1);
    Paragraph::new("[Back to sessions]")
        .style(Style::default().fg(theme.teal).bg(theme.modal).add_modifier(Modifier::BOLD))
        .render(back, buf);
    push_modal_hit(layout, back, HitTarget::ExistingSessionBackToCatalog);
    render_modal_line(
        "Advanced import indexes only an exact provider session ID; it does not copy raw messages or provider paths.",
        area,
        11,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_modal_line(
        "Tab fields | arrows select | Enter import | b back to sessions | Esc cancel",
        area,
        13,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

fn render_existing_session_field(
    label: &str,
    value: &str,
    active: bool,
    cycles: bool,
    field: ExistingSessionField,
    area: Rect,
    row: u16,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    let style = if active {
        Style::default()
            .fg(theme.active_tab_text)
            .bg(theme.accent)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(theme.text).bg(theme.modal)
    };
    let rendered_value = if cycles {
        format!("[< {value} >]")
    } else {
        format!("[ {value} ]")
    };
    let prefix = format!("{} {:<18} ", if active { ">" } else { " " }, label);
    let line = format!("{prefix}{rendered_value}");
    render_modal_line(line.clone(), area, row, style, buf);
    let line_width = (cell_width(&line) as u16).min(area.width);
    push_modal_hit(
        layout,
        Rect::new(area.x, area.y.saturating_add(row), line_width, 1),
        HitTarget::ExistingSessionField(field),
    );
    if cycles {
        let value_start = area.x.saturating_add(cell_width(&prefix) as u16);
        let left_x = value_start.saturating_add(1);
        let right_x = value_start
            .saturating_add(4)
            .saturating_add(cell_width(value) as u16);
        if left_x < area.right() {
            push_modal_hit(
                layout,
                Rect::new(left_x, area.y.saturating_add(row), 1, 1),
                HitTarget::ExistingSessionFieldPrevious(field),
            );
        }
        if right_x < area.right() {
            push_modal_hit(
                layout,
                Rect::new(right_x, area.y.saturating_add(row), 1, 1),
                HitTarget::ExistingSessionFieldNext(field),
            );
        }
    }
}

fn render_spawn(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(spawn) = &app.spawn else {
        return;
    };
    let width = 86.min(area.width);
    let height = 19.min(area.height);
    let dialog = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::Spawn).copied());
    layout.spawn_modal = dialog;
    layout.note_overlay(dialog);
    fill_rect(dialog, theme.modal, buf);
    Block::bordered()
        .title(" session lab / launch ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dialog, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(dialog.x, dialog.y, dialog.width, 1),
        target: HitTarget::SpawnDrag,
    });
    render_modal_close(dialog, buf, layout, theme);
    if dialog.width < 3 || dialog.height < 3 {
        return;
    }
    let inner = Rect::new(dialog.x + 1, dialog.y + 1, dialog.width - 2, dialog.height - 2);
    let node_choices = app.launch_field_choice_count(spawn, LaunchField::Node);
    let node_value = node_route_value(app, &spawn.node_id);
    render_launch_field(
        "Node",
        &node_value,
        spawn.field == LaunchField::Node,
        node_choices.is_some_and(|choices| choices > 1),
        LaunchField::Node,
        inner,
        0,
        theme,
        buf,
        layout,
    );
    let workspace_choices = app.launch_field_choice_count(spawn, LaunchField::Workspace);
    let workspace_field_end = render_launch_field(
        "Workspace",
        &spawn.workspace_id,
        spawn.field == LaunchField::Workspace,
        workspace_choices.is_some_and(|choices| choices > 1),
        LaunchField::Workspace,
        inner,
        1,
        theme,
        buf,
        layout,
    );
    render_inline_launch_icon_action(
        icons::IconId::Search,
        "[Browse\u{2026}]",
        workspace_field_end,
        inner,
        1,
        true,
        HitTarget::SpawnRegisterWorkspace,
        app.rail_icons, app.icon_family,
        theme,
        buf,
        layout,
    );
    let target_field_end = render_launch_field(
        "Git location",
        match spawn.target {
            LaunchTarget::ExistingWorkspace => "Existing workspace",
            LaunchTarget::NewLinkedWorktree => "New linked worktree",
            LaunchTarget::NewStandaloneRepository => "New standalone repository",
        },
        spawn.field == LaunchField::GitLocation,
        true,
        LaunchField::GitLocation,
        inner,
        2,
        theme,
        buf,
        layout,
    );
    render_inline_launch_icon_action(
        icons::IconId::RepoForked,
        "[Configure\u{2026}]",
        target_field_end,
        inner,
        2,
        spawn.target != LaunchTarget::ExistingWorkspace,
        HitTarget::SpawnConfigureGitLocation,
        app.rail_icons, app.icon_family,
        theme,
        buf,
        layout,
    );
    render_launch_field(
        "Provider",
        &spawn.provider.to_string(),
        spawn.field == LaunchField::Provider,
        true,
        LaunchField::Provider,
        inner,
        3,
        theme,
        buf,
        layout,
    );
    let bundle_choices = app.launch_field_choice_count(spawn, LaunchField::Delivery);
    let bundle_value = if spawn.bundle_id.is_empty() && bundle_choices == Some(1) {
        "none installed"
    } else if spawn.bundle_id.is_empty() {
        "none"
    } else {
        &spawn.bundle_id
    };
    render_launch_field(
        "Delivery",
        bundle_value,
        spawn.field == LaunchField::Delivery,
        bundle_choices.is_some_and(|choices| choices > 1),
        LaunchField::Delivery,
        inner,
        4,
        theme,
        buf,
        layout,
    );
    let context_available = app.spawn_context_available(spawn);
    render_launch_field(
        "Continue from",
        match (spawn.context_mode, context_available) {
            (LaunchContextMode::None, false) => "none (no exported pack)",
            (LaunchContextMode::None, true) => "none",
            (LaunchContextMode::ContextPack, _) => "context-pack",
        },
        spawn.field == LaunchField::ContinueFrom,
        context_available,
        LaunchField::ContinueFrom,
        inner,
        5,
        theme,
        buf,
        layout,
    );
    let launch = Rect::new(inner.right().saturating_sub(8), inner.y + 7, 8.min(inner.width), 1);
    Paragraph::new("[Launch]")
        .style(Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD))
        .render(launch, buf);
    push_modal_hit(layout, launch, HitTarget::SpawnLaunch);
    let cancel = Rect::new(launch.x.saturating_sub(9).max(inner.x), inner.y + 7, 8.min(inner.width), 1);
    Paragraph::new("[Cancel]")
        .style(Style::default().fg(theme.text).bg(theme.active))
        .render(cancel, buf);
    push_modal_hit(layout, cancel, HitTarget::SpawnCancel);
    render_modal_line(
        launch_field_help(spawn.field, spawn.target),
        inner,
        9,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_modal_line(
        "Enter configures new Git locations; Launch always starts an interactive PTY",
        inner,
        10,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_receipt(app, inner, 12, buf, theme);
}

fn launch_field_help(field: LaunchField, target: LaunchTarget) -> &'static str {
    match field {
        LaunchField::Node => "Connected machine that owns the CLI process, workspaces, Git operations, and delivery.",
        LaunchField::Workspace => "Registered project root on the selected Node where the session can start.",
        LaunchField::GitLocation if target == LaunchTarget::ExistingWorkspace => {
            "Use selected workspace: start directly in its current Git working tree."
        }
        LaunchField::GitLocation if target == LaunchTarget::NewLinkedWorktree => {
            "Configure the linked worktree; managed policy comes from the selected workspace."
        }
        LaunchField::GitLocation => "Configure a new standalone Git repository before launching in it.",
        LaunchField::Provider => "Installed CLI adapter to wrap; provider login remains outside Gate4Agent.",
        LaunchField::Delivery => {
            "Immutable skills/plugin package already installed on this Node; none installed means no delivery occurs."
        }
        LaunchField::ContinueFrom => {
            "Attach a same-Node exported ContextPack file; provider consumption is a separate explicit step."
        }
    }
}

fn render_launch_field(
    label: &str,
    value: &str,
    active: bool,
    cycles: bool,
    field: LaunchField,
    area: Rect,
    row: u16,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) -> u16 {
    let style = if active {
        Style::default()
            .fg(theme.active_tab_text)
            .bg(theme.accent)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(theme.text).bg(theme.modal)
    };
    let rendered_value = if cycles {
        format!("[< {value} >]")
    } else {
        format!("[ {value} ]")
    };
    let prefix = format!("{} {:<18} ", if active { ">" } else { " " }, label);
    let line = format!("{prefix}{rendered_value}");
    let line_width = (cell_width(&line) as u16).min(area.width);
    render_modal_line(
        line,
        area,
        row,
        style,
        buf,
    );
    push_modal_hit(
        layout,
        Rect::new(area.x, area.y.saturating_add(row), line_width, 1),
        HitTarget::SpawnField(field),
    );
    if cycles {
        let value_start = area.x.saturating_add(cell_width(&prefix) as u16);
        let left_x = value_start.saturating_add(1);
        let right_x = value_start
            .saturating_add(4)
            .saturating_add(cell_width(value) as u16);
        let right = area.right();
        if left_x < right {
            push_modal_hit(
                layout,
                Rect::new(left_x, area.y.saturating_add(row), 1, 1),
                HitTarget::SpawnFieldPrevious(field),
            );
        }
        if right_x < right {
            push_modal_hit(
                layout,
                Rect::new(right_x, area.y.saturating_add(row), 1, 1),
                HitTarget::SpawnFieldNext(field),
            );
        }
    }
    area.x.saturating_add(line_width)
}

/// Paints the Spawn dialog's own `[Browse…]`/`[Configure…]` action right
/// after a launch field's own value, as a compact icon in `RailIcons::
/// Sixel` mode or the original bracketed label unchanged in `RailIcons::
/// Ascii` mode -- see [`render_compact_icon_button`]'s own doc comment
/// for that split. Also SHRINKS the immediately-preceding field's own
/// already-pushed `HitRegion` width so the two never overlap: it scans
/// `layout.hits` in reverse for the most recent `SpawnField` hit on the
/// same row that starts before this action does, and clamps that hit's
/// width to end exactly where this action begins. That coupling reads
/// this action's OWN drawn width, so it stays correct however narrow the
/// icon body ends up relative to the label this replaced.
fn render_inline_launch_icon_action(
    icon: icons::IconId,
    ascii_label: &str,
    field_end: u16,
    area: Rect,
    row: u16,
    enabled: bool,
    target: HitTarget,
    tier: RailIcons,
    family: IconFamily,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    if row >= area.height || area.width == 0 {
        return;
    }
    let width = compact_icon_button_width(ascii_label, tier).min(area.width);
    let x = field_end
        .saturating_add(1)
        .min(area.right().saturating_sub(width));
    let action = Rect::new(x, area.y + row, width, 1);
    if let Some(field_hit) = layout.hits.iter_mut().rev().find(|hit| {
        matches!(hit.target, HitTarget::SpawnField(_))
            && hit.rect.y == action.y
            && hit.rect.x < action.x
    }) {
        field_hit.rect.width = action.x.saturating_sub(field_hit.rect.x);
    }
    let style = Style::default()
        .fg(if enabled { theme.teal } else { theme.muted })
        .bg(theme.modal)
        .add_modifier(Modifier::BOLD);
    render_compact_icon_button(action, icon, ascii_label, style, tier, family, buf, layout);
    if enabled {
        push_modal_hit(layout, action, target);
    }
}

fn render_history(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(history) = &app.history else {
        return;
    };
    let width = 96.min(area.width.saturating_sub(4));
    let height = 22.min(area.height.saturating_sub(2));
    let dialog = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::History).copied());
    layout.history_modal = dialog;
    layout.note_overlay(dialog);
    fill_rect(dialog, theme.modal, buf);
    Block::bordered()
        .title(" native session history ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(dialog, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(dialog.x, dialog.y, dialog.width, 1),
        target: HitTarget::HistoryDrag,
    });
    render_modal_close(dialog, buf, layout, theme);
    if dialog.width < 3 || dialog.height < 3 {
        return;
    }
    let inner = Rect::new(dialog.x + 1, dialog.y + 1, dialog.width - 2, dialog.height - 2);
    render_modal_line(
        format!(
            "source provider={} address={}/{} #{}:{}",
            history.source_provider,
            history.source.node_id,
            history.source.workspace_id,
            history.source.instance_id,
            history.source.generation,
        ),
        inner,
        0,
        Style::default().fg(theme.text).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    render_modal_line(
        format!("source workspace={}", host_path_display(&history.source_workspace_root)),
        inner,
        1,
        Style::default().fg(theme.dim).bg(theme.modal),
        buf,
    );
    render_modal_line(
        format!("candidates ({})", history.candidates.len()),
        inner,
        2,
        Style::default().fg(theme.teal).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    let candidate_capacity = 5_usize;
    let selected = history.selected.min(history.candidates.len().saturating_sub(1));
    let start = selected.saturating_sub(candidate_capacity.saturating_sub(1));
    for (visible, (index, candidate)) in history
        .candidates
        .iter()
        .enumerate()
        .skip(start)
        .take(candidate_capacity)
        .enumerate()
    {
        let active = index == selected;
        let timestamp = candidate
            .modified_at_unix_ms
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unknown".to_owned());
        let style = if active {
            Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(theme.text).bg(theme.modal)
        };
        render_modal_line(
            format!(
                "{} id={} | hint={} | modified_unix_ms={timestamp}",
                if active { ">" } else { " " },
                candidate.id,
                candidate.session_id_hint,
            ),
            inner,
            3 + visible as u16,
            style,
            buf,
        );
    }
    let loaded = history.loaded.as_ref().map(|loaded| {
        format!(
            "loaded native_session_id={} message_count={} completed_turn_count={}",
            loaded.session_id,
            loaded.message_count,
            loaded.completed_turn_count.map(|count| count.to_string()).unwrap_or_else(|| "unknown".to_owned()),
        )
    }).unwrap_or_else(|| "loaded none".to_owned());
    render_modal_line(loaded, inner, 8, Style::default().fg(theme.green).bg(theme.modal), buf);
    if let Some(context) = history.context.as_ref() {
        render_modal_line(format!("exported context_id={}", context.id), inner, 9, Style::default().fg(theme.teal).bg(theme.modal), buf);
        render_modal_line(format!("exported digest={}", context.digest), inner, 10, Style::default().fg(theme.dim).bg(theme.modal), buf);
        render_modal_line(
            format!(
                "exported message_count={}/{} truncated={}",
                context.retained_message_count, context.source_message_count, context.truncated
            ),
            inner,
            11,
            Style::default().fg(theme.dim).bg(theme.modal),
            buf,
        );
    } else {
        render_modal_line("exported context none", inner, 9, Style::default().fg(theme.muted).bg(theme.modal), buf);
    }
    if let Some(pending) = history.pending_label.as_ref() {
        render_modal_line(format!("pending {pending}"), inner, 12, Style::default().fg(theme.yellow).bg(theme.modal), buf);
    }
    render_modal_line(
        "Enter load | x export | f forget exported context | Esc close",
        inner,
        13,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_receipt(app, inner, 15, buf, theme);
}

fn render_receipt(app: &App, area: Rect, start_row: u16, buf: &mut TerminalBuffer, theme: Theme) {
    let receipt = resolved_receipt(app);
    render_modal_line(
        if receipt.is_some() { "last resolved launch" } else { "last resolved launch none" },
        area,
        start_row.saturating_sub(1),
        Style::default().fg(theme.teal).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    let Some((receipt, managed_worktree)) = receipt else {
        return;
    };
    render_modal_line(
        format!(
            "provider={} mode={} workspace={} worktree={}",
            receipt.provider,
            session_mode_label(receipt.mode),
            receipt.target.workspace_id,
            receipt.target.worktree_id.as_ref().map(|id| id.as_str()).unwrap_or("current"),
        ),
        area,
        start_row,
        Style::default().fg(theme.text).bg(theme.modal),
        buf,
    );
    let environment = receipt.environment_profile.as_ref().map(|profile| {
        format!(" env={}@{}", profile.profile_id, profile.profile_revision)
    }).unwrap_or_default();
    let managed = managed_worktree.map(|lease| {
        let latest = app
            .last_managed_worktree_lease
            .as_ref()
            .filter(|latest| latest.lease_id == lease.lease_id)
            .unwrap_or(lease);
        format!(" managed={}@{}", latest.profile_id, latest.profile_revision)
    }).unwrap_or_default();
    render_modal_line(
        format!("profile={} revision={}{}{}", receipt.profile_id, receipt.profile_revision, environment, managed),
        area,
        start_row + 1,
        Style::default().fg(theme.dim).bg(theme.modal),
        buf,
    );
    if let Some(initial) = managed_worktree {
        let latest = app
            .last_managed_worktree_lease
            .as_ref()
            .filter(|lease| lease.lease_id == initial.lease_id)
            .unwrap_or(initial);
        let removed = app
            .last_managed_worktree_removed
            .as_deref()
            .is_some_and(|lease_id| lease_id == initial.lease_id.as_str());
        let failure = latest
            .cleanup_failure
            .map(managed_worktree_cleanup_failure_label)
            .unwrap_or("none");
        render_modal_line(
            format!(
                "worktree state={} sessions={} records={} failure={}",
                if removed { "removed" } else { managed_worktree_state_label(latest.state) },
                latest.active_session_count,
                latest.managed_record_count,
                failure,
            ),
            area,
            start_row + 2,
            Style::default().fg(theme.dim).bg(theme.modal),
            buf,
        );
    } else {
        render_modal_line(
            "worktree=none",
            area,
            start_row + 2,
            Style::default().fg(theme.dim).bg(theme.modal),
            buf,
        );
    }
    let bundle = receipt.bundle.as_ref().map(|bundle| {
        format!("bundle revision={} digest={}", bundle.revision, compact_digest(bundle.digest.as_str()))
    }).unwrap_or_else(|| "bundle=none".to_owned());
    render_modal_line(bundle, area, start_row + 3, Style::default().fg(theme.dim).bg(theme.modal), buf);
    let context = receipt.context.as_ref().map(|context| {
        format!(
            "ctx src={}/{}#{}:{}/{} digest={} count={}/{} cut={}",
            context.lineage.source_node_id,
            context.lineage.source_session.workspace_id,
            context.lineage.source_session.session.instance_id.0,
            context.lineage.source_session.session.generation.0,
            context.lineage.source_provider,
            compact_digest_hash(context.digest.as_str()),
            context.retained_message_count,
            context.source_message_count,
            context.truncated,
        )
    }).unwrap_or_else(|| "context=none".to_owned());
    render_modal_line(context, area, start_row + 4, Style::default().fg(theme.dim).bg(theme.modal), buf);
}

fn resolved_receipt(app: &App) -> Option<(&ResolvedSpawnReceipt, Option<&ManagedWorktreeLeaseSnapshot>)> {
    app.last_managed_spawn_receipt
        .as_ref()
        .map(|receipt| (&receipt.spawn, Some(&receipt.lease)))
        .or_else(|| app.last_spawn_receipt.as_ref().map(|receipt| (receipt, None)))
}

fn session_mode_label(mode: SessionMode) -> &'static str {
    match mode {
        SessionMode::Pty => "pty",
        SessionMode::Inline => "inline",
        SessionMode::Acp => "acp",
    }
}

fn managed_worktree_state_label(state: ManagedWorktreeLeaseState) -> &'static str {
    match state {
        ManagedWorktreeLeaseState::Allocating => "allocating",
        ManagedWorktreeLeaseState::Ready => "ready",
        ManagedWorktreeLeaseState::InUse => "in-use",
        ManagedWorktreeLeaseState::Retained => "retained",
        ManagedWorktreeLeaseState::CleanupBlocked => "cleanup-blocked",
        ManagedWorktreeLeaseState::RecoveryRequired => "recovery-required",
        ManagedWorktreeLeaseState::Removed => "removed",
    }
}

fn managed_worktree_cleanup_failure_label(failure: ManagedWorktreeCleanupFailure) -> &'static str {
    match failure {
        ManagedWorktreeCleanupFailure::Busy => "busy",
        ManagedWorktreeCleanupFailure::Dirty => "dirty",
        ManagedWorktreeCleanupFailure::Locked => "locked",
        ManagedWorktreeCleanupFailure::Prunable => "prunable",
        ManagedWorktreeCleanupFailure::OwnershipConflict => "ownership-conflict",
        ManagedWorktreeCleanupFailure::Backend => "backend",
    }
}

fn compact_digest(digest: &str) -> String {
    let keep = "sha256:".len() + 12;
    if digest.len() <= keep {
        digest.to_owned()
    } else {
        format!("{}...", &digest[..keep])
    }
}

fn compact_digest_hash(digest: &str) -> &str {
    digest
        .strip_prefix("sha256:")
        .unwrap_or(digest)
        .get(..8)
        .unwrap_or(digest)
}

fn render_modal_line(
    text: impl AsRef<str>,
    area: Rect,
    row: u16,
    style: Style,
    buf: &mut TerminalBuffer,
) {
    if row >= area.height {
        return;
    }
    Paragraph::new(truncate_cells(text.as_ref(), area.width as usize))
        .style(style)
        .render(Rect::new(area.x, area.y + row, area.width, 1), buf);
}

fn modal_row(area: Rect, row: u16) -> Rect {
    if row >= area.height {
        Rect::default()
    } else {
        Rect::new(area.x, area.y + row, area.width, 1)
    }
}

fn push_modal_hit(layout: &mut LayoutRects, rect: Rect, target: HitTarget) {
    if rect.width > 0 && rect.height > 0 {
        layout.hits.push(HitRegion { rect, target });
    }
}

/// The standard `[x]` close control every bordered modal/dialog in this
/// crate carries, drawn once here rather than reimplemented per modal --
/// the single shared place both this decoration and its hit region
/// (`HitTarget::ModalClose`, dispatched by `App::close_focused_modal`)
/// exist. Sits directly on `modal`'s own top border row, right-aligned
/// against the top-right corner (flush against it, so the border stays
/// visually continuous up to that corner glyph). Call once per modal,
/// right after that modal's own border is drawn -- and after any drag hit
/// region already covering that same row is pushed, so `App::click`'s
/// last-pushed-wins scan (`.iter().rev().find(...)`) picks the cross over
/// the drag region for that one cell.
///
/// Every modal/dialog surface in the crate calls this: `render_spawn`,
/// `render_existing_session`, `render_add_space`, `render_folder_browser`,
/// `render_create_worktree`, `render_create_workspace_entry`, `render_
/// remove_worktree`, `render_rename_session`, `render_task_id`, `render_
/// forget_session`, `render_history`, `render_settings` (covers BOTH the
/// small `MenuPlacement::Sidebar` "settings" popup and the expanded
/// `MenuPlacement::Modal` "control" modal -- both are the exact same
/// bordered `modal` rect this one fn draws), and `render_harness_reverse_
/// attribution` (HarnessLinks -- in addition to, not instead of, that
/// modal's own pre-existing `[Close]` content-row button, which is
/// untouched). Slice 1 of the uniform overlay-close contract
/// (`docs/gate4agent/plans/gate4agent-tui-overlay-uniform-contract-
/// 2026-08-24.md`) added three more callers that used to have no cross at
/// all: `render_agent_menu`, `render_native_session_menu`, and `render_
/// global_search_dropdown`. The layout-preset menu (`render_tabs`) is the
/// one overlay deliberately left out -- it renders as inline labels with
/// no frame to hang a cross on, see its own call site's doc comment.
fn render_modal_close(modal: Rect, buf: &mut TerminalBuffer, layout: &mut LayoutRects, theme: Theme) {
    const CLOSE: &str = "[x]";
    let width = CLOSE.len() as u16;
    // Leave both top corners intact: `width + 2` reserves 1 column for
    // the left corner (never touched by this fn) and 1 for the right
    // corner the cross sits flush against.
    if modal.width < width.saturating_add(2) || modal.height == 0 {
        return;
    }
    let rect = Rect::new(
        modal.right().saturating_sub(1).saturating_sub(width),
        modal.y,
        width,
        1,
    );
    Paragraph::new(CLOSE)
        .style(Style::default().fg(theme.teal).bg(theme.modal))
        .render(rect, buf);
    layout.hits.push(HitRegion { rect, target: HitTarget::ModalClose });
}

/// [`render_modal_close`]'s own sibling for a modal that RETURNS the
/// player somewhere rather than closing the whole overlay it belongs to
/// -- today, only `render_pet_arcade_info`. Owner report: "ты сделал
/// возврат из механики через Х, лучше сделай через стрелочку <-, иначе не
/// очевидно" -- `[x]` reads as "close everything", which returning from
/// the mechanics modal to the board is not (the arcade run underneath
/// keeps going untouched, see `App::click_pet_arcade_info`'s own doc
/// comment). Identical geometry to `render_modal_close` (same corner, same
/// width, same `HitTarget::ModalClose` -- the ACTION is unchanged, only
/// the glyph is), kept as a separate fn rather than a parameter on that
/// one so every one of its many OTHER callers (`render_spawn`, `render_
/// existing_session`, ...) -- which genuinely DO mean "close everything" --
/// never has to pass a flag to say so.
fn render_modal_back(modal: Rect, buf: &mut TerminalBuffer, layout: &mut LayoutRects, theme: Theme) {
    const BACK: &str = "<-";
    let width = BACK.len() as u16;
    if modal.width < width.saturating_add(2) || modal.height == 0 {
        return;
    }
    let rect = Rect::new(
        modal.right().saturating_sub(1).saturating_sub(width),
        modal.y,
        width,
        1,
    );
    Paragraph::new(BACK)
        .style(Style::default().fg(theme.teal).bg(theme.modal))
        .render(rect, buf);
    layout.hits.push(HitRegion { rect, target: HitTarget::ModalClose });
}

fn render_add_space(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(dialog) = &app.add_space else {
        return;
    };
    let width = 72.min(area.width.saturating_sub(4));
    let height = 10.min(area.height.saturating_sub(2));
    let modal = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::AddSpace).copied());
    layout.add_space_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .title(" add workspace ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(modal.x, modal.y, modal.width, 1),
        target: HitTarget::AddSpaceDrag,
    });
    render_modal_close(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let inner = Rect::new(modal.x + 1, modal.y + 1, modal.width - 2, modal.height - 2);
    render_modal_line(
        format!("  {:<12} {}", "node", dialog.node_id),
        inner,
        0,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
    render_add_space_field(
        "workspace ID",
        &dialog.workspace_id,
        dialog.field == AddSpaceField::WorkspaceId,
        AddSpaceField::WorkspaceId,
        inner,
        1,
        theme,
        buf,
        layout,
    );
    render_add_space_field(
        "root path",
        &dialog.root,
        dialog.field == AddSpaceField::Root,
        AddSpaceField::Root,
        inner,
        2,
        theme,
        buf,
        layout,
    );
    // Icon-only control now (no trailing "Browse…" word, see `render_
    // compact_icon_button`'s own doc comment); nothing else in this
    // modal anchors off `browse`'s own rect, so its width can shrink to
    // match via `compact_icon_button_width` rather than keeping the old
    // literal `10` sized for the icon-plus-word footprint.
    let browse_ascii_label = "[Browse…]";
    let browse = Rect::new(
        inner.right().saturating_sub(compact_icon_button_width(browse_ascii_label, app.rail_icons).min(inner.width)),
        inner.y + 2,
        compact_icon_button_width(browse_ascii_label, app.rail_icons).min(inner.width),
        1,
    );
    render_compact_icon_button(
        browse,
        icons::IconId::Search,
        browse_ascii_label,
        Style::default().fg(theme.teal).bg(theme.modal).add_modifier(Modifier::BOLD),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    push_modal_hit(layout, browse, HitTarget::AddSpaceBrowse);
    let register = Rect::new(inner.right().saturating_sub(10), inner.y + 4, 10.min(inner.width), 1);
    Paragraph::new("[Register]")
        .style(Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD))
        .render(register, buf);
    push_modal_hit(layout, register, HitTarget::AddSpaceRegister);
    let cancel = Rect::new(register.x.saturating_sub(9).max(inner.x), inner.y + 4, 8.min(inner.width), 1);
    Paragraph::new("[Cancel]")
        .style(Style::default().fg(theme.text).bg(theme.active))
        .render(cancel, buf);
    push_modal_hit(layout, cancel, HitTarget::AddSpaceCancel);
    render_modal_line(
        "Click a field, then type or paste | drag title",
        inner,
        6,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

fn render_add_space_field(
    label: &str,
    value: &str,
    active: bool,
    field: AddSpaceField,
    area: Rect,
    row: u16,
    theme: Theme,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
) {
    let style = if active {
        Style::default()
            .fg(theme.active_tab_text)
            .bg(theme.accent)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(theme.text).bg(theme.modal)
    };
    render_modal_line(
        format!("{} {:<12} [ {} ]", if active { ">" } else { " " }, label, value),
        area,
        row,
        style,
        buf,
    );
    push_modal_hit(layout, modal_row(area, row), HitTarget::AddSpaceField(field));
}

fn render_folder_browser(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(browser) = &app.folder_browser else {
        return;
    };
    let width = 92.min(area.width.saturating_sub(2));
    let height = 26.min(area.height.saturating_sub(2));
    let modal = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::FolderBrowser).copied());
    layout.folder_browser_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    Block::bordered()
        .title(" browse directories on node ")
        .border_style(Style::default().fg(theme.accent))
        .style(Style::default().bg(theme.modal))
        .render(modal, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(modal.x, modal.y, modal.width, 1),
        target: HitTarget::FolderBrowserDrag,
    });
    render_modal_close(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let inner = Rect::new(modal.x + 1, modal.y + 1, modal.width - 2, modal.height - 2);
    let directory = browser
        .directory
        .as_ref()
        .map(host_path_display)
        .unwrap_or_else(|| "computer roots".to_owned());
    render_modal_line(
        format!("node={} | {}", browser.node_id, directory),
        inner,
        0,
        Style::default().fg(theme.text).bg(theme.modal).add_modifier(Modifier::BOLD),
        buf,
    );
    // Icon-only control now (no trailing "Parent" word, see `render_
    // compact_icon_button`'s own doc comment); nothing else in this
    // modal anchors off `parent`'s own rect, so its width shrinks to
    // match via `compact_icon_button_width` rather than the old literal
    // `12` sized for the icon-plus-word footprint.
    let parent_ascii_label = "[↑ Parent]";
    let parent = Rect::new(inner.x, inner.y + 1, compact_icon_button_width(parent_ascii_label, app.rail_icons).min(inner.width), 1);
    render_compact_icon_button(
        parent,
        icons::IconId::ArrowUp,
        parent_ascii_label,
        Style::default().fg(theme.teal).bg(theme.modal),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    push_modal_hit(layout, parent, HitTarget::FolderBrowserParent);
    let filter_active = browser.field == FolderBrowserField::Filter;
    let filter = Rect::new(inner.x, inner.y + 2, inner.width, 1);
    Paragraph::new(format!(
        "{} filter [ {} ]",
        if filter_active { ">" } else { " " },
        browser.filter,
    ))
    .style(if filter_active {
        Style::default()
            .fg(theme.active_tab_text)
            .bg(theme.accent)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(theme.text).bg(theme.modal)
    })
    .render(filter, buf);
    push_modal_hit(layout, filter, HitTarget::FolderBrowserFilter);

    let visible = app.visible_host_directory_indices();
    let list_capacity = inner.height.saturating_sub(8) as usize;
    let selected = browser.selected.min(visible.len().saturating_sub(1));
    let start = selected.saturating_sub(list_capacity.saturating_sub(1));
    for (row, entry_index) in visible
        .iter()
        .copied()
        .skip(start)
        .take(list_capacity)
        .enumerate()
    {
        let Some(entry) = browser.entries.get(entry_index) else {
            continue;
        };
        let active = start + row == selected && browser.field == FolderBrowserField::Entries;
        let marker = if entry.is_link { "↪" } else { "▸" };
        let line = Rect::new(inner.x, inner.y + 3 + row as u16, inner.width, 1);
        Paragraph::new(format!(
            "{} {} {}",
            if active { ">" } else { " " },
            marker,
            entry.display_name,
        ))
        .style(if active {
            Style::default()
                .fg(theme.active_tab_text)
                .bg(theme.accent)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(theme.text).bg(theme.modal)
        })
        .render(line, buf);
        push_modal_hit(layout, line, HitTarget::FolderBrowserEntry(entry_index));
    }

    let action_row = inner.bottom().saturating_sub(3);
    let can_load_more = browser.next_after.is_some()
        && browser.entries.len() < MAX_BROWSER_LOADED_ENTRIES
        && !browser.pending;
    let load_more_ascii_label = if can_load_more { "[Load more]" } else { " Load more " };
    // Icon-only control now (no trailing "more" word, see `render_
    // compact_icon_button`'s own doc comment); nothing else on this row
    // anchors off `load_more`'s own rect (`use_folder`/`cancel` are
    // right-anchored independently), so its width shrinks to match via
    // `compact_icon_button_width` rather than the old literal `13` sized
    // for the icon-plus-word footprint.
    let load_more = Rect::new(inner.x, action_row, compact_icon_button_width(load_more_ascii_label, app.rail_icons).min(inner.width), 1);
    render_compact_icon_button(
        load_more,
        icons::IconId::CloudDownload,
        load_more_ascii_label,
        Style::default().fg(if can_load_more { theme.teal } else { theme.muted }).bg(theme.modal),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    if can_load_more {
        push_modal_hit(layout, load_more, HitTarget::FolderBrowserLoadMore);
    }
    // Icon-only control now (no trailing "Use this folder" word, see
    // `render_compact_icon_button`'s own doc comment) -- but the rect's
    // own geometry (the literal `17`, sized for the OLD icon-plus-word
    // ascii label) is deliberately left untouched: `cancel`, below, is
    // positioned via `use_folder.x.saturating_sub(9)`, a magic-number
    // offset from this rect's own `x`, not from a returned cursor value
    // -- shrinking `use_folder` here would silently drag `cancel` left
    // with it. That chained pair is exactly the case this task's own
    // brief says to leave untouched and report, not reach into.
    let use_folder = Rect::new(inner.right().saturating_sub(17), action_row, 17.min(inner.width), 1);
    render_compact_icon_button(
        use_folder,
        icons::IconId::Check,
        "[Use this folder]",
        Style::default().fg(if browser.directory.is_some() { theme.active_tab_text } else { theme.muted }).bg(if browser.directory.is_some() { theme.accent } else { theme.modal }).add_modifier(Modifier::BOLD),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    if browser.directory.is_some() {
        push_modal_hit(layout, use_folder, HitTarget::FolderBrowserUse);
    }
    let cancel = Rect::new(use_folder.x.saturating_sub(9).max(inner.x), action_row, 8.min(inner.width), 1);
    render_compact_icon_button(
        cancel,
        icons::IconId::Close,
        "[Cancel]",
        Style::default().fg(theme.text).bg(theme.active),
        app.rail_icons, app.icon_family,
        buf,
        layout,
    );
    push_modal_hit(layout, cancel, HitTarget::FolderBrowserCancel);

    let status = if browser.pending {
        if browser.append_pending { "loading next page…".to_owned() } else { "loading directory…".to_owned() }
    } else if let Some(error) = browser.error.as_ref() {
        format!("error: {error}")
    } else if browser.entries.len() == MAX_BROWSER_LOADED_ENTRIES
        && browser.next_after.is_some()
    {
        format!("{} directories loaded (client limit reached)", visible.len())
    } else {
        format!(
            "{} director{} loaded{}",
            visible.len(),
            if visible.len() == 1 { "y" } else { "ies" },
            if browser.incomplete { " (incomplete)" } else { "" },
        )
    };
    render_modal_line(status, inner, inner.height.saturating_sub(2), Style::default().fg(theme.dim).bg(theme.modal), buf);
    render_modal_line(
        "Enter open | ←/Backspace parent | u use | m more | Tab filter | drag title",
        inner,
        inner.height.saturating_sub(1),
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

fn render_create_worktree(
    app: &App,
    area: Rect,
    buf: &mut TerminalBuffer,
    layout: &mut LayoutRects,
    theme: Theme,
) {
    let Some(dialog) = &app.create_worktree else {
        return;
    };
    let width = 72.min(area.width.saturating_sub(4));
    let height = 14.min(area.height.saturating_sub(2));
    let modal = positioned_modal(area, width, height, app.overlay_positions.get(&OverlayId::CreateWorktree).copied());
    layout.create_worktree_modal = modal;
    layout.note_overlay(modal);
    fill_rect(modal, theme.modal, buf);
    let prefix = |field| if dialog.field == field { ">" } else { " " };
    let (lines, editable_fields, primary_label, primary_enabled, detail) = match dialog.kind {
        GitLocationDialogKind::ManualLinked => (
            vec![
                Line::styled(format!("source  {} / {}", dialog.node_id, dialog.source_workspace_id), Style::default().fg(theme.muted)),
                Line::styled(format!("{} worktree id  {}", prefix(CreateWorktreeField::WorkspaceId), dialog.workspace_id), Style::default().fg(theme.text)),
                Line::styled(format!("{} root         {}", prefix(CreateWorktreeField::TargetRoot), dialog.target_root), Style::default().fg(theme.text)),
                Line::styled(format!("{} branch       {}", prefix(CreateWorktreeField::Branch), dialog.branch), Style::default().fg(theme.text)),
                Line::styled(format!("{} base         {}", prefix(CreateWorktreeField::Base), if dialog.base.is_empty() { "(HEAD)" } else { &dialog.base }), Style::default().fg(theme.text)),
                Line::styled("Manual policy: Node creates and registers this linked worktree.", Style::default().fg(theme.muted)),
            ],
            vec![(1, CreateWorktreeField::WorkspaceId), (2, CreateWorktreeField::TargetRoot), (3, CreateWorktreeField::Branch), (4, CreateWorktreeField::Base)],
            "[Create & register]",
            true,
            "Tab field | Enter create and return ready to Launch | Esc cancel",
        ),
        GitLocationDialogKind::Standalone => (
            vec![
                Line::styled(format!("node  {}", dialog.node_id), Style::default().fg(theme.muted)),
                Line::styled(format!("{} workspace id    {}", prefix(CreateWorktreeField::WorkspaceId), dialog.workspace_id), Style::default().fg(theme.text)),
                Line::styled(format!("{} root            {}", prefix(CreateWorktreeField::TargetRoot), dialog.target_root), Style::default().fg(theme.text)),
                Line::styled(format!("{} initial branch  {}", prefix(CreateWorktreeField::Branch), if dialog.branch.is_empty() { "(default)" } else { &dialog.branch }), Style::default().fg(theme.text)),
                Line::styled("Creates a new standalone Git repository outside the source workspace.", Style::default().fg(theme.muted)),
            ],
            vec![(1, CreateWorktreeField::WorkspaceId), (2, CreateWorktreeField::TargetRoot), (3, CreateWorktreeField::Branch)],
            "[Create repository]",
            true,
            "Tab field | Enter create and return ready to Launch | Esc cancel",
        ),
        GitLocationDialogKind::ManagedLinked => {
            let policy = app.spawn.as_ref().and_then(|spawn| app.selected_managed_worktree_profile(spawn));
            let summary = policy.as_ref().map(|profile| format!("profile    {}@{}", profile.id, profile.revision)).unwrap_or_else(|| "profile    none advertised".to_owned());
            let retention = policy.as_ref().map(|profile| match profile.retention {
                ManagedWorktreeRetention::RemoveWhenReleased => "remove when released",
                ManagedWorktreeRetention::Retain => "retain after session",
            }).unwrap_or("unavailable");
            (
                vec![
                    Line::styled(format!("source     {} / {}", dialog.node_id, dialog.source_workspace_id), Style::default().fg(theme.muted)),
                    Line::styled("mode       Managed", Style::default().fg(theme.text)),
                    Line::styled(summary, Style::default().fg(theme.text)),
                    Line::styled(format!("retention  {retention}"), Style::default().fg(theme.text)),
                    Line::styled("The advertised Node policy is read-only in Launch.", Style::default().fg(theme.muted)),
                ],
                Vec::new(),
                "[Launch]",
                policy.is_some(),
                "Enter confirms the advertised policy and launches an interactive PTY",
            )
        }
        GitLocationDialogKind::LinkedDisabled => (
            vec![
                Line::styled(format!("source  {} / {}", dialog.node_id, dialog.source_workspace_id), Style::default().fg(theme.muted)),
                Line::styled("mode     Off", Style::default().fg(theme.text)),
                Line::styled("Disabled: this workspace explicitly disallows linked worktrees.", Style::default().fg(theme.red)),
                Line::styled("Choose Existing workspace or New standalone repository.", Style::default().fg(theme.muted)),
            ],
            Vec::new(),
            "[Disabled]",
            false,
            "Esc returns to Git location",
        ),
    };
    Paragraph::new(Text::from_lines(lines))
    .block(
        Block::bordered()
            .title(" configure Git location ")
            .border_style(Style::default().fg(theme.accent))
            .style(Style::default().bg(theme.modal)),
    )
    .style(Style::default().fg(theme.text).bg(theme.modal))
    .render(modal, buf);
    layout.hits.push(HitRegion {
        rect: Rect::new(modal.x, modal.y, modal.width, 1),
        target: HitTarget::CreateWorktreeDrag,
    });
    render_modal_close(modal, buf, layout, theme);
    if modal.width < 3 || modal.height < 3 {
        return;
    }
    let inner = Rect::new(modal.x + 1, modal.y + 1, modal.width - 2, modal.height - 2);
    for (row, field) in editable_fields {
        push_modal_hit(layout, modal_row(inner, row), HitTarget::CreateWorktreeField(field));
    }
    if let Some(preview) = match dialog.kind {
        GitLocationDialogKind::ManualLinked => Some(format!(
            "preview: {} -> {} | branch {} @ {}",
            dialog.source_workspace_id,
            dialog.workspace_id,
            dialog.branch,
            if dialog.base.is_empty() { "HEAD" } else { &dialog.base },
        )),
        GitLocationDialogKind::Standalone => Some(format!(
            "preview: repository {} at {} | initial branch {}",
            dialog.workspace_id,
            dialog.target_root,
            if dialog.branch.is_empty() { "provider default" } else { &dialog.branch },
        )),
        GitLocationDialogKind::ManagedLinked | GitLocationDialogKind::LinkedDisabled => None,
    } {
        render_modal_line(
            preview,
            inner,
            6,
            Style::default().fg(theme.dim).bg(theme.modal),
            buf,
        );
    }
    let primary_width = (cell_width(primary_label) as u16).min(inner.width);
    let create = Rect::new(inner.right().saturating_sub(primary_width), inner.y + 8, primary_width, 1);
    Paragraph::new(primary_label)
        .style(if primary_enabled {
            Style::default().fg(theme.active_tab_text).bg(theme.accent).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(theme.muted).bg(theme.modal)
        })
        .render(create, buf);
    if primary_enabled {
        push_modal_hit(layout, create, HitTarget::CreateWorktreeCreate);
    }
    let cancel = Rect::new(create.x.saturating_sub(9).max(inner.x), inner.y + 8, 8.min(inner.width), 1);
    Paragraph::new("[Cancel]")
        .style(Style::default().fg(theme.text).bg(theme.active))
        .render(cancel, buf);
    push_modal_hit(layout, cancel, HitTarget::CreateWorktreeCancel);
    render_modal_line(
        detail,
        inner,
        10,
        Style::default().fg(theme.muted).bg(theme.modal),
        buf,
    );
}

