    /// A running, non-attention, `Unknown`-screen session -- the baseline
    /// [`session_state`]'s own tests below start from and override one
    /// field on top of, rather than repeating this whole literal per test.
    fn base_session_view(address: SessionAddress) -> SessionView {
        SessionView {
            address,
            provider: provider("codex"),
            status: "running".to_owned(),
            running: true,
            stoppable: true,
            removable: false,
            restartable: false,
            attention: false,
            has_provider_session_identity: true,
            progress: None,
            terminal_formatted: Vec::new(),
            terminal_scrollback: Vec::new(),
            terminal_alternate_screen: false,
            terminal_mouse_protocol_enabled: false,
            terminal_mouse_protocol_encoding: TerminalMouseProtocolEncoding::Default,
            terminal_cursor: None,
            screen_state: PtyScreenState::Unknown,
        }
    }

    fn test_session_view_address() -> SessionAddress {
        SessionAddress {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            instance_id: 2,
            generation: 1,
        }
    }

    /// `OperatorGate`, `Failing`, and `attention` must be visually
    /// distinguishable from one another -- distinct labels, asserted side
    /// by side so the three provably differ, not merely each differ from
    /// "blocked" in isolation (which a shared fallback label could still
    /// pass).
    #[test]
    fn session_state_distinguishes_operator_gate_failing_and_attention() {
        let theme = Theme::for_mode(PtyColorMode::Inherited);
        let address = test_session_view_address();

        let mut gated = base_session_view(address.clone());
        gated.screen_state = PtyScreenState::OperatorGate {
            gate: OperatorGateState::new(OperatorGateKind::WorkspaceTrust),
        };
        let (_, _, gated_label) = session_state(&gated, theme);

        let mut failing = base_session_view(address.clone());
        failing.screen_state = PtyScreenState::Failing { reason: "crash-loop".to_owned() };
        let (_, _, failing_label) = session_state(&failing, theme);

        let mut attention = base_session_view(address);
        attention.attention = true;
        let (_, _, attention_label) = session_state(&attention, theme);

        assert_eq!(gated_label, "workspace trust");
        assert_eq!(failing_label, "crash-loop");
        assert_eq!(attention_label, "blocked");
        assert_ne!(gated_label, failing_label);
        assert_ne!(gated_label, attention_label);
        assert_ne!(failing_label, attention_label);
    }

    /// `Unknown` -- every session's pre-observation default -- must render
    /// EXACTLY as it did before `screen_state` existed: `running` alone
    /// decides "working" yellow, with no alert layered on top that would
    /// paint a warning on a healthy, freshly-observed session at startup.
    #[test]
    fn session_state_renders_an_unknown_screen_exactly_like_before_this_feature() {
        let theme = Theme::for_mode(PtyColorMode::Inherited);
        let mut session = base_session_view(test_session_view_address());
        session.screen_state = PtyScreenState::Unknown;
        assert_eq!(session_state(&session, theme), ("●", theme.yellow, "working"));
    }

    fn buffer_text(buf: &TerminalBuffer) -> String {
        (0..buf.height())
            .map(|row| {
                (0..buf.width())
                    .map(|column| buf.get(column, row).symbol.as_str())
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// Same shape as `buffer_text`, scoped to a single rect -- used for the
    /// activity rail so assertions can't collide with unrelated chrome
    /// (e.g. the tab strip's own unrelated `[#]` layout-menu button).
    fn rect_text(buf: &TerminalBuffer, rect: Rect) -> String {
        (rect.y..rect.bottom())
            .map(|row| {
                (rect.x..rect.right())
                    .map(|column| buf.get(column, row).symbol.as_str())
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// The zone's own render pass is driven by the REAL wall clock
    /// (`App::clock_text` reads `SystemTime::now()`), so this cannot pin
    /// an exact digit string the way `app::tests::clock_display_text_*`
    /// does -- what it CAN pin, regardless of what time it happens to run
    /// at, is that the zone never truncates (no `…`) even in manual mode
    /// with the widest prefix armed, proving the real render pipeline
    /// (not just the pure arithmetic) actually fits inside `STATUS_BAR_
    /// LEFT_WIDTH`.
    #[test]
    fn status_bar_left_zone_never_truncates_the_clock() {
        let mut app = App::default();
        app.clock_settings.follow_system = false;
        app.clock_settings.manual_offset_hours = 12;
        app.clock_settings.use_24h = false;
        app.clock_settings.show_utc_prefix = true;
        let mut buf = TerminalBuffer::new(80, 20);
        let layout = render(&app, &mut buf);
        let text = rect_text(&buf, layout.status_bar_left);
        assert!(!text.contains('\u{2026}'), "clock zone truncated: {text:?}");
    }

    /// Owner instruction (slice B item 5): slice A's coloured network-
    /// status dot is removed from the LEFT zone outright -- the RIGHT
    /// zone's pet is now the app's only status-bar connection indicator
    /// (`app::pet_connection_color_key`). `App::default()` (no nodes
    /// registered) previously ALWAYS painted the muted `\u{b7}` dot here
    /// regardless of node state, so proving it is gone for that case is
    /// sufficient: every other `NetworkSummary` variant only ever swapped
    /// which dot glyph/colour painted, never whether one painted at all.
    #[test]
    fn status_bar_left_zone_has_no_network_dot() {
        let app = App::default();
        let mut buf = TerminalBuffer::new(80, 20);
        let layout = render(&app, &mut buf);
        let text = rect_text(&buf, layout.status_bar_left);
        assert!(!text.contains('\u{25cf}'), "left zone still paints the filled network dot: {text:?}");
        assert!(!text.contains('\u{b7}'), "left zone still paints the muted network dot: {text:?}");
    }

