    fn inspection() -> WorkspaceInspection {
        WorkspaceInspection {
            workspace_id: WorkspaceId::new("workspace-a").unwrap(),
            entries: vec![
                WorkspaceEntry {
                    relative_path: repository_path("src"),
                    kind: WorkspaceEntryKind::Directory,
                },
                WorkspaceEntry {
                    relative_path: repository_path("src/main.rs"),
                    kind: WorkspaceEntryKind::File,
                },
            ],
            tree_truncated: false,
            git: GitSnapshot {
                is_repository: true,
                branch: Some("main".to_owned()),
                status: vec![GitStatusEntry {
                    index_status: " ".to_owned(),
                    worktree_status: "M".to_owned(),
                    path: repository_path("src/main.rs"),
                    previous_path: None,
                }],
                recent_commits: vec![GitCommitSummary {
                    id: "abcdef0".to_owned(),
                    summary: "ship workspace controls".to_owned(),
                }],
                worktrees: Vec::new(),
                managed_worktree: None,
                truncated: false,
                diagnostic: None,
            },
            truncation: None,
        }
    }

    #[test]
    fn sidebar_geometry_uses_configured_width_split_and_drag_hits() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.sidebar_width = 32;
        app.sidebar_split_percent = 40;
        let mut buf = TerminalBuffer::new(100, 24);
        let layout = render(&app, &mut buf);
        assert_eq!(layout.spaces.width, 31);
        assert_eq!(layout.agents.width, 31);
        assert_eq!(layout.spaces.height, 9);
        // 14, not 24 - 9 = 15: the status bar's own last row (see
        // `render::render`'s own doc comment on `area` vs `full_area`)
        // leaves the sidebar's own content one row shorter to split.
        assert_eq!(layout.agents.height, 14);
        assert_eq!(layout.tabs.height, 1);
        assert_eq!(layout.viewport, Rect::new(32, 1, 68, 22));
        assert_eq!(buf.get(31, 0).symbol, "│");
        assert!(layout.hits.iter().any(|hit| hit.target == HitTarget::SidebarWidthDrag));
        assert!(layout.hits.iter().any(|hit| hit.target == HitTarget::SidebarSplitDrag));
    }

    #[test]
    fn inspector_roster_and_tabs_have_compact_mode_and_action_hits() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.roster_mode = RosterMode::Workspaces;
        let mut buf = TerminalBuffer::new(100, 24);
        let workspace_layout = render(&app, &mut buf);
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::AddSpace));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::RemoveSpace));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::SpawnSpace(0)));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::SidebarMode(SidebarMode::Files)));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::SidebarMode(SidebarMode::Git)));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::RosterMode(RosterMode::Agents)));
        assert!(!workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::RosterMode(RosterMode::NativeSessions)));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::RosterMode(RosterMode::Workspaces)));
        assert!(workspace_layout.hits.iter().any(|hit| hit.target == HitTarget::AddTab));
        // `fixture()` defaults to (Sidebar, Split): no activity rail, so
        // the tab strip's own icon gear (never the rejected "[S]" bracket
        // text) is this chrome's mouse entry to Settings -- see
        // `file_surface_separates_global_controls_pane_title_actions_and_
        // scrollbar`'s own assertion on that exact hit region, and
        // `sidebar_gear_opens_only_compact_positioned_settings` for the
        // (Sidebar, Activity) chrome where the rail alone carries it.

        app.roster_mode = RosterMode::Agents;
        let agent_layout = render(&app, &mut buf);
        assert!(agent_layout.hits.iter().any(|hit| hit.target == HitTarget::AddAgent));
        assert!(agent_layout.hits.iter().all(|hit| !matches!(hit.target, HitTarget::Viewport) || hit.rect == agent_layout.viewport));
    }

    /// Pins the actual defect this fixed: the global search dropdown used
    /// to be painted from inside `render_tabs` (`render_global_search`'s
    /// own call chain), which runs BEFORE `render_surface` -- and the
    /// surface's own pane header (`render_surface_pane_tabs`'s
    /// unconditional `fill_rect`) sits exactly on the dropdown's own top
    /// border row, one row under the tab strip. Painted in the wrong
    /// order, that border and its first content row got silently erased
    /// every frame the dropdown was open. `render::render`'s own top-level
    /// sequence now paints it AFTER the surface instead (see that call
    /// site's own doc comment) -- so this dropdown's own top-left corner
    /// must still show a real border glyph, not the header's plain space,
    /// once both have painted the same frame.
    #[test]
    fn global_search_dropdown_paints_after_the_surface_so_its_border_survives() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.focus = Focus::GlobalSearch;
        app.global_search.expand_target_open = true;
        app.global_search.expand_step = crate::app::SEARCH_EXPAND_STEPS;
        let mut buf = TerminalBuffer::new(100, 24);

        let layout = render(&app, &mut buf);

        assert_ne!(layout.global_search_dropdown, Rect::default(), "dropdown should be open and recorded this frame");
        let dropdown = layout.global_search_dropdown;
        // The dropdown's own top row sits directly under the tab strip
        // (`render_global_search_dropdown`'s own `anchor.bottom()`), which
        // is exactly the surface's own pane header row -- see this test's
        // own doc comment. A plain space here would mean the header's
        // `fill_rect` ran AFTER the dropdown and erased its border; the
        // real corner glyph (`Block::bordered`'s default `BorderType::
        // Plain` top-left) proves the opposite order actually happened.
        let corner = buf.get(dropdown.x, dropdown.y);
        assert_eq!(corner.symbol, "┌");
    }

    /// `render_global_search_dropdown`'s own `anchor.width.max(28)` /
    /// `rows + 2` footprint assumes the strip has that much room to the
    /// right and that many rows free below it -- nothing bounded it
    /// against the actual buffer before this fix, so an anchor sitting
    /// close enough to the right edge or the bottom (unreachable through
    /// `render::render` itself, which refuses anything under 56x14, but
    /// reachable by calling this helper directly, the same way the
    /// pre-strip fallback tests above call `render_workspace_files`/
    /// `render_workspace_git` directly) ran the raw rect straight past
    /// `buf`'s own bounds. Picks an anchor/buffer pair that overflows both
    /// the right edge AND the bottom at once, and pins the exact clamped
    /// rect this fix now records -- not just "still inside", since a
    /// clamp that silently produced the wrong size would pass a looser
    /// check just as well.
    #[test]
    fn global_search_dropdown_clamps_to_a_narrow_short_buffer() {
        let mut app = App::default();
        // Four deterministic matches purely from `ControlSection::ALL`
        // ("files", "agents", "workspaces", "settings" -- see that enum's
        // own `id()`), independent of any fixture node/tab data, so `rows`
        // is a known 4 regardless of what else this `App` does or doesn't
        // hold.
        app.global_search.query = "s".to_owned();
        let mut buf = TerminalBuffer::new(16, 7);
        let mut layout = LayoutRects::default();
        let theme = Theme::for_mode(PtyColorMode::GateOverride);
        let anchor = Rect::new(10, 2, 4, 1);

        render_global_search_dropdown(&app, anchor, &mut buf, &mut layout, theme);

        // Unclamped this would have been `Rect::new(10, 3, 28, 6)` --
        // right edge 38, bottom 9 -- well past this 16x7 buffer on both
        // axes.
        assert_eq!(layout.global_search_dropdown, Rect::new(10, 3, 6, 4));
        assert!(layout.global_search_dropdown.right() <= buf.width());
        assert!(layout.global_search_dropdown.bottom() <= buf.height());
    }

    /// The tab strip's own AddTab/LayoutMenuToggle controls: the STRIP
    /// tier's real icon footprint now drives their own width instead of
    /// the old literal `" + "`/`" [#] "` text widths (3/5 cells) --
    /// `IconId::Add` at 2 cells (`icons::STRIP_SIXEL_ICON_CELLS_WIDE`, no
    /// accent margin -- like `render_control_strip_button`'s own
    /// `AddSpace`/`AddAgent`, a one-shot action, never a persisted
    /// selected view), `IconId::Layout` at 3 (that same 2-cell icon plus
    /// ONE leading margin column reserved for its own open/closed marker
    /// -- see `tab_strip_layout_toggle_marks_open_state_with_an_accent_
    /// bar_not_a_plate` for that marker itself). Both push a real STRIP-
    /// tier sixel placement now, not the old bracket text.
    #[test]
    fn tab_strip_add_and_layout_controls_render_strip_icons_in_sixel_tier() {
        let app = fixture(PtyColorMode::GateOverride);
        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut buf = TerminalBuffer::new(100, 24);
        let layout = render(&app, &mut buf);

        let add_rect = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::AddTab)
            .expect("AddTab hit")
            .rect;
        let layout_rect = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit")
            .rect;

        assert_eq!(add_rect.height, 1);
        assert_eq!(add_rect.width, icons::STRIP_SIXEL_ICON_CELLS_WIDE);
        assert_eq!(layout_rect.height, 1);
        assert_eq!(layout_rect.width, 1 + icons::STRIP_SIXEL_ICON_CELLS_WIDE);
        assert_eq!(
            layout_rect.x,
            add_rect.right(),
            "the toggle sits immediately after the add control, no gap, matching the old adjacent text",
        );

        assert!(
            layout.sixel_icons.iter().any(|placement| {
                placement.icon == icons::IconId::Add
                    && placement.size == SixelIconSize::Strip
                    && placement.variant == icons::SixelVariant::GateActive
                    && add_rect.contains(placement.rect.x, placement.rect.y)
            }),
            "{:?}",
            layout.sixel_icons,
        );
        assert!(
            layout.sixel_icons.iter().any(|placement| {
                placement.icon == icons::IconId::Layout
                    && placement.size == SixelIconSize::Strip
                    && placement.variant == icons::SixelVariant::GateActive
                    // The icon itself sits one column INSIDE the toggle's
                    // own rect -- the leading column is the accent-bar
                    // margin, never part of the icon (see this fn's own
                    // doc comment above).
                    && placement.rect.x == layout_rect.x + 1
            }),
            "{:?}",
            layout.sixel_icons,
        );

        // Neither control paints its own old glyph as text any more --
        // the real pixels are the flush hook's job, invisible to a
        // `render()`-only cell-buffer inspection like this one.
        let add_text = rect_text(&buf, add_rect);
        assert!(!add_text.contains('+'), "{add_text:?}");
        let layout_text = rect_text(&buf, layout_rect);
        assert!(!layout_text.contains('#'), "{layout_text:?}");
    }

    /// `render_rail_button`'s own lesson, reused for this toggle: a
    /// selected/open control never states a background of its own --
    /// only `render_rail_button`'s own "▎" accent-bar marker (`theme.
    /// active_tab_text` on the SAME `theme.active` every other cell on
    /// this row already shows) marks it, painted into the leading margin
    /// column the toggle's own width reserves for exactly this. The old
    /// `theme.accent` plate under the `" [#] "` glyph is gone outright,
    /// not just moved -- this asserts both that the marker appears when
    /// open and that the control's body never states `theme.accent`
    /// either way.
    #[test]
    fn tab_strip_layout_toggle_marks_open_state_with_an_accent_bar_not_a_plate() {
        let mut app = fixture(PtyColorMode::GateOverride);
        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let theme = Theme::for_mode(app.color_mode);

        app.layout_menu_open = false;
        let mut closed_buf = TerminalBuffer::new(100, 24);
        let closed_layout = render(&app, &mut closed_buf);
        let closed_rect = closed_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit")
            .rect;
        assert_ne!(closed_buf.get(closed_rect.x, closed_rect.y).symbol, "▎");
        assert_eq!(closed_buf.get(closed_rect.x, closed_rect.y).style.bg, theme.active);

        app.layout_menu_open = true;
        let mut open_buf = TerminalBuffer::new(100, 24);
        let open_layout = render(&app, &mut open_buf);
        let open_rect = open_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit")
            .rect;
        // Same geometry whether open or closed -- the toggle never
        // resizes itself to make room for its own marker.
        assert_eq!(open_rect, closed_rect);
        assert_eq!(open_buf.get(open_rect.x, open_rect.y).symbol, "▎");
        assert_eq!(open_buf.get(open_rect.x, open_rect.y).style.fg, theme.active_tab_text);
        // The bar is the ONLY marker: the body never states a background
        // of its own, open or not -- never the old `theme.accent` plate.
        assert_eq!(open_buf.get(open_rect.x, open_rect.y).style.bg, theme.active);
        assert_ne!(open_buf.get(open_rect.x, open_rect.y).style.bg, theme.accent);
    }

    /// `RailIcons::Ascii` has no raster to swap in for these two controls
    /// (see `icons.rs`'s own module doc comment: "no raster in that
    /// tier") -- it must keep painting the EXACT old literal, padded
    /// labels this fn always drew before today, at their old widths (3
    /// for `" + "`, 5 for `" [#] "`), with the old `theme.accent` open-
    /// state plate untouched; only `RailIcons::Sixel`'s own geometry and
    /// marker changed. Both `HitTarget`s still resolve in EITHER tier --
    /// only their own rect WIDTH differs, which is the expected effect of
    /// `RailIcons::Sixel` now sizing off the icon's real width instead of
    /// the old text.
    #[test]
    fn tab_strip_ascii_tier_keeps_its_old_text_and_both_controls_keep_their_hit_targets() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.rail_icons = RailIcons::Ascii;
        let theme = Theme::for_mode(app.color_mode);
        let mut buf = TerminalBuffer::new(100, 24);
        let layout = render(&app, &mut buf);

        let add_rect = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::AddTab)
            .expect("AddTab hit in Ascii tier")
            .rect;
        let layout_rect = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit in Ascii tier")
            .rect;
        assert_eq!(add_rect.width, 3);
        assert_eq!(layout_rect.width, 5);
        assert_eq!(rect_text(&buf, add_rect), " + ");
        assert_eq!(rect_text(&buf, layout_rect), " [#] ");
        assert_eq!(buf.get(layout_rect.x, layout_rect.y).style.bg, theme.active);
        assert!(layout.sixel_icons.is_empty());

        app.layout_menu_open = true;
        let mut open_buf = TerminalBuffer::new(100, 24);
        let open_layout = render(&app, &mut open_buf);
        let open_rect = open_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit in Ascii tier while open")
            .rect;
        assert_eq!(rect_text(&open_buf, open_rect), " [#] ");
        // Ascii keeps the OLD marker exactly -- a `theme.accent` plate
        // under the glyph, never the sixel tier's own "▎" accent bar.
        assert_eq!(open_buf.get(open_rect.x, open_rect.y).style.bg, theme.accent);
        assert!(open_layout.sixel_icons.is_empty());
    }

    /// The layout-preset list drawn to the right of the toggle when open
    /// keeps its own text-based entries unchanged (`format!(" {} ",
    /// preset.id())`) but now starts wherever the NEW, narrower `Sixel`
    /// tier control group actually ends, not the old wider text-based
    /// one -- this is `controls_width`/`controls_right`'s own real
    /// effect, not a separate code path of its own. Comparing the two
    /// tiers' own first-preset start column is the actual proof the
    /// geometry recompute reached the preset list at all: the `Sixel`
    /// tier's own start must sit STRICTLY to the LEFT of `Ascii`'s (the
    /// icons are narrower than the old padded text), and in both tiers
    /// the first preset must start EXACTLY at the toggle's own right
    /// edge (no gap, matching the pre-existing adjacency every other
    /// control on this row already has).
    #[test]
    fn tab_strip_layout_preset_menu_starts_at_the_new_control_width_when_open() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.layout_menu_open = true;
        assert_eq!(app.rail_icons, RailIcons::Sixel);

        let mut sixel_buf = TerminalBuffer::new(100, 24);
        let sixel_layout = render(&app, &mut sixel_buf);
        let sixel_toggle_rect = sixel_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit")
            .rect;
        let sixel_first_preset_rect = sixel_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutPreset(LayoutPreset::ALL[0]))
            .expect("first LayoutPreset hit")
            .rect;
        assert_eq!(sixel_first_preset_rect.x, sixel_toggle_rect.right());

        app.rail_icons = RailIcons::Ascii;
        let mut ascii_buf = TerminalBuffer::new(100, 24);
        let ascii_layout = render(&app, &mut ascii_buf);
        let ascii_toggle_rect = ascii_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutMenuToggle)
            .expect("LayoutMenuToggle hit")
            .rect;
        let ascii_first_preset_rect = ascii_layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::LayoutPreset(LayoutPreset::ALL[0]))
            .expect("first LayoutPreset hit")
            .rect;
        assert_eq!(ascii_first_preset_rect.x, ascii_toggle_rect.right());

        assert!(
            sixel_first_preset_rect.x < ascii_first_preset_rect.x,
            "the icon tier's own narrower controls must free up room, moving the preset list left: sixel={sixel_first_preset_rect:?} ascii={ascii_first_preset_rect:?}",
        );
    }

    /// The workspaces roster's own pre-strip fallback (panel too short
    /// for `control_strip_fits`, see `space_list_control_strip_falls_
    /// back_to_inline_buttons_when_the_panel_is_too_short` for the exact
    /// threshold): AddSpace and RemoveSpace are both icon-only controls in
    /// `Sixel` mode -- AddSpace used to keep a "workspace" trailing word
    /// next to [`icons::IconId::Add`], but a control is its icon alone,
    /// never icon-plus-word (see [`render_compact_icon_button`]'s own doc
    /// comment), so the word is gone and the (unique, unambiguous) glyph
    /// carries the control by itself, same as RemoveSpace's plain remove
    /// action mirroring RemoveWorktree already did. Same 2-tier + stable-
    /// hit-rect coverage as `workspace_files_create_buttons_render_in_the_
    /// control_strip_per_tier`. Renders `render_space_list` directly
    /// (not the full `render()`) -- the Explorer panel's own control-
    /// plane strip now ALSO carries an `AddSpace`/`RemoveSpace` button
    /// (see `explorer_control_strip_carries_the_specified_buttons_in_
    /// order`), and in the default Split presentation both panels are
    /// on screen at once, so a full render leaves two hit regions for
    /// each target; this test's own subject is `render_space_list`'s
    /// OWN fallback button specifically, not whichever one a full
    /// render's hit list happens to list first.
    #[test]
    fn space_list_add_and_remove_buttons_render_an_icon_only_control_per_tier() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.roster_mode = RosterMode::Workspaces;
        let area = Rect::new(0, 0, 40, 4);
        assert!(!control_strip_fits(area), "4 rows must be below the strip's own minimum");
        let theme = Theme::for_mode(app.color_mode);

        let hit_rect = |layout: &LayoutRects, target: HitTarget| {
            layout
                .hits
                .iter()
                .find(|hit| hit.target == target)
                .unwrap_or_else(|| panic!("missing hit for {target:?}"))
                .rect
        };

        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut sixel_buf = TerminalBuffer::new(40, 4);
        let mut sixel_layout = LayoutRects::default();
        render_space_list(&app, area, &mut sixel_buf, &mut sixel_layout, theme);
        let add_rect = hit_rect(&sixel_layout, HitTarget::AddSpace);
        let remove_rect = hit_rect(&sixel_layout, HitTarget::RemoveSpace);
        assert!(sixel_layout.sixel_icons.iter().any(|placement| {
            placement.icon == icons::IconId::Add
                && placement.size == crate::app::SixelIconSize::Strip
                && add_rect.contains(placement.rect.x, placement.rect.y)
        }));
        assert!(sixel_layout.sixel_icons.iter().any(|placement| {
            placement.icon == icons::IconId::Trash
                && placement.size == crate::app::SixelIconSize::Strip
                && remove_rect.contains(placement.rect.x, placement.rect.y)
        }));
        assert!(!rect_text(&sixel_buf, add_rect).contains("workspace"));
        assert!(!rect_text(&sixel_buf, remove_rect).contains("remove"));

        app.rail_icons = RailIcons::Ascii;
        let mut ascii_buf = TerminalBuffer::new(40, 4);
        let mut ascii_layout = LayoutRects::default();
        render_space_list(&app, area, &mut ascii_buf, &mut ascii_layout, theme);
        let ascii_add_rect = hit_rect(&ascii_layout, HitTarget::AddSpace);
        // AddSpace is left-anchored (`Rect::new(area.x, area.y, add_width,
        // 1)`) and `add_width` is now tier-aware (`compact_icon_button_
        // width`): ascii keeps the full bracketed label's own width,
        // sixel shrinks to the icon alone, so the two rects share their
        // left edge but no longer their width -- unlike RemoveSpace,
        // whose own width was never tier-aware (see `render_space_list`'s
        // own body) and so keeps the SAME rect across both tiers.
        assert_eq!(ascii_add_rect.x, add_rect.x);
        assert!(ascii_add_rect.width > add_rect.width, "ascii={ascii_add_rect:?} sixel={add_rect:?}");
        assert_eq!(hit_rect(&ascii_layout, HitTarget::RemoveSpace), remove_rect);
        assert!(ascii_layout.sixel_icons.is_empty());
        assert!(rect_text(&ascii_buf, ascii_add_rect).contains("+ workspace"));
        assert!(rect_text(&ascii_buf, remove_rect).contains("- remove"));
    }

    #[test]
    fn agent_run_controls_use_stable_keys_in_roster_tree_and_inspector_header() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.roster_mode = RosterMode::Agents;
        let expected = AgentRowKey::Legacy(active_pty_address(&app));
        let mut buf = TerminalBuffer::new(100, 32);
        let layout = render(&app, &mut buf);
        let run = layout.hits.iter().find(|hit| {
            hit.target == HitTarget::AgentRun(expected.clone())
        }).cloned().expect("agent roster exposes stable run target");
        app.layout = layout;
        let action = app.click(run.rect.x, run.rect.y);
        assert!(matches!(action, crate::app::AppAction::InspectWorkspace { .. }));

        let lens_layout = render(&app, &mut buf);
        assert!(lens_layout.hits.iter().any(|hit| hit.target == HitTarget::AgentRunAll));
        assert!(lens_layout.hits.iter().any(|hit| {
            hit.target == HitTarget::AgentRun(expected.clone())
        }));
        let all = lens_layout.hits.iter().find(|hit| hit.target == HitTarget::AgentRunAll).unwrap();
        assert!(!lens_layout.hits.iter().any(|hit| {
            matches!(hit.target, HitTarget::NewFile | HitTarget::NewDirectory)
                && hit.rect.contains(all.rect.x, all.rect.y)
        }));

        let mut unified = fixture(PtyColorMode::Inherited);
        unified.focus = Focus::Agents;
        let _ = unified.reduce(crate::app::UiKey::Char('a'));
        // The unified tree starts with every provider branch collapsed on first
        // open (see `begin_existing_session`'s one-time
        // `native_provider_branches_initialized` seeding); expand kimi's branch
        // before its row's stable AgentRun key becomes reachable.
        let opening = render(&unified, &mut buf);
        let provider_branch = opening
            .hits
            .iter()
            .find(|hit| {
                hit.target
                    == HitTarget::NativeProviderGroup(
                        NativeSessionGroupKey::Workspace("workspace-a".to_owned()),
                        provider("kimi"),
                    )
            })
            .cloned()
            .expect("native tree exposes the kimi provider branch");
        unified.layout = opening;
        unified.click(provider_branch.rect.x, provider_branch.rect.y);
        let tree = render(&unified, &mut buf);
        assert!(tree.hits.iter().any(|hit| {
            hit.target == HitTarget::AgentRun(AgentRowKey::Legacy(active_pty_address(&unified)))
        }));
    }

    #[test]
    fn roster_controls_span_split_and_modal_but_activity_rail_drops_workspaces() {
        let mut app = fixture(PtyColorMode::Inherited);
        let mut buf = TerminalBuffer::new(100, 24);

        let split = render(&app, &mut buf);
        assert!([RosterMode::Agents, RosterMode::Workspaces]
            .iter()
            .all(|mode| split.hits.iter().any(|hit| hit.target == HitTarget::RosterMode(*mode))));
        assert!(!split.hits.iter().any(|hit| {
            hit.target == HitTarget::RosterMode(RosterMode::NativeSessions)
        }));

        // D1a: the activity rail's top group is Explorer/Source Control/
        // Agents/Board only -- Workspaces has no rail button anymore (it
        // folds into Explorer's header in D1b). Agents stays reachable;
        // Workspaces and NativeSessions do not.
        app.sidebar_presentation = SidebarPresentation::Activity;
        app.control_section = ControlSection::Agents;
        let activity = render(&app, &mut buf);
        // FIX3: the rail's own Agents button is `ActivitySection` now,
        // not `RosterMode` -- see `activity_rail_hit_regions_dispatch_
        // the_same_actions_as_before`'s own doc comment for the full
        // reasoning; the Split/Modal roster header checked just above and
        // below still uses `RosterMode` unchanged, that surface was never
        // touched.
        assert!(activity.hits.iter().any(|hit| hit.target == HitTarget::ActivitySection(ControlSection::Agents)));
        assert!(!activity.hits.iter().any(|hit| {
            hit.target == HitTarget::RosterMode(RosterMode::Workspaces)
        }));
        assert!(!activity.hits.iter().any(|hit| {
            hit.target == HitTarget::RosterMode(RosterMode::NativeSessions)
        }));

        // The Modal-placement Settings tab strip is unaffected by the rail
        // redesign -- it still lists all of ControlSection::ALL, Workspaces
        // included.
        app.menu_placement = MenuPlacement::Modal;
        app.focus = Focus::Settings;
        let modal = render(&app, &mut buf);
        assert!([RosterMode::Agents, RosterMode::Workspaces]
            .iter()
            .all(|mode| modal.hits.iter().any(|hit| hit.target == HitTarget::RosterMode(*mode))));
        assert!(!modal.hits.iter().any(|hit| {
            hit.target == HitTarget::RosterMode(RosterMode::NativeSessions)
        }));
    }

