    #[test]
    fn workspace_files_render_create_actions_and_entry_dialog() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.apply_workspace_inspection("node-a".to_owned(), inspection());
        app.sidebar_mode = SidebarMode::Files;
        let mut files = TerminalBuffer::new(100, 24);

        let files_layout = render(&app, &mut files);

        assert!(files_layout.hits.iter().any(|hit| hit.target == HitTarget::NewFile));
        assert!(files_layout
            .hits
            .iter()
            .any(|hit| hit.target == HitTarget::NewDirectory));
        // `fixture()` defaults to `RailIcons::Sixel` -- NewFile/NewDirectory
        // now paint a compact baked icon there (see
        // `workspace_files_create_buttons_render_a_compact_icon_per_tier`
        // for the full 2-tier coverage), not the old literal "[+.]"/"[+>]"
        // text; that text is still exactly what `RailIcons::Ascii` paints.
        let files_text = buffer_text(&files);
        assert!(!files_text.contains("[+.]") && !files_text.contains("[+>]"), "{files_text}");
        assert!(!files_text.contains("+file") && !files_text.contains("+dir"), "{files_text}");
        assert!(
            files_layout.sixel_icons.iter().any(|placement| placement.icon == icons::IconId::NewFile),
            "{:?}",
            files_layout.sixel_icons,
        );
        assert!(
            files_layout.sixel_icons.iter().any(|placement| placement.icon == icons::IconId::NewFolder),
            "{:?}",
            files_layout.sixel_icons,
        );

        app.create_workspace_entry = Some(CreateWorkspaceEntryDialog {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            kind: WorkspaceEntryKind::File,
            path: "notes/new.md".to_owned(),
            pending: false,
            token: 0,
            error: None,
        });
        app.focus = Focus::CreateWorkspaceEntry;
        let mut narrow = TerminalBuffer::new(48, 10);
        let mut modal_layout = LayoutRects::default();

        render_create_workspace_entry(
            &app,
            Rect::new(0, 0, 48, 10),
            &mut narrow,
            &mut modal_layout,
            Theme::for_mode(app.color_mode),
        );

        for target in [
            HitTarget::CreateWorkspaceEntrySubmit,
            HitTarget::CreateWorkspaceEntryCancel,
            HitTarget::ModalClose,
        ] {
            let hit = modal_layout
                .hits
                .iter()
                .find(|hit| hit.target == target)
                .expect("create dialog action hit");
            assert!(hit.rect.right() <= narrow.width());
            assert!(hit.rect.bottom() <= narrow.height());
        }
        let text = buffer_text(&narrow);
        assert!(text.contains("notes/new.md"));
        assert!(text.contains("target"));
        assert!(text.contains("No overwrite"));
    }

    /// The control-plane strip's own NewFile/NewDirectory buttons: a
    /// strip-tier baked icon (`icons::sixel_strip` -- see `render_
    /// control_strip_button`'s own doc comment) in `Sixel` mode, and a
    /// short 2-char catalog label (`icons::ascii`) in `Ascii` mode, NOT
    /// the pre-strip bracket text -- the strip's fixed 2-cell body cannot
    /// fit `"[+.]"`/`"[+>]"`. The load-bearing invariant carried over
    /// from the pre-strip version: their own [`HitRegion`] rect is
    /// BYTE-IDENTICAL across both tiers (same position, same target). The
    /// sixel tier's own asset
    /// also resolves to `GateActive` (this fixture's `PtyColorMode::
    /// GateOverride`) -- cause 1's fix, see `icons::SixelVariant`'s own
    /// doc comment.
    #[test]
    fn workspace_files_create_buttons_render_in_the_control_strip_per_tier() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.apply_workspace_inspection("node-a".to_owned(), inspection());
        app.sidebar_mode = SidebarMode::Files;

        let hit_rect = |layout: &LayoutRects, target: HitTarget| {
            layout
                .hits
                .iter()
                .find(|hit| hit.target == target)
                .unwrap_or_else(|| panic!("missing hit for {target:?}"))
                .rect
        };

        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut sixel_buf = TerminalBuffer::new(100, 24);
        let sixel_layout = render(&app, &mut sixel_buf);
        let new_file_rect = hit_rect(&sixel_layout, HitTarget::NewFile);
        let new_directory_rect = hit_rect(&sixel_layout, HitTarget::NewDirectory);
        assert_eq!(new_file_rect.height, CONTROL_STRIP_BUTTON_ROWS);
        assert_eq!(new_file_rect.width, CONTROL_STRIP_BUTTON_WIDTH);
        assert_eq!(new_directory_rect.height, CONTROL_STRIP_BUTTON_ROWS);
        assert!(sixel_layout.sixel_icons.iter().any(|placement| {
            placement.icon == icons::IconId::NewFile
                && placement.size == crate::app::SixelIconSize::Strip
                && placement.variant == icons::SixelVariant::GateActive
                && new_file_rect.contains(placement.rect.x, placement.rect.y)
        }));
        assert!(sixel_layout.sixel_icons.iter().any(|placement| {
            placement.icon == icons::IconId::NewFolder
                && placement.size == crate::app::SixelIconSize::Strip
                && new_directory_rect.contains(placement.rect.x, placement.rect.y)
        }));
        let sixel_text = buffer_text(&sixel_buf);
        assert!(!sixel_text.contains("[+.]") && !sixel_text.contains("[+>]"), "{sixel_text}");

        app.rail_icons = RailIcons::Ascii;
        let mut ascii_buf = TerminalBuffer::new(100, 24);
        let ascii_layout = render(&app, &mut ascii_buf);
        assert_eq!(hit_rect(&ascii_layout, HitTarget::NewFile), new_file_rect);
        assert_eq!(hit_rect(&ascii_layout, HitTarget::NewDirectory), new_directory_rect);
        assert!(ascii_layout.sixel_icons.is_empty());
        let ascii_text = buffer_text(&ascii_buf);
        assert!(!ascii_text.contains("[+.]") && !ascii_text.contains("[+>]"), "{ascii_text}");
        assert!(rect_text(&ascii_buf, new_file_rect).contains(icons::ascii(icons::IconId::NewFile)));
        assert!(rect_text(&ascii_buf, new_directory_rect).contains(icons::ascii(icons::IconId::NewFolder)));
    }

    /// The actual fix, strip's own analogue of `activity_rail_column_
    /// inherits_the_panel_background_in_every_mode`: the gap column
    /// BETWEEN two strip buttons and a button's own body must read as
    /// the EXACT SAME background in `PtyColorMode::Inherited` (`Color::
    /// Reset`, the terminal's own real background) -- an un-selected
    /// strip button is not a real, deliberate state the owner needs to
    /// see, so it states no background distinct from its own row.
    /// Stating an explicit `SIDEBAR_BG`/`ACTIVE_BG` pair here used to be
    /// this crate's own plate defect: `SIDEBAR_BG` reads as a visibly
    /// LIGHTER column than the terminal's own real (usually darker)
    /// background, and painting `ACTIVE_BG` under every button regardless
    /// of selection compounded it one level further.
    #[test]
    fn control_strip_row_and_button_body_inherit_the_same_background_in_inherited_mode() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.apply_workspace_inspection("node-a".to_owned(), inspection());
        app.sidebar_mode = SidebarMode::Files;
        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut buf = TerminalBuffer::new(100, 24);
        let layout = render(&app, &mut buf);

        let new_file_rect = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::NewFile)
            .expect("explorer control-strip NewFile button")
            .rect;
        // One column past NewFile's own body, inside the strip's own
        // `CONTROL_STRIP_BUTTON_GAP` before NewFolder starts -- never
        // painted by any button's own body fill.
        let gap_cell = buf.get(new_file_rect.right(), new_file_rect.y);
        let body_cell = buf.get(new_file_rect.x, new_file_rect.y);
        assert_eq!(gap_cell.style.bg, Color::Reset, "the gap between two strip buttons must inherit the terminal's own real background in Inherited mode");
        assert_eq!(body_cell.style.bg, Color::Reset, "an un-selected strip button's own body must be indistinguishable from the row around it");
    }

