    /// FIX4: the gallery renders the expected 12-icon grid in each of the
    /// two `RailIcons` tiers (the sixel tier places three DIFFERENTLY
    /// sized sixel icons per row -- the strip/rail/gallery pixel sizes --
    /// the ascii tier paints that same tier's own rendering everywhere,
    /// per `render_icon_gallery`'s own doc comment), and its tab opens
    /// and closes like any other surface tab.
    #[test]
    fn icon_gallery_renders_the_expected_grid_in_each_tier_and_its_tab_opens_and_closes() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.focus = Focus::Settings;
        assert_eq!(app.reduce(crate::UiKey::Char('g')), AppAction::None);
        assert_eq!(app.surface.active_tab(), Some(&SurfaceTab::IconGallery));
        assert!(app.surface.all_tabs().iter().any(|tab| **tab == SurfaceTab::IconGallery));
        // Opening a tab APPENDS it (same precedent as `SurfaceTab::
        // AgentBoard`) -- the fixture's own PTY tab is still there too.
        assert!(app.surface.all_tabs().iter().any(|tab| matches!(tab, SurfaceTab::Pty(_))));

        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut sixel_buf = TerminalBuffer::new(120, 40);
        let sixel_layout = render(&app, &mut sixel_buf);
        for size in [SixelIconSize::Strip, SixelIconSize::Rail, SixelIconSize::Gallery] {
            assert!(
                sixel_layout.sixel_icons.iter().any(|placement| placement.icon == icons::IconId::Files && placement.size == size),
                "missing {size:?} gallery placement for Files: {:?}",
                sixel_layout.sixel_icons,
            );
        }
        let sixel_text = rect_text(&sixel_buf, sixel_layout.viewport);
        assert!(sixel_text.contains("Files"), "row must be labelled with the icon's own name: {sixel_text:?}");
        assert!(sixel_text.contains("ascii"), "header must label the dedicated comparison column: {sixel_text:?}");
        // The dedicated Ascii column is UNCONDITIONAL (always "for
        // comparison", regardless of the current global tier -- see
        // `render_icon_gallery`'s own doc comment), so the ascii label is
        // present here too, alongside the three real sixel placements
        // just asserted above.
        assert!(sixel_text.contains(icons::ascii(icons::IconId::Files)), "the dedicated ascii column must still paint the Files label in sixel tier: {sixel_text:?}");

        app.rail_icons = RailIcons::Ascii;
        let mut ascii_buf = TerminalBuffer::new(120, 40);
        let ascii_layout = render(&app, &mut ascii_buf);
        assert!(ascii_layout.sixel_icons.is_empty(), "ascii tier must not place any sixel icon: {:?}", ascii_layout.sixel_icons);
        let ascii_text = rect_text(&ascii_buf, ascii_layout.viewport);
        assert!(ascii_text.contains(icons::ascii(icons::IconId::Files)), "ascii tier must paint the Files ascii label: {ascii_text:?}");

        // Closes like any other tab (`Ctrl+W`'s own production handler).
        app.close_selected_tab();
        assert!(!app.surface.all_tabs().iter().any(|tab| **tab == SurfaceTab::IconGallery));
        assert!(app.surface.all_tabs().iter().any(|tab| matches!(tab, SurfaceTab::Pty(_))));
    }

    /// This task's own brief: "each row shows the same IconId in BOTH
    /// families side by side at each tier ... Label the columns by
    /// family." Checks the header text names both families at every
    /// tier, that a mapped icon (`Files`) gets TWO distinct sixel
    /// placements per tier (one `Codicons`, one `Lucide`, at different
    /// columns), and that a documented mapping gap (`CircleFilled`) gets
    /// exactly one (`Codicons` only) plus a visible `n/a` label instead
    /// of a silently-missing Lucide swatch.
    #[test]
    fn icon_gallery_shows_both_families_side_by_side_at_every_tier() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.focus = Focus::Settings;
        assert_eq!(app.reduce(crate::UiKey::Char('g')), AppAction::None);
        assert_eq!(app.rail_icons, RailIcons::Sixel);

        // The gallery lists the WHOLE catalog, which no terminal shows at
        // once, so the two halves of this check need two renders: the
        // rows near the top unscrolled, and the Lucide gap icons after
        // scrolling far enough to reach them. A scroll past the end
        // clamps, so this asks for the last page without computing it.
        let mut buf = TerminalBuffer::new(160, 70);
        let layout = render(&app, &mut buf);
        let mut tail_app = app.clone();
        tail_app.icon_gallery_scroll = u16::MAX;
        let mut tail_buf = TerminalBuffer::new(160, 70);
        let tail_layout = render(&tail_app, &mut tail_buf);
        // Same whole-viewport text blob `icon_gallery_renders_the_
        // expected_grid_in_each_tier_and_its_tab_opens_and_closes` already
        // scans above -- the gallery's own header row sits below the pane's
        // tab strip, not at the viewport's own row 0.
        let header = rect_text(&buf, layout.viewport);
        assert!(header.contains("Cod"), "header must label the codicons column: {header:?}");
        assert!(header.contains("Luc"), "header must label the lucide column: {header:?}");

        for size in [SixelIconSize::Strip, SixelIconSize::Rail, SixelIconSize::Gallery] {
            let files_placements: Vec<_> = layout
                .sixel_icons
                .iter()
                .filter(|placement| placement.icon == icons::IconId::Files && placement.size == size)
                .collect();
            assert_eq!(files_placements.len(), 2, "{size:?}: Files must get exactly one Codicons + one Lucide placement: {files_placements:?}");
            assert!(
                files_placements.iter().any(|p| p.family == IconFamily::Codicons),
                "{size:?}: missing the Codicons placement for Files"
            );
            assert!(
                files_placements.iter().any(|p| p.family == IconFamily::Lucide),
                "{size:?}: missing the Lucide placement for Files"
            );
            assert_ne!(
                files_placements[0].rect.x, files_placements[1].rect.x,
                "{size:?}: the two family placements must sit in different columns, not overlap"
            );

            // `CircleFilled` is a documented Lucide mapping gap (see
            // `icons.rs`'s own "Lucide" doc section) -- exactly one
            // placement (Codicons), never a silently-missing Lucide one.
            let gap_placements: Vec<_> = tail_layout
                .sixel_icons
                .iter()
                .filter(|placement| placement.icon == icons::IconId::RunAll && placement.size == size)
                .collect();
            assert_eq!(gap_placements.len(), 1, "{size:?}: RunAll must get exactly one placement (Codicons only): {gap_placements:?}");
            assert_eq!(gap_placements[0].family, IconFamily::Codicons);
        }
        let gallery_text = rect_text(&tail_buf, tail_layout.viewport);
        assert!(gallery_text.contains("n/a"), "the RunAll gap row must show a visible n/a label: {gallery_text:?}");
    }

    /// FIX1's own reservation generalized: the icon gallery is a
    /// scrollable, often bottom-most viewport tab, so it can reach the
    /// terminal's true last row exactly like the activity rail could
    /// (see `render_icon_gallery`'s own `usable_bottom` doc comment).
    /// Sweeps a range of terminal heights, scrolled all the way to the
    /// gallery's own bottom each time, and asserts no gallery-tier sixel
    /// placement's own bottom row is ever the terminal's last row.
    #[test]
    fn icon_gallery_sixel_rows_never_land_on_the_terminals_last_row_even_fully_scrolled() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.focus = Focus::Settings;
        assert_eq!(app.reduce(crate::UiKey::Char('g')), AppAction::None);
        assert_eq!(app.rail_icons, RailIcons::Sixel);

        for height in 14..40 {
            app.icon_gallery_scroll = u16::MAX;
            let mut buf = TerminalBuffer::new(120, height);
            let layout = render(&app, &mut buf);
            for placement in layout.sixel_icons.iter().filter(|placement| placement.size == SixelIconSize::Gallery) {
                assert!(
                    placement.rect.bottom() < buf.height(),
                    "height={height}: gallery sixel placement {placement:?} must never reach the terminal's last row",
                );
            }
        }
    }

    /// DEFECT 2 (owner: "в иконка галери иконки вылазят за предел
    /// панели (ну прямо на рамку)" -- gallery icons overflow the panel,
    /// right onto its frame): `client::flush_sixel_icon_into` always
    /// paints a sixel placement at its OWN tier's fixed native pixel
    /// size, ignoring `rect.width`/`rect.height` entirely -- see
    /// `render_gallery_size_swatch`'s own doc comment for the full
    /// mechanism. The escaping edge was NOT the pane's bottom row (that
    /// was already correctly guarded, see `icon_gallery_sixel_rows_
    /// never_land_on_the_terminals_last_row_even_fully_scrolled` above)
    /// -- it was the RIGHT edge of the Gallery-tier column: the former
    /// `render_gallery_size_swatch` shrank the RESERVED rect to whatever
    /// room a narrow pane left, which looked safe (the bookkeeping rect
    /// always landed inside the pane), but `flush_sixel_icon_into` still
    /// painted the full, un-shrunk asset at that rect's origin -- the
    /// real pixels beyond the shrunk width bled straight past the pane's
    /// own edge onto its frame.
    ///
    /// Sweeping the sidebar width (holding the terminal width fixed and
    /// comfortably above `render`'s own 56-column floor) walks the
    /// gallery pane's own viewport width through every value, including
    /// the ones where the Gallery-tier column's own available width
    /// lands strictly between 1 and `GALLERY_SIXEL_ICON_CELLS_WIDE - 1`
    /// -- the exact reproduction. Every EMITTED placement must be its
    /// own tier's exact native size (the fix: too-narrow means dropped,
    /// never shrunk) and must stay inside the pane's own content rect.
    #[test]
    fn gallery_swatch_drops_a_placement_that_does_not_fit_its_own_column_instead_of_shrinking_it() {
        let mut app = fixture(PtyColorMode::GateOverride);
        app.surface.open_in_focused(SurfaceTab::IconGallery);
        app.sidebar_collapsed = false;
        assert_eq!(app.rail_icons, RailIcons::Sixel);

        let native_size = |size: SixelIconSize| -> (u16, u16) {
            match size {
                SixelIconSize::Strip => {
                    (icons::STRIP_SIXEL_ICON_CELLS_WIDE, icons::STRIP_SIXEL_ICON_CELLS_TALL)
                }
                SixelIconSize::Rail => (icons::SIXEL_ICON_CELLS_WIDE, icons::SIXEL_ICON_CELLS_TALL),
                SixelIconSize::Gallery => {
                    (icons::GALLERY_SIXEL_ICON_CELLS_WIDE, icons::GALLERY_SIXEL_ICON_CELLS_TALL)
                }
                SixelIconSize::Compact => {
                    (icons::COMPACT_SIXEL_ICON_CELLS_WIDE, icons::COMPACT_SIXEL_ICON_CELLS_TALL)
                }
            }
        };

        // 63 == the gallery's own total column span (name + 4 gaps +
        // strip + rail + gallery + ascii, see `render_icon_gallery`'s own
        // `headers` construction) -- below it, at least one column no
        // longer has its full width to work with.
        let mut narrowed_below_full_column_width = false;
        for sidebar_width in 18..70u16 {
            app.sidebar_width = sidebar_width;
            let mut buf = TerminalBuffer::new(100, 30);
            let layout = render(&app, &mut buf);
            let Some(pane) = layout.surface_panes.first() else { continue };
            if pane.viewport.width < 63 {
                narrowed_below_full_column_width = true;
            }
            for placement in layout.sixel_icons.iter() {
                if placement.rect.intersect(pane.frame).is_empty() {
                    continue;
                }
                let (native_w, native_h) = native_size(placement.size);
                assert_eq!(
                    (placement.rect.width, placement.rect.height),
                    (native_w, native_h),
                    "sidebar_width={sidebar_width}: {:?} placement {:?} was emitted smaller than \
                     its own tier's native size -- client::flush_sixel_icon_into paints the full \
                     asset regardless, so this bleeds real pixels past its own reserved rect",
                    placement.icon, placement.rect,
                );
                assert!(
                    placement.rect.right() <= pane.viewport.right()
                        && placement.rect.bottom() <= pane.viewport.bottom(),
                    "sidebar_width={sidebar_width}: placement {:?} escapes the pane's own content rect {:?}",
                    placement.rect, pane.viewport,
                );
            }
        }
        assert!(
            narrowed_below_full_column_width,
            "this sweep must actually narrow the gallery pane below its own full column width \
             (63 cells) for the test to mean anything",
        );
    }

    /// The actual OSC 11 background fix, the gallery's own analogue of
    /// `activity_rail_column_and_inactive_button_body_share_the_real_
    /// background_in_inherited_mode`: a swatch's own reserved column is
    /// wider than its icon's own footprint (see `render_gallery_size_
    /// swatch`'s own doc comment), so the padding around the icon within
    /// that same column and the icon's own reserved cells must be the
    /// EXACT SAME `Color::Reset` in `PtyColorMode::Inherited` -- the
    /// gallery is a read-only comparison grid with no selected state at
    /// all, so nothing about it should ever stand out from the pane
    /// around it. Stating an explicit `SIDEBAR_BG`/`ACTIVE_BG` pair here
    /// (the previous, retired fix) is exactly the plate defect this test
    /// now guards against.
    #[test]
    fn gallery_swatch_column_and_icon_share_the_real_background_in_inherited_mode() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.surface.open_in_focused(SurfaceTab::IconGallery);
        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut buf = TerminalBuffer::new(120, 40);
        let layout = render(&app, &mut buf);

        let strip_placement = layout
            .sixel_icons
            .iter()
            .find(|placement| placement.size == SixelIconSize::Strip)
            .expect("the gallery's own Strip-size column must place at least one swatch");
        // One column past the icon's own footprint, still inside the
        // SAME (wider) swatch column -- `SIZE_COL_WIDTH` (12) is well
        // past `STRIP_SIXEL_ICON_CELLS_WIDE` (2), and this row's own
        // Rail-size column does not start until well past that either.
        let padding_x = strip_placement.rect.right();
        let padding_cell = buf.get(padding_x, strip_placement.rect.y);
        let icon_cell = buf.get(strip_placement.rect.x, strip_placement.rect.y);
        assert_eq!(padding_cell.style.bg, Color::Reset, "the swatch column's own padding around the icon must inherit the terminal's own real background in Inherited mode");
        assert_eq!(icon_cell.style.bg, Color::Reset, "the icon's own reserved cells must be indistinguishable from the padding around them, not a plate");
    }

    /// Reproduces the reported defect exactly: the icon gallery's own
    /// sixel placements (base content, painted first) must not survive
    /// underneath an overlay drawn on top of them -- a sixel is raster
    /// painted directly over the terminal with no z-order of its own (see
    /// `LayoutRects::sixel_icons`'s own doc comment), so nothing but
    /// `render::render`'s own end-of-frame occlusion pass stops the old
    /// ghosting/repaint-through-the-modal bug from recurring. Closing the
    /// overlay afterward must bring the very same base placements back --
    /// they are occluded for one frame, never actually lost.
    #[test]
    fn overlay_occludes_covered_base_sixel_placements_and_releases_them_on_close() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.surface.open_in_focused(SurfaceTab::IconGallery);
        assert_eq!(app.rail_icons, RailIcons::Sixel);

        // Baseline: the gallery alone, no overlay -- proves real
        // placements exist before asserting they get occluded.
        let mut baseline_buf = TerminalBuffer::new(120, 40);
        let baseline = render(&app, &mut baseline_buf);
        assert!(
            !baseline.sixel_icons.is_empty(),
            "the gallery must place sixel icons for this test to mean anything",
        );

        app.focus = Focus::Spawn;
        app.spawn = Some(SpawnDialog {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            provider: provider("codex"),
            target: LaunchTarget::NewLinkedWorktree,
            profile_id: "default".to_owned(),
            worktree_profile_id: String::new(),
            bundle_id: String::new(),
            context_mode: LaunchContextMode::None,
            field: LaunchField::Workspace,
        });
        let mut covered_buf = TerminalBuffer::new(120, 40);
        let covered = render(&app, &mut covered_buf);

        // The modal actually has to land on top of at least one baseline
        // placement, or the assertion below proves nothing.
        assert!(
            baseline.sixel_icons.iter().any(|placement| {
                !placement.rect.intersect(covered.spawn_modal).is_empty()
            }),
            "spawn modal {:?} must cover at least one gallery placement: {:?}",
            covered.spawn_modal, baseline.sixel_icons,
        );
        // Only BASELINE (background gallery) placements are required to
        // have been occluded here -- the spawn dialog now paints its own
        // Browse/Configure actions as compact icons (see `render_spawn`),
        // and those legitimately live INSIDE `covered.spawn_modal`, on
        // top of it, same as any other modal content. Filtering to
        // placements the gallery baseline already had keeps this
        // assertion about occlusion of the covered BASE layer, not a
        // blanket "nothing may ever paint inside this modal" claim.
        assert!(
            covered.sixel_icons.iter()
                .filter(|placement| baseline.sixel_icons.contains(placement))
                .all(|placement| placement.rect.intersect(covered.spawn_modal).is_empty()),
            "no surviving BASE placement may intersect the spawn modal: {:?} vs {:?}",
            covered.sixel_icons, covered.spawn_modal,
        );

        // Close it: the same base placements repaint, unchanged -- they
        // were occluded for one frame, not discarded.
        app.focus = Focus::Viewport;
        app.spawn = None;
        let mut reopened_buf = TerminalBuffer::new(120, 40);
        let reopened = render(&app, &mut reopened_buf);
        assert_eq!(reopened.sixel_icons, baseline.sixel_icons);
    }

    /// Placements an overlay draws AS PART OF ITS OWN content must
    /// survive that same overlay's own occlusion check -- the case the
    /// naive "drop anything whose rect sits inside a registered overlay
    /// rect" version of this fix would get wrong. Reuses a real, already-
    /// shipped example: the Settings "control" modal (Modal placement)
    /// hosts the Agents roster directly inside itself, control strip and
    /// all (see `render_settings`'s own `ControlSection::Agents`
    /// dispatch) -- its `AddAgent` strip icon sits geometrically INSIDE
    /// `layout.control_modal`'s own rect, and must still be there after
    /// the end-of-frame occlusion pass.
    #[test]
    fn overlay_hosted_icon_survives_its_own_overlays_occlusion() {
        let mut app = fixture(PtyColorMode::Inherited);
        app.menu_placement = MenuPlacement::Modal;
        app.control_section = ControlSection::Agents;
        app.roster_mode = RosterMode::Agents;
        app.focus = Focus::Settings;
        // `control_modal_default_size` sizes the modal to this fixture's
        // own single agent row (height 7), which leaves the roster's own
        // header (2 rows) and control strip (`control_strip_fits` needs
        // >= 5) no room at all -- explicit size, same precedent as
        // `control_modal_is_opaque_and_reuses_operational_sections`, so
        // the strip this test is actually about has somewhere to render.
        app.control_modal_size = Some((100, 20));
        assert_eq!(app.rail_icons, RailIcons::Sixel);
        let mut buf = TerminalBuffer::new(120, 40);

        let layout = render(&app, &mut buf);

        // The containment clause disambiguates from `render_tabs`'s own
        // AddTab strip icon -- the SAME `IconId::Add` + `SixelIconSize::
        // Strip` pair, drawn unconditionally in every chrome including
        // `MenuPlacement::Modal` (see that fn's own always-run call in
        // `render::render`) -- so this only ever matches the Agents
        // roster's OWN AddAgent icon, the one this test is actually
        // about, never whichever `IconId::Add` placement happens to sit
        // first in `sixel_icons` this frame.
        let add_agent = layout
            .sixel_icons
            .iter()
            .find(|placement| {
                placement.icon == icons::IconId::Add
                    && placement.size == SixelIconSize::Strip
                    && layout.control_modal.contains(placement.rect.x, placement.rect.y)
            })
            .unwrap_or_else(|| {
                panic!(
                    "the Agents roster's own AddAgent strip icon must survive inside {:?}: {:?}",
                    layout.control_modal, layout.sixel_icons,
                )
            });
        assert!(
            layout.control_modal.contains(add_agent.rect.x, add_agent.rect.y),
            "the surviving icon must actually sit inside its own overlay's rect: {:?} vs {:?}",
            add_agent.rect, layout.control_modal,
        );
    }

    /// A sixel cannot be clipped to a sub-rect, so an overlay covering
    /// only PART of a placement's own rect must still drop it whole, not
    /// leave a corner peeking out from under the modal. Exercises `drop_
    /// sixel_icons_covered_by_overlays` directly for exact control over
    /// the overlap geometry -- see that fn's own doc comment for the
    /// `drawn_before` index-cutoff mechanism this also implicitly proves
    /// (the placement here predates the overlay, so it is a candidate at
    /// all).
    #[test]
    fn overlay_partially_covering_a_placement_drops_it_whole() {
        let mut layout = LayoutRects::default();
        layout.sixel_icons.push(SixelIconPlacement {
            icon: icons::IconId::Files,
            rect: Rect::new(10, 10, 4, 2),
            variant: icons::SixelVariant::GateActive,
            size: SixelIconSize::Rail,
            family: IconFamily::Codicons,
        });
        // Overlaps only the placement's own right half (x=12..14 of the
        // placement's own x=10..14), same two rows.
        layout.note_overlay(Rect::new(12, 10, 20, 2));

        drop_sixel_icons_covered_by_overlays(&mut layout);

        assert!(layout.sixel_icons.is_empty(), "{:?}", layout.sixel_icons);
    }

