    #[test]
    fn file_selection_predicate_reuses_one_precomputed_utf8_byte_range() {
        let mut editor = crate::text_editor::TextEditor::from_text("zero\nЖ🙂tail\nlast".to_owned())
            .expect("editor");
        editor
            .start_selection(crate::text_editor::CursorPosition { line: 1, column: 1 })
            .expect("selection start");
        editor
            .update_selection(crate::text_editor::CursorPosition { line: 2, column: 1 })
            .expect("selection end");

        let selection = editor.selection_range().expect("byte range");
        let second_line_start = editor.line_byte_start(1).expect("second line start");
        let third_line_start = editor.line_byte_start(2).expect("third line start");

        assert!(!file_byte_is_selected(Some(&selection), second_line_start));
        assert!(file_byte_is_selected(Some(&selection), second_line_start + "Ж".len()));
        assert!(file_byte_is_selected(Some(&selection), third_line_start));
        assert!(!file_byte_is_selected(Some(&selection), third_line_start + 1));
        assert!(!file_byte_is_selected(None, second_line_start + "Ж".len()));
    }

    #[test]
    fn file_surface_separates_global_controls_pane_title_actions_and_scrollbar() {
        let mut app = fixture(PtyColorMode::GateOverride);
        let key = crate::app::WorkspaceFileTabKey {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            path: repository_path("src/lib.rs"),
        };
        let text = (0..60)
            .map(|line| format!("pub const LINE_{line}: usize = {line};"))
            .collect::<Vec<_>>()
            .join("\n");
        app.file_tabs.insert(
            key.clone(),
            WorkspaceFileTabView {
                editor: crate::text_editor::TextEditor::from_text(text).unwrap(),
                state: WorkspaceFileState::Ready,
                edit_mode: false,
                request_token: 1,
                inline_history: None,
            },
        );
        app.surface.open_in_focused(SurfaceTab::File(key.clone()));
        let pane_id = app.surface.focused;
        let mut buffer = TerminalBuffer::new(120, 24);

        let layout = render(&app, &mut buffer);
        let top = (layout.tabs.x..layout.tabs.right())
            .map(|column| buffer.get(column, layout.tabs.y).symbol.as_str())
            .collect::<String>();
        let header = layout.surface_panes[0].header;
        let header_text = (header.x..header.right())
            .map(|column| buffer.get(column, header.y).symbol.as_str())
            .collect::<String>();
        let actions_text = (header.x..header.right())
            .map(|column| buffer.get(column, header.y + 1).symbol.as_str())
            .collect::<String>();

        // `fixture()` defaults to `RailIcons::Sixel` -- AddTab/
        // LayoutMenuToggle now paint real STRIP-tier icons at the very
        // start of this row (see `tab_strip_add_and_layout_controls_
        // render_strip_icons_in_sixel_tier` for that coverage), not the
        // old literal `" +  [#] "` text; that text is still exactly what
        // `RailIcons::Ascii` paints (see `tab_strip_ascii_tier_keeps_its_
        // old_text_and_both_controls_keep_their_hit_targets`).
        assert!(!top.starts_with(" +  [#] "), "{top:?}");
        assert!(
            layout.hits.iter().any(|hit| {
                hit.target == HitTarget::AddTab && layout.tabs.contains(hit.rect.x, hit.rect.y)
            }),
            "the tab strip must still carry its own AddTab control: {top:?}",
        );
        assert!(
            layout.hits.iter().any(|hit| {
                hit.target == HitTarget::LayoutMenuToggle && layout.tabs.contains(hit.rect.x, hit.rect.y)
            }),
            "the tab strip must still carry its own LayoutMenuToggle control: {top:?}",
        );
        // `fixture()` defaults to (Sidebar, Split), which has no activity
        // rail at all -- the tab strip's own gear (an icon, never the
        // rejected "[S]" bracket text, see `render_tabs`'s own FIX5
        // comment) is this chrome's only mouse entry to Settings, so it
        // MUST be here, unlike (Sidebar, Activity) where the rail alone
        // carries it (see `sidebar_gear_opens_only_compact_positioned_
        // settings`).
        assert!(!top.contains("[S]"), "{top:?}");
        assert!(
            layout.hits.iter().any(|hit| {
                hit.target == HitTarget::ActivitySection(ControlSection::Settings)
                    && layout.tabs.contains(hit.rect.x, hit.rect.y)
            }),
            "the tab strip must carry the Settings gear in a rail-less chrome",
        );
        assert!(!top.contains(" file "), "{top:?}");
        assert!(header_text.contains(" lib.rs "), "{header_text:?}");
        assert!(!header_text.contains(" file "), "{header_text:?}");
        // `RailIcons::Sixel` (the default here) draws these four actions
        // as compact icons, not the old bracketed text -- check the icon
        // placements landing on the actions row instead of `actions_text`
        // (see `folder_browser_parent_use_and_cancel_buttons_render_a_
        // compact_icon_per_tier` for the same per-tier assertion shape;
        // the ASCII-mode fallback keeping the original bracket text is
        // covered separately by `tab_strip_ascii_tier_keeps_its_old_text_
        // and_both_controls_keep_their_hit_targets`'s own sibling
        // coverage for this row).
        let actions_row_has_icon = |icon: icons::IconId| {
            layout.sixel_icons.iter().any(|placement| {
                placement.icon == icon && placement.rect.y == header.y + 1
            })
        };
        assert!(actions_row_has_icon(icons::IconId::History), "{actions_text:?}");
        assert!(actions_row_has_icon(icons::IconId::Diff), "{actions_text:?}");
        assert!(actions_row_has_icon(icons::IconId::Edit), "{actions_text:?}");
        assert!(actions_row_has_icon(icons::IconId::Save), "{actions_text:?}");
        for target in [
            HitTarget::FileHistory(pane_id),
            HitTarget::FileChanges(pane_id),
            HitTarget::FileEdit(pane_id),
            HitTarget::FileSave(pane_id),
            HitTarget::FileScrollbar(pane_id),
        ] {
            assert!(layout.hits.iter().any(|hit| hit.target == target), "{target:?}");
        }
        let scrollbar = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::FileScrollbar(pane_id))
            .unwrap()
            .rect;
        assert_eq!(scrollbar.x, layout.surface_panes[0].viewport.right() - 1);
        assert_eq!(buffer.get(scrollbar.x, scrollbar.y).symbol, "#");
        let history_hit = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::FileHistory(pane_id))
            .unwrap()
            .rect;
        let changes_hit = layout
            .hits
            .iter()
            .find(|hit| hit.target == HitTarget::FileChanges(pane_id))
            .unwrap()
            .rect;
        let mut changes_app = app.clone();
        changes_app.layout = layout.clone();
        let crate::app::AppAction::ReadGitHistory {
            path: Some(changes_path),
            ..
        } = changes_app.click(changes_hit.x, changes_hit.y)
        else {
            panic!("Changes hit must win over the pane header");
        };
        assert_eq!(changes_path.as_utf8(), Some("src/lib.rs"));
        assert!(matches!(
            changes_app.file_tabs[&key]
                .inline_history
                .as_ref()
                .and_then(|history| history.pending_diff.as_ref()),
            Some(crate::app::WorkspaceGitDiffTarget::Working { path: Some(ref path) })
                if path.as_utf8() == Some("src/lib.rs")
        ));
        assert!(changes_app.git_tabs.is_empty());

        app.layout = layout.clone();
        let crate::app::AppAction::ReadGitHistory {
            path: Some(history_path),
            ..
        } = app.click(history_hit.x, history_hit.y)
        else {
            panic!("History hit must win over the pane header");
        };
        assert_eq!(history_path.as_utf8(), Some("src/lib.rs"));
        let history_layout = render(&app, &mut buffer);
        let history_header = history_layout.surface_panes[0].header;
        let history_header_text = (history_header.x..history_header.right())
            .map(|column| buffer.get(column, history_header.y).symbol.as_str())
            .collect::<String>();
        let history_actions_text = (history_header.x..history_header.right())
            .map(|column| buffer.get(column, history_header.y + 1).symbol.as_str())
            .collect::<String>();
        assert!(history_header_text.contains(" lib.rs "), "{history_header_text:?}");
        assert!(!history_header_text.contains("commits"), "{history_header_text:?}");
        // `RailIcons::Sixel` draws `[Source]` as a compact `File` icon,
        // not the old bracket text -- see this test's own earlier
        // `actions_row_has_icon` assertion for the same per-tier shape.
        assert!(
            history_layout.sixel_icons.iter().any(|placement| {
                placement.icon == icons::IconId::File && placement.rect.y == history_header.y + 1
            }),
            "{history_actions_text:?}",
        );
        assert!(history_actions_text.contains("commits | Up/Down"), "{history_actions_text:?}");
        assert!(buffer_text(&buffer).contains("loading file history"));
        assert!(app.git_tabs.is_empty());
    }

    #[test]
    fn empty_surface_has_only_global_controls_and_no_empty_label() {
        let mut app = App::default();
        app.menu_placement = MenuPlacement::Modal;
        let mut buffer = TerminalBuffer::new(80, 18);

        let layout = render(&app, &mut buffer);
        let global = (layout.tabs.x..layout.tabs.right())
            .map(|column| buffer.get(column, layout.tabs.y).symbol.as_str())
            .collect::<String>();
        let pane = layout.surface_panes[0].header;
        let pane_chrome = (pane.y..pane.y.saturating_add(2))
            .flat_map(|row| {
                (pane.x..pane.right())
                    .map(|column| buffer.get(column, row).symbol.as_str())
                    .collect::<Vec<_>>()
            })
            .collect::<String>();

        // `App::default()` defaults to `RailIcons::Sixel` -- see
        // `file_surface_separates_global_controls_pane_title_actions_and_
        // scrollbar`'s own matching assertion for why this must no longer
        // start with the old literal `" +  [#] "` text.
        assert!(!global.starts_with(" +  [#] "), "{global:?}");
        assert!(
            layout.hits.iter().any(|hit| {
                hit.target == HitTarget::AddTab && layout.tabs.contains(hit.rect.x, hit.rect.y)
            }),
            "the tab strip must still carry its own AddTab control: {global:?}",
        );
        // The tab strip's Settings entry is an icon button, never the
        // rejected "[S]" bracket text -- see `file_surface_separates_
        // global_controls_pane_title_actions_and_scrollbar`'s own
        // assertion on the actual hit region this chrome carries.
        assert!(!global.contains("[S]"), "{global:?}");
        assert!(!global.to_ascii_lowercase().contains("empty"), "{global:?}");
        assert!(!pane_chrome.to_ascii_lowercase().contains("empty"), "{pane_chrome:?}");
        assert!(pane_chrome.trim().is_empty(), "{pane_chrome:?}");
    }

    #[test]
    fn file_and_commit_panes_keep_independent_headers_and_ascii_chrome() {
        let mut app = App::default();
        // Ascii tier: the "[History]" check below asserts the file
        // pane's own literal bracket text, which only `RailIcons::Ascii`
        // still paints -- `RailIcons::Sixel` (the default) draws a
        // History icon there instead.
        app.rail_icons = RailIcons::Ascii;
        app.menu_placement = MenuPlacement::Modal;
        let file_key = crate::app::WorkspaceFileTabKey {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            path: repository_path("src/alpha.rs"),
        };
        app.file_tabs.insert(
            file_key.clone(),
            WorkspaceFileTabView {
                editor: crate::text_editor::TextEditor::from_text("fn alpha() {}".to_owned()).unwrap(),
                state: WorkspaceFileState::Ready,
                edit_mode: false,
                request_token: 1,
                inline_history: None,
            },
        );
        let git_key = crate::app::WorkspaceGitTabKey {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            history_path: Some(repository_path("src/beta.rs")),
        };
        app.git_tabs.insert(
            git_key.clone(),
            WorkspaceGitTabView {
                state: WorkspaceGitState::Ready,
                mode: WorkspaceGitPaneMode::List,
                history_path: Some(repository_path("src/beta.rs")),
                commits: Vec::new(),
                selected: 0,
                list_scroll: 0,
                detail_scroll: 0,
                next_before: None,
                has_more: false,
                history_truncated: false,
                diff: None,
                diff_error: None,
                pending_diff: None,
                history_token: 1,
                diff_token: 0,
            },
        );
        app.surface.open_in_focused(SurfaceTab::File(file_key));
        app.surface
            .drop_tab(SurfaceTab::Git(git_key), PaneId(0), SurfaceDropZone::Right)
            .unwrap();
        let mut buffer = TerminalBuffer::new(100, 22);

        let layout = render(&app, &mut buffer);
        assert_eq!(layout.surface_panes.len(), 2);
        let left = layout.surface_panes.iter().min_by_key(|pane| pane.frame.x).unwrap();
        let right = layout.surface_panes.iter().max_by_key(|pane| pane.frame.x).unwrap();
        let header_text = |pane: &SurfacePaneLayout| {
            (pane.header.x..pane.header.right())
                .map(|column| buffer.get(column, pane.header.y).symbol.as_str())
                .collect::<String>()
        };
        let action_text = |pane: &SurfacePaneLayout| {
            (pane.header.x..pane.header.right())
                .map(|column| buffer.get(column, pane.header.y + 1).symbol.as_str())
                .collect::<String>()
        };
        let left_header = header_text(left);
        let right_header = header_text(right);

        assert!(left_header.contains("alpha.rs"), "{left_header:?}");
        assert!(!left_header.contains("beta.rs"), "{left_header:?}");
        assert!(right_header.contains("beta.rs commits"), "{right_header:?}");
        assert!(!right_header.contains("alpha.rs"), "{right_header:?}");
        assert!(!left_header.contains(" file "), "{left_header:?}");
        assert!(!right_header.contains(" git "), "{right_header:?}");
        assert!(action_text(left).contains("[History]"));
        assert!(action_text(right).contains("commits | Enter diff"));
        let divider_x = left.frame.right();
        assert_eq!(buffer.get(divider_x, left.frame.y).symbol, "|");
        for text in [left_header, right_header, action_text(left), action_text(right)] {
            assert!(text.is_ascii(), "{text:?}");
        }
        for row in left.frame.y..left.frame.bottom() {
            assert!(buffer.get(divider_x, row).symbol.is_ascii());
        }
    }

    /// FIX2 (owner report: viewport panes had no mouse close control): a
    /// two-pane split renders one independent `[x]` cross per pane, each
    /// carrying its own `PaneId` (`HitTarget::SurfacePaneClose`), UNLESS
    /// that pane is too narrow for both its own tab label and the cross
    /// -- in which case it drops the cross rather than crowd or truncate
    /// the label. The left pane's own single tab label is sized (via a
    /// deliberately lopsided split ratio) to fill its 22-cell header
    /// EXACTLY wall to wall, leaving zero free cells; the right pane's
    /// short label leaves plenty of room.
    #[test]
    fn surface_pane_close_cross_renders_per_pane_and_drops_when_the_pane_is_too_narrow() {
        let mut app = App::default();
        app.menu_placement = MenuPlacement::Modal;
        let narrow_name = "x".repeat(20);
        let narrow_key = crate::app::WorkspaceFileTabKey {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            path: repository_path(narrow_name.clone()),
        };
        app.file_tabs.insert(
            narrow_key.clone(),
            WorkspaceFileTabView {
                editor: crate::text_editor::TextEditor::from_text("fn narrow() {}".to_owned()).unwrap(),
                state: WorkspaceFileState::Ready,
                edit_mode: false,
                request_token: 1,
                inline_history: None,
            },
        );
        let wide_key = crate::app::WorkspaceFileTabKey {
            node_id: "node-a".to_owned(),
            workspace_id: "workspace-a".to_owned(),
            path: repository_path("wide.rs"),
        };
        app.file_tabs.insert(
            wide_key.clone(),
            WorkspaceFileTabView {
                editor: crate::text_editor::TextEditor::from_text("fn wide() {}".to_owned()).unwrap(),
                state: WorkspaceFileState::Ready,
                edit_mode: false,
                request_token: 1,
                inline_history: None,
            },
        );
        app.surface.open_in_focused(SurfaceTab::File(narrow_key));
        let right_pane = app
            .surface
            .drop_tab(SurfaceTab::File(wide_key), PaneId(0), SurfaceDropZone::Right)
            .unwrap();
        // 40% of the 55 usable columns (56-wide terminal, 1 column spent
        // on the divider) lands the left pane at exactly 22 cells wide --
        // the tab label's own rendered width (`" " + 20 x's + " "`) below.
        assert!(app.surface.set_split_ratio(&PaneSplitPath(Vec::new()), 4000));
        let mut buffer = TerminalBuffer::new(56, 14);

        let layout = render(&app, &mut buffer);
        assert_eq!(layout.surface_panes.len(), 2);
        let left = layout.surface_panes.iter().min_by_key(|pane| pane.frame.x).unwrap();
        let right = layout.surface_panes.iter().max_by_key(|pane| pane.frame.x).unwrap();
        assert_eq!(left.pane_id, PaneId(0));
        assert_eq!(right.pane_id, right_pane);
        assert_eq!(left.header.width, 22, "test fixture assumption: the ratio must land the narrow pane at exactly 22 cells");

        let header_text = |pane: &SurfacePaneLayout| {
            (pane.header.x..pane.header.right())
                .map(|column| buffer.get(column, pane.header.y).symbol.as_str())
                .collect::<String>()
        };
        let left_header = header_text(left);
        let right_header = header_text(right);

        assert!(
            left_header.contains(&format!(" {narrow_name} ")),
            "the narrow pane's own label must survive untruncated, not crowded to make room for a cross: {left_header:?}"
        );
        assert!(!left_header.contains("[x]"), "a too-narrow pane must render no close cross: {left_header:?}");
        assert!(
            !layout.hits.iter().any(|hit| hit.target == HitTarget::SurfacePaneClose(PaneId(0))),
            "a too-narrow pane must register no close-cross hit region"
        );

        assert!(right_header.contains("wide.rs"), "{right_header:?}");
        assert!(right_header.contains("[x]"), "a wide-enough pane must render its own close cross: {right_header:?}");
        assert!(
            layout.hits.iter().any(|hit| hit.target == HitTarget::SurfacePaneClose(right_pane)),
            "a wide-enough pane must register its own close-cross hit region"
        );
    }

